/* ==========================================================================
 * FILE: Bootstrap.php
 * ========================================================================== */
/**
 * Arena AI Coding Agent — PHP edition.
 * Bootstrap: paths, autoloading, error handling, runtime capability probe.
 *
 * Port of agent-python/app/{runtime,config}.py plumbing.
 */

/**
 * Single source of truth for the application version.
 *
 * Reported by /health, /api/version and /api/__diag, and sent as the
 * outbound User-Agent. See CHANGELOG.md. Semantic versioning: bump the minor
 * for new capability, the patch for fixes.
 *
 * APP_API_VERSION is the HTTP contract version and is intentionally pinned:
 * the bundled single-page UI depends on those response shapes.
 */
const APP_VERSION = '3.1.0';
const APP_API_VERSION = 'v1';
const PORTED_FROM_VERSION = '3.0.0';

final class Bootstrap
{
    public static string $root = '';
    public static string $dataDir = '';
    public static string $storageDir = '';
    public static string $workspacesDir = '';
    public static string $uploadsDir = '';
    public static string $jobOutputsDir = '';
    public static string $backupsDir = '';
    public static string $publicDir = '';
    public static string $binDir = '';
    public static string $scriptsDir = '';
    private static bool $booted = false;

    public static function init(): void
    {
        if (self::$booted) {
            return;
        }
        self::$booted = true;

        self::$root = dirname(__DIR__);
        self::$dataDir = self::envPath('AGENT_DATA_DIR', self::$root . '/data');
        self::$storageDir = self::envPath('AGENT_STORAGE_DIR', self::$root . '/storage');
        self::$workspacesDir = self::envPath('AGENT_WORKSPACES_DIR', self::$storageDir . '/workspaces');
        self::$uploadsDir = self::$storageDir . '/uploads';
        self::$jobOutputsDir = self::$storageDir . '/job_outputs';
        self::$backupsDir = self::$storageDir . '/backups';
        self::$publicDir = self::$root . '/public';
        self::$binDir = self::$root . '/bin';
        self::$scriptsDir = self::$root . '/scripts';

        foreach ([
            self::$dataDir,
            self::$storageDir,
            self::$workspacesDir,
            self::$uploadsDir,
            self::$jobOutputsDir,
            self::$backupsDir,
            self::$workspacesDir . '/default',
        ] as $dir) {
            if (!is_dir($dir)) {
                @mkdir($dir, 0775, true);
            }
        }

        // Files that declare more than one class need an explicit map.
        $classMap = [
            'HttpError' => 'Http',
            'Request' => 'Http',
            'Response' => 'Http',
            'Sse' => 'Http',
            'CircuitBreaker' => 'Providers',
            'ProviderStore' => 'Providers',
            'ToolContext' => 'AgentTools',
        ];

        spl_autoload_register(static function (string $class) use ($classMap): void {
            if (!str_starts_with($class, 'Arena\\')) {
                return;
            }
            $rel = str_replace('\\', '/', substr($class, strlen('Arena\\')));
            $file = __DIR__ . '/' . ($classMap[$rel] ?? $rel) . '.php';
            if (is_file($file)) {
                require_once $file;
            }
        });

        self::loadDotEnv(self::$root . '/.env');

        mb_internal_encoding('UTF-8');
        date_default_timezone_set(getenv('AGENT_TZ') ?: 'UTC');

        // Long agent loops and streaming responses must not be cut short.
        @set_time_limit(0);
        @ini_set('max_execution_time', '0');
        @ini_set('memory_limit', getenv('AGENT_MEMORY_LIMIT') ?: '512M');
        @ini_set('display_errors', '0');
        @ini_set('log_errors', '1');
        @ini_set('error_log', self::$storageDir . '/php-error.log');
        error_reporting(E_ALL);

        set_error_handler(static function (int $no, string $str, string $file = '', int $line = 0): bool {
            if (!(error_reporting() & $no)) {
                return false;
            }
            throw new \ErrorException($str, 0, $no, $file, $line);
        });
    }

    private static function envPath(string $key, string $fallback): string
    {
        $v = getenv($key);
        return ($v !== false && $v !== '') ? rtrim($v, '/') : $fallback;
    }

    /** Minimal .env loader (KEY=VALUE, # comments, optional quotes). */
    public static function loadDotEnv(string $path): void
    {
        if (!is_file($path) || !is_readable($path)) {
            return;
        }
        foreach (file($path, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES) ?: [] as $line) {
            $line = trim($line);
            if ($line === '' || str_starts_with($line, '#')) {
                continue;
            }
            $pos = strpos($line, '=');
            if ($pos === false) {
                continue;
            }
            $key = trim(substr($line, 0, $pos));
            $val = trim(substr($line, $pos + 1));
            if (strlen($val) >= 2
                && (($val[0] === '"' && str_ends_with($val, '"')) || ($val[0] === "'" && str_ends_with($val, "'")))) {
                $val = substr($val, 1, -1);
            }
            if ($key !== '' && getenv($key) === false) {
                putenv("$key=$val");
                $_ENV[$key] = $val;
            }
        }
    }

    /**
     * Probe what the host actually offers. The whole point of the PHP edition
     * is that these are normally all `true`.
     */
    public static function capabilities(): array
    {
        static $cache = null;
        if ($cache !== null) {
            return $cache;
        }

        $disabled = array_map('trim', explode(',', (string) ini_get('disable_functions')));
        $can = static fn(string $fn): bool => function_exists($fn) && !in_array($fn, $disabled, true);

        $exec = $can('proc_open');
        $which = static function (string $bin) use ($exec): ?string {
            if (!$exec) {
                return null;
            }
            $out = Terminal::rawCapture(['sh', '-lc', 'command -v ' . escapeshellarg($bin) . ' 2>/dev/null'], null, 5);
            $path = trim($out['stdout'] ?? '');
            return $path !== '' ? explode("\n", $path)[0] : null;
        };

        $cache = [
            'procOpen'      => $exec,
            'shellExec'     => $can('shell_exec'),
            'popen'         => $can('popen'),
            'pcntl'         => $can('pcntl_fork'),
            'posix'         => $can('posix_kill'),
            'curl'          => function_exists('curl_init'),
            'pdoSqlite'     => class_exists('PDO') && in_array('sqlite', \PDO::getAvailableDrivers(), true),
            'zip'           => class_exists('ZipArchive'),
            'dom'           => class_exists('DOMDocument'),
            'php'           => PHP_BINARY,
            'phpVersion'    => PHP_VERSION,
            'python'        => $which('python3') ?? $which('python'),
            'node'          => $which('node'),
            'npm'           => $which('npm'),
            'git'           => $which('git'),
            'bash'          => $which('bash'),
            'docker'        => $which('docker'),
            'composer'      => $which('composer'),
            'os'            => PHP_OS_FAMILY,
            'uname'         => php_uname('a'),
        ];
        return $cache;
    }

    public static function missingRequirements(): array
    {
        $c = self::capabilities();
        $missing = [];
        if (!$c['pdoSqlite']) {
            $missing[] = 'pdo_sqlite extension (required: the agent database)';
        }
        if (!$c['curl']) {
            $missing[] = 'curl extension (required: LLM provider calls and streaming)';
        }
        if (!$c['procOpen']) {
            $missing[] = 'proc_open() (required: terminal, code execution, git). '
                . 'Remove it from disable_functions in php.ini.';
        }
        return $missing;
    }
}

/* ==========================================================================
 * FILE: Http.php
 * ========================================================================== */
/**
 * HTTP layer: request wrapper, JSON responses, SSE streaming, error type.
 * Replaces FastAPI's Request/JSONResponse/StreamingResponse.
 */

class HttpError extends \RuntimeException
{
    public array $payload;

    public function __construct(int $status, string $detail, array $extra = [])
    {
        parent::__construct($detail, $status);
        $this->payload = array_merge(['detail' => $detail], $extra);
    }
}

final class Request
{
    public string $method;
    public string $path;
    /** @var array<string,string> */
    public array $query = [];
    /** @var array<string,string> */
    public array $headers = [];
    /** @var array<string,string> */
    public array $cookies = [];
    /** @var array<string,mixed> */
    public array $params = [];
    public ?string $rawBody = null;
    private ?array $jsonCache = null;
    public ?array $user = null;

    /**
     * URL prefix the browser must prepend to every API path.
     *
     * '' when the app owns the domain root and mod_rewrite works,
     * '/agent' for a subdirectory install,
     * '/agent/index.php' when there is no URL rewriting at all.
     */
    public static string $basePath = '';

    /** True when this request arrived as /index.php/api/... (no rewrite engine). */
    public static bool $viaFrontControllerPath = false;

    public static function capture(): self
    {
        $r = new self();
        $r->method = strtoupper($_SERVER['REQUEST_METHOD'] ?? 'GET');
        $uri = (string) ($_SERVER['REQUEST_URI'] ?? '/');
        $path = rawurldecode((string) (parse_url($uri, PHP_URL_PATH) ?: '/'));

        // ------------------------------------------------ install prefix
        // Shared hosts serve the app from a subdirectory, and plenty of them
        // ship without mod_rewrite. Both cases are detected here instead of
        // forcing the operator to hand-edit paths.
        $script = (string) ($_SERVER['SCRIPT_NAME'] ?? '');
        $frontFile = basename((string) ($_SERVER['SCRIPT_FILENAME'] ?? 'index.php'));
        // Guard against the PHP built-in server, which reports the *requested*
        // path in SCRIPT_NAME when a router script is used.
        $scriptIsFrontController = $script !== ''
            && str_ends_with($script, '.php')
            && basename($script) === $frontFile;

        $dir = $scriptIsFrontController ? rtrim(str_replace('\\', '/', dirname($script)), '/') : '';
        if ($dir === '/' || $dir === '.') {
            $dir = '';
        }

        $pathInfo = (string) ($_SERVER['PATH_INFO'] ?? '');
        if ($pathInfo !== '') {
            // /agent/index.php/api/health  →  PATH_INFO = /api/health
            $path = $pathInfo;
            self::$viaFrontControllerPath = true;
            self::$basePath = $script;
        } elseif ($scriptIsFrontController && str_starts_with($path, $script)) {
            // Same shape, but the SAPI did not populate PATH_INFO.
            $path = substr($path, strlen($script));
            self::$viaFrontControllerPath = true;
            self::$basePath = $script;
        } elseif ($dir !== '' && ($path === $dir || str_starts_with($path, $dir . '/'))) {
            $path = substr($path, strlen($dir));
            self::$basePath = $dir;
        } else {
            self::$basePath = '';
        }

        // Last-ditch escape hatch for hosts with neither rewriting nor
        // PATH_INFO: /index.php?__path=/api/health
        $queryPath = $_GET['__path'] ?? null;
        if (is_string($queryPath) && $queryPath !== '') {
            $path = $queryPath;
            self::$viaFrontControllerPath = true;
            if (self::$basePath === '') {
                self::$basePath = $script;
            }
            unset($_GET['__path']);
        }

        if ($path === '' || $path[0] !== '/') {
            $path = '/' . $path;
        }
        $r->path = $path;
        if (strlen($r->path) > 1) {
            $r->path = rtrim($r->path, '/');
            if ($r->path === '') {
                $r->path = '/';
            }
        }
        $r->query = $_GET;
        $r->cookies = $_COOKIE;
        foreach ($_SERVER as $k => $v) {
            if (str_starts_with($k, 'HTTP_')) {
                $r->headers[strtolower(str_replace('_', '-', substr($k, 5)))] = (string) $v;
            }
        }
        if (isset($_SERVER['CONTENT_TYPE'])) {
            $r->headers['content-type'] = (string) $_SERVER['CONTENT_TYPE'];
        }
        if (isset($_SERVER['CONTENT_LENGTH'])) {
            $r->headers['content-length'] = (string) $_SERVER['CONTENT_LENGTH'];
        }
        return $r;
    }

    public function header(string $name, ?string $default = null): ?string
    {
        return $this->headers[strtolower($name)] ?? $default;
    }

    public function isMultipart(): bool
    {
        return str_contains((string) $this->header('content-type', ''), 'multipart/form-data');
    }

    public function body(): string
    {
        if ($this->rawBody === null) {
            $this->rawBody = (string) file_get_contents('php://input');
        }
        return $this->rawBody;
    }

    /** Parsed JSON body (empty array when absent/invalid) merged with form fields. */
    public function json(): array
    {
        if ($this->jsonCache !== null) {
            return $this->jsonCache;
        }
        $ct = (string) $this->header('content-type', '');
        if (str_contains($ct, 'multipart/form-data') || str_contains($ct, 'x-www-form-urlencoded')) {
            $this->jsonCache = $_POST;
            return $this->jsonCache;
        }
        $raw = $this->body();
        if ($raw === '') {
            $this->jsonCache = [];
            return $this->jsonCache;
        }
        $decoded = json_decode($raw, true);
        $this->jsonCache = is_array($decoded) ? $decoded : [];
        return $this->jsonCache;
    }

    /** Value from JSON body, then form, then query string. */
    public function input(string $key, mixed $default = null): mixed
    {
        $body = $this->json();
        if (array_key_exists($key, $body)) {
            return $body[$key];
        }
        if (array_key_exists($key, $_POST)) {
            return $_POST[$key];
        }
        if (array_key_exists($key, $this->query)) {
            return $this->query[$key];
        }
        return $default;
    }

    public function str(string $key, string $default = ''): string
    {
        $v = $this->input($key, $default);
        return is_scalar($v) ? (string) $v : $default;
    }

    public function int(string $key, int $default = 0): int
    {
        $v = $this->input($key, $default);
        return is_numeric($v) ? (int) $v : $default;
    }

    public function bool(string $key, bool $default = false): bool
    {
        $v = $this->input($key, $default);
        if (is_bool($v)) {
            return $v;
        }
        if (is_string($v)) {
            return in_array(strtolower($v), ['1', 'true', 'yes', 'on'], true);
        }
        return (bool) $v;
    }

    public function arr(string $key, array $default = []): array
    {
        $v = $this->input($key, $default);
        return is_array($v) ? $v : $default;
    }

    public function param(string $key, string $default = ''): string
    {
        return isset($this->params[$key]) ? (string) $this->params[$key] : $default;
    }

    public function clientIp(): string
    {
        foreach (['http-x-forwarded-for', 'x-forwarded-for', 'cf-connecting-ip', 'x-real-ip'] as $h) {
            $v = $this->header($h);
            if ($v) {
                return trim(explode(',', $v)[0]);
            }
        }
        return (string) ($_SERVER['REMOTE_ADDR'] ?? 'unknown');
    }

    public function userAgent(): string
    {
        return (string) $this->header('user-agent', 'unknown');
    }
}

final class Response
{
    public static bool $headersSent = false;

    public static function json(mixed $data, int $status = 200, array $headers = []): void
    {
        self::sendHeaders($status, array_merge(['Content-Type' => 'application/json; charset=utf-8'], $headers));
        echo json_encode(
            $data,
            JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_INVALID_UTF8_SUBSTITUTE | JSON_PARTIAL_OUTPUT_ON_ERROR
        );
    }

    public static function text(string $body, int $status = 200, array $headers = []): void
    {
        self::sendHeaders($status, array_merge(['Content-Type' => 'text/plain; charset=utf-8'], $headers));
        echo $body;
    }

    public static function html(string $body, int $status = 200, array $headers = []): void
    {
        self::sendHeaders($status, array_merge(['Content-Type' => 'text/html; charset=utf-8'], $headers));
        echo $body;
    }

    public static function raw(string $body, string $contentType, int $status = 200, array $headers = []): void
    {
        self::sendHeaders($status, array_merge(['Content-Type' => $contentType], $headers));
        echo $body;
    }

    public static function file(string $absPath, ?string $contentType = null, ?string $downloadName = null): void
    {
        if (!is_file($absPath)) {
            throw new HttpError(404, 'File not found');
        }
        $headers = [
            'Content-Type' => $contentType ?? Files::mimeType($absPath),
            'Content-Length' => (string) filesize($absPath),
            'Cache-Control' => 'no-cache',
        ];
        if ($downloadName !== null) {
            $headers['Content-Disposition'] = 'attachment; filename="' . addslashes($downloadName) . '"';
        }
        self::sendHeaders(200, $headers);
        $fh = fopen($absPath, 'rb');
        if ($fh) {
            fpassthru($fh);
            fclose($fh);
        }
    }

    public static function noContent(int $status = 204): void
    {
        self::sendHeaders($status, []);
    }

    public static function redirect(string $location, int $status = 302): void
    {
        self::sendHeaders($status, ['Location' => $location]);
    }

    public static function sendHeaders(int $status, array $headers): void
    {
        if (self::$headersSent || headers_sent()) {
            self::$headersSent = true;
            return;
        }
        http_response_code($status);
        foreach ($headers as $k => $v) {
            header("$k: $v");
        }
        self::$headersSent = true;
    }

    public static function setCookie(string $name, string $value, int $maxAge, bool $httpOnly = true): void
    {
        $secure = (($_SERVER['HTTPS'] ?? '') !== '')
            || (($_SERVER['HTTP_X_FORWARDED_PROTO'] ?? '') === 'https');
        setcookie($name, $value, [
            'expires' => $maxAge > 0 ? time() + $maxAge : 0,
            'path' => '/',
            'httponly' => $httpOnly,
            'samesite' => 'Lax',
            'secure' => $secure,
        ]);
    }

    public static function clearCookie(string $name): void
    {
        setcookie($name, '', ['expires' => time() - 3600, 'path' => '/']);
    }
}

/**
 * Server-Sent Events writer. Mirrors the Python `event: <type>\ndata: <json>\n\n`
 * wire format exactly so the existing SPA parser keeps working.
 */
final class Sse
{
    private bool $started = false;
    public bool $aborted = false;

    public function start(): void
    {
        if ($this->started) {
            return;
        }
        $this->started = true;
        @ini_set('zlib.output_compression', '0');
        @ini_set('output_buffering', '0');
        @ini_set('implicit_flush', '1');
        while (ob_get_level() > 0) {
            @ob_end_flush();
        }
        ob_implicit_flush(true);
        ignore_user_abort(false);
        Response::sendHeaders(200, [
            'Content-Type' => 'text/event-stream; charset=utf-8',
            'Cache-Control' => 'no-cache, no-transform',
            'Connection' => 'keep-alive',
            'X-Accel-Buffering' => 'no',
        ]);
        // Nudge proxies to start forwarding immediately.
        echo ": stream-open\n\n";
        @flush();
    }

    public function send(string $event, mixed $data): void
    {
        $this->start();
        $payload = is_string($data)
            ? $data
            : json_encode($data, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_PARTIAL_OUTPUT_ON_ERROR);
        echo "event: {$event}\n";
        echo 'data: ' . $payload . "\n\n";
        @flush();
        if (connection_aborted()) {
            $this->aborted = true;
        }
    }

    public function comment(string $text): void
    {
        $this->start();
        echo ': ' . $text . "\n\n";
        @flush();
    }
}

/* ==========================================================================
 * FILE: Crypto.php
 * ========================================================================== */
/**
 * Hashing, token generation and at-rest encryption for provider API keys.
 * Port of agent-python/app/security.py (hashlib/secrets) — here with
 * hash_pbkdf2() and openssl_encrypt(), byte-compatible with the Python version
 * so an existing SQLite file keeps working.
 */

final class Crypto
{
    public const PBKDF2_ITERATIONS = 100000;

    /** @return array{0:string,1:string} [hash, salt] — hex encoded, same as Python. */
    public static function hashPassword(string $password, ?string $salt = null): array
    {
        $salt = $salt ?: bin2hex(random_bytes(16));
        $hash = hash_pbkdf2('sha256', $password, $salt, self::PBKDF2_ITERATIONS, 0, false);
        return [$hash, $salt];
    }

    public static function verifyPassword(string $password, string $hash, string $salt): bool
    {
        [$computed] = self::hashPassword($password, $salt);
        return hash_equals($hash, $computed);
    }

    /** URL-safe token, equivalent to Python's secrets.token_urlsafe(32). */
    public static function token(int $bytes = 32): string
    {
        return rtrim(strtr(base64_encode(random_bytes($bytes)), '+/', '-_'), '=');
    }

    public static function hex(int $bytes = 16): string
    {
        return bin2hex(random_bytes($bytes));
    }

    private static function secretKey(): string
    {
        $secret = getenv('AGENT_SECRET_KEY') ?: '';
        if ($secret === '') {
            // Derive a stable per-install key and persist it so restarts can
            // still decrypt stored provider keys.
            $stored = Database::state('__secret_key');
            if ($stored === null || $stored === '') {
                $stored = self::hex(32);
                Database::setState('__secret_key', $stored);
            }
            $secret = $stored;
        }
        return hash('sha256', $secret, true);
    }

    /** AES-256-GCM, output "enc:v1:<base64(iv|tag|ciphertext)>". */
    public static function encrypt(string $plain): string
    {
        if ($plain === '' || !function_exists('openssl_encrypt')) {
            return $plain;
        }
        $iv = random_bytes(12);
        $tag = '';
        $cipher = openssl_encrypt($plain, 'aes-256-gcm', self::secretKey(), OPENSSL_RAW_DATA, $iv, $tag);
        if ($cipher === false) {
            return $plain;
        }
        return 'enc:v1:' . base64_encode($iv . $tag . $cipher);
    }

    public static function decrypt(string $value): string
    {
        if (!str_starts_with($value, 'enc:v1:') || !function_exists('openssl_decrypt')) {
            return $value;
        }
        $raw = base64_decode(substr($value, 7), true);
        if ($raw === false || strlen($raw) < 29) {
            return '';
        }
        $iv = substr($raw, 0, 12);
        $tag = substr($raw, 12, 16);
        $cipher = substr($raw, 28);
        $plain = openssl_decrypt($cipher, 'aes-256-gcm', self::secretKey(), OPENSSL_RAW_DATA, $iv, $tag);
        return $plain === false ? '' : $plain;
    }

    /** "tes••••••••7890" — identical masking to the Python/Workers versions. */
    public static function maskKey(string $key): string
    {
        $len = strlen($key);
        if ($len === 0) {
            return '';
        }
        if ($len <= 8) {
            return str_repeat('•', $len);
        }
        return substr($key, 0, 3) . '••••••••' . substr($key, -4);
    }

    public static function sha256(string $data): string
    {
        return hash('sha256', $data);
    }
}

/* ==========================================================================
 * FILE: Config.php
 * ========================================================================== */
/**
 * Mutable configuration. Port of agent-python/app/config.py.
 *
 * Back to the original design: `data/environment.json` for mutable settings and
 * `data/master.key` for the encryption key (the Workers port had to use KV and
 * a deployment secret). Secrets are stored encrypted and masked on read.
 */

final class Config
{
    public const DEFAULT_PROXY_URL = 'https://proxy.fazilat-ma.workers.dev/?url={url}';

    public const KEYS = [
        'OPENROUTER_API_KEY',
        'GROQ_API_KEY',
        'TOGETHER_API_KEY',
        'MISTRAL_API_KEY',
        'GEMINI_API_KEY',
        'DEEPSEEK_API_KEY',
        'ANTHROPIC_API_KEY',
        'CLOUDFLARE_API_TOKEN',
        'CLOUDFLARE_ACCOUNT_ID',
        'GITHUB_TOKEN',
        'OLLAMA_BASE_URL',
        'PROVIDERS_FILE',
        'AGENT_PROXY_URL',
        'AGENT_PROXY_ENABLED',
        'AGENT_AUTH_TOKEN',
        'AUTH_ENABLED',
        'REQUIRE_FILE_APPROVAL',
        'MAX_CONCURRENT_JOBS',
        'RATE_LIMIT_PER_MINUTE',
        'CORS_ORIGINS',
    ];

    private static ?array $cache = null;

    public static function envFile(): string
    {
        return Bootstrap::$dataDir . '/environment.json';
    }

    public static function masterKeyFile(): string
    {
        return Bootstrap::$dataDir . '/master.key';
    }

    public static function isSecretKey(string $key): bool
    {
        if ($key === 'CLOUDFLARE_ACCOUNT_ID') {
            return false;
        }
        foreach (['KEY', 'TOKEN', 'SECRET', 'PASSWORD'] as $w) {
            if (str_contains($key, $w)) {
                return true;
            }
        }
        return false;
    }

    private static function store(): array
    {
        if (self::$cache !== null) {
            return self::$cache;
        }
        $file = self::envFile();
        $data = [];
        if (is_file($file)) {
            $decoded = json_decode((string) file_get_contents($file), true);
            if (is_array($decoded)) {
                $data = $decoded;
            }
        }
        self::$cache = $data;
        return $data;
    }

    private static function writeStore(array $data): void
    {
        self::$cache = $data;
        $file = self::envFile();
        $tmp = $file . '.tmp';
        file_put_contents($tmp, json_encode($data, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE));
        @chmod($tmp, 0600);
        rename($tmp, $file);
    }

    public static function invalidate(): void
    {
        self::$cache = null;
    }

    /** Port of config.get_raw_config: stored value wins, then env, then default. */
    public static function raw(string $key, string $fallback = ''): string
    {
        if ($key === 'AGENT_PROXY_URL' && $fallback === '') {
            $fallback = self::DEFAULT_PROXY_URL;
        }
        $store = self::store();
        if (isset($store[$key]) && trim((string) $store[$key]) !== '') {
            $val = (string) $store[$key];
            return str_starts_with($val, 'enc:') ? Crypto::decrypt($val) : $val;
        }
        $fromEnv = getenv($key);
        if ($fromEnv !== false && trim($fromEnv) !== '') {
            return $fromEnv;
        }
        return $fallback;
    }

    public static function rawInt(string $key, int $fallback): int
    {
        $v = self::raw($key, (string) $fallback);
        return is_numeric($v) ? (int) $v : $fallback;
    }

    public static function rawBool(string $key, bool $fallback = false): bool
    {
        $v = strtolower(trim(self::raw($key, $fallback ? 'true' : 'false')));
        return in_array($v, ['1', 'true', 'yes', 'on'], true);
    }

    /** Masked view for the settings UI (port of config.read_environment). */
    public static function readEnvironment(): array
    {
        $store = self::store();
        $out = [];
        foreach (self::KEYS as $k) {
            $val = $store[$k] ?? '';
            if (trim((string) $val) === '') {
                $fromEnv = getenv($k);
                $val = $fromEnv === false ? '' : $fromEnv;
            }
            if ($k === 'AGENT_PROXY_URL' && $val === '') {
                $val = self::DEFAULT_PROXY_URL;
            }
            if (self::isSecretKey($k)) {
                $plain = str_starts_with((string) $val, 'enc:') ? Crypto::decrypt((string) $val) : (string) $val;
                $out[$k] = $plain !== '' ? Crypto::maskKey($plain) : '';
            } else {
                $out[$k] = (string) $val;
            }
        }
        return $out;
    }

    /** Port of config.write_environment. */
    public static function writeEnvironment(array $incoming): array
    {
        $current = self::store();
        foreach ($incoming as $k => $raw) {
            if (!in_array($k, self::KEYS, true)) {
                continue;
            }
            $val = trim((string) ($raw ?? ''));
            if (self::isSecretKey($k)) {
                // Only overwrite a secret when the user typed a real value.
                if ($val !== '' && !str_contains($val, '••••')) {
                    $current[$k] = Crypto::encrypt($val);
                }
            } else {
                $current[$k] = $val;
            }
        }
        self::writeStore($current);
        return self::readEnvironment();
    }

    public static function authEnabled(): bool
    {
        $val = strtolower(self::raw('AUTH_ENABLED', ''));
        $token = self::raw('AGENT_AUTH_TOKEN', '');
        return in_array($val, ['1', 'true', 'yes', 'on'], true) || $token !== '';
    }

    public static function fileApprovalRequired(): bool
    {
        return self::rawBool('REQUIRE_FILE_APPROVAL', true);
    }

    public static function rateLimitPerMinute(): int
    {
        return self::rawInt('RATE_LIMIT_PER_MINUTE', 200);
    }

    public static function maxConcurrentJobs(): int
    {
        return max(1, self::rawInt('MAX_CONCURRENT_JOBS', 3));
    }

    public static function corsOrigins(): array
    {
        $raw = trim(self::raw('CORS_ORIGINS', '*'));
        if ($raw === '' || $raw === '*') {
            return ['*'];
        }
        return array_values(array_filter(array_map('trim', explode(',', $raw))));
    }

    /**
     * Port of config.parse_proxy_setting.
     *
     * Unlike the Workers build, PHP/cURL CAN use a real forward proxy, so a
     * `http://host:port` or `socks5://…` value is returned as `proxyClient`
     * and actually applied by Http client (CURLOPT_PROXY).
     *
     * @return array{effectiveUrl:string, proxyClient:?string}
     */
    public static function parseProxySetting(string $proxyVal, string $targetUrl): array
    {
        $v = trim($proxyVal);
        if ($v === '') {
            return ['effectiveUrl' => $targetUrl, 'proxyClient' => null];
        }
        foreach (['{url}', '{URL}', '{target}', '{TARGET}'] as $ph) {
            if (str_contains($v, $ph)) {
                return [
                    'effectiveUrl' => str_replace($ph, rawurlencode($targetUrl), $v),
                    'proxyClient' => null,
                ];
            }
        }
        if (str_contains($v, 'workers.dev') || str_contains($v, '?') || str_ends_with($v, '=')) {
            if (str_ends_with($v, '=') || str_ends_with($v, '?')) {
                return ['effectiveUrl' => $v . rawurlencode($targetUrl), 'proxyClient' => null];
            }
            if (str_contains($v, '?')) {
                return ['effectiveUrl' => $v . '&url=' . rawurlencode($targetUrl), 'proxyClient' => null];
            }
            return ['effectiveUrl' => rtrim($v, '/') . '/?url=' . rawurlencode($targetUrl), 'proxyClient' => null];
        }
        if (preg_match('#^(https?|socks5h?|socks4a?)://#i', $v)) {
            return ['effectiveUrl' => $targetUrl, 'proxyClient' => $v];
        }
        return ['effectiveUrl' => $targetUrl, 'proxyClient' => null];
    }

    /** @return array{effectiveUrl:string, proxyClient:?string} */
    public static function proxyConfig(string $targetUrl, ?string $customProxyUrl = null): array
    {
        if ($customProxyUrl !== null && trim($customProxyUrl) !== '') {
            return self::parseProxySetting($customProxyUrl, $targetUrl);
        }
        if (!self::rawBool('AGENT_PROXY_ENABLED', false)) {
            return ['effectiveUrl' => $targetUrl, 'proxyClient' => null];
        }
        return self::parseProxySetting(self::raw('AGENT_PROXY_URL', self::DEFAULT_PROXY_URL), $targetUrl);
    }
}

/* ==========================================================================
 * FILE: Observability.php
 * ========================================================================== */
/**
 * Structured logging, provider metrics and system metrics.
 * Port of agent-python/app/observability.py.
 *
 * Back on a real host the "disk" card can report genuine statvfs numbers again
 * (the Workers build had to substitute R2 usage against a fake 1 GiB budget).
 */

final class Observability
{
    private static int $sinceTrim = 0;
    private static float $started = 0.0;

    public static function boot(): void
    {
        if (self::$started === 0.0) {
            self::$started = microtime(true);
        }
    }

    public static function log(string $level, string $category, string $message, array $meta = []): void
    {
        try {
            Database::run(
                'INSERT INTO app_logs (level, category, message, meta) VALUES (?,?,?,?)',
                [
                    strtoupper($level ?: 'INFO'),
                    $category,
                    Security::maskLogTokens($message),
                    json_encode($meta, JSON_UNESCAPED_UNICODE) ?: '{}',
                ]
            );
            if (++self::$sinceTrim >= 100) {
                self::$sinceTrim = 0;
                Database::run('DELETE FROM app_logs WHERE id <= (SELECT MAX(id) - 2000 FROM app_logs)');
            }
        } catch (\Throwable) {
            // logging must never break a request
        }
    }

    public static function logs(?string $level = null, ?string $search = null, int $limit = 100): array
    {
        $sql = 'SELECT id, timestamp, level, category, message, meta FROM app_logs WHERE 1=1';
        $params = [];
        if ($level !== null && $level !== '') {
            $sql .= ' AND level = ?';
            $params[] = strtoupper($level);
        }
        if ($search !== null && $search !== '') {
            $sql .= ' AND (lower(message) LIKE ? OR lower(category) LIKE ?)';
            $t = '%' . strtolower($search) . '%';
            $params[] = $t;
            $params[] = $t;
        }
        $sql .= ' ORDER BY id DESC LIMIT ?';
        $params[] = max(1, min($limit, 1000));

        try {
            $rows = Database::all($sql, $params);
        } catch (\Throwable) {
            return [];
        }
        return array_map(static function (array $r): array {
            $meta = json_decode((string) ($r['meta'] ?? '{}'), true);
            return [
                'id' => (int) $r['id'],
                'timestamp' => $r['timestamp'],
                'level' => $r['level'],
                'category' => $r['category'],
                'module' => $r['category'],
                'message' => $r['message'],
                'details' => $r['meta'],
                'meta' => is_array($meta) ? $meta : [],
            ];
        }, $rows);
    }

    /** Port of observability.get_system_metrics — with real host numbers. */
    public static function systemMetrics(string $activeWorkspaceId): array
    {
        $active = (int) Database::scalar("SELECT COUNT(*) FROM jobs WHERE status IN ('running','queued')");
        $completed = (int) Database::scalar("SELECT COUNT(*) FROM jobs WHERE status = 'done'");
        $failed = (int) Database::scalar("SELECT COUNT(*) FROM jobs WHERE status = 'failed'");

        $ws = Workspaces::find($activeWorkspaceId) ?? Workspaces::fallback();
        $root = Workspaces::ensureRoot($ws);
        $size = Files::dirSize($root);

        $total = (float) (@disk_total_space($root) ?: 0);
        $free = (float) (@disk_free_space($root) ?: 0);
        $used = $total - $free;

        $caps = Bootstrap::capabilities();
        $load = function_exists('sys_getloadavg') ? (sys_getloadavg() ?: [0, 0, 0]) : [0, 0, 0];

        return [
            'activeJobs' => $active,
            'completedJobs' => $completed,
            'failedJobs' => $failed,
            'disk' => [
                'totalBytes' => (int) $total,
                'freeBytes' => (int) $free,
                'usedBytes' => (int) $used,
                'usedPercent' => $total > 0 ? round($used / $total * 1000) / 10 : 0,
                'backend' => 'local-filesystem',
                'note' => 'Real filesystem usage of the partition hosting the workspaces.',
            ],
            'storage' => [
                'fileCount' => $size['files'],
                'totalSizeBytes' => $size['bytes'],
                'totalSizeMB' => round($size['bytes'] / 1048576, 2),
                'root' => $root,
            ],
            'memory' => [
                'usageBytes' => memory_get_usage(true),
                'peakBytes' => memory_get_peak_usage(true),
                'limit' => ini_get('memory_limit'),
            ],
            'loadAverage' => ['1m' => $load[0] ?? 0, '5m' => $load[1] ?? 0, '15m' => $load[2] ?? 0],
            'runtime' => 'php-' . PHP_VERSION,
            'pythonVersion' => $caps['python'] ? Terminal::probeVersion((string) $caps['python'], '--version') : null,
            'nodeVersion' => $caps['node'] ? Terminal::probeVersion((string) $caps['node'], '--version') : null,
            'gitVersion' => $caps['git'] ? Terminal::probeVersion((string) $caps['git'], '--version') : null,
            'workerdVersion' => APP_VERSION,
            'databaseBytes' => is_file(Database::path()) ? (int) filesize(Database::path()) : 0,
            'uptimeSeconds' => (int) round(microtime(true) - (self::$started ?: microtime(true))),
        ];
    }

    public static function exportCsv(array $logs): string
    {
        $esc = static fn($v): string => '"' . str_replace('"', '""', (string) ($v ?? '')) . '"';
        $lines = [implode(',', ['ID', 'Timestamp', 'Level', 'Module', 'Message', 'Details'])];
        foreach ($logs as $l) {
            $lines[] = implode(',', array_map($esc, [
                $l['id'] ?? '',
                $l['timestamp'] ?? '',
                $l['level'] ?? '',
                $l['module'] ?? '',
                $l['message'] ?? '',
                $l['details'] ?? '',
            ]));
        }
        return implode("\n", $lines);
    }

    // ------------------------------------------------------ provider stats

    public static function recordProviderCall(
        string $providerId,
        string $modelId,
        bool $ok,
        float $latencyMs,
        int $tokens = 0
    ): void {
        try {
            Database::run(
                "INSERT INTO provider_metrics
                    (provider_id, model_id, request_count, error_count, total_tokens, total_latency_ms, last_latency_ms, last_status, updated_at)
                 VALUES (?,?,1,?,?,?,?,?,datetime('now'))
                 ON CONFLICT(provider_id, model_id) DO UPDATE SET
                    request_count = request_count + 1,
                    error_count = error_count + ?,
                    total_tokens = total_tokens + ?,
                    total_latency_ms = total_latency_ms + ?,
                    last_latency_ms = ?,
                    last_status = ?,
                    updated_at = datetime('now')",
                [
                    $providerId, $modelId, $ok ? 0 : 1, $tokens, $latencyMs, $latencyMs, $ok ? 'ok' : 'error',
                    $ok ? 0 : 1, $tokens, $latencyMs, $latencyMs, $ok ? 'ok' : 'error',
                ]
            );
        } catch (\Throwable) {
            // metrics are best effort
        }
    }

    public static function providerMetrics(): array
    {
        $rows = Database::all('SELECT * FROM provider_metrics ORDER BY request_count DESC');
        return array_map(static function (array $r): array {
            $count = max(1, (int) $r['request_count']);
            return [
                'providerId' => $r['provider_id'],
                'modelId' => $r['model_id'],
                'requestCount' => (int) $r['request_count'],
                'errorCount' => (int) $r['error_count'],
                'totalTokens' => (int) $r['total_tokens'],
                'avgLatencyMs' => round(((float) $r['total_latency_ms']) / $count, 1),
                'lastLatencyMs' => round((float) $r['last_latency_ms'], 1),
                'lastStatus' => $r['last_status'],
                'circuitBreakerTripped' => (int) $r['circuit_breaker_tripped'] === 1,
                'updatedAt' => $r['updated_at'],
            ];
        }, $rows);
    }
}

/* ==========================================================================
 * FILE: Database.php
 * ========================================================================== */
/**
 * SQLite storage via PDO. Port of agent-python/app/database.py.
 *
 * On Cloudflare this was D1; here we are back on a real local SQLite file with
 * WAL journaling, which also lets the CLI job worker share the database with
 * the web front controller.
 */

final class Database
{
    private static ?\PDO $pdo = null;
    private static bool $initialised = false;

    public static function path(): string
    {
        $env = getenv('AGENT_DB_PATH');
        if ($env !== false && $env !== '') {
            return $env;
        }
        return Bootstrap::$storageDir . '/agent.db';
    }

    public static function pdo(): \PDO
    {
        if (self::$pdo instanceof \PDO) {
            return self::$pdo;
        }
        $path = self::path();
        $dir = dirname($path);
        if (!is_dir($dir)) {
            @mkdir($dir, 0775, true);
        }
        $pdo = new \PDO('sqlite:' . $path, null, null, [
            \PDO::ATTR_ERRMODE => \PDO::ERRMODE_EXCEPTION,
            \PDO::ATTR_DEFAULT_FETCH_MODE => \PDO::FETCH_ASSOC,
            \PDO::ATTR_EMULATE_PREPARES => false,
            \PDO::ATTR_TIMEOUT => 15,
        ]);
        $pdo->exec('PRAGMA journal_mode = WAL');
        $pdo->exec('PRAGMA synchronous = NORMAL');
        $pdo->exec('PRAGMA foreign_keys = ON');
        $pdo->exec('PRAGMA busy_timeout = 15000');
        self::$pdo = $pdo;
        return $pdo;
    }

    public static function init(): void
    {
        if (self::$initialised) {
            return;
        }
        self::$initialised = true;
        $pdo = self::pdo();
        $sqlFile = Bootstrap::$root . '/migrations/0001_init.sql';
        if (is_file($sqlFile)) {
            $pdo->exec((string) file_get_contents($sqlFile));
        } elseif (class_exists('Arena\\EmbeddedAssets') && defined('Arena\\EmbeddedAssets::INIT_SQL')) {
            $pdo->exec(EmbeddedAssets::INIT_SQL);
        }
        self::seed();
    }

    /** Bootstrap default rows: admin user, default project/workspace. */
    private static function seed(): void
    {
        $pdo = self::pdo();

        $userCount = (int) $pdo->query('SELECT COUNT(*) FROM users')->fetchColumn();
        if ($userCount === 0) {
            $password = getenv('AGENT_INITIAL_ADMIN_PASSWORD') ?: 'admin123';
            [$hash, $salt] = Crypto::hashPassword($password);
            self::run(
                'INSERT INTO users (id, username, password_hash, salt, role, full_name) VALUES (?,?,?,?,?,?)',
                ['user-admin', 'admin', $hash, $salt, 'Admin', 'Administrator']
            );
            Observability::log('INFO', 'AUTH', 'Bootstrapped default admin user "admin"');
        }

        try {
            self::run("ALTER TABLE projects ADD COLUMN code_generation_mode TEXT DEFAULT 'smart-auto'");
        } catch (\Throwable $e) {}

        $projCount = (int) $pdo->query("SELECT COUNT(*) FROM projects WHERE id = 'proj-default'")->fetchColumn();
        if ($projCount === 0) {
            self::run(
                'INSERT INTO projects (id, name, description, path, code_generation_mode, is_default) VALUES (?,?,?,?,?,1)',
                ['proj-default', 'Primary Project', 'Default project', Bootstrap::$workspacesDir . '/default', 'smart-auto']
            );
        }

        $wsCount = (int) $pdo->query("SELECT COUNT(*) FROM workspaces WHERE id = 'default'")->fetchColumn();
        if ($wsCount === 0) {
            self::run(
                'INSERT INTO workspaces (id, name, path, is_default) VALUES (?,?,?,1)',
                ['default', 'Main Project', Bootstrap::$workspacesDir . '/default']
            );
        }

        if (self::state('active_workspace_id') === null) {
            self::setState('active_workspace_id', 'default');
        }
        if (self::state('active_project_id') === null) {
            self::setState('active_project_id', 'proj-default');
        }
    }

    // ---------------------------------------------------------------- queries

    public static function run(string $sql, array $params = []): \PDOStatement
    {
        $stmt = self::pdo()->prepare($sql);
        $stmt->execute(self::normalise($params));
        return $stmt;
    }

    public static function all(string $sql, array $params = []): array
    {
        return self::run($sql, $params)->fetchAll();
    }

    public static function one(string $sql, array $params = []): ?array
    {
        $row = self::run($sql, $params)->fetch();
        return $row === false ? null : $row;
    }

    public static function scalar(string $sql, array $params = []): mixed
    {
        $v = self::run($sql, $params)->fetchColumn();
        return $v === false ? null : $v;
    }

    public static function exists(string $sql, array $params = []): bool
    {
        return self::one($sql, $params) !== null;
    }

    public static function transaction(callable $fn): mixed
    {
        $pdo = self::pdo();
        if ($pdo->inTransaction()) {
            return $fn($pdo);
        }
        $pdo->beginTransaction();
        try {
            $result = $fn($pdo);
            $pdo->commit();
            return $result;
        } catch (\Throwable $e) {
            if ($pdo->inTransaction()) {
                $pdo->rollBack();
            }
            throw $e;
        }
    }

    private static function normalise(array $params): array
    {
        $out = [];
        foreach ($params as $k => $v) {
            if (is_bool($v)) {
                $v = $v ? 1 : 0;
            } elseif (is_array($v) || is_object($v)) {
                $v = json_encode($v, JSON_UNESCAPED_UNICODE);
            }
            $out[$k] = $v;
        }
        return $out;
    }

    // ------------------------------------------------------------- app_state

    public static function state(string $key, ?string $default = null): ?string
    {
        $v = self::scalar('SELECT value FROM app_state WHERE key = ?', [$key]);
        return $v === null ? $default : (string) $v;
    }

    public static function setState(string $key, string $value): void
    {
        self::run(
            "INSERT INTO app_state (key, value, updated_at) VALUES (?,?,datetime('now'))
             ON CONFLICT(key) DO UPDATE SET value = excluded.value, updated_at = datetime('now')",
            [$key, $value]
        );
    }

    public static function stateJson(string $key, mixed $default = null): mixed
    {
        $raw = self::state($key);
        if ($raw === null || $raw === '') {
            return $default;
        }
        $decoded = json_decode($raw, true);
        return $decoded === null ? $default : $decoded;
    }

    public static function setStateJson(string $key, mixed $value): void
    {
        self::setState($key, (string) json_encode($value, JSON_UNESCAPED_UNICODE));
    }

    public static function now(): string
    {
        return gmdate('Y-m-d H:i:s');
    }

    /** Sortable, collision-resistant id, matching the Python `uuid4().hex[:12]` style. */
    public static function id(string $prefix = ''): string
    {
        $hex = bin2hex(random_bytes(6));
        return $prefix !== '' ? $prefix . '-' . $hex : $hex;
    }
}

/* ==========================================================================
 * FILE: Files.php
 * ========================================================================== */
/**
 * Filesystem primitives: path normalisation, MIME detection, previews, trees,
 * archives. Port of the pathlib/shutil/mimetypes usage in
 * agent-python/app/workspaces.py — back on a real local filesystem instead of
 * the R2 object store the Workers build had to fake.
 */

final class Files
{
    public const IGNORED_SEGMENTS = [
        '.git', '.venv', 'venv', '__pycache__', 'node_modules',
        '.pytest_cache', '.cache', '.DS_Store', '.mypy_cache',
    ];

    public const IMAGE_EXT = ['.png', '.jpg', '.jpeg', '.gif', '.svg', '.webp', '.bmp', '.ico'];
    public const AUDIO_EXT = ['.mp3', '.wav', '.ogg', '.aac', '.flac', '.m4a'];
    public const VIDEO_EXT = ['.mp4', '.webm', '.ogv', '.mov', '.mkv'];
    public const EXEC_EXT  = ['.py', '.pyw', '.sh', '.bash', '.js', '.ts', '.html'];

    private const MIME = [
        '.html' => 'text/html; charset=utf-8',
        '.htm' => 'text/html; charset=utf-8',
        '.css' => 'text/css; charset=utf-8',
        '.js' => 'text/javascript; charset=utf-8',
        '.mjs' => 'text/javascript; charset=utf-8',
        '.ts' => 'text/plain; charset=utf-8',
        '.tsx' => 'text/plain; charset=utf-8',
        '.jsx' => 'text/plain; charset=utf-8',
        '.json' => 'application/json; charset=utf-8',
        '.md' => 'text/markdown; charset=utf-8',
        '.markdown' => 'text/markdown; charset=utf-8',
        '.txt' => 'text/plain; charset=utf-8',
        '.csv' => 'text/csv; charset=utf-8',
        '.tsv' => 'text/tab-separated-values; charset=utf-8',
        '.xml' => 'application/xml; charset=utf-8',
        '.yml' => 'text/yaml; charset=utf-8',
        '.yaml' => 'text/yaml; charset=utf-8',
        '.py' => 'text/x-python; charset=utf-8',
        '.pyw' => 'text/x-python; charset=utf-8',
        '.php' => 'text/x-php; charset=utf-8',
        '.sh' => 'text/x-shellscript; charset=utf-8',
        '.bash' => 'text/x-shellscript; charset=utf-8',
        '.sql' => 'application/sql; charset=utf-8',
        '.toml' => 'text/plain; charset=utf-8',
        '.ini' => 'text/plain; charset=utf-8',
        '.png' => 'image/png',
        '.jpg' => 'image/jpeg',
        '.jpeg' => 'image/jpeg',
        '.gif' => 'image/gif',
        '.svg' => 'image/svg+xml',
        '.webp' => 'image/webp',
        '.bmp' => 'image/bmp',
        '.ico' => 'image/x-icon',
        '.pdf' => 'application/pdf',
        '.mp3' => 'audio/mpeg',
        '.wav' => 'audio/wav',
        '.ogg' => 'audio/ogg',
        '.aac' => 'audio/aac',
        '.flac' => 'audio/flac',
        '.m4a' => 'audio/mp4',
        '.mp4' => 'video/mp4',
        '.webm' => 'video/webm',
        '.ogv' => 'video/ogg',
        '.zip' => 'application/zip',
        '.wasm' => 'application/wasm',
    ];

    // ------------------------------------------------------------- paths

    /** Port of workspaces.safe_path normalisation. Returns '' for the root. */
    public static function normalizeRel(?string $raw): string
    {
        $clean = trim((string) ($raw ?? '.'));
        if ($clean === '' || $clean === '.' || $clean === './') {
            return '';
        }
        $clean = str_replace('\\', '/', $clean);
        $clean = ltrim($clean, '/');
        $parts = [];
        foreach (explode('/', $clean) as $seg) {
            if ($seg === '' || $seg === '.') {
                continue;
            }
            if ($seg === '..') {
                if (!$parts) {
                    throw new HttpError(400, "Path traversal detected: '{$raw}' is outside the workspace root");
                }
                array_pop($parts);
                continue;
            }
            $parts[] = $seg;
        }
        return implode('/', $parts);
    }

    public static function isIgnored(string $rel): bool
    {
        foreach (explode('/', $rel) as $seg) {
            if (in_array($seg, self::IGNORED_SEGMENTS, true)) {
                return true;
            }
        }
        return false;
    }

    public static function basename(string $rel): string
    {
        $parts = array_values(array_filter(explode('/', str_replace('\\', '/', $rel)), 'strlen'));
        return $parts ? end($parts) : '';
    }

    public static function dirname(string $rel): string
    {
        $parts = array_values(array_filter(explode('/', str_replace('\\', '/', $rel)), 'strlen'));
        array_pop($parts);
        return implode('/', $parts);
    }

    public static function extname(string $rel): string
    {
        $name = self::basename($rel);
        $i = strrpos($name, '.');
        return ($i !== false && $i > 0) ? strtolower(substr($name, $i)) : '';
    }

    public static function mimeType(string $path): string
    {
        return self::MIME[self::extname($path)] ?? 'application/octet-stream';
    }

    public static function isTextMime(string $path): bool
    {
        $m = self::mimeType($path);
        return str_starts_with($m, 'text/')
            || in_array($m, ['application/json; charset=utf-8', 'application/xml; charset=utf-8', 'application/sql; charset=utf-8'], true);
    }

    // ------------------------------------------------------------ helpers

    public static function ensureDir(string $abs): void
    {
        if (!is_dir($abs) && !@mkdir($abs, 0775, true) && !is_dir($abs)) {
            throw new HttpError(500, 'Unable to create directory: ' . $abs);
        }
    }

    public static function write(string $abs, string $content): int
    {
        self::ensureDir(dirname($abs));
        $bytes = file_put_contents($abs, $content, LOCK_EX);
        if ($bytes === false) {
            throw new HttpError(500, 'Unable to write file: ' . basename($abs));
        }
        return $bytes;
    }

    public static function read(string $abs): string
    {
        $data = @file_get_contents($abs);
        if ($data === false) {
            throw new HttpError(404, 'File not found');
        }
        return $data;
    }

    public static function deleteTree(string $abs): int
    {
        if (is_file($abs) || is_link($abs)) {
            @unlink($abs);
            return 1;
        }
        if (!is_dir($abs)) {
            return 0;
        }
        $count = 0;
        $it = new \RecursiveIteratorIterator(
            new \RecursiveDirectoryIterator($abs, \FilesystemIterator::SKIP_DOTS),
            \RecursiveIteratorIterator::CHILD_FIRST
        );
        foreach ($it as $item) {
            /** @var \SplFileInfo $item */
            if ($item->isDir()) {
                @rmdir($item->getPathname());
            } else {
                @unlink($item->getPathname());
                $count++;
            }
        }
        @rmdir($abs);
        return $count;
    }

    public static function copyTree(string $from, string $to): int
    {
        if (is_file($from)) {
            self::ensureDir(dirname($to));
            copy($from, $to);
            return 1;
        }
        if (!is_dir($from)) {
            return 0;
        }
        self::ensureDir($to);
        $count = 0;
        $it = new \RecursiveIteratorIterator(
            new \RecursiveDirectoryIterator($from, \FilesystemIterator::SKIP_DOTS),
            \RecursiveIteratorIterator::SELF_FIRST
        );
        foreach ($it as $item) {
            /** @var \SplFileInfo $item */
            $target = $to . '/' . substr($item->getPathname(), strlen($from) + 1);
            if ($item->isDir()) {
                self::ensureDir($target);
            } else {
                self::ensureDir(dirname($target));
                copy($item->getPathname(), $target);
                $count++;
            }
        }
        return $count;
    }

    public static function dirSize(string $abs): array
    {
        $bytes = 0;
        $files = 0;
        $dirs = 0;
        if (!is_dir($abs)) {
            return ['bytes' => 0, 'files' => 0, 'dirs' => 0];
        }
        $it = new \RecursiveIteratorIterator(
            new \RecursiveDirectoryIterator($abs, \FilesystemIterator::SKIP_DOTS),
            \RecursiveIteratorIterator::SELF_FIRST
        );
        foreach ($it as $item) {
            /** @var \SplFileInfo $item */
            if ($item->isDir()) {
                $dirs++;
            } else {
                $files++;
                $bytes += $item->getSize() ?: 0;
            }
        }
        return ['bytes' => $bytes, 'files' => $files, 'dirs' => $dirs];
    }

    /** Non-recursive directory listing; dirs first, then files, both A→Z. */
    public static function listDir(string $rootAbs, string $rel = ''): array
    {
        $abs = $rel === '' ? $rootAbs : $rootAbs . '/' . $rel;
        if (!is_dir($abs)) {
            return [];
        }
        $entries = [];
        foreach (scandir($abs) ?: [] as $name) {
            if ($name === '.' || $name === '..') {
                continue;
            }
            $childRel = $rel === '' ? $name : $rel . '/' . $name;
            if (self::isIgnored($childRel)) {
                continue;
            }
            $childAbs = $abs . '/' . $name;
            $isDir = is_dir($childAbs);
            $entries[] = [
                'path' => $childRel,
                'name' => $name,
                'type' => $isDir ? 'dir' : 'file',
                'size' => $isDir ? 0 : (int) (@filesize($childAbs) ?: 0),
                'extension' => $isDir ? '' : self::extname($name),
                'modified' => (int) (@filemtime($childAbs) ?: 0),
            ];
        }
        usort($entries, static function (array $a, array $b): int {
            if ($a['type'] !== $b['type']) {
                return $a['type'] === 'dir' ? -1 : 1;
            }
            return strcasecmp($a['name'], $b['name']);
        });
        return $entries;
    }

    /** Full recursive listing (files only), used by tree/zip/search. */
    public static function listRecursive(string $rootAbs, string $rel = '', int $limit = 20000): array
    {
        $base = $rel === '' ? $rootAbs : $rootAbs . '/' . $rel;
        if (!is_dir($base)) {
            return [];
        }
        $out = [];
        $it = new \RecursiveIteratorIterator(
            new \RecursiveDirectoryIterator($base, \FilesystemIterator::SKIP_DOTS),
            \RecursiveIteratorIterator::SELF_FIRST
        );
        foreach ($it as $item) {
            /** @var \SplFileInfo $item */
            $itemRel = ltrim(str_replace('\\', '/', substr($item->getPathname(), strlen($rootAbs) + 1)), '/');
            if (self::isIgnored($itemRel)) {
                continue;
            }
            $out[] = [
                'path' => $itemRel,
                'name' => $item->getFilename(),
                'type' => $item->isDir() ? 'dir' : 'file',
                'size' => $item->isDir() ? 0 : ($item->getSize() ?: 0),
                'extension' => $item->isDir() ? '' : self::extname($item->getFilename()),
                'modified' => $item->getMTime() ?: 0,
            ];
            if (count($out) >= $limit) {
                break;
            }
        }
        usort($out, static fn(array $a, array $b): int => strcmp($a['path'], $b['path']));
        return $out;
    }

    /** Nested tree structure for the file explorer. */
    public static function buildTree(string $rootAbs, string $rel = '', int $depth = 0, int $maxDepth = 12): array
    {
        $nodes = [];
        foreach (self::listDir($rootAbs, $rel) as $entry) {
            $node = $entry;
            if ($entry['type'] === 'dir') {
                $node['children'] = $depth < $maxDepth
                    ? self::buildTree($rootAbs, $entry['path'], $depth + 1, $maxDepth)
                    : [];
            }
            $nodes[] = $node;
        }
        return $nodes;
    }

    // ----------------------------------------------------------- previews

    public static function parseCsv(string $text, string $delimiter = ','): array
    {
        $rows = [];
        $row = [];
        $field = '';
        $inQuotes = false;
        $len = strlen($text);
        for ($i = 0; $i < $len; $i++) {
            $ch = $text[$i];
            if ($inQuotes) {
                if ($ch === '"') {
                    if (($text[$i + 1] ?? '') === '"') {
                        $field .= '"';
                        $i++;
                    } else {
                        $inQuotes = false;
                    }
                } else {
                    $field .= $ch;
                }
                continue;
            }
            if ($ch === '"') {
                $inQuotes = true;
            } elseif ($ch === $delimiter) {
                $row[] = $field;
                $field = '';
            } elseif ($ch === "\n") {
                $row[] = $field;
                $rows[] = $row;
                $row = [];
                $field = '';
            } elseif ($ch !== "\r") {
                $field .= $ch;
            }
        }
        if ($field !== '' || $row) {
            $row[] = $field;
            $rows[] = $row;
        }
        return $rows;
    }

    /**
     * Build the preview payload consumed by the SPA. Shape must stay identical
     * to the Python/Workers versions.
     */
    public static function buildPreview(string $rootAbs, string $path, string $rawUrlBase): array
    {
        $rel = self::normalizeRel($path);
        $abs = $rel === '' ? $rootAbs : $rootAbs . '/' . $rel;

        if (is_dir($abs)) {
            return [
                'path' => $path,
                'filename' => self::basename($rel) ?: '.',
                'isDir' => true,
                'type' => 'dir',
                'items' => self::listDir($rootAbs, $rel),
            ];
        }
        if (!is_file($abs)) {
            throw new HttpError(404, 'File not found');
        }

        $suffix = self::extname($rel);
        $size = (int) (filesize($abs) ?: 0);
        $mime = self::mimeType($rel);
        $isExecutable = in_array($suffix, self::EXEC_EXT, true);

        $previewType = 'code';
        $contentText = null;
        $base64 = null;
        $csvData = null;

        if (in_array($suffix, self::IMAGE_EXT, true)) {
            $previewType = 'image';
            $base64 = base64_encode(self::read($abs));
        } elseif ($suffix === '.pdf') {
            $previewType = 'pdf';
        } elseif (in_array($suffix, self::AUDIO_EXT, true)) {
            $previewType = 'audio';
        } elseif (in_array($suffix, self::VIDEO_EXT, true)) {
            $previewType = 'video';
        } elseif (in_array($suffix, ['.html', '.htm'], true)) {
            $previewType = 'html';
            $contentText = self::read($abs);
        } elseif (in_array($suffix, ['.md', '.markdown'], true)) {
            $previewType = 'markdown';
            $contentText = self::read($abs);
        } elseif (in_array($suffix, ['.csv', '.tsv'], true)) {
            $previewType = 'csv';
            $contentText = self::read($abs);
            $rows = self::parseCsv($contentText, $suffix === '.tsv' ? "\t" : ',');
            $csvData = [
                'headers' => $rows[0] ?? [],
                'rows' => count($rows) > 1 ? array_slice($rows, 1, 100) : [],
                'totalRows' => count($rows),
            ];
        } else {
            $decoded = self::read($abs);
            if (str_contains($decoded, "\0")) {
                $previewType = 'binary';
            } else {
                $contentText = $decoded;
            }
        }

        return [
            'path' => $path,
            'filename' => self::basename($rel),
            'size' => $size,
            'type' => $previewType,
            'mimeType' => $mime,
            'isExecutable' => $isExecutable,
            'content' => $contentText !== null && in_array($suffix, ['.html', '.htm'], true) ? self::bundleHtmlPreview($contentText, dirname($abs)) : $contentText,
            'base64' => $base64,
            'csvData' => $csvData,
            'rawUrl' => $rawUrlBase . rawurlencode($path),
        ];
    }

    /** Inlines local stylesheets, scripts, and small images in HTML to prevent 404s when previewed in browser iframes. */
    public static function bundleHtmlPreview(string $htmlContent, string $baseDir): string
    {
        if ($htmlContent === '') {
            return '';
        }

        // 1. Inline <link rel="stylesheet" href="...">
        $htmlContent = (string) preg_replace_callback(
            '/<link\s+[^>]*?href=["\']([^"\']+\.css(?:\?[^"\']*)?)["\'][^>]*?>/i',
            static function (array $m) use ($baseDir): string {
                $href = trim($m[1]);
                if (preg_match('#^(https?:|//|data:)#i', $href)) {
                    return $m[0];
                }
                $clean = ltrim(explode('?', explode('#', $href)[0])[0], '/');
                $cssFile = $baseDir . '/' . $clean;
                if (is_file($cssFile)) {
                    $cssCode = (string) file_get_contents($cssFile);
                    return '<style data-inlined-from="' . htmlspecialchars($href, ENT_QUOTES) . "\">\n" . $cssCode . "\n</style>";
                }
                return $m[0];
            },
            $htmlContent
        );

        // 2. Inline <script src="..."></script>
        $htmlContent = (string) preg_replace_callback(
            '/<script\s+[^>]*?src=["\']([^"\']+\.(?:js|mjs)(?:\?[^"\']*)?)["\'][^>]*?>\s*<\/script>/i',
            static function (array $m) use ($baseDir): string {
                $src = trim($m[1]);
                if (preg_match('#^(https?:|//|data:)#i', $src)) {
                    return $m[0];
                }
                $clean = ltrim(explode('?', explode('#', $src)[0])[0], '/');
                $jsFile = $baseDir . '/' . $clean;
                if (is_file($jsFile)) {
                    $jsCode = (string) file_get_contents($jsFile);
                    return '<script data-inlined-from="' . htmlspecialchars($src, ENT_QUOTES) . "\">\n" . $jsCode . "\n</script>";
                }
                return $m[0];
            },
            $htmlContent
        );

        // 3. Inline images <img src="...">
        $htmlContent = (string) preg_replace_callback(
            '/(<img\s+[^>]*?)src=["\']([^"\']+)["\']([^>]*?>)/i',
            static function (array $m) use ($baseDir): string {
                $prefix = $m[1];
                $src = trim($m[2]);
                $suffix = $m[3];
                if (preg_match('#^(https?:|//|data:)#i', $src)) {
                    return $m[0];
                }
                $clean = ltrim(explode('?', explode('#', $src)[0])[0], '/');
                $imgFile = $baseDir . '/' . $clean;
                if (is_file($imgFile) && (filesize($imgFile) ?: 0) < 5 * 1024 * 1024) {
                    $mime = self::mimeType($imgFile);
                    $b64 = base64_encode((string) file_get_contents($imgFile));
                    return $prefix . 'src="data:' . $mime . ';base64,' . $b64 . '"' . $suffix;
                }
                return $m[0];
            },
            $htmlContent
        );

        return $htmlContent;
    }

    public static function humanSize(int|float $bytes): string
    {
        $units = ['B', 'KB', 'MB', 'GB', 'TB'];
        $i = 0;
        $v = (float) $bytes;
        while ($v >= 1024 && $i < count($units) - 1) {
            $v /= 1024;
            $i++;
        }
        return ($i === 0 ? (string) (int) $v : number_format($v, 1)) . ' ' . $units[$i];
    }

    /** ZIP a directory tree (ZipArchive is a real extension here — no hand-rolled writer). */
    public static function zipDirectory(string $rootAbs, string $zipPath, string $subRel = ''): int
    {
        if (!class_exists('ZipArchive')) {
            throw new HttpError(501, 'The zip extension is not enabled on this host');
        }
        $zip = new \ZipArchive();
        if ($zip->open($zipPath, \ZipArchive::CREATE | \ZipArchive::OVERWRITE) !== true) {
            throw new HttpError(500, 'Unable to create archive');
        }
        $count = 0;
        foreach (self::listRecursive($rootAbs, $subRel) as $entry) {
            if ($entry['type'] === 'dir') {
                $zip->addEmptyDir($entry['path']);
                continue;
            }
            $zip->addFile($rootAbs . '/' . $entry['path'], $entry['path']);
            $count++;
        }
        $zip->close();
        return $count;
    }

    public static function unzip(string $zipPath, string $destAbs): int
    {
        if (!class_exists('ZipArchive')) {
            throw new HttpError(501, 'The zip extension is not enabled on this host');
        }
        $zip = new \ZipArchive();
        if ($zip->open($zipPath) !== true) {
            throw new HttpError(400, 'Invalid archive');
        }
        self::ensureDir($destAbs);
        $n = $zip->numFiles;
        $zip->extractTo($destAbs);
        $zip->close();
        return $n;
    }
}

/* ==========================================================================
 * FILE: Diff.php
 * ========================================================================== */
/**
 * Unified-diff engine — PHP replacement for Python's `difflib.unified_diff`
 * used by agent-python/app/changesets.py. Output is byte-compatible with
 * difflib for the cases the app relies on:
 *   --- a/<file> / +++ b/<file> / @@ -l,s +l,s @@  with 3 lines of context.
 */

final class Diff
{
    private const CELL_LIMIT = 4000000;

    /** Like Python's str.splitlines(keepends=True). */
    public static function splitLinesKeepEnds(string $text): array
    {
        if ($text === '') {
            return [];
        }
        $out = [];
        $start = 0;
        $len = strlen($text);
        for ($i = 0; $i < $len; $i++) {
            $ch = $text[$i];
            if ($ch === "\n") {
                $out[] = substr($text, $start, $i + 1 - $start);
                $start = $i + 1;
            } elseif ($ch === "\r") {
                if (($text[$i + 1] ?? '') === "\n") {
                    $out[] = substr($text, $start, $i + 2 - $start);
                    $i++;
                } else {
                    $out[] = substr($text, $start, $i + 1 - $start);
                }
                $start = $i + 1;
            }
        }
        if ($start < $len) {
            $out[] = substr($text, $start);
        }
        return $out;
    }

    /** @return array<int, array{0:string,1:int,2:int,3:int,4:int}> */
    private static function computeOpcodes(array $a, array $b): array
    {
        $na = count($a);
        $nb = count($b);
        $ops = [];

        $pre = 0;
        while ($pre < $na && $pre < $nb && $a[$pre] === $b[$pre]) {
            $pre++;
        }
        $suf = 0;
        while ($suf < $na - $pre && $suf < $nb - $pre && $a[$na - 1 - $suf] === $b[$nb - 1 - $suf]) {
            $suf++;
        }

        if ($pre > 0) {
            $ops[] = ['equal', 0, $pre, 0, $pre];
        }

        $aMid = array_slice($a, $pre, $na - $suf - $pre);
        $bMid = array_slice($b, $pre, $nb - $suf - $pre);

        if ($aMid || $bMid) {
            foreach (self::lcsOpcodes($aMid, $bMid) as $op) {
                $ops[] = [$op[0], $op[1] + $pre, $op[2] + $pre, $op[3] + $pre, $op[4] + $pre];
            }
        }
        if ($suf > 0) {
            $ops[] = ['equal', $na - $suf, $na, $nb - $suf, $nb];
        }
        return self::mergeOpcodes($ops);
    }

    private static function mergeOpcodes(array $ops): array
    {
        $out = [];
        foreach ($ops as $op) {
            if ($op[1] === $op[2] && $op[3] === $op[4]) {
                continue;
            }
            $lastIdx = count($out) - 1;
            if ($lastIdx >= 0 && $out[$lastIdx][0] === $op[0]
                && $out[$lastIdx][2] === $op[1] && $out[$lastIdx][4] === $op[3]) {
                $out[$lastIdx][2] = $op[2];
                $out[$lastIdx][4] = $op[4];
            } else {
                $out[] = $op;
            }
        }
        return $out;
    }

    private static function lcsOpcodes(array $a, array $b): array
    {
        $n = count($a);
        $m = count($b);
        if ($n === 0 && $m === 0) {
            return [];
        }
        if ($n === 0) {
            return [['insert', 0, 0, 0, $m]];
        }
        if ($m === 0) {
            return [['delete', 0, $n, 0, 0]];
        }
        if ($n * $m > self::CELL_LIMIT) {
            return [['replace', 0, $n, 0, $m]];
        }

        // dp[i][j] = LCS length of a[i:], b[j:]
        $dp = [];
        $dp[$n] = array_fill(0, $m + 1, 0);
        for ($i = $n - 1; $i >= 0; $i--) {
            $row = array_fill(0, $m + 1, 0);
            $next = $dp[$i + 1];
            $ai = $a[$i];
            for ($j = $m - 1; $j >= 0; $j--) {
                $row[$j] = ($ai === $b[$j])
                    ? $next[$j + 1] + 1
                    : max($next[$j], $row[$j + 1]);
            }
            $dp[$i] = $row;
        }

        $ops = [];
        $i = 0;
        $j = 0;
        $pendA = 0;
        $pendB = 0;
        $eqStartA = -1;

        $flush = static function () use (&$ops, &$pendA, &$pendB, &$i, &$j): void {
            if ($pendA > 0 && $pendB > 0) {
                $ops[] = ['replace', $i - $pendA, $i, $j - $pendB, $j];
            } elseif ($pendA > 0) {
                $ops[] = ['delete', $i - $pendA, $i, $j, $j];
            } elseif ($pendB > 0) {
                $ops[] = ['insert', $i, $i, $j - $pendB, $j];
            }
            $pendA = 0;
            $pendB = 0;
        };

        while ($i < $n && $j < $m) {
            if ($a[$i] === $b[$j]) {
                $flush();
                if ($eqStartA < 0) {
                    $eqStartA = $i;
                }
                $i++;
                $j++;
            } else {
                if ($eqStartA >= 0) {
                    $ops[] = ['equal', $eqStartA, $i, $j - ($i - $eqStartA), $j];
                    $eqStartA = -1;
                }
                if ($dp[$i + 1][$j] >= $dp[$i][$j + 1]) {
                    $i++;
                    $pendA++;
                } else {
                    $j++;
                    $pendB++;
                }
            }
        }
        if ($eqStartA >= 0) {
            $ops[] = ['equal', $eqStartA, $i, $j - ($i - $eqStartA), $j];
        }
        $flush();
        if ($i < $n || $j < $m) {
            if ($i < $n && $j < $m) {
                $ops[] = ['replace', $i, $n, $j, $m];
            } elseif ($i < $n) {
                $ops[] = ['delete', $i, $n, $j, $j];
            } else {
                $ops[] = ['insert', $i, $i, $j, $m];
            }
        }
        return self::mergeOpcodes($ops);
    }

    /** difflib.SequenceMatcher.get_grouped_opcodes. */
    private static function groupOpcodes(array $ops, int $n = 3): array
    {
        if (!$ops) {
            return [];
        }
        $codes = $ops;
        if ($codes[0][0] === 'equal') {
            [$tag, $i1, $i2, $j1, $j2] = $codes[0];
            $codes[0] = [$tag, max($i1, $i2 - $n), $i2, max($j1, $j2 - $n), $j2];
        }
        $lastIdx = count($codes) - 1;
        if ($codes[$lastIdx][0] === 'equal') {
            [$tag, $i1, $i2, $j1, $j2] = $codes[$lastIdx];
            $codes[$lastIdx] = [$tag, $i1, min($i2, $i1 + $n), $j1, min($j2, $j1 + $n)];
        }

        $nn = $n + $n;
        $groups = [];
        $group = [];
        foreach ($codes as $code) {
            [$tag, $i1, $i2, $j1, $j2] = $code;
            if ($tag === 'equal' && $i2 - $i1 > $nn) {
                $group[] = [$tag, $i1, min($i2, $i1 + $n), $j1, min($j2, $j1 + $n)];
                $groups[] = $group;
                $group = [];
                $i1 = max($i1, $i2 - $n);
                $j1 = max($j1, $j2 - $n);
            }
            $group[] = [$tag, $i1, $i2, $j1, $j2];
        }
        if ($group && !(count($group) === 1 && $group[0][0] === 'equal')) {
            $groups[] = $group;
        }
        return $groups;
    }

    private static function rangeStr(int $start, int $stop): string
    {
        $length = $stop - $start;
        $begin = $length ? $start + 1 : $start;
        return $length === 1 ? (string) $begin : "{$begin},{$length}";
    }

    /** Port of changesets.compute_diff. */
    public static function compute(string $oldContent, string $newContent, string $filename): string
    {
        if ($oldContent === $newContent) {
            return '';
        }
        $a = self::splitLinesKeepEnds($oldContent);
        $b = self::splitLinesKeepEnds($newContent);
        $groups = self::groupOpcodes(self::computeOpcodes($a, $b), 3);
        if (!$groups) {
            return '';
        }

        $out = ["--- a/{$filename}\n", "+++ b/{$filename}\n"];
        foreach ($groups as $group) {
            $first = $group[0];
            $last = $group[count($group) - 1];
            $out[] = '@@ -' . self::rangeStr($first[1], $last[2])
                . ' +' . self::rangeStr($first[3], $last[4]) . " @@\n";
            foreach ($group as [$tag, $i1, $i2, $j1, $j2]) {
                if ($tag === 'equal') {
                    foreach (array_slice($a, $i1, $i2 - $i1) as $line) {
                        $out[] = ' ' . $line;
                    }
                    continue;
                }
                if ($tag === 'replace' || $tag === 'delete') {
                    foreach (array_slice($a, $i1, $i2 - $i1) as $line) {
                        $out[] = '-' . $line;
                    }
                }
                if ($tag === 'replace' || $tag === 'insert') {
                    foreach (array_slice($b, $j1, $j2 - $j1) as $line) {
                        $out[] = '+' . $line;
                    }
                }
            }
        }
        return implode('', $out);
    }

    /** Port of changesets.parse_diff_hunks. */
    public static function parseHunks(string $diffText): array
    {
        $lines = explode("\n", $diffText);
        $hunks = [];
        $current = null;
        $idx = 0;
        foreach ($lines as $line) {
            if (str_starts_with($line, '@@')) {
                if ($current !== null) {
                    $hunks[] = $current;
                }
                $idx++;
                $current = ['index' => $idx, 'header' => $line, 'lines' => [], 'status' => 'pending'];
            } elseif ($current !== null) {
                $kind = 'context';
                if (str_starts_with($line, '+')) {
                    $kind = 'add';
                } elseif (str_starts_with($line, '-')) {
                    $kind = 'del';
                }
                $current['lines'][] = ['text' => $line, 'type' => $kind];
            }
        }
        if ($current !== null) {
            $hunks[] = $current;
        }
        return $hunks;
    }

    /** Stats used by the changeset list UI. */
    public static function stats(string $diffText): array
    {
        $additions = 0;
        $deletions = 0;
        foreach (explode("\n", $diffText) as $line) {
            if (str_starts_with($line, '+') && !str_starts_with($line, '+++')) {
                $additions++;
            } elseif (str_starts_with($line, '-') && !str_starts_with($line, '---')) {
                $deletions++;
            }
        }
        return ['additions' => $additions, 'deletions' => $deletions];
    }
}

/* ==========================================================================
 * FILE: Security.php
 * ========================================================================== */
/**
 * Sessions, rate limiting, audit logging, token masking, RBAC helpers.
 * Port of agent-python/app/security.py.
 */

final class Security
{
    public const ROLE_ADMIN = 'Admin';
    public const ROLE_DEVELOPER = 'Developer';
    public const ROLE_VIEWER = 'Viewer';
    public const SESSION_TTL_HOURS = 24;
    public const SESSION_COOKIE = 'arena_session';

    private const SENSITIVE_PATTERNS = [
        '/(Bearer\s+)([A-Za-z0-9_\-\.]{8,})/i',
        '/((?:key|token|password|secret|authorization)["\']?\s*[:=]\s*["\']?)([A-Za-z0-9_\-\.]{8,})(["\']?)/i',
        '/(sk-[A-Za-z0-9_\-]{10,})/i',
        '/(ghp_[A-Za-z0-9]{20,})/i',
    ];

    // ------------------------------------------------------------- sessions

    public static function createSession(string $userId, string $ip = '', string $userAgent = ''): string
    {
        $token = Crypto::token(32);
        $expiresAt = microtime(true) + (self::SESSION_TTL_HOURS * 3600);
        $sessionId = Crypto::hex(16);

        if (!Database::exists('SELECT id FROM users WHERE id = ?', [$userId])) {
            Database::run(
                "INSERT OR IGNORE INTO users (id, username, password_hash, salt, role, full_name)
                 VALUES (?,?,'env','env','Admin',?)",
                [$userId, $userId, $userId]
            );
        }
        Database::run(
            'INSERT INTO sessions (id, user_id, token, expires_at, ip_address, user_agent) VALUES (?,?,?,?,?,?)',
            [$sessionId, $userId, $token, $expiresAt, $ip, $userAgent]
        );
        return $token;
    }

    public static function validateSession(string $token): ?array
    {
        if ($token === '') {
            return null;
        }
        $envToken = Config::raw('AGENT_AUTH_TOKEN', '');
        if ($envToken !== '' && hash_equals($envToken, $token)) {
            return [
                'id' => 'env-admin',
                'username' => 'env-admin',
                'role' => self::ROLE_ADMIN,
                'full_name' => 'Environment Admin',
            ];
        }
        $row = Database::one(
            'SELECT u.id, u.username, u.role, u.full_name, s.id AS session_id, s.expires_at
             FROM sessions s JOIN users u ON s.user_id = u.id
             WHERE s.token = ? AND s.expires_at > ?',
            [$token, microtime(true)]
        );
        if ($row === null) {
            return null;
        }
        Database::run("UPDATE sessions SET last_active = datetime('now') WHERE id = ?", [$row['session_id']]);
        return [
            'id' => $row['id'],
            'username' => $row['username'],
            'role' => $row['role'],
            'full_name' => $row['full_name'],
            'session_id' => $row['session_id'],
        ];
    }

    public static function renewSession(string $token): bool
    {
        $now = microtime(true);
        $stmt = Database::run(
            'UPDATE sessions SET expires_at = ? WHERE token = ? AND expires_at > ?',
            [$now + (self::SESSION_TTL_HOURS * 3600), $token, $now]
        );
        return $stmt->rowCount() > 0;
    }

    public static function deleteSession(string $token): bool
    {
        return Database::run('DELETE FROM sessions WHERE token = ?', [$token])->rowCount() > 0;
    }

    public static function deleteAllUserSessions(string $userId): int
    {
        return Database::run('DELETE FROM sessions WHERE user_id = ?', [$userId])->rowCount();
    }

    public static function purgeExpiredSessions(): int
    {
        return Database::run('DELETE FROM sessions WHERE expires_at < ?', [microtime(true)])->rowCount();
    }

    // ---------------------------------------------------------- rate limits

    /**
     * Sliding-ish window counter backed by SQLite (the Workers port could only
     * do this per-isolate; here every PHP process shares the same table).
     */
    public static function checkRateLimit(string $key, int $limit = 120, int $windowSeconds = 60): bool
    {
        $window = (int) (time() / max(1, $windowSeconds));
        try {
            Database::run(
                'INSERT INTO rate_limits (bucket, window_start, hits) VALUES (?,?,1)
                 ON CONFLICT(bucket, window_start) DO UPDATE SET hits = hits + 1',
                [$key, $window]
            );
            $hits = (int) Database::scalar(
                'SELECT hits FROM rate_limits WHERE bucket = ? AND window_start = ?',
                [$key, $window]
            );
            if (random_int(1, 200) === 1) {
                Database::run('DELETE FROM rate_limits WHERE window_start < ?', [$window - 5]);
            }
            return $hits <= $limit;
        } catch (\Throwable) {
            return true; // never lock the user out because of a storage hiccup
        }
    }

    // --------------------------------------------------------------- audit

    public static function logEvent(
        string $event,
        string $status,
        string $details = '',
        string $ip = '',
        string $userId = ''
    ): void {
        try {
            Database::run(
                'INSERT INTO security_logs (ip, user_id, event, status, details) VALUES (?,?,?,?,?)',
                [$ip, $userId, $event, $status, self::maskLogTokens($details)]
            );
        } catch (\Throwable) {
            // auditing must never break a request
        }
    }

    public static function maskLogTokens(?string $text): string
    {
        if ($text === null || $text === '') {
            return '';
        }
        $result = $text;
        foreach (self::SENSITIVE_PATTERNS as $i => $pattern) {
            $replacement = $i === 1 ? '$1••••••••$3' : '$1••••••••';
            if ($i >= 2) {
                $replacement = '••••••••';
            }
            $result = (string) preg_replace($pattern, $replacement, $result);
        }
        return $result;
    }

    // ---------------------------------------------------------------- RBAC

    public static function roleRank(string $role): int
    {
        return match ($role) {
            self::ROLE_ADMIN => 3,
            self::ROLE_DEVELOPER => 2,
            self::ROLE_VIEWER => 1,
            default => 0,
        };
    }

    public static function requireRole(?array $user, string $minimumRole): void
    {
        if (!Config::authEnabled()) {
            return;
        }
        $role = (string) ($user['role'] ?? '');
        if (self::roleRank($role) < self::roleRank($minimumRole)) {
            throw new HttpError(403, "Insufficient permissions. {$minimumRole} role required.");
        }
    }

    /** Blocks path traversal attempts before they reach the filesystem layer. */
    public static function assertSafeRelativePath(string $path): void
    {
        $normalised = str_replace('\\', '/', $path);
        if (str_contains($normalised, '../') || str_starts_with($normalised, '/') || preg_match('/^[A-Za-z]:/', $normalised)) {
            throw new HttpError(400, 'Invalid path: traversal outside the workspace is not allowed');
        }
    }

    // ----------------------------------------------------------- CSRF (opt)

    public static function generateCsrfToken(string $sessionId): string
    {
        $token = Crypto::hex(16);
        Database::setState('csrf:' . $sessionId . ':' . $token, (string) (time() + 86400));
        return $token;
    }

    public static function validateCsrfToken(string $sessionId, string $token): bool
    {
        $exp = Database::state('csrf:' . $sessionId . ':' . $token);
        return $exp !== null && (int) $exp > time();
    }
}

/* ==========================================================================
 * FILE: Terminal.php
 * ========================================================================== */
/**
 * Real terminal execution. Port of agent-python/app/terminal_sandbox.py.
 *
 * This is the module the Cloudflare port could not have: `proc_open()` gives
 * back a genuine shell, so `python`, `node`, `git`, `npm`, package installs,
 * long running servers and the self-healing execute/repair loop all work
 * exactly like the original FastAPI app.
 */

final class Terminal
{
    public const DANGEROUS_PATTERNS = [
        'rm -rf /',
        'rm -rf /*',
        'mkfs',
        'dd if=',
        ':(){ :|:& };:',
        '> /dev/sda',
        'chmod -R 777 /',
        'chown -R',
        'shutdown',
        'reboot',
        'poweroff',
        'init 0',
        'drop table',
        'truncate table',
        'git push --force',
        'git push -f',
        'git reset --hard origin',
    ];

    public const MAX_OUTPUT = 30000;
    public const MAX_TIMEOUT = 300;

    public static function isDangerous(string $command): bool
    {
        $lower = strtolower($command);
        foreach (self::DANGEROUS_PATTERNS as $p) {
            if (str_contains($lower, $p)) {
                return true;
            }
        }
        return false;
    }

    /** Child environment with server secrets stripped (port of get_clean_env). */
    public static function cleanEnv(array $extra = []): array
    {
        $env = getenv();
        $keep = ['PATH', 'HOME', 'USER', 'LANG', 'LC_ALL', 'SHELL', 'TERM', 'GITHUB_TOKEN', 'TMPDIR'];
        foreach (array_keys($env) as $k) {
            foreach (['KEY', 'TOKEN', 'SECRET', 'AUTH', 'PASS'] as $secret) {
                if (str_contains($k, $secret) && !in_array($k, $keep, true)) {
                    unset($env[$k]);
                    break;
                }
            }
        }
        $env['PYTHONUNBUFFERED'] = '1';
        $env['PYTHONIOENCODING'] = 'utf-8';
        $env['CI'] = '1';
        $env['TERM'] = $env['TERM'] ?? 'xterm-256color';
        $env['NO_COLOR'] = '1';
        return array_merge($env, $extra);
    }

    /**
     * Low-level capture used by capability probing (never touches the DB).
     *
     * @param array|string $cmd argv array or shell string
     * @return array{stdout:string, stderr:string, exitCode:int, timedOut:bool, pid:int}
     */
    public static function rawCapture(array|string $cmd, ?string $cwd = null, int $timeout = 60, ?array $env = null, ?string $stdin = null): array
    {
        if (!function_exists('proc_open')) {
            return ['stdout' => '', 'stderr' => 'proc_open() is disabled on this host', 'exitCode' => 126, 'timedOut' => false, 'pid' => 0];
        }
        $descriptors = [
            0 => ['pipe', 'r'],
            1 => ['pipe', 'w'],
            2 => ['pipe', 'w'],
        ];
        $pipes = [];
        $proc = @proc_open($cmd, $descriptors, $pipes, $cwd, $env);
        if (!is_resource($proc)) {
            return ['stdout' => '', 'stderr' => 'Failed to spawn process', 'exitCode' => 127, 'timedOut' => false, 'pid' => 0];
        }
        $status = proc_get_status($proc);
        $pid = (int) ($status['pid'] ?? 0);

        if ($stdin !== null && $stdin !== '') {
            @fwrite($pipes[0], $stdin);
        }
        fclose($pipes[0]);
        stream_set_blocking($pipes[1], false);
        stream_set_blocking($pipes[2], false);

        $stdout = '';
        $stderr = '';
        $deadline = microtime(true) + max(1, $timeout);
        $timedOut = false;

        while (true) {
            $read = array_filter([$pipes[1], $pipes[2]], static fn($p) => is_resource($p) && !feof($p));
            if ($read) {
                $write = null;
                $except = null;
                $remaining = $deadline - microtime(true);
                if ($remaining <= 0) {
                    $timedOut = true;
                    break;
                }
                $sec = (int) floor(min($remaining, 1));
                $usec = (int) ((min($remaining, 1) - $sec) * 1000000);
                if (@stream_select($read, $write, $except, $sec, $usec) > 0) {
                    foreach ($read as $stream) {
                        $chunk = fread($stream, 65536);
                        if ($chunk === false || $chunk === '') {
                            continue;
                        }
                        if ($stream === $pipes[1]) {
                            $stdout .= $chunk;
                        } else {
                            $stderr .= $chunk;
                        }
                    }
                }
            }
            $status = proc_get_status($proc);
            if (!$status['running']) {
                // Drain whatever is still buffered.
                foreach ([1, 2] as $i) {
                    if (is_resource($pipes[$i])) {
                        $rest = stream_get_contents($pipes[$i]);
                        if ($rest !== false && $rest !== '') {
                            if ($i === 1) {
                                $stdout .= $rest;
                            } else {
                                $stderr .= $rest;
                            }
                        }
                    }
                }
                break;
            }
            if (microtime(true) > $deadline) {
                $timedOut = true;
                break;
            }
        }

        $exitCode = 0;
        if ($timedOut) {
            self::killTree($pid);
            $exitCode = 124;
            proc_terminate($proc, 9);
        } else {
            $status = proc_get_status($proc);
            $exitCode = (int) ($status['exitcode'] ?? -1);
        }
        foreach ([1, 2] as $i) {
            if (is_resource($pipes[$i])) {
                fclose($pipes[$i]);
            }
        }
        $closed = proc_close($proc);
        if (!$timedOut && $exitCode < 0) {
            $exitCode = $closed;
        }

        return [
            'stdout' => $stdout,
            'stderr' => $stderr,
            'exitCode' => $exitCode,
            'timedOut' => $timedOut,
            'pid' => $pid,
        ];
    }

    /** SIGTERM then SIGKILL, to the whole process group when possible. */
    public static function killTree(int $pid, int $graceMs = 500): bool
    {
        if ($pid <= 0) {
            return false;
        }
        $killed = false;
        if (function_exists('posix_kill') && function_exists('posix_getpgid')) {
            $pgid = @posix_getpgid($pid);
            if ($pgid && $pgid > 1) {
                $killed = @posix_kill(-$pgid, 15);
                usleep($graceMs * 1000);
                @posix_kill(-$pgid, 9);
            }
        }
        if (!$killed) {
            @self::rawCapture(['sh', '-c', 'kill -TERM -' . $pid . ' 2>/dev/null; kill -TERM ' . $pid . ' 2>/dev/null'], null, 5);
            usleep($graceMs * 1000);
            @self::rawCapture(['sh', '-c', 'kill -KILL -' . $pid . ' 2>/dev/null; kill -KILL ' . $pid . ' 2>/dev/null'], null, 5);
            $killed = true;
        }
        return $killed;
    }

    public static function probeVersion(string $binary, string $flag = '--version'): ?string
    {
        $r = self::rawCapture([$binary, $flag], null, 8);
        $text = trim($r['stdout'] !== '' ? $r['stdout'] : $r['stderr']);
        return $text === '' ? null : explode("\n", $text)[0];
    }

    /**
     * Port of terminal_sandbox.execute_sandboxed_command.
     *
     * @return array{command:string, exitCode:int, stdout:string, stderr:string, durationMs:int, mode?:string, requiresApproval?:bool}
     */
    public static function execute(
        string $command,
        ?string $cwd = null,
        int $timeout = 60,
        bool $confirmedDangerous = false,
        string $userId = 'agent',
        array $extraEnv = []
    ): array {
        if (self::isDangerous($command) && !$confirmedDangerous) {
            return [
                'command' => $command,
                'exitCode' => -1,
                'stdout' => '',
                'stderr' => 'BLOCKED: This command is classified as potentially dangerous and requires explicit user confirmation.',
                'durationMs' => 0,
                'requiresApproval' => true,
            ];
        }
        if (!function_exists('proc_open')) {
            return [
                'command' => $command,
                'exitCode' => 126,
                'stdout' => '',
                'stderr' => 'proc_open() is disabled on this host; remove it from disable_functions to enable the terminal.',
                'durationMs' => 0,
                'mode' => 'unsupported',
                'unsupported' => true,
            ];
        }

        $targetDir = self::resolveCwd($cwd);
        $timeout = max(1, min($timeout, self::MAX_TIMEOUT));
        $env = self::cleanEnv($extraEnv);
        $started = microtime(true);

        $useDocker = Config::rawBool('DOCKER_SANDBOX_ENABLED', false)
            && (Bootstrap::capabilities()['docker'] !== null);

        if ($useDocker) {
            $wsRoot = Workspaces::ensureRoot(Workspaces::active());
            $dockerCmd = 'docker run --rm -i --net bridge --memory 1024m --cpus 2.0 '
                . '-v ' . escapeshellarg($wsRoot) . ':/workspace -w /workspace '
                . 'python:3.11-slim bash -c ' . escapeshellarg($command);
            $r = self::rawCapture(['sh', '-c', $dockerCmd], $targetDir, $timeout, $env);
            return self::shape($command, $r, $started, 'docker');
        }

        $shell = Bootstrap::capabilities()['bash'] ?? '/bin/sh';
        $argv = self::hasSetsid()
            ? ['setsid', $shell, '-c', $command]
            : [$shell, '-c', $command];

        $r = self::registeredRun($argv, $targetDir, $timeout, $env, $command, $userId);
        return self::shape($command, $r, $started, 'host');
    }

    private static function shape(string $command, array $r, float $started, string $mode): array
    {
        $out = [
            'command' => $command,
            'exitCode' => $r['exitCode'],
            'stdout' => Security::maskLogTokens(self::tail($r['stdout'])),
            'stderr' => Security::maskLogTokens(self::tail($r['stderr'])),
            'durationMs' => (int) round((microtime(true) - $started) * 1000),
            'mode' => $mode,
        ];
        if ($r['timedOut']) {
            $out['stderr'] = trim($out['stderr'] . "\nExecution timed out.");
            $out['timedOut'] = true;
        }
        return $out;
    }

    private static function tail(string $s): string
    {
        return strlen($s) > self::MAX_OUTPUT ? substr($s, -self::MAX_OUTPUT) : $s;
    }

    private static function hasSetsid(): bool
    {
        static $has = null;
        if ($has === null) {
            $r = self::rawCapture(['sh', '-c', 'command -v setsid >/dev/null 2>&1 && echo yes'], null, 5);
            $has = trim($r['stdout']) === 'yes';
        }
        return $has;
    }

    public static function resolveCwd(?string $cwd): string
    {
        $cwd = trim((string) $cwd);
        if ($cwd !== '' && str_starts_with($cwd, '/') && is_dir($cwd)) {
            return $cwd;
        }
        $ws = Workspaces::active();
        try {
            $abs = Workspaces::safePath($ws, $cwd === '' ? '.' : $cwd);
            return is_dir($abs) ? $abs : Workspaces::ensureRoot($ws);
        } catch (\Throwable) {
            return Workspaces::ensureRoot($ws);
        }
    }

    // --------------------------------------------------- process registry

    /** Run while registering the PID so the UI can list/kill it mid-flight. */
    private static function registeredRun(array $argv, string $cwd, int $timeout, array $env, string $command, string $userId): array
    {
        $descriptors = [0 => ['pipe', 'r'], 1 => ['pipe', 'w'], 2 => ['pipe', 'w']];
        $pipes = [];
        $proc = @proc_open($argv, $descriptors, $pipes, $cwd, $env);
        if (!is_resource($proc)) {
            return ['stdout' => '', 'stderr' => 'Failed to spawn process', 'exitCode' => 127, 'timedOut' => false, 'pid' => 0];
        }
        $pid = (int) (proc_get_status($proc)['pid'] ?? 0);
        self::register($pid, $command, $cwd, $userId);

        fclose($pipes[0]);
        stream_set_blocking($pipes[1], false);
        stream_set_blocking($pipes[2], false);

        $stdout = '';
        $stderr = '';
        $deadline = microtime(true) + $timeout;
        $timedOut = false;
        $lastControlCheck = 0.0;

        while (true) {
            $read = array_filter([$pipes[1], $pipes[2]], static fn($p) => is_resource($p) && !feof($p));
            if ($read) {
                $w = null;
                $e = null;
                if (@stream_select($read, $w, $e, 0, 200000) > 0) {
                    foreach ($read as $stream) {
                        $chunk = fread($stream, 65536);
                        if ($chunk === false || $chunk === '') {
                            continue;
                        }
                        if ($stream === $pipes[1]) {
                            $stdout .= $chunk;
                        } else {
                            $stderr .= $chunk;
                        }
                    }
                }
            }
            $status = proc_get_status($proc);
            if (!$status['running']) {
                foreach ([1, 2] as $i) {
                    if (is_resource($pipes[$i])) {
                        $rest = stream_get_contents($pipes[$i]);
                        if (is_string($rest) && $rest !== '') {
                            if ($i === 1) {
                                $stdout .= $rest;
                            } else {
                                $stderr .= $rest;
                            }
                        }
                    }
                }
                break;
            }
            if (microtime(true) > $deadline) {
                $timedOut = true;
                break;
            }
            // Honour a kill requested from another request.
            $now = microtime(true);
            if ($now - $lastControlCheck > 1.0) {
                $lastControlCheck = $now;
                if (self::killRequested($pid)) {
                    $timedOut = false;
                    self::killTree($pid);
                    $stderr .= "\nProcess terminated by user request.";
                    break;
                }
            }
        }

        $exitCode = 0;
        if ($timedOut) {
            self::killTree($pid);
            $exitCode = 124;
            $stderr = trim($stderr . "\nExecution timed out after {$timeout} seconds.");
            @proc_terminate($proc, 9);
        } else {
            $st = proc_get_status($proc);
            $exitCode = (int) ($st['exitcode'] ?? -1);
        }
        foreach ([1, 2] as $i) {
            if (is_resource($pipes[$i])) {
                fclose($pipes[$i]);
            }
        }
        $closed = @proc_close($proc);
        if (!$timedOut && $exitCode < 0) {
            $exitCode = $closed;
        }
        self::unregister($pid);

        return ['stdout' => $stdout, 'stderr' => $stderr, 'exitCode' => $exitCode, 'timedOut' => $timedOut, 'pid' => $pid];
    }

    public static function register(int $pid, string $command, string $cwd, string $userId, string $logPath = '', bool $detached = false): void
    {
        if ($pid <= 0) {
            return;
        }
        try {
            Database::run(
                'INSERT OR REPLACE INTO terminal_processes (pid, command, cwd, user_id, started_at, log_path, detached)
                 VALUES (?,?,?,?,?,?,?)',
                [$pid, $command, $cwd, $userId, microtime(true), $logPath, $detached ? 1 : 0]
            );
        } catch (\Throwable) {
        }
    }

    public static function unregister(int $pid): void
    {
        try {
            Database::run('DELETE FROM terminal_processes WHERE pid = ?', [$pid]);
            Database::run('DELETE FROM app_state WHERE key = ?', ['kill:' . $pid]);
        } catch (\Throwable) {
        }
    }

    public static function isAlive(int $pid): bool
    {
        if ($pid <= 0) {
            return false;
        }
        if (function_exists('posix_kill')) {
            return @posix_kill($pid, 0);
        }
        return is_dir('/proc/' . $pid);
    }

    /** Port of terminal_sandbox.list_active_processes. */
    public static function listProcesses(): array
    {
        $now = microtime(true);
        $rows = Database::all('SELECT * FROM terminal_processes ORDER BY started_at DESC');
        $out = [];
        foreach ($rows as $r) {
            $pid = (int) $r['pid'];
            if (!self::isAlive($pid)) {
                self::unregister($pid);
                continue;
            }
            $out[] = [
                'pid' => $pid,
                'command' => $r['command'],
                'cwd' => $r['cwd'],
                'started_at' => (float) $r['started_at'],
                'running_seconds' => round($now - (float) $r['started_at'], 1),
                'detached' => (int) $r['detached'] === 1,
                'logPath' => $r['log_path'] ?: null,
            ];
        }
        return $out;
    }

    /** Port of terminal_sandbox.kill_process. */
    public static function kill(int $pid): bool
    {
        $row = Database::one('SELECT pid FROM terminal_processes WHERE pid = ?', [$pid]);
        if ($row === null) {
            return false;
        }
        // Flag it so the owning request stops waiting, then signal the tree.
        Database::setState('kill:' . $pid, '1');
        $ok = self::killTree($pid);
        self::unregister($pid);
        return $ok;
    }

    private static function killRequested(int $pid): bool
    {
        return Database::state('kill:' . $pid) === '1';
    }

    /**
     * Fire-and-forget process (dev servers, the job worker daemon, long builds).
     * Output is tee'd into a log file the UI can poll.
     */
    public static function startDetached(string $command, ?string $cwd = null, string $userId = 'agent', ?string $logPath = null): array
    {
        if (!function_exists('proc_open')) {
            throw new HttpError(501, 'proc_open() is disabled on this host');
        }
        $targetDir = self::resolveCwd($cwd);
        $logPath ??= Bootstrap::$storageDir . '/proc-' . Crypto::hex(4) . '.log';
        Files::ensureDir(dirname($logPath));

        $shell = Bootstrap::capabilities()['bash'] ?? '/bin/sh';
        $wrapped = '{ ' . $command . ' ; } > ' . escapeshellarg($logPath) . ' 2>&1 & echo $!';
        $argv = self::hasSetsid() ? ['setsid', $shell, '-c', $wrapped] : [$shell, '-c', $wrapped];

        $pipes = [];
        $proc = @proc_open($argv, [0 => ['pipe', 'r'], 1 => ['pipe', 'w'], 2 => ['pipe', 'w']], $pipes, $targetDir, self::cleanEnv());
        if (!is_resource($proc)) {
            throw new HttpError(500, 'Unable to start background process');
        }
        fclose($pipes[0]);
        $pidText = trim((string) stream_get_contents($pipes[1]));
        fclose($pipes[1]);
        fclose($pipes[2]);
        proc_close($proc);

        $pid = (int) $pidText;
        if ($pid > 0) {
            self::register($pid, $command, $targetDir, $userId, $logPath, true);
        }
        return ['pid' => $pid, 'command' => $command, 'cwd' => $targetDir, 'logPath' => $logPath, 'detached' => true];
    }

    /**
     * Run a single workspace file with the right interpreter. Unlike the
     * Workers port this really executes python/node/bash/php, so the agent's
     * self-healing loop has genuine tracebacks to work with.
     */
    public static function executeFile(array $ws, string $path, ?string $conversationId = null, int $timeout = 60): array
    {
        $rel = Files::normalizeRel($path);
        $abs = Workspaces::safePath($ws, $rel);
        if (!is_file($abs)) {
            return ['ok' => false, 'success' => false, 'error' => "File not found: {$path}", 'exitCode' => 1, 'path' => $path];
        }
        // Files::extname() returns the dot-prefixed suffix; the API exposes it bare.
        $ext = ltrim(Files::extname($rel), '.');

        if ($ext === 'html' || $ext === 'htm') {
            $qs = ['path' => $rel];
            if ($conversationId !== null && $conversationId !== '') {
                $qs['conversation_id'] = $conversationId;
            }
            return [
                'ok' => true,
                'success' => true,
                'type' => 'html',
                'fileType' => 'html',
                'path' => $path,
                'previewUrl' => '/api/workspace/raw?' . http_build_query($qs),
                'exitCode' => 0,
                'stdout' => 'Live HTML preview ready.',
                'stderr' => '',
                'message' => 'HTML ready for live preview.',
            ];
        }

        $caps = Bootstrap::capabilities();
        $interpreter = match (true) {
            in_array($ext, ['py', 'pyw'], true) => $caps['python'] ?? 'python3',
            $ext === 'php' => $caps['php'] ?? 'php',
            in_array($ext, ['sh', 'bash'], true) => $caps['bash'] ?? '/bin/sh',
            in_array($ext, ['js', 'mjs', 'cjs'], true) => $caps['node'] ?? 'node',
            $ext === 'ts' => $caps['node'] !== null ? 'npx --yes tsx' : null,
            default => null,
        };

        if ($interpreter === null) {
            return [
                'ok' => true,
                'success' => true,
                'type' => 'text',
                'fileType' => $ext,
                'path' => $path,
                'exitCode' => 0,
                'stdout' => substr(Files::read($abs), 0, 30000),
                'stderr' => '',
                'message' => 'File created (no interpreter needed).',
            ];
        }

        $cmd = $interpreter . ' ' . escapeshellarg($rel);
        $res = self::execute($cmd, Workspaces::ensureRoot($ws), $timeout, true, 'agent');
        $exit = (int) ($res['exitCode'] ?? 1);

        return [
            'ok' => $exit === 0,
            'success' => $exit === 0,
            'command' => $res['command'] ?? $cmd,
            'path' => $path,
            'type' => 'script',
            'fileType' => $ext,
            'exitCode' => $exit,
            'stdout' => $res['stdout'] ?? '',
            'stderr' => $res['stderr'] ?? '',
            'durationMs' => $res['durationMs'] ?? 0,
            'mode' => $res['mode'] ?? 'host',
        ] + (isset($res['unsupported']) ? ['unsupported' => true] : []);
    }

    public static function readLog(string $logPath, int $maxBytes = 65536): string
    {
        if (!is_file($logPath)) {
            return '';
        }
        $size = filesize($logPath) ?: 0;
        $fh = fopen($logPath, 'rb');
        if (!$fh) {
            return '';
        }
        if ($size > $maxBytes) {
            fseek($fh, -$maxBytes, SEEK_END);
        }
        $data = (string) stream_get_contents($fh);
        fclose($fh);
        return $data;
    }
}

/* ==========================================================================
 * FILE: Git.php
 * ========================================================================== */
/**
 * Git integration — the REAL `git` CLI.
 * Direct port of agent-python/app/git_manager.py.
 *
 * The Cloudflare build had to emulate this through the GitHub REST API and
 * could not support stash / cherry-pick / revert / merge / conflict
 * resolution at all. Here every subcommand is the genuine article.
 */

final class Git
{
    public static function available(): bool
    {
        return Bootstrap::capabilities()['git'] !== null && function_exists('proc_open');
    }

    /** @return array{ok:bool, exitCode:int, stdout:string, stderr:string, cmd:string} */
    public static function run(array $args, ?string $cwd = null, int $timeout = 60): array
    {
        $root = $cwd ?? Workspaces::ensureRoot(Workspaces::active());
        $cmd = array_merge(['git'], $args);
        if (!self::available()) {
            return [
                'ok' => false,
                'exitCode' => -1,
                'stdout' => '',
                'stderr' => 'git is not installed on this host (or proc_open is disabled).',
                'cmd' => implode(' ', $cmd),
            ];
        }
        $env = Terminal::cleanEnv([
            'GIT_TERMINAL_PROMPT' => '0',
            'GIT_ASKPASS' => 'echo',
            'GCM_INTERACTIVE' => 'never',
        ]);
        $r = Terminal::rawCapture($cmd, $root, $timeout, $env);
        return [
            'ok' => $r['exitCode'] === 0,
            'exitCode' => $r['exitCode'],
            'stdout' => $r['stdout'],
            'stderr' => Security::maskLogTokens($r['stderr']),
            'cmd' => implode(' ', $cmd),
        ];
    }

    public static function isRepo(?string $cwd = null): bool
    {
        return self::run(['rev-parse', '--is-inside-work-tree'], $cwd, 15)['ok'];
    }

    public static function init(?string $cwd = null, string $branch = 'main'): array
    {
        $r = self::run(['init', '-b', $branch], $cwd);
        if (!$r['ok']) {
            $r = self::run(['init'], $cwd);
        }
        return $r;
    }

    public static function status(?string $cwd = null): array
    {
        $r = self::run(['status', '--porcelain', '-b'], $cwd);
        if (!$r['ok']) {
            return ['isRepo' => false, 'branch' => '', 'files' => [], 'raw' => $r['stderr']];
        }
        $lines = preg_split('/\r?\n/', rtrim($r['stdout'], "\n")) ?: [];
        $branchLine = $lines[0] ?? '';
        $branchName = 'unknown';
        $ahead = 0;
        $behind = 0;

        if (str_starts_with($branchLine, '## ')) {
            $info = substr($branchLine, 3);
            if (str_contains($info, '...')) {
                $parts = explode('...', $info, 2);
                $branchName = $parts[0];
                if (str_contains($parts[1], '[')) {
                    $meta = rtrim(explode('[', $parts[1], 2)[1], ']');
                    foreach (explode(',', $meta) as $m) {
                        $m = trim($m);
                        if (str_starts_with($m, 'ahead ')) {
                            $ahead = (int) explode(' ', $m)[1];
                        } elseif (str_starts_with($m, 'behind ')) {
                            $behind = (int) explode(' ', $m)[1];
                        }
                    }
                }
            } else {
                $branchName = explode(' ', trim($info))[0];
            }
        }

        $files = [];
        foreach (array_slice($lines, 1) as $l) {
            if (strlen($l) >= 4) {
                $files[] = [
                    'path' => trim(substr($l, 3)),
                    'staged' => !in_array($l[0], [' ', '?'], true),
                    'status' => trim(substr($l, 0, 2)),
                ];
            }
        }

        return [
            'isRepo' => true,
            'branch' => $branchName,
            'ahead' => $ahead,
            'behind' => $behind,
            'files' => $files,
            'raw' => $r['stdout'],
        ];
    }

    public static function diff(bool $stagedOnly = false, ?string $filePath = null, ?string $cwd = null): array
    {
        $args = ['diff'];
        if ($stagedOnly) {
            $args[] = '--staged';
        }
        if ($filePath !== null && $filePath !== '') {
            $args[] = '--';
            $args[] = $filePath;
        }
        $res = self::run($args, $cwd);
        $statArgs = array_merge(['diff', '--stat'], $stagedOnly ? ['--staged'] : []);
        $stat = self::run($statArgs, $cwd);
        return ['diff' => $res['stdout'], 'stat' => $stat['stdout'], 'ok' => $res['ok']];
    }

    public static function branches(?string $cwd = null): array
    {
        $r = self::run(['branch', '-a'], $cwd);
        if (!$r['ok']) {
            return ['branches' => [], 'current' => ''];
        }
        $branches = [];
        $current = '';
        foreach (preg_split('/\r?\n/', $r['stdout']) ?: [] as $line) {
            $line = trim($line);
            if ($line === '') {
                continue;
            }
            $isCurrent = str_starts_with($line, '*');
            $name = trim(ltrim($line, '* '));
            if (str_contains($name, ' -> ')) {
                $name = explode(' -> ', $name)[0];
            }
            $branches[] = ['name' => $name, 'current' => $isCurrent, 'remote' => str_starts_with($name, 'remotes/')];
            if ($isCurrent) {
                $current = $name;
            }
        }
        return ['branches' => $branches, 'current' => $current];
    }

    public static function createBranch(string $name, bool $checkout = true, ?string $cwd = null): array
    {
        return self::run($checkout ? ['checkout', '-b', $name] : ['branch', $name], $cwd);
    }

    public static function switchBranch(string $name, ?string $cwd = null): array
    {
        return self::run(['checkout', str_replace('remotes/origin/', '', $name)], $cwd);
    }

    public static function renameBranch(string $old, string $new, ?string $cwd = null): array
    {
        return self::run(['branch', '-m', $old, $new], $cwd);
    }

    public static function deleteBranch(string $name, bool $force = false, ?string $cwd = null): array
    {
        return self::run(['branch', $force ? '-D' : '-d', $name], $cwd);
    }

    public static function fetch(string $remote = 'origin', ?string $cwd = null): array
    {
        return self::run(['fetch', $remote], $cwd, 180);
    }

    public static function pull(string $remote = 'origin', string $branch = '', ?string $cwd = null): array
    {
        $args = ['pull', $remote];
        if ($branch !== '') {
            $args[] = $branch;
        }
        return self::run($args, $cwd, 300);
    }

    public static function push(string $remote = 'origin', string $branch = '', bool $force = false, bool $approved = false, ?string $cwd = null): array
    {
        if (!$approved) {
            throw new HttpError(400, 'Git push operations require explicit approval.');
        }
        $args = ['push', $remote];
        if ($branch !== '') {
            $args[] = $branch;
        }
        if ($force) {
            $args[] = '--force';
        }
        return self::run($args, $cwd, 300);
    }

    public static function commit(string $message, bool $approved = false, ?string $cwd = null): array
    {
        if (!$approved) {
            throw new HttpError(400, 'Commit operations require explicit approval.');
        }
        if (trim($message) === '') {
            throw new HttpError(400, 'Commit message cannot be empty.');
        }
        self::ensureIdentity($cwd);
        self::run(['add', '-A'], $cwd);
        return self::run(['commit', '-m', $message], $cwd);
    }

    private static function ensureIdentity(?string $cwd = null): void
    {
        $name = self::run(['config', 'user.name'], $cwd, 10);
        if (trim($name['stdout']) === '') {
            self::run(['config', 'user.name', Config::raw('GIT_AUTHOR_NAME', 'Arena Agent')], $cwd, 10);
        }
        $email = self::run(['config', 'user.email'], $cwd, 10);
        if (trim($email['stdout']) === '') {
            self::run(['config', 'user.email', Config::raw('GIT_AUTHOR_EMAIL', 'agent@arena.local')], $cwd, 10);
        }
    }

    public static function history(int $limit = 50, ?string $cwd = null): array
    {
        $fmt = '%H|%h|%an|%ae|%at|%s';
        $r = self::run(['log', '-n' . $limit, '--pretty=format:' . $fmt], $cwd);
        if (!$r['ok']) {
            return [];
        }
        $commits = [];
        foreach (preg_split('/\r?\n/', $r['stdout']) ?: [] as $line) {
            $parts = explode('|', $line);
            if (count($parts) >= 6) {
                $ts = (int) $parts[4];
                $commits[] = [
                    'hash' => $parts[0],
                    'shortHash' => $parts[1],
                    'author' => $parts[2],
                    'email' => $parts[3],
                    'timestamp' => $ts,
                    'date' => gmdate('Y-m-d H:i:s', $ts),
                    'message' => implode('|', array_slice($parts, 5)),
                ];
            }
        }
        return $commits;
    }

    public static function commitDetails(string $hash, ?string $cwd = null): array
    {
        $show = self::run(['show', '--stat', '--patch', $hash], $cwd);
        $files = self::run(['diff-tree', '--no-commit-id', '--name-only', '-r', $hash], $cwd);
        return [
            'hash' => $hash,
            'details' => $show['stdout'],
            'files' => array_values(array_filter(preg_split('/\r?\n/', $files['stdout']) ?: [], 'strlen')),
        ];
    }

    public static function cherryPick(string $hash, ?string $cwd = null): array
    {
        return self::run(['cherry-pick', $hash], $cwd);
    }

    public static function revert(string $hash, ?string $cwd = null): array
    {
        return self::run(['revert', '--no-edit', $hash], $cwd);
    }

    public static function merge(string $branch, ?string $cwd = null): array
    {
        return self::run(['merge', $branch], $cwd);
    }

    public static function stashes(?string $cwd = null): array
    {
        $r = self::run(['stash', 'list'], $cwd);
        if (!$r['ok']) {
            return [];
        }
        $out = [];
        foreach (preg_split('/\r?\n/', $r['stdout']) ?: [] as $line) {
            if (str_contains($line, ':')) {
                $parts = explode(':', $line, 3);
                $out[] = [
                    'id' => trim($parts[0]),
                    'branch' => trim($parts[1] ?? ''),
                    'message' => trim($parts[2] ?? ''),
                ];
            }
        }
        return $out;
    }

    public static function stashSave(string $message = '', ?string $cwd = null): array
    {
        $args = ['stash', 'push'];
        if ($message !== '') {
            $args[] = '-m';
            $args[] = $message;
        }
        return self::run($args, $cwd);
    }

    public static function stashApply(string $stashId = 'stash@{0}', ?string $cwd = null): array
    {
        return self::run(['stash', 'apply', $stashId], $cwd);
    }

    public static function stashDrop(string $stashId = 'stash@{0}', ?string $cwd = null): array
    {
        return self::run(['stash', 'drop', $stashId], $cwd);
    }

    public static function remotes(?string $cwd = null): array
    {
        $r = self::run(['remote', '-v'], $cwd);
        if (!$r['ok']) {
            return [];
        }
        $remotes = [];
        foreach (preg_split('/\r?\n/', $r['stdout']) ?: [] as $line) {
            $parts = preg_split('/\s+/', trim($line)) ?: [];
            if (count($parts) >= 2) {
                $remotes[$parts[0]] = $parts[1];
            }
        }
        $out = [];
        foreach ($remotes as $name => $url) {
            $out[] = ['name' => $name, 'url' => Security::maskLogTokens($url)];
        }
        return $out;
    }

    public static function addRemote(string $name, string $url, ?string $cwd = null): array
    {
        $existing = self::run(['remote', 'get-url', $name], $cwd, 10);
        if ($existing['ok']) {
            return self::run(['remote', 'set-url', $name, $url], $cwd);
        }
        return self::run(['remote', 'add', $name, $url], $cwd);
    }

    public static function conflicts(?string $cwd = null): array
    {
        $ws = Workspaces::active();
        $status = self::status($cwd);
        $out = [];
        foreach ($status['files'] ?? [] as $f) {
            if (str_contains((string) $f['status'], 'U')) {
                $abs = Workspaces::safePath($ws, (string) $f['path']);
                if (is_file($abs)) {
                    $content = Files::read($abs);
                    $out[] = [
                        'path' => $f['path'],
                        'hasMarkers' => str_contains($content, '<<<<<<<'),
                        'content' => $content,
                    ];
                }
            }
        }
        return $out;
    }

    public static function resolveConflict(string $relPath, string $mode, ?string $customContent = null, ?string $cwd = null): array
    {
        $ws = Workspaces::active();
        $abs = Workspaces::safePath($ws, $relPath);
        if ($mode === 'ours' || $mode === 'theirs') {
            self::run(['checkout', '--' . $mode, $relPath], $cwd);
            self::run(['add', $relPath], $cwd);
        } elseif ($mode === 'custom' && $customContent !== null) {
            Files::write($abs, $customContent);
            self::run(['add', $relPath], $cwd);
        } else {
            throw new HttpError(400, 'Invalid resolution mode');
        }
        return ['ok' => true, 'path' => $relPath, 'mode' => $mode];
    }

    public static function clone(string $url, string $destination, string $branch = '', ?string $token = null): array
    {
        $authUrl = $url;
        if ($token !== null && $token !== '' && str_starts_with($url, 'https://')) {
            $authUrl = preg_replace('#^https://#', 'https://' . $token . '@', $url) ?? $url;
        }
        $args = ['clone'];
        if ($branch !== '') {
            $args[] = '--branch';
            $args[] = $branch;
        }
        $args[] = $authUrl;
        $args[] = $destination;
        $r = self::run($args, dirname($destination), 600);
        $r['cmd'] = Security::maskLogTokens($r['cmd']);
        return $r;
    }
}

/* ==========================================================================
 * FILE: GitHub.php
 * ========================================================================== */
/**
 * GitHub REST v3 connector. Port of agent-python/app/github_workspace.py.
 *
 * On this host the connector complements the local `git` CLI (clone/push over
 * HTTPS with the token) instead of replacing it.
 */

final class GitHub
{
    public const API_BASE = 'https://api.github.com';

    public static function token(): string
    {
        $token = Config::raw('GITHUB_TOKEN', '');
        if ($token === '') {
            throw new HttpError(400, 'GITHUB_TOKEN is not configured in Environment settings.');
        }
        return $token;
    }

    public static function hasToken(): bool
    {
        return Config::raw('GITHUB_TOKEN', '') !== '';
    }

    private static function headers(): array
    {
        return [
            'Authorization' => 'Bearer ' . self::token(),
            'Accept' => 'application/vnd.github+json',
            'X-GitHub-Api-Version' => '2022-11-28',
            'User-Agent' => 'Arena-Agent-PHP/1.0',
            'Content-Type' => 'application/json',
        ];
    }

    public static function request(string $method, string $path, mixed $body = null, array $params = []): mixed
    {
        $url = self::API_BASE . '/' . ltrim($path, '/');
        $query = array_filter($params, static fn($v): bool => $v !== null && $v !== '');
        if ($query) {
            $url .= (str_contains($url, '?') ? '&' : '?') . http_build_query($query);
        }
        $proxy = Config::proxyConfig($url);
        $payload = $body === null ? null : json_encode($body, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
        $r = HttpClient::request($method, $proxy['effectiveUrl'], self::headers(), $payload, 45, $proxy['proxyClient']);

        if ($r['status'] === 204) {
            return ['ok' => true];
        }
        $data = json_decode($r['body'], true);
        if ($data === null && $r['body'] !== '') {
            $data = $r['body'];
        }
        if ($r['status'] >= 400) {
            $message = is_array($data) && isset($data['message'])
                ? (string) $data['message']
                : (is_string($data) ? substr($data, 0, 500) : 'GitHub API error');
            throw new HttpError($r['status'], $message);
        }
        if ($r['error'] !== null) {
            throw new HttpError(502, 'GitHub request failed: ' . $r['error']);
        }
        return $data;
    }

    public static function get(string $path, array $params = []): mixed
    {
        return self::request('GET', $path, null, $params);
    }

    public static function post(string $path, mixed $body): mixed
    {
        return self::request('POST', $path, $body);
    }

    public static function put(string $path, mixed $body): mixed
    {
        return self::request('PUT', $path, $body);
    }

    public static function patch(string $path, mixed $body): mixed
    {
        return self::request('PATCH', $path, $body);
    }

    public static function delete(string $path, mixed $body = null): mixed
    {
        return self::request('DELETE', $path, $body);
    }

    // ------------------------------------------------- high level helpers

    public static function user(): mixed
    {
        return self::get('user');
    }

    public static function repos(): mixed
    {
        return self::get('user/repos', ['per_page' => 100, 'sort' => 'updated']);
    }

    public static function branches(string $owner, string $repo): mixed
    {
        return self::get("repos/{$owner}/{$repo}/branches", ['per_page' => 100]);
    }

    public static function tree(string $owner, string $repo, string $branch = 'main'): mixed
    {
        return self::get("repos/{$owner}/{$repo}/git/trees/{$branch}", ['recursive' => '1']);
    }

    public static function file(string $owner, string $repo, string $path, ?string $ref = null): mixed
    {
        $data = self::get("repos/{$owner}/{$repo}/contents/{$path}", ['ref' => $ref]);
        if (is_array($data) && ($data['encoding'] ?? '') === 'base64' && isset($data['content'])) {
            $decoded = base64_decode(str_replace("\n", '', (string) $data['content']), true);
            $data['decodedContent'] = $decoded === false ? null : $decoded;
        }
        return $data;
    }

    public static function putFile(
        string $owner,
        string $repo,
        string $path,
        string $content,
        string $message,
        ?string $branch = null,
        ?string $sha = null
    ): mixed {
        $fileSha = $sha;
        if ($fileSha === null) {
            try {
                $existing = self::get("repos/{$owner}/{$repo}/contents/{$path}", ['ref' => $branch]);
                $fileSha = is_array($existing) ? ($existing['sha'] ?? null) : null;
            } catch (\Throwable) {
                $fileSha = null;
            }
        }
        $body = [
            'message' => $message !== '' ? $message : "Update {$path} via Arena Agent",
            'content' => base64_encode($content),
        ];
        if ($branch !== null && $branch !== '') {
            $body['branch'] = $branch;
        }
        if ($fileSha !== null) {
            $body['sha'] = $fileSha;
        }
        return self::put("repos/{$owner}/{$repo}/contents/{$path}", $body);
    }

    public static function deleteFile(string $owner, string $repo, string $path, string $message, ?string $branch = null): mixed
    {
        $existing = self::get("repos/{$owner}/{$repo}/contents/{$path}", ['ref' => $branch]);
        $body = [
            'message' => $message !== '' ? $message : "Delete {$path} via Arena Agent",
            'sha' => is_array($existing) ? ($existing['sha'] ?? null) : null,
        ];
        if ($branch !== null && $branch !== '') {
            $body['branch'] = $branch;
        }
        return self::delete("repos/{$owner}/{$repo}/contents/{$path}", $body);
    }

    public static function pulls(string $owner, string $repo, string $state = 'open'): mixed
    {
        return self::get("repos/{$owner}/{$repo}/pulls", ['state' => $state, 'per_page' => 50]);
    }

    public static function pull(string $owner, string $repo, int $number): mixed
    {
        return self::get("repos/{$owner}/{$repo}/pulls/{$number}");
    }

    public static function createPull(string $owner, string $repo, array $body): mixed
    {
        return self::post("repos/{$owner}/{$repo}/pulls", $body);
    }

    public static function mergePull(string $owner, string $repo, int $number, array $body = []): mixed
    {
        return self::put("repos/{$owner}/{$repo}/pulls/{$number}/merge", $body);
    }

    public static function reviewPull(string $owner, string $repo, int $number, array $body): mixed
    {
        return self::post("repos/{$owner}/{$repo}/pulls/{$number}/reviews", $body);
    }

    public static function workflowRuns(string $owner, string $repo): mixed
    {
        return self::get("repos/{$owner}/{$repo}/actions/runs", ['per_page' => 30]);
    }

    public static function rerunWorkflow(string $owner, string $repo, int $runId): mixed
    {
        return self::post("repos/{$owner}/{$repo}/actions/runs/{$runId}/rerun", new \stdClass());
    }

    public static function issues(string $owner, string $repo, string $state = 'open'): mixed
    {
        return self::get("repos/{$owner}/{$repo}/issues", ['state' => $state, 'per_page' => 50]);
    }

    public static function createIssue(string $owner, string $repo, array $body): mixed
    {
        return self::post("repos/{$owner}/{$repo}/issues", $body);
    }

    public static function commentIssue(string $owner, string $repo, int $number, string $body): mixed
    {
        return self::post("repos/{$owner}/{$repo}/issues/{$number}/comments", ['body' => $body]);
    }

    /**
     * Clone a repository straight into a workspace using the local git CLI —
     * something the Workers port could not do at all.
     */
    public static function cloneIntoWorkspace(string $repoUrl, array $ws, string $branch = ''): array
    {
        $root = Workspaces::ensureRoot($ws);
        $token = self::hasToken() ? Config::raw('GITHUB_TOKEN', '') : null;
        $entries = array_diff(scandir($root) ?: [], ['.', '..']);
        if ($entries) {
            $tmp = $root . '/.arena-clone-' . Crypto::hex(3);
            $res = Git::clone($repoUrl, $tmp, $branch, $token);
            if (!$res['ok']) {
                Files::deleteTree($tmp);
                return $res;
            }
            foreach (array_diff(scandir($tmp) ?: [], ['.', '..']) as $item) {
                @rename($tmp . '/' . $item, $root . '/' . $item);
            }
            Files::deleteTree($tmp);
            return $res;
        }
        return Git::clone($repoUrl, $root, $branch, $token);
    }
}

/* ==========================================================================
 * FILE: Browser.php
 * ========================================================================== */
/**
 * Browser automation. Port of agent-python/app/browser_automation.py.
 *
 * Tiers, in order:
 *   1. REAL Playwright, driven through scripts/browser_agent.py (python3).
 *   2. Headless Chrome/Chromium CLI (--dump-dom / --screenshot).
 *   3. cURL + DOMDocument extraction (title / text / links).
 *   4. Synthetic offline document.
 *
 * Tier 1 and 2 were impossible on Cloudflare Workers; on a host with a real
 * terminal they are the default again.
 */

final class Browser
{
    private const SESSION_PREFIX = 'browser:session:';

    public static function validateUrl(string $url): string
    {
        $u = trim($url);
        if ($u === '') {
            throw new HttpError(400, 'A URL is required');
        }
        if (!preg_match('#^https?://#i', $u)) {
            $u = 'https://' . $u;
        }
        $parts = parse_url($u);
        if ($parts === false || empty($parts['host'])) {
            throw new HttpError(400, "Invalid URL: {$url}");
        }
        return $u;
    }

    // ------------------------------------------------------------ sessions

    private static function emptySession(string $sessionId): array
    {
        return [
            'sessionId' => $sessionId,
            'url' => 'about:blank',
            'status' => 200,
            'title' => 'Empty Page',
            'content' => '',
            'rawHtml' => '<html><body></body></html>',
            'links' => [],
            'consoleLogs' => [],
            'networkLogs' => [],
            'engine' => self::engineName(),
            'updatedAt' => time(),
        ];
    }

    public static function loadSession(string $sessionId = 'default'): array
    {
        $raw = Database::stateJson(self::SESSION_PREFIX . $sessionId, null);
        return is_array($raw) ? $raw : self::emptySession($sessionId);
    }

    private static function saveSession(array $session): void
    {
        $session['updatedAt'] = time();
        Database::setStateJson(self::SESSION_PREFIX . $session['sessionId'], $session);
    }

    public static function createSession(string $sessionId = 'default'): array
    {
        $session = self::emptySession($sessionId);
        self::saveSession($session);
        return ['ok' => true, 'sessionId' => $sessionId, 'engine' => $session['engine']];
    }

    public static function closeSession(string $sessionId = 'default'): array
    {
        Database::run('DELETE FROM app_state WHERE key = ?', [self::SESSION_PREFIX . $sessionId]);
        return ['ok' => true, 'closed' => $sessionId];
    }

    // ------------------------------------------------------------- engines

    public static function playwrightAvailable(): bool
    {
        $cached = Database::state('browser:playwright');
        if ($cached !== null && $cached !== '') {
            $decoded = json_decode($cached, true);
            if (is_array($decoded) && (time() - (int) ($decoded['at'] ?? 0)) < 3600) {
                return (bool) $decoded['ok'];
            }
        }
        $ok = false;
        $python = Bootstrap::capabilities()['python'];
        if ($python !== null && function_exists('proc_open')) {
            $r = Terminal::rawCapture(
                [$python, Bootstrap::$scriptsDir . '/browser_agent.py', '{"action":"probe"}'],
                Bootstrap::$root,
                60
            );
            $data = json_decode(trim($r['stdout']), true);
            $ok = is_array($data) && ($data['ok'] ?? false) === true;
        }
        Database::setStateJson('browser:playwright', ['ok' => $ok, 'at' => time()]);
        return $ok;
    }

    public static function chromeBinary(): ?string
    {
        foreach (['google-chrome', 'chromium', 'chromium-browser', 'chrome'] as $bin) {
            $r = Terminal::rawCapture(['sh', '-c', 'command -v ' . escapeshellarg($bin)], null, 5);
            $path = trim($r['stdout']);
            if ($path !== '') {
                return explode("\n", $path)[0];
            }
        }
        $env = Config::raw('CHROME_BIN', '');
        return ($env !== '' && is_executable($env)) ? $env : null;
    }

    public static function engineName(): string
    {
        if (self::playwrightAvailable()) {
            return 'playwright-chromium';
        }
        if (self::chromeBinary() !== null) {
            return 'headless-chrome-cli';
        }
        return 'curl-dom';
    }

    private static function callBridge(array $payload, int $timeout = 90): ?array
    {
        $python = Bootstrap::capabilities()['python'];
        if ($python === null || !function_exists('proc_open')) {
            return null;
        }
        $r = Terminal::rawCapture(
            [$python, Bootstrap::$scriptsDir . '/browser_agent.py', (string) json_encode($payload)],
            Bootstrap::$root,
            $timeout
        );
        $data = json_decode(trim($r['stdout']), true);
        if (!is_array($data)) {
            return null;
        }
        return $data;
    }

    // ------------------------------------------------------------ actions

    public static function navigate(string $url, string $sessionId = 'default'): array
    {
        $target = self::validateUrl($url);

        if (self::playwrightAvailable()) {
            $res = self::callBridge(['action' => 'navigate', 'url' => $target]);
            if ($res !== null && ($res['ok'] ?? false)) {
                $session = [
                    'sessionId' => $sessionId,
                    'url' => (string) ($res['url'] ?? $target),
                    'status' => (int) ($res['status'] ?? 200),
                    'title' => (string) ($res['title'] ?? ''),
                    'content' => (string) ($res['content'] ?? ''),
                    'rawHtml' => (string) ($res['rawHtml'] ?? ''),
                    'links' => (array) ($res['links'] ?? []),
                    'consoleLogs' => (array) ($res['consoleLogs'] ?? []),
                    'networkLogs' => (array) ($res['networkLogs'] ?? []),
                    'engine' => (string) ($res['engine'] ?? 'playwright-chromium'),
                    'updatedAt' => time(),
                ];
                self::saveSession($session);
                return self::publicSession($session);
            }
        }

        $chrome = self::chromeBinary();
        if ($chrome !== null) {
            $r = Terminal::rawCapture(
                [$chrome, '--headless=new', '--disable-gpu', '--no-sandbox', '--dump-dom', $target],
                null,
                60
            );
            if (trim($r['stdout']) !== '') {
                $extracted = self::extractFromHtml($r['stdout'], $target);
                $session = array_merge($extracted, [
                    'sessionId' => $sessionId,
                    'url' => $target,
                    'status' => 200,
                    'engine' => 'headless-chrome-cli',
                    'consoleLogs' => [],
                    'networkLogs' => [],
                    'updatedAt' => time(),
                ]);
                self::saveSession($session);
                return self::publicSession($session);
            }
        }

        // Tier 3: plain HTTP + DOM extraction.
        $proxy = Config::proxyConfig($target);
        $resp = HttpClient::request('GET', $proxy['effectiveUrl'], [
            'User-Agent' => 'Mozilla/5.0 (compatible; ArenaAgent-PHP/1.0)',
            'Accept' => 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
        ], null, 45, $proxy['proxyClient']);

        if ($resp['body'] === '' && $resp['error'] !== null) {
            $session = array_merge(self::emptySession($sessionId), [
                'url' => $target,
                'status' => 0,
                'title' => 'Navigation failed',
                'content' => 'Unable to load the page: ' . $resp['error'],
                'engine' => 'offline',
            ]);
            self::saveSession($session);
            $out = self::publicSession($session);
            $out['ok'] = false;
            $out['error'] = $resp['error'];
            return $out;
        }

        $extracted = self::extractFromHtml($resp['body'], $target);
        $session = array_merge($extracted, [
            'sessionId' => $sessionId,
            'url' => $resp['effectiveUrl'] ?: $target,
            'status' => $resp['status'],
            'engine' => 'curl-dom',
            'consoleLogs' => [],
            'networkLogs' => [['url' => $target, 'status' => $resp['status']]],
            'updatedAt' => time(),
        ]);
        self::saveSession($session);
        return self::publicSession($session);
    }

    public static function screenshot(string $sessionId = 'default', bool $fullPage = false): array
    {
        $session = self::loadSession($sessionId);
        $url = (string) ($session['url'] ?? 'about:blank');

        if ($url !== 'about:blank' && self::playwrightAvailable()) {
            $res = self::callBridge(['action' => 'screenshot', 'url' => $url, 'fullPage' => $fullPage], 120);
            if ($res !== null && ($res['ok'] ?? false) && !empty($res['screenshotBase64'])) {
                return [
                    'ok' => true,
                    'engine' => 'playwright-chromium',
                    'mimeType' => 'image/png',
                    'imageBase64' => $res['screenshotBase64'],
                    'url' => $url,
                    'fullPage' => $fullPage,
                ];
            }
        }

        $chrome = self::chromeBinary();
        if ($url !== 'about:blank' && $chrome !== null) {
            $tmp = Bootstrap::$storageDir . '/shot-' . Crypto::hex(4) . '.png';
            $args = [$chrome, '--headless=new', '--disable-gpu', '--no-sandbox', '--hide-scrollbars',
                '--window-size=1280,800', '--screenshot=' . $tmp, $url];
            Terminal::rawCapture($args, null, 90);
            if (is_file($tmp)) {
                $data = base64_encode(Files::read($tmp));
                @unlink($tmp);
                return [
                    'ok' => true,
                    'engine' => 'headless-chrome-cli',
                    'mimeType' => 'image/png',
                    'imageBase64' => $data,
                    'url' => $url,
                    'fullPage' => $fullPage,
                ];
            }
        }

        // Synthetic wireframe (same fallback the Python version used).
        $svg = self::renderWireframe($session);
        return [
            'ok' => true,
            'engine' => 'synthetic-wireframe',
            'mimeType' => 'image/svg+xml',
            'imageBase64' => base64_encode($svg),
            'url' => $url,
            'fullPage' => $fullPage,
            'note' => 'No browser engine available; rendered a synthetic wireframe. '
                . 'Install Playwright (pip install playwright && playwright install chromium) for real screenshots.',
        ];
    }

    public static function evaluate(string $expression, string $sessionId = 'default'): array
    {
        $session = self::loadSession($sessionId);
        $url = (string) ($session['url'] ?? 'about:blank');
        if ($url !== 'about:blank' && self::playwrightAvailable()) {
            $res = self::callBridge(['action' => 'evaluate', 'url' => $url, 'expression' => $expression], 90);
            if ($res !== null && ($res['ok'] ?? false)) {
                return ['ok' => true, 'engine' => 'playwright-chromium', 'result' => $res['result'] ?? null];
            }
        }
        return [
            'ok' => false,
            'engine' => self::engineName(),
            'result' => null,
            'error' => 'JavaScript evaluation requires Playwright. Install it with: pip install playwright && playwright install chromium',
        ];
    }

    public static function click(string $selector, string $sessionId = 'default'): array
    {
        $session = self::loadSession($sessionId);
        $url = (string) ($session['url'] ?? 'about:blank');
        if ($url !== 'about:blank' && self::playwrightAvailable()) {
            $res = self::callBridge(['action' => 'click', 'url' => $url, 'selector' => $selector], 90);
            if ($res !== null && ($res['ok'] ?? false)) {
                $session = array_merge($session, [
                    'url' => (string) ($res['url'] ?? $url),
                    'title' => (string) ($res['title'] ?? $session['title']),
                    'content' => (string) ($res['content'] ?? $session['content']),
                    'rawHtml' => (string) ($res['rawHtml'] ?? $session['rawHtml']),
                    'links' => (array) ($res['links'] ?? $session['links']),
                ]);
                self::saveSession($session);
                return array_merge(['ok' => true, 'clicked' => $selector], self::publicSession($session));
            }
        }
        // DOM-only fallback: follow the link the selector points at.
        foreach ((array) ($session['links'] ?? []) as $link) {
            if (str_contains((string) ($link['text'] ?? ''), trim($selector, '#.'))) {
                return self::navigate((string) $link['href'], $sessionId);
            }
        }
        return ['ok' => false, 'error' => 'Click requires a real browser engine (Playwright or headless Chrome).', 'selector' => $selector];
    }

    public static function fill(string $selector, string $text, string $sessionId = 'default'): array
    {
        $session = self::loadSession($sessionId);
        $url = (string) ($session['url'] ?? 'about:blank');
        if ($url !== 'about:blank' && self::playwrightAvailable()) {
            $res = self::callBridge(['action' => 'fill', 'url' => $url, 'selector' => $selector, 'text' => $text], 90);
            if ($res !== null && ($res['ok'] ?? false)) {
                return ['ok' => true, 'filled' => $selector, 'engine' => 'playwright-chromium'];
            }
        }
        return ['ok' => false, 'error' => 'Form filling requires Playwright.', 'selector' => $selector];
    }

    public static function logs(string $sessionId = 'default'): array
    {
        $session = self::loadSession($sessionId);
        return [
            'ok' => true,
            'sessionId' => $sessionId,
            'consoleLogs' => $session['consoleLogs'] ?? [],
            'networkLogs' => $session['networkLogs'] ?? [],
            'engine' => $session['engine'] ?? self::engineName(),
        ];
    }

    /** Raw HTTP GET used by the `http_request` agent tool. */
    public static function fetchUrl(string $url): array
    {
        $target = self::validateUrl($url);
        $proxy = Config::proxyConfig($target);
        $r = HttpClient::request('GET', $proxy['effectiveUrl'], [
            'User-Agent' => 'Mozilla/5.0 (compatible; ArenaAgent-PHP/1.0)',
        ], null, 45, $proxy['proxyClient']);
        $body = $r['body'];
        return [
            'ok' => $r['ok'],
            'url' => $target,
            'status' => $r['status'],
            'contentType' => $r['headers']['content-type'] ?? '',
            'length' => strlen($body),
            'body' => strlen($body) > 100000 ? substr($body, 0, 100000) . "\n… (truncated)" : $body,
            'error' => $r['error'],
        ];
    }

    // ------------------------------------------------------------ helpers

    public static function extractFromHtml(string $html, string $baseUrl): array
    {
        $title = '';
        if (preg_match('#<title[^>]*>(.*?)</title>#is', $html, $m)) {
            $title = trim(html_entity_decode(strip_tags($m[1]), ENT_QUOTES | ENT_HTML5, 'UTF-8'));
        }

        $links = [];
        $content = '';

        if (class_exists('DOMDocument') && trim($html) !== '') {
            $doc = new \DOMDocument();
            $prev = libxml_use_internal_errors(true);
            $doc->loadHTML('<?xml encoding="UTF-8">' . $html);
            libxml_clear_errors();
            libxml_use_internal_errors($prev);

            foreach ($doc->getElementsByTagName('script') as $node) {
                $node->textContent = '';
            }
            foreach ($doc->getElementsByTagName('style') as $node) {
                $node->textContent = '';
            }
            $body = $doc->getElementsByTagName('body')->item(0);
            $content = trim((string) preg_replace('/\n{3,}/', "\n\n", (string) ($body?->textContent ?? '')));

            foreach ($doc->getElementsByTagName('a') as $a) {
                $href = $a->getAttribute('href');
                if ($href === '' || str_starts_with($href, 'javascript:')) {
                    continue;
                }
                $links[] = [
                    'href' => self::absoluteUrl($href, $baseUrl),
                    'text' => trim(preg_replace('/\s+/', ' ', $a->textContent) ?? ''),
                ];
                if (count($links) >= 100) {
                    break;
                }
            }
        } else {
            $content = trim(html_entity_decode(strip_tags($html), ENT_QUOTES | ENT_HTML5, 'UTF-8'));
        }

        return [
            'title' => $title !== '' ? $title : $baseUrl,
            'content' => strlen($content) > 200000 ? substr($content, 0, 200000) : $content,
            'rawHtml' => strlen($html) > 500000 ? substr($html, 0, 500000) : $html,
            'links' => $links,
        ];
    }

    private static function absoluteUrl(string $href, string $base): string
    {
        if (preg_match('#^[a-z][a-z0-9+.\-]*://#i', $href) || str_starts_with($href, 'mailto:')) {
            return $href;
        }
        $b = parse_url($base);
        if ($b === false || empty($b['scheme']) || empty($b['host'])) {
            return $href;
        }
        $origin = $b['scheme'] . '://' . $b['host'] . (isset($b['port']) ? ':' . $b['port'] : '');
        if (str_starts_with($href, '//')) {
            return $b['scheme'] . ':' . $href;
        }
        if (str_starts_with($href, '/')) {
            return $origin . $href;
        }
        $path = $b['path'] ?? '/';
        $dir = str_ends_with($path, '/') ? $path : dirname($path) . '/';
        return $origin . $dir . $href;
    }

    private static function publicSession(array $session): array
    {
        $content = (string) ($session['content'] ?? '');
        return [
            'ok' => true,
            'sessionId' => $session['sessionId'],
            'url' => $session['url'],
            'status' => $session['status'],
            'title' => $session['title'],
            'content' => strlen($content) > 50000 ? substr($content, 0, 50000) . "\n… (truncated)" : $content,
            'links' => array_slice((array) ($session['links'] ?? []), 0, 100),
            'linkCount' => count((array) ($session['links'] ?? [])),
            'engine' => $session['engine'],
            'consoleLogs' => $session['consoleLogs'] ?? [],
            'networkLogs' => $session['networkLogs'] ?? [],
        ];
    }

    private static function renderWireframe(array $session): string
    {
        $esc = static fn(string $s): string => htmlspecialchars($s, ENT_QUOTES | ENT_XML1, 'UTF-8');
        $title = $esc(substr((string) ($session['title'] ?? 'Untitled'), 0, 80));
        $url = $esc(substr((string) ($session['url'] ?? ''), 0, 90));
        $lines = array_slice(array_values(array_filter(
            preg_split('/\r?\n/', (string) ($session['content'] ?? '')) ?: [],
            static fn(string $l): bool => trim($l) !== ''
        )), 0, 18);

        $body = '';
        $y = 150;
        foreach ($lines as $line) {
            $body .= '<text x="40" y="' . $y . '" font-family="monospace" font-size="14" fill="#c9d1d9">'
                . $esc(substr(trim($line), 0, 96)) . '</text>';
            $y += 24;
        }

        return '<?xml version="1.0" encoding="UTF-8"?>'
            . '<svg xmlns="http://www.w3.org/2000/svg" width="1280" height="800" viewBox="0 0 1280 800">'
            . '<rect width="1280" height="800" fill="#0d1117"/>'
            . '<rect x="0" y="0" width="1280" height="90" fill="#161b22"/>'
            . '<circle cx="30" cy="30" r="8" fill="#ff5f56"/><circle cx="56" cy="30" r="8" fill="#ffbd2e"/>'
            . '<circle cx="82" cy="30" r="8" fill="#27c93f"/>'
            . '<rect x="110" y="16" width="1140" height="28" rx="14" fill="#0d1117"/>'
            . '<text x="126" y="35" font-family="monospace" font-size="14" fill="#58a6ff">' . $url . '</text>'
            . '<text x="40" y="78" font-family="sans-serif" font-size="20" fill="#f0f6fc">' . $title . '</text>'
            . $body
            . '<text x="40" y="780" font-family="sans-serif" font-size="12" fill="#8b949e">'
            . 'Synthetic wireframe — install Playwright for real screenshots</text>'
            . '</svg>';
    }
}

/* ==========================================================================
 * FILE: HttpClient.php
 * ========================================================================== */
/**
 * cURL based HTTP client — replacement for Python's httpx / the Workers fetch().
 *
 * Two things the Workers build could not do and this one can:
 *   - real forward proxies (CURLOPT_PROXY, incl. socks5) instead of only
 *     "?url=" gateway proxies;
 *   - reaching `localhost` services such as a local Ollama install.
 */

final class HttpClient
{
    public const DEFAULT_TIMEOUT = 120;

    /**
     * @param array<string,string> $headers
     * @return array{ok:bool, status:int, headers:array<string,string>, body:string, error:?string, latencyMs:float, effectiveUrl:string}
     */
    public static function request(
        string $method,
        string $url,
        array $headers = [],
        ?string $body = null,
        int $timeout = self::DEFAULT_TIMEOUT,
        ?string $proxy = null
    ): array {
        $started = microtime(true);
        if (!function_exists('curl_init')) {
            return self::failure($url, 'The cURL extension is not enabled on this host', $started);
        }

        $ch = curl_init();
        $responseHeaders = [];
        curl_setopt_array($ch, [
            CURLOPT_URL => $url,
            CURLOPT_CUSTOMREQUEST => strtoupper($method),
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_FOLLOWLOCATION => true,
            CURLOPT_MAXREDIRS => 5,
            CURLOPT_CONNECTTIMEOUT => min(30, $timeout),
            CURLOPT_TIMEOUT => $timeout,
            CURLOPT_HTTPHEADER => self::flattenHeaders($headers),
            CURLOPT_ENCODING => '',
            CURLOPT_SSL_VERIFYPEER => !Config::rawBool('AGENT_INSECURE_TLS', false),
            CURLOPT_SSL_VERIFYHOST => Config::rawBool('AGENT_INSECURE_TLS', false) ? 0 : 2,
            CURLOPT_USERAGENT => 'ArenaCodingAgent-PHP/' . APP_VERSION,
            CURLOPT_HEADERFUNCTION => static function ($_ch, string $line) use (&$responseHeaders): int {
                $len = strlen($line);
                $parts = explode(':', $line, 2);
                if (count($parts) === 2) {
                    $responseHeaders[strtolower(trim($parts[0]))] = trim($parts[1]);
                }
                return $len;
            },
        ]);
        if ($body !== null && $body !== '') {
            curl_setopt($ch, CURLOPT_POSTFIELDS, $body);
        }
        if ($proxy !== null && $proxy !== '') {
            curl_setopt($ch, CURLOPT_PROXY, $proxy);
            if (str_starts_with(strtolower($proxy), 'socks5h://')) {
                curl_setopt($ch, CURLOPT_PROXYTYPE, CURLPROXY_SOCKS5_HOSTNAME);
            } elseif (str_starts_with(strtolower($proxy), 'socks5://')) {
                curl_setopt($ch, CURLOPT_PROXYTYPE, CURLPROXY_SOCKS5);
            } elseif (str_starts_with(strtolower($proxy), 'socks4')) {
                curl_setopt($ch, CURLOPT_PROXYTYPE, CURLPROXY_SOCKS4);
            }
        }

        $responseBody = curl_exec($ch);
        $status = (int) curl_getinfo($ch, CURLINFO_RESPONSE_CODE);
        $effective = (string) (curl_getinfo($ch, CURLINFO_EFFECTIVE_URL) ?: $url);
        $error = curl_errno($ch) !== 0 ? curl_error($ch) : null;
        curl_close($ch);

        return [
            'ok' => $error === null && $status >= 200 && $status < 300,
            'status' => $status,
            'headers' => $responseHeaders,
            'body' => is_string($responseBody) ? $responseBody : '',
            'error' => $error,
            'latencyMs' => round((microtime(true) - $started) * 1000, 1),
            'effectiveUrl' => $effective,
        ];
    }

    public static function getJson(string $url, array $headers = [], int $timeout = 30, ?string $proxy = null): array
    {
        $r = self::request('GET', $url, $headers, null, $timeout, $proxy);
        $r['json'] = json_decode($r['body'], true);
        return $r;
    }

    public static function postJson(string $url, array $payload, array $headers = [], int $timeout = self::DEFAULT_TIMEOUT, ?string $proxy = null): array
    {
        $headers['Content-Type'] = 'application/json';
        $r = self::request('POST', $url, $headers, (string) json_encode($payload, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES), $timeout, $proxy);
        $r['json'] = json_decode($r['body'], true);
        return $r;
    }

    /**
     * Streaming POST. `$onChunk(string $chunk): bool` — return false to abort.
     * Used for SSE token streaming from the LLM providers.
     *
     * @return array{ok:bool, status:int, error:?string, latencyMs:float, aborted:bool}
     */
    public static function stream(
        string $url,
        array $headers,
        string $body,
        callable $onChunk,
        int $timeout = 600,
        ?string $proxy = null,
        string $method = 'POST'
    ): array {
        $started = microtime(true);
        if (!function_exists('curl_init')) {
            return ['ok' => false, 'status' => 0, 'error' => 'The cURL extension is not enabled on this host', 'latencyMs' => 0.0, 'aborted' => false];
        }
        $aborted = false;
        $ch = curl_init();
        curl_setopt_array($ch, [
            CURLOPT_URL => $url,
            CURLOPT_CUSTOMREQUEST => strtoupper($method),
            CURLOPT_RETURNTRANSFER => false,
            CURLOPT_FOLLOWLOCATION => true,
            CURLOPT_CONNECTTIMEOUT => 30,
            CURLOPT_TIMEOUT => $timeout,
            CURLOPT_HTTPHEADER => self::flattenHeaders(array_merge(['Content-Type' => 'application/json', 'Accept' => 'text/event-stream'], $headers)),
            CURLOPT_POSTFIELDS => $body,
            CURLOPT_SSL_VERIFYPEER => !Config::rawBool('AGENT_INSECURE_TLS', false),
            CURLOPT_SSL_VERIFYHOST => Config::rawBool('AGENT_INSECURE_TLS', false) ? 0 : 2,
            CURLOPT_USERAGENT => 'ArenaCodingAgent-PHP/' . APP_VERSION,
            CURLOPT_WRITEFUNCTION => static function ($_ch, string $chunk) use ($onChunk, &$aborted): int {
                $len = strlen($chunk);
                if ($aborted) {
                    return 0;
                }
                $keepGoing = $onChunk($chunk);
                if ($keepGoing === false) {
                    $aborted = true;
                    return 0; // makes cURL abort the transfer
                }
                return $len;
            },
        ]);
        if ($proxy !== null && $proxy !== '') {
            curl_setopt($ch, CURLOPT_PROXY, $proxy);
        }

        curl_exec($ch);
        $status = (int) curl_getinfo($ch, CURLINFO_RESPONSE_CODE);
        $errno = curl_errno($ch);
        $error = ($errno !== 0 && !($aborted && $errno === CURLE_WRITE_ERROR)) ? curl_error($ch) : null;
        curl_close($ch);

        return [
            'ok' => $error === null && $status >= 200 && $status < 300,
            'status' => $status,
            'error' => $error,
            'latencyMs' => round((microtime(true) - $started) * 1000, 1),
            'aborted' => $aborted,
        ];
    }

    /** Download to disk (used by the workspace importer). */
    public static function download(string $url, string $destination, int $timeout = 300, ?string $proxy = null): array
    {
        Files::ensureDir(dirname($destination));
        $fh = fopen($destination, 'wb');
        if (!$fh) {
            throw new HttpError(500, 'Unable to open destination file');
        }
        $ch = curl_init();
        curl_setopt_array($ch, [
            CURLOPT_URL => $url,
            CURLOPT_FILE => $fh,
            CURLOPT_FOLLOWLOCATION => true,
            CURLOPT_TIMEOUT => $timeout,
            CURLOPT_SSL_VERIFYPEER => true,
        ]);
        if ($proxy) {
            curl_setopt($ch, CURLOPT_PROXY, $proxy);
        }
        curl_exec($ch);
        $status = (int) curl_getinfo($ch, CURLINFO_RESPONSE_CODE);
        $error = curl_errno($ch) !== 0 ? curl_error($ch) : null;
        curl_close($ch);
        fclose($fh);
        return ['ok' => $error === null && $status < 400, 'status' => $status, 'error' => $error, 'path' => $destination];
    }

    private static function flattenHeaders(array $headers): array
    {
        $out = [];
        foreach ($headers as $k => $v) {
            if (is_int($k)) {
                $out[] = (string) $v;
            } else {
                $out[] = $k . ': ' . $v;
            }
        }
        return $out;
    }

    /** Parse an SSE buffer into complete `event/data` records. */
    public static function parseSseBuffer(string &$buffer): array
    {
        $events = [];
        while (($pos = strpos($buffer, "\n\n")) !== false || ($pos = strpos($buffer, "\r\n\r\n")) !== false) {
            $sep = substr($buffer, $pos, 2) === "\n\n" ? 2 : 4;
            $raw = substr($buffer, 0, $pos);
            $buffer = substr($buffer, $pos + $sep);
            $event = ['event' => 'message', 'data' => ''];
            foreach (preg_split('/\r?\n/', $raw) ?: [] as $line) {
                if (str_starts_with($line, 'data:')) {
                    $event['data'] .= ltrim(substr($line, 5));
                } elseif (str_starts_with($line, 'event:')) {
                    $event['event'] = trim(substr($line, 6));
                }
            }
            if ($event['data'] !== '') {
                $events[] = $event;
            }
        }
        return $events;
    }
}

/* ==========================================================================
 * FILE: Providers.php
 * ========================================================================== */
/**
 * Provider catalog, API key rotation and the circuit breaker.
 * Port of agent-python/app/providers.py.
 *
 * The catalog lives in `data/providers.json` again (the Workers build had to
 * keep it in KV). The circuit-breaker state is persisted in `app_state` so it
 * survives across PHP processes — on Workers it was only per-isolate.
 */

final class CircuitBreaker
{
    public function __construct(
        public int $failureThreshold = 5,
        public int $recoveryTimeout = 60
    ) {
    }

    private function load(): array
    {
        $state = Database::stateJson('circuit_breaker', []);
        return is_array($state) ? $state : [];
    }

    private function store(array $state): void
    {
        Database::setStateJson('circuit_breaker', $state);
    }

    public function isTripped(string $providerId): bool
    {
        $state = $this->load();
        $entry = $state[$providerId] ?? null;
        if (!$entry) {
            return false;
        }
        $failures = (int) ($entry['failures'] ?? 0);
        $last = (float) ($entry['last'] ?? 0);
        if ($failures >= $this->failureThreshold) {
            return (microtime(true) - $last) <= $this->recoveryTimeout;
        }
        return false;
    }

    public function recordSuccess(string $providerId): void
    {
        $state = $this->load();
        $state[$providerId] = ['failures' => 0, 'last' => microtime(true)];
        $this->store($state);
    }

    public function recordFailure(string $providerId): void
    {
        $state = $this->load();
        $failures = (int) ($state[$providerId]['failures'] ?? 0) + 1;
        $state[$providerId] = ['failures' => $failures, 'last' => microtime(true)];
        $this->store($state);
    }

    public function reset(string $providerId = ''): void
    {
        if ($providerId === '') {
            $this->store([]);
            return;
        }
        $state = $this->load();
        unset($state[$providerId]);
        $this->store($state);
    }
}

final class ProviderStore
{
    /** @var array<string, array> */
    public array $data = [];
    private static ?self $instance = null;
    private static ?CircuitBreaker $breaker = null;

    public static function breaker(): CircuitBreaker
    {
        return self::$breaker ??= new CircuitBreaker();
    }

    public static function file(): string
    {
        $custom = Config::raw('PROVIDERS_FILE', '');
        if ($custom !== '' && is_file($custom)) {
            return $custom;
        }
        return Bootstrap::$dataDir . '/providers.json';
    }

    public static function load(): self
    {
        if (self::$instance !== null) {
            return self::$instance;
        }
        $store = new self();
        $raw = [];
        $file = self::file();
        if (is_file($file)) {
            $decoded = json_decode((string) file_get_contents($file), true);
            if (is_array($decoded)) {
                $raw = $decoded;
            }
        }
        foreach ($raw as $key => $value) {
            if (!is_array($value)) {
                continue;
            }
            try {
                $p = self::normalizeProvider($value, (string) $key);
                $store->data[$p['id']] = $p;
            } catch (\Throwable) {
                // skip malformed entries (same as a pydantic validation failure)
            }
        }
        self::$instance = $store;
        return $store;
    }

    public static function reload(): self
    {
        self::$instance = null;
        return self::load();
    }

    // -------------------------------------------------------- normalising

    /** Keys the agent understands on a model record; everything else is kept in `extra`. */
    private const MODEL_KEYS = [
        'id', 'name', 'toolCalling', 'vision', 'free', 'maxInputTokens', 'maxOutputTokens',
        'enabled', 'inputCostPer1M', 'outputCostPer1M', 'extra',
    ];

    public static function normalizeModel(array|string $raw): array
    {
        if (is_string($raw)) {
            $raw = ['id' => $raw];
        }

        // Foreign catalogs carry per-model bookkeeping (tested / available /
        // testDetails / nonChat / rateLimited / …). Dropping it would silently
        // destroy the user's data on the first save, so it is parked in
        // `extra` and re-exported verbatim.
        $extra = (array) ($raw['extra'] ?? []);
        foreach ($raw as $k => $v) {
            if (!in_array((string) $k, self::MODEL_KEYS, true)) {
                $extra[(string) $k] = $v;
            }
        }

        $id = trim((string) ($raw['id'] ?? $raw['model'] ?? $raw['model_id'] ?? $raw['modelId'] ?? $raw['slug'] ?? $raw['name'] ?? ''));
        $name = trim((string) ($raw['name'] ?? $raw['title'] ?? $raw['label'] ?? $raw['display_name'] ?? $raw['displayName'] ?? $id));
        if ($name === '') {
            $name = $id;
        }
        if ($id === '' && $name !== '') {
            $id = $name;
        }
        $enabled = !array_key_exists('enabled', $raw) || (bool) $raw['enabled'];
        // A model the source catalog marked as "not a chat model" must not end
        // up in the chat picker.
        if (!empty($raw['nonChat'])) {
            $enabled = false;
        }

        return [
            'id' => $id,
            'name' => $name,
            'toolCalling' => (bool) ($raw['toolCalling'] ?? $raw['tool_calling'] ?? $raw['function_calling'] ?? $raw['tools'] ?? false),
            'vision' => (bool) ($raw['vision'] ?? $raw['multimodal'] ?? false),
            'free' => (bool) ($raw['free'] ?? false),
            'maxInputTokens' => (int) ($raw['maxInputTokens'] ?? $raw['max_input_tokens'] ?? $raw['contextLength'] ?? $raw['context_length'] ?? 128000),
            'maxOutputTokens' => (int) ($raw['maxOutputTokens'] ?? $raw['max_output_tokens'] ?? $raw['max_tokens'] ?? 8192),
            'enabled' => $enabled,
            'inputCostPer1M' => (float) ($raw['inputCostPer1M'] ?? $raw['input_cost_per_1m'] ?? 0),
            'outputCostPer1M' => (float) ($raw['outputCostPer1M'] ?? $raw['output_cost_per_1m'] ?? 0),
            'extra' => $extra,
        ];
    }

    /** Best-effort protocol sniffing for catalogs that omit the field. */
    private static function guessProtocol(string $id, string $vendor, string $url): string
    {
        $hay = strtolower($id . ' ' . $vendor . ' ' . $url);
        foreach ([
            'ollama' => 'ollama',
            'anthropic' => 'anthropic',
            'claude' => 'anthropic',
            'generativelanguage' => 'gemini',
            'gemini' => 'gemini',
            'mistral' => 'mistral',
            'azure' => 'azure',
            'cloudflare' => 'cloudflare',
            'workers-ai' => 'cloudflare',
        ] as $needle => $protocol) {
            if (str_contains($hay, $needle)) {
                return $protocol;
            }
        }
        return 'openai-compatible';
    }

    public static function normalizeProvider(array $raw, string $fallbackId = ''): array
    {
        $id = trim((string) ($raw['id'] ?? $raw['slug'] ?? $fallbackId));
        if ($id === '') {
            $id = trim((string) ($raw['name'] ?? ''));
        }
        $id = strtolower((string) preg_replace('/[^A-Za-z0-9._-]+/', '-', $id));
        $id = trim($id, '-');
        if ($id === '') {
            throw new \InvalidArgumentException('Provider is missing an "id" (and no usable name to derive one from)');
        }
        $models = [];
        foreach ((array) ($raw['models'] ?? []) as $m) {
            if (!is_array($m) && !is_string($m)) {
                continue;
            }
            $model = self::normalizeModel($m);
            if ($model['id'] !== '') {
                $models[] = $model;
            }
        }
        $vendor = (string) ($raw['vendor'] ?? 'custom');
        $url = (string) ($raw['url'] ?? $raw['baseUrl'] ?? $raw['base_url'] ?? $raw['endpoint'] ?? '');

        $rawApiKeys = $raw['apiKeys'] ?? $raw['api_keys'] ?? [];
        $apiKeys = [];
        if (is_array($rawApiKeys)) {
            foreach ($rawApiKeys as $k => $v) {
                if (is_string($v) && trim($v) !== '') {
                    $apiKeys[] = trim($v);
                } elseif (is_array($v)) {
                    $candidate = (string) ($v['key'] ?? $v['apiKey'] ?? $v['api_key'] ?? $v['value'] ?? '');
                    if (trim($candidate) !== '') {
                        $apiKeys[] = trim($candidate);
                    }
                }
            }
        } elseif (is_string($rawApiKeys) && trim($rawApiKeys) !== '') {
            $apiKeys = array_values(array_filter(array_map('trim', preg_split('/[\r\n,]+/', $rawApiKeys))));
        }

        $singleKey = (string) ($raw['apiKey'] ?? $raw['api_key'] ?? '');
        if ($singleKey !== '' && !in_array($singleKey, $apiKeys, true)) {
            array_unshift($apiKeys, $singleKey);
        }

        return [
            'id' => $id,
            'name' => (string) ($raw['name'] ?? $id),
            'vendor' => $vendor,
            'url' => $url,
            'protocol' => (string) ($raw['protocol'] ?? self::guessProtocol($id, $vendor, $url)),
            'enabled' => (bool) ($raw['enabled'] ?? false),
            'apiKey' => $singleKey ?: ($apiKeys[0] ?? ''),
            'apiKeys' => array_values(array_unique($apiKeys)),
            'apiKeyEnv' => (string) ($raw['apiKeyEnv'] ?? ''),
            'proxyUrl' => (string) ($raw['proxyUrl'] ?? ''),
            'priority' => (int) ($raw['priority'] ?? 1),
            'timeoutSec' => (int) ($raw['timeoutSec'] ?? 120),
            'models' => $models,
            'extra' => (array) ($raw['extra'] ?? []),
        ];
    }

    // -------------------------------------------------------------- store

    /**
     * Fail with an actionable message *before* writing.
     *
     * Bootstrap turns every PHP warning into an ErrorException, so an
     * unwritable data directory used to surface as an opaque 400 in the UI.
     */
    private static function assertWritable(string $file): void
    {
        $dir = dirname($file);
        if (!is_dir($dir)) {
            throw new HttpError(500, 'The data directory ' . $dir . ' does not exist and could not be created.');
        }
        if (!is_writable($dir)) {
            throw new HttpError(500, 'The data directory ' . $dir . ' is not writable by the PHP user ('
                . (function_exists('posix_getpwuid') && function_exists('posix_geteuid')
                    ? (posix_getpwuid(posix_geteuid())['name'] ?? '?')
                    : (get_current_user() ?: '?'))
                . '). Fix it with: chmod -R 775 ' . $dir);
        }
        if (is_file($file) && !is_writable($file)) {
            throw new HttpError(500, 'The catalog file ' . $file . ' is not writable. Fix it with: chmod 664 ' . $file);
        }
    }

    public function save(): void
    {
        $dump = [];
        foreach ($this->data as $k => $v) {
            $d = $v;
            if (!empty($d['apiKey']) && !str_starts_with((string) $d['apiKey'], 'enc:')) {
                $d['apiKey'] = Crypto::encrypt((string) $d['apiKey']);
            }
            if (!empty($d['apiKeys'])) {
                $d['apiKeys'] = array_map(
                    static fn(string $key): string => str_starts_with($key, 'enc:') ? $key : Crypto::encrypt($key),
                    $d['apiKeys']
                );
            }
            $dump[$k] = $d;
        }
        $file = self::file();
        Files::ensureDir(dirname($file));
        self::assertWritable($file);

        $encoded = json_encode($dump, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
        if ($encoded === false) {
            throw new HttpError(500, 'The provider catalog could not be encoded as JSON: ' . json_last_error_msg()
                . ' (a model field probably contains invalid UTF-8).');
        }
        if (@file_put_contents($file . '.tmp', $encoded) === false) {
            throw new HttpError(500, 'Could not write ' . $file . '.tmp — check the permissions on '
                . dirname($file) . ' (the PHP user must own it).');
        }
        @chmod($file . '.tmp', 0600);
        if (!@rename($file . '.tmp', $file)) {
            @unlink($file . '.tmp');
            throw new HttpError(500, 'Could not replace ' . $file . ' — the file exists but is not writable '
                . 'by the PHP user. Fix it with: chmod 664 ' . $file);
        }
    }

    public function get(string $id): ?array
    {
        return $this->data[$id] ?? null;
    }

    public function require(string $id): array
    {
        $p = $this->get($id);
        if ($p === null) {
            throw new HttpError(404, "Provider '{$id}' not found");
        }
        return $p;
    }

    /** Port of ProviderStore.get_api_key, with round-robin rotation. */
    public function apiKey(array $p): string
    {
        $keys = $p['apiKeys'] ?? [];
        if ($keys) {
            $stateKey = 'keyidx:' . $p['id'];
            $idx = (int) (Database::state($stateKey, '0') ?? '0');
            $raw = (string) $keys[$idx % count($keys)];
            Database::setState($stateKey, (string) (($idx + 1) % max(1, count($keys))));
            return str_starts_with($raw, 'enc:') ? Crypto::decrypt($raw) : $raw;
        }
        if (!empty($p['apiKey'])) {
            $v = (string) $p['apiKey'];
            return str_starts_with($v, 'enc:') ? Crypto::decrypt($v) : $v;
        }
        if (!empty($p['apiKeyEnv'])) {
            $val = Config::raw((string) $p['apiKeyEnv'], '');
            if ($val !== '') {
                return $val;
            }
        }
        $guess = strtoupper((string) preg_replace('/[^A-Za-z0-9]/', '_', (string) $p['id'])) . '_API_KEY';
        return Config::raw($guess, '');
    }

    public function publicView(array $p): array
    {
        $key = $this->apiKey($p);
        $out = $p;
        $out['hasApiKey'] = $key !== '';
        $out['apiKey'] = !empty($p['apiKey']) ? Crypto::maskKey(
            str_starts_with((string) $p['apiKey'], 'enc:') ? Crypto::decrypt((string) $p['apiKey']) : (string) $p['apiKey']
        ) : '';
        $out['apiKeys'] = array_map(
            static fn(string $k): string => Crypto::maskKey(str_starts_with($k, 'enc:') ? Crypto::decrypt($k) : $k),
            (array) ($p['apiKeys'] ?? [])
        );
        $out['circuitBreakerTripped'] = self::breaker()->isTripped((string) $p['id']);
        return $out;
    }

    public function allPublic(): array
    {
        $list = array_values($this->data);
        usort($list, static fn(array $a, array $b): int => ($b['priority'] ?? 1) <=> ($a['priority'] ?? 1));
        return array_map(fn(array $p): array => $this->publicView($p), $list);
    }

    public function upsert(array $p): array
    {
        $p = self::normalizeProvider($p);
        $existing = $this->data[$p['id']] ?? null;
        if ($existing !== null) {
            if (empty($p['apiKey']) || str_contains((string) $p['apiKey'], '••••')) {
                $p['apiKey'] = $existing['apiKey'];
            }
            if (empty($p['apiKeys'])) {
                $p['apiKeys'] = $existing['apiKeys'];
            }
        }
        $this->data[$p['id']] = $p;
        $this->save();
        return $this->publicView($p);
    }

    public function delete(string $pid): void
    {
        unset($this->data[$pid]);
        $this->save();
    }

    public function addModel(string $pid, array $model): void
    {
        if (!isset($this->data[$pid])) {
            throw new HttpError(404, 'Provider not found');
        }
        $this->data[$pid]['models'][] = self::normalizeModel($model);
        $this->save();
    }

    public function updateModel(string $pid, string $mid, array $model): void
    {
        if (!isset($this->data[$pid])) {
            throw new HttpError(404, 'Provider not found');
        }
        $normalized = self::normalizeModel($model);
        $this->data[$pid]['models'] = array_map(
            static fn(array $m): array => $m['id'] === $mid ? $normalized : $m,
            $this->data[$pid]['models']
        );
        $this->save();
    }

    public function deleteModel(string $pid, string $mid): void
    {
        if (!isset($this->data[$pid])) {
            throw new HttpError(404, 'Provider not found');
        }
        $this->data[$pid]['models'] = array_values(array_filter(
            $this->data[$pid]['models'],
            static fn(array $m): bool => $m['id'] !== $mid
        ));
        $this->save();
    }

    public function findModel(array $provider, string $modelId): array
    {
        foreach ($provider['models'] as $m) {
            if ($m['id'] === $modelId) {
                return $m;
            }
        }
        return self::normalizeModel(['id' => $modelId, 'name' => $modelId, 'toolCalling' => true]);
    }

    /** Port of ProviderStore.record_metric. */
    public function recordMetric(string $providerId, string $modelId, float $latencyMs, bool $isError, int $tokens = 0): void
    {
        if ($isError) {
            self::breaker()->recordFailure($providerId);
        } else {
            self::breaker()->recordSuccess($providerId);
        }
        Observability::recordProviderCall($providerId, $modelId, !$isError, $latencyMs, $tokens);
        try {
            Database::run(
                'UPDATE provider_metrics SET circuit_breaker_tripped = ? WHERE provider_id = ? AND model_id = ?',
                [self::breaker()->isTripped($providerId) ? 1 : 0, $providerId, $modelId]
            );
        } catch (\Throwable) {
        }
    }

    /**
     * Port of ProviderStore.get_verified_fallback_candidates.
     * @return array<int, array{0:array,1:array}>
     */
    public function verifiedFallbackCandidates(
        ?string $excludeProviderId = null,
        ?string $excludeModelId = null,
        bool $preferDifferentProvider = false
    ): array {
        $out = [];
        $seen = [];
        try {
            $rows = Database::all(
                "SELECT provider_id, model_id, last_latency_ms FROM provider_metrics
                 WHERE last_status = 'ok' ORDER BY last_latency_ms ASC, updated_at DESC"
            );
        } catch (\Throwable) {
            $rows = [];
        }
        foreach ($rows as $row) {
            $pid = (string) $row['provider_id'];
            $mid = (string) $row['model_id'];
            if ($pid === $excludeProviderId && $mid === $excludeModelId) {
                continue;
            }
            $key = $pid . '::' . $mid;
            if (isset($seen[$key])) {
                continue;
            }
            $provider = $this->get($pid);
            if ($provider === null || !$provider['enabled'] || self::breaker()->isTripped($pid)) {
                continue;
            }
            $apiKey = $this->apiKey($provider);
            if ($apiKey === '' && !in_array($provider['protocol'], ['ollama', 'workers-ai'], true)) {
                continue;
            }
            $out[] = [$provider, $this->findModel($provider, $mid)];
            $seen[$key] = true;
        }

        // Providers that have never been measured yet are still valid fallbacks.
        foreach ($this->data as $provider) {
            if (!$provider['enabled'] || self::breaker()->isTripped((string) $provider['id'])) {
                continue;
            }
            $apiKey = $this->apiKey($provider);
            if ($apiKey === '' && !in_array($provider['protocol'], ['ollama', 'workers-ai'], true)) {
                continue;
            }
            foreach ($provider['models'] as $m) {
                if (!($m['enabled'] ?? true)) {
                    continue;
                }
                if ($provider['id'] === $excludeProviderId && $m['id'] === $excludeModelId) {
                    continue;
                }
                $key = $provider['id'] . '::' . $m['id'];
                if (isset($seen[$key])) {
                    continue;
                }
                $out[] = [$provider, $m];
                $seen[$key] = true;
            }
        }

        if ($preferDifferentProvider && $excludeProviderId !== null) {
            usort($out, static function (array $a, array $b) use ($excludeProviderId): int {
                return (($a[0]['id'] !== $excludeProviderId) ? 0 : 1) <=> (($b[0]['id'] !== $excludeProviderId) ? 0 : 1);
            });
        }
        return $out;
    }

    public function exportJson(): string
    {
        $dump = [];
        foreach ($this->data as $k => $v) {
            $dump[$k] = array_merge($v, ['apiKey' => '', 'apiKeys' => []]);
        }
        return (string) json_encode($dump, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
    }

    /**
     * Tolerant provider import.
     *
     * Real-world exports come in half a dozen shapes, so instead of demanding
     * one canonical layout we sniff the payload and accept all of these:
     *
     *   {"openrouter": {...}, "ollama": {...}}      object keyed by provider id
     *   [{"id": "openrouter", ...}, ...]            list of providers
     *   {"providers": <either of the above>}        wrapped (also data/result/config)
     *   {"id": "openrouter", "models": [...]}       one single provider
     *   {"version": 3, "providers": {...}}          export envelope with metadata
     *
     * Unknown per-model keys (`tested`, `available`, `testDetails`, `nonChat`,
     * …) are not thrown away: they are folded into `model.extra` so a catalog
     * exported from another tool survives the round trip untouched.
     *
     * @return array{providers:int,models:int,created:string[],updated:string[],skipped:array<int,array{key:string,reason:string}>}
     */
    public function importJson(string $text, bool $replace = false): array
    {
        $raw = self::decodeImport($text);
        $entries = self::collectProviderEntries($raw);

        if (!$entries) {
            // Check if payload was actually a list of models without provider envelope
            if (!empty($this->data)) {
                $targetPid = array_key_first($this->data);
                try {
                    $mRes = $this->importModelsForProvider($targetPid, $text, $replace);
                    return [
                        'providers' => count($this->data),
                        'models' => $mRes['modelsCount'],
                        'created' => [],
                        'updated' => [$targetPid],
                        'skipped' => [],
                    ];
                } catch (\Throwable) {}
            }
            throw new HttpError(400, self::importHint($raw));
        }

        $parsed = [];
        $skipped = [];
        $created = [];
        $updated = [];
        $modelCount = 0;

        foreach ($entries as [$key, $value]) {
            try {
                $p = self::normalizeProvider($value, $key);
            } catch (\Throwable $e) {
                $skipped[] = ['key' => $key, 'reason' => $e->getMessage()];
                continue;
            }
            $existing = $replace ? null : ($this->data[$p['id']] ?? null);
            $merged = $existing !== null ? self::mergeProvider($existing, $p, $value) : $p;
            $parsed[$p['id']] = $merged;
            $modelCount += count($merged['models']);
            if ($existing !== null) {
                $updated[] = $p['id'];
            } else {
                $created[] = $p['id'];
            }
        }

        if (!$parsed) {
            throw new HttpError(400, 'No importable provider was found. ' . ($skipped[0]['reason'] ?? ''));
        }

        $this->data = $replace ? $parsed : array_merge($this->data, $parsed);
        $this->save();

        return [
            'providers' => count($parsed),
            'models' => $modelCount,
            'created' => $created,
            'updated' => $updated,
            'skipped' => $skipped,
        ];
    }

    /** Import models into a specific provider (auto-creates provider if not already present). */
    public function importModelsForProvider(string $providerId, string $text, bool $replace = false): array
    {
        if (!isset($this->data[$providerId])) {
            $name = ucwords(str_replace(['-', '_'], ' ', $providerId));
            $url = $providerId === 'ollama' ? 'http://localhost:11434' : ($providerId === 'anthropic' ? 'https://api.anthropic.com' : 'https://api.openai.com/v1');
            $protocol = $providerId === 'ollama' ? 'ollama' : ($providerId === 'anthropic' ? 'anthropic' : 'openai-compatible');
            $this->data[$providerId] = [
                'id' => $providerId,
                'name' => $name,
                'url' => $url,
                'protocol' => $protocol,
                'enabled' => true,
                'models' => [],
                'apiKeys' => [],
                'extra' => [],
            ];
        }
        $raw = self::decodeImport($text);
        $models = [];
        $candidates = [];
        if (is_array($raw)) {
            // Check if specific provider key exists in raw
            if (isset($raw[$providerId]) && is_array($raw[$providerId]) && isset($raw[$providerId]['models']) && is_array($raw[$providerId]['models'])) {
                $candidates = $raw[$providerId]['models'];
            } elseif (isset($raw['data']) && is_array($raw['data'])) {
                $candidates = $raw['data'];
            } elseif (isset($raw['models']) && is_array($raw['models'])) {
                $candidates = $raw['models'];
            } elseif (isset($raw['items']) && is_array($raw['items'])) {
                $candidates = $raw['items'];
            } elseif (isset($raw['options']) && is_array($raw['options'])) {
                $candidates = $raw['options'];
            } elseif (isset($raw['results']) && is_array($raw['results'])) {
                $candidates = $raw['results'];
            } elseif (array_is_list($raw)) {
                $candidates = $raw;
            } else {
                // Check if any sub-key has models (e.g. user pasted full catalog to single provider importer)
                $foundSubModels = [];
                foreach ($raw as $k => $v) {
                    if (is_array($v) && isset($v['models']) && is_array($v['models'])) {
                        foreach ($v['models'] as $sm) {
                            $foundSubModels[] = $sm;
                        }
                    }
                }
                if (!empty($foundSubModels)) {
                    $candidates = $foundSubModels;
                } else {
                    // Check if dict mapping model_id -> spec
                    $isMap = true;
                    foreach ($raw as $k => $v) {
                        if (!is_array($v) && !is_string($v)) { $isMap = false; break; }
                    }
                    if ($isMap && !isset($raw['url']) && !isset($raw['baseUrl'])) {
                        $candidates = [];
                        foreach ($raw as $k => $v) {
                            $candidates[] = is_array($v) ? array_merge(['id' => (string) $k], $v) : ['id' => (string) $k, 'name' => (string) $v];
                        }
                    } else {
                        $candidates = [$raw];
                    }
                }
            }
        }
        foreach ($candidates as $m) {
            if (is_string($m) && trim($m) !== '') {
                $models[] = self::normalizeModel(['id' => trim($m), 'name' => trim($m)]);
            } elseif (is_array($m)) {
                $norm = self::normalizeModel($m);
                if ($norm['id'] !== '') {
                    $models[] = $norm;
                }
            }
        }
        if (empty($models)) {
            throw new HttpError(400, 'No valid models found in the import payload.');
        }

        $existing = $this->data[$providerId];
        $byId = [];
        if (!$replace) {
            foreach ((array) ($existing['models'] ?? []) as $em) {
                if (is_array($em) && ($em['id'] ?? '') !== '') {
                    $byId[(string) $em['id']] = $em;
                }
            }
        }
        $added = 0;
        $updated = 0;
        foreach ($models as $nm) {
            $mid = (string) $nm['id'];
            if (isset($byId[$mid])) {
                $byId[$mid] = array_merge($byId[$mid], $nm, [
                    'extra' => array_merge((array) ($byId[$mid]['extra'] ?? []), (array) ($nm['extra'] ?? [])),
                ]);
                $updated++;
            } else {
                $byId[$mid] = $nm;
                $added++;
            }
        }
        $this->data[$providerId]['models'] = array_values($byId);
        $this->save();

        return [
            'ok' => true,
            'provider' => $providerId,
            'modelsCount' => count($this->data[$providerId]['models']),
            'added' => $added,
            'updated' => $updated,
            'replace' => $replace,
        ];
    }

    /** json_decode with tolerant error recovery for truncated/unclosed pastes. */
    public static function decodeImport(string $text): mixed
    {
        $text = trim($text);
        if ($text === '') {
            throw new HttpError(
                400,
                'The import payload was empty. If you pasted a large catalog, the web server may have '
                . 'dropped the request body: raise post_max_size / upload_max_filesize, or import from the '
                . 'CLI with "php bin/console.php provider:import <file>".'
            );
        }

        // Tolerate a UTF-8 BOM, smart quotes, and markdown code block wrappers
        $text = preg_replace('/^\xEF\xBB\xBF/', '', $text) ?? $text;
        if (str_starts_with($text, '```')) {
            $lines = explode("\n", $text);
            if (!empty($lines) && str_starts_with(trim($lines[0]), '```')) {
                array_shift($lines);
            }
            if (!empty($lines) && str_starts_with(trim(end($lines)), '```')) {
                array_pop($lines);
            }
            $text = trim(implode("\n", $lines));
        }
        $text = str_replace(["\u{201C}", "\u{201D}", "\u{2018}", "\u{2019}", "«", "»", "„"], ['"', '"', "'", "'", '"', '"', '"'], $text);

        $decoded = json_decode($text, true);
        if (json_last_error() === JSON_ERROR_NONE && $decoded !== null) {
            return $decoded;
        }
        $relaxed = preg_replace('/,\s*([}\]])/', '$1', $text);
        if (is_string($relaxed)) {
            $decoded = json_decode($relaxed, true);
            if (json_last_error() === JSON_ERROR_NONE && $decoded !== null) {
                return $decoded;
            }
        }

        // Auto-repair truncated / cut-off JSON
        $repaired = self::repairTruncatedJson($text);
        if ($repaired !== null) {
            return $repaired;
        }

        // Plain line-by-line model list fallback (e.g. pasted model IDs, or plain text list)
        $lines = preg_split('/[\r\n]+/', $text);
        $plainModels = [];
        foreach ($lines as $line) {
            $line = trim($line, " \t\r\n,;\"'");
            if ($line === '' || str_starts_with($line, '#') || str_starts_with($line, '//')) {
                continue;
            }
            $plainModels[] = ['id' => $line, 'name' => $line];
        }
        if (!empty($plainModels)) {
            return ['models' => $plainModels];
        }

        $len = strlen($text);
        $tail = substr($text, -60);
        throw new HttpError(
            400,
            'The text could not be parsed as JSON or a list of models (' . json_last_error_msg() . '). Length ' . $len
            . ' bytes, ends with: ' . $tail
            . ' — a truncated paste is the usual cause; upload the file instead of pasting it.'
        );
    }

    public static function repairTruncatedJson(string $text): mixed
    {
        $t = trim($text);
        $len = strlen($t);
        if ($len < 2) return null;

        $inString = false;
        $escape = false;
        $stack = [];

        for ($i = 0; $i < $len; $i++) {
            $ch = $t[$i];
            if ($escape) {
                $escape = false;
                continue;
            }
            if ($ch === '\\') {
                $escape = true;
                continue;
            }
            if ($ch === '"') {
                $inString = !$inString;
                continue;
            }
            if (!$inString) {
                if ($ch === '{' || $ch === '[') {
                    $stack[] = $ch;
                } elseif ($ch === '}') {
                    if (!empty($stack) && end($stack) === '{') array_pop($stack);
                } elseif ($ch === ']') {
                    if (!empty($stack) && end($stack) === '[') array_pop($stack);
                }
            }
        }

        $repaired = $t;
        if ($inString) {
            $repaired .= '"';
        }

        $repaired = preg_replace('/,\s*$/', '', $repaired) ?? $repaired;
        $repaired = preg_replace('/:\s*$/', ': null', $repaired) ?? $repaired;
        $repaired = preg_replace('/,\s*([}\]])/', '$1', $repaired) ?? $repaired;

        while (!empty($stack)) {
            $open = array_pop($stack);
            $repaired = preg_replace('/,\s*$/', '', $repaired) ?? $repaired;
            if ($open === '{') {
                if (preg_match('/"[^"]+"\s*:\s*$/', $repaired)) {
                    $repaired .= 'null';
                }
                $repaired .= '}';
            } elseif ($open === '[') {
                $repaired .= ']';
            }
        }

        $decoded = json_decode($repaired, true);
        if (json_last_error() === JSON_ERROR_NONE && $decoded !== null) {
            return $decoded;
        }

        $lastComma = strrpos($t, ',');
        if ($lastComma !== false && $lastComma > 10) {
            return self::repairTruncatedJson(substr($t, 0, $lastComma));
        }

        return null;
    }

    /**
     * Reduce any accepted wrapper to a list of [key, providerArray] pairs.
     *
     * @return array<int, array{0:string,1:array}>
     */
    private static function collectProviderEntries(mixed $raw, int $depth = 0): array
    {
        if (!is_array($raw) || $depth > 3) {
            return [];
        }

        // A single provider object.
        if (self::looksLikeProvider($raw)) {
            return [[(string) ($raw['id'] ?? ''), $raw]];
        }

        // A list: either of providers, or of [key => provider] singletons.
        if (array_is_list($raw)) {
            $out = [];
            foreach ($raw as $item) {
                if (!is_array($item)) {
                    continue;
                }
                if (self::looksLikeProvider($item)) {
                    $out[] = [(string) ($item['id'] ?? ''), $item];
                    continue;
                }
                foreach (self::collectProviderEntries($item, $depth + 1) as $nested) {
                    $out[] = $nested;
                }
            }
            return $out;
        }

        // An object keyed by provider id.
        $out = [];
        $wrappers = [];
        foreach ($raw as $k => $v) {
            if (!is_array($v)) {
                continue; // metadata such as "version" / "exportedAt"
            }
            if (self::looksLikeProvider($v)) {
                $out[] = [(string) $k, $v];
            } elseif (in_array((string) $k, ['providers', 'data', 'result', 'config', 'catalog', 'items'], true)) {
                $wrappers[] = $v;
            }
        }
        if ($out) {
            return $out;
        }
        foreach ($wrappers as $w) {
            foreach (self::collectProviderEntries($w, $depth + 1) as $nested) {
                $out[] = $nested;
            }
        }
        return $out;
    }

    /** Heuristic: does this associative array describe a provider? */
    private static function looksLikeProvider(array $v): bool
    {
        if (array_is_list($v)) {
            return false;
        }
        foreach (['models', 'url', 'baseUrl', 'base_url', 'protocol', 'apiKey', 'api_key', 'vendor'] as $marker) {
            if (array_key_exists($marker, $v)) {
                return true;
            }
        }
        // If it contains model-specific fields, it is a model spec, not a provider
        foreach (['maxInputTokens', 'max_input_tokens', 'maxOutputTokens', 'max_output_tokens', 'toolCalling', 'tool_calling', 'vision', 'multimodal', 'contextLength', 'context_length'] as $marker) {
            if (array_key_exists($marker, $v)) {
                return false;
            }
        }
        return array_key_exists('id', $v) && array_key_exists('name', $v);
    }

    private static function importHint(mixed $raw): string
    {
        $type = get_debug_type($raw);
        if (is_array($raw)) {
            $keys = array_slice(array_map('strval', array_keys($raw)), 0, 8);
            return 'The JSON parsed correctly but contains no provider object. Top-level keys were: '
                . (count($keys) ? implode(', ', $keys) : '(empty)')
                . '. Expected {"openrouter": {"url": "...", "models": [...]}} , a list of providers, '
                . 'or {"providers": {...}}.';
        }
        return 'Expected a JSON object or array of providers, got ' . $type . '.';
    }

    /**
     * Merge an imported provider into an existing one without losing local
     * state: models are merged by id, and an empty incoming credential never
     * wipes a stored one.
     */
    private static function mergeProvider(array $existing, array $incoming, array $rawIncoming): array
    {
        $merged = array_merge($existing, $incoming);

        foreach (['apiKey', 'apiKeyEnv', 'proxyUrl', 'url'] as $k) {
            if (($incoming[$k] ?? '') === '' && ($existing[$k] ?? '') !== '') {
                $merged[$k] = $existing[$k];
            }
        }
        if (!($incoming['apiKeys'] ?? []) && ($existing['apiKeys'] ?? [])) {
            $merged['apiKeys'] = $existing['apiKeys'];
        }
        if (!array_key_exists('enabled', $rawIncoming)) {
            $merged['enabled'] = (bool) ($existing['enabled'] ?? false);
        }
        $merged['extra'] = array_merge((array) ($existing['extra'] ?? []), (array) ($incoming['extra'] ?? []));

        $byId = [];
        foreach ((array) ($existing['models'] ?? []) as $m) {
            if (is_array($m) && ($m['id'] ?? '') !== '') {
                $byId[(string) $m['id']] = $m;
            }
        }
        foreach ($incoming['models'] as $m) {
            $id = (string) ($m['id'] ?? '');
            if ($id === '') {
                continue;
            }
            $byId[$id] = isset($byId[$id])
                ? array_merge($byId[$id], $m, [
                    'extra' => array_merge((array) ($byId[$id]['extra'] ?? []), (array) ($m['extra'] ?? [])),
                ])
                : $m;
        }
        $merged['models'] = array_values($byId);

        return $merged;
    }
}

/* ==========================================================================
 * FILE: Models.php
 * ========================================================================== */
/**
 * Provider/model health tests and the proxy probe.
 * Port of the `/api/providers/{pid}/models/{mid}/test`, `/api/providers/test-all`
 * and `/api/config/test-proxy` engines from agent-python/app/main.py.
 *
 * The full diagnostic payload shape is preserved verbatim because the SPA
 * renders every field of it. Unlike the Workers build, a real forward proxy is
 * actually used when one is configured, and `localhost` providers (Ollama,
 * LM Studio, vLLM…) are reachable.
 */

final class Models
{
    public const TEST_PROMPT = 'Reply with the single word: OK';

    public static function maskHeaders(array $headers): array
    {
        $out = [];
        foreach ($headers as $k => $v) {
            $lk = strtolower((string) $k);
            if (in_array($lk, ['authorization', 'x-api-key', 'api-key'], true)) {
                $raw = (string) preg_replace('/^Bearer\s+/i', '', (string) $v);
                $out[$k] = strlen($raw) <= 8
                    ? '••••••••'
                    : ($lk === 'authorization' ? 'Bearer ' : '') . substr($raw, 0, 3) . '••••••••' . substr($raw, -4);
            } else {
                $out[$k] = $v;
            }
        }
        return $out;
    }

    public static function nowIso(): string
    {
        return gmdate('Y-m-d\TH:i:s.000\Z');
    }

    /** @return array{url:string, headers:array, body:array} */
    public static function buildTestRequest(array $provider, array $model, string $apiKey): array
    {
        $base = rtrim((string) $provider['url'], '/');
        $headers = ['Content-Type' => 'application/json'];

        if ($provider['protocol'] === 'anthropic') {
            $headers['x-api-key'] = $apiKey;
            $headers['anthropic-version'] = '2023-06-01';
            return [
                'url' => str_ends_with($base, '/messages') ? $base : $base . '/v1/messages',
                'headers' => $headers,
                'body' => [
                    'model' => $model['id'],
                    'max_tokens' => 16,
                    'messages' => [['role' => 'user', 'content' => self::TEST_PROMPT]],
                ],
            ];
        }

        if ($provider['protocol'] === 'ollama') {
            return [
                'url' => str_ends_with($base, '/chat') ? $base : $base . '/api/chat',
                'headers' => $headers,
                'body' => [
                    'model' => $model['id'],
                    'messages' => [['role' => 'user', 'content' => self::TEST_PROMPT]],
                    'stream' => false,
                ],
            ];
        }

        if ($provider['protocol'] === 'gemini') {
            return [
                'url' => ($base !== '' ? $base : 'https://generativelanguage.googleapis.com/v1beta')
                    . '/models/' . $model['id'] . ':generateContent?key=' . rawurlencode($apiKey),
                'headers' => $headers,
                'body' => [
                    'contents' => [['role' => 'user', 'parts' => [['text' => self::TEST_PROMPT]]]],
                    'generationConfig' => ['maxOutputTokens' => 16],
                ],
            ];
        }

        if ($provider['protocol'] === 'azure') {
            $headers['api-key'] = $apiKey;
        } elseif ($apiKey !== '') {
            $headers['Authorization'] = 'Bearer ' . $apiKey;
        }

        return [
            'url' => str_ends_with($base, '/chat/completions') ? $base : $base . '/chat/completions',
            'headers' => $headers,
            'body' => [
                'model' => $model['id'],
                'messages' => [['role' => 'user', 'content' => self::TEST_PROMPT]],
                'max_tokens' => 16,
                'temperature' => 0,
            ],
        ];
    }

    /** @return array{text:string, reasoning:string} */
    public static function renderText(string $protocol, mixed $data): array
    {
        if (!is_array($data)) {
            return ['text' => '', 'reasoning' => ''];
        }
        if ($protocol === 'anthropic') {
            $text = '';
            $reasoning = '';
            foreach ((array) ($data['content'] ?? []) as $b) {
                if (($b['type'] ?? '') === 'text') {
                    $text .= (string) ($b['text'] ?? '');
                } elseif (($b['type'] ?? '') === 'thinking') {
                    $reasoning .= (string) ($b['thinking'] ?? '');
                }
            }
            return ['text' => $text, 'reasoning' => $reasoning];
        }
        if ($protocol === 'ollama') {
            return ['text' => (string) ($data['message']['content'] ?? ''), 'reasoning' => ''];
        }
        if ($protocol === 'gemini') {
            $text = '';
            foreach ((array) ($data['candidates'][0]['content']['parts'] ?? []) as $part) {
                $text .= (string) ($part['text'] ?? '');
            }
            return ['text' => $text, 'reasoning' => ''];
        }
        $msg = $data['choices'][0]['message'] ?? [];
        return [
            'text' => (string) ($msg['content'] ?? ''),
            'reasoning' => (string) ($msg['reasoning_content'] ?? $msg['reasoning'] ?? $msg['thought'] ?? ''),
        ];
    }

    public static function testProviderModel(ProviderStore $store, array $provider, array $model, float $readTimeoutSec = 15.0): array
    {
        $apiKey = $store->apiKey($provider);
        ['url' => $directEndpoint, 'headers' => $headers, 'body' => $body] =
            self::buildTestRequest($provider, $model, $apiKey);

        $isLocal = $provider['protocol'] === 'ollama'
            || str_contains($directEndpoint, '127.0.0.1')
            || str_contains($directEndpoint, 'localhost');

        $proxy = $isLocal
            ? ['effectiveUrl' => $directEndpoint, 'proxyClient' => null]
            : Config::proxyConfig($directEndpoint, $provider['proxyUrl'] ?: null);

        $proxyMode = $isLocal
            ? 'Direct (Local / Ollama)'
            : ($proxy['proxyClient']
                ? "Forward proxy '{$proxy['proxyClient']}' (cURL CURLOPT_PROXY)"
                : ($proxy['effectiveUrl'] !== $directEndpoint ? 'Gateway Proxy (URL rewrite)' : 'Direct'));

        $base = [
            'provider' => $provider['id'],
            'providerName' => $provider['name'],
            'model' => $model['id'],
            'modelName' => $model['name'],
            'protocol' => $provider['protocol'],
            'request' => [
                'method' => 'POST',
                'directEndpoint' => $directEndpoint,
                'effectiveEndpoint' => $proxy['effectiveUrl'],
                'proxyClient' => $proxy['proxyClient'],
                'isProxyActive' => $proxy['effectiveUrl'] !== $directEndpoint || (bool) $proxy['proxyClient'],
                'proxyMode' => $proxyMode,
                'headers' => self::maskHeaders($headers),
                'body' => $body,
            ],
            'timestamp' => self::nowIso(),
        ];

        if ($apiKey === '' && !in_array($provider['protocol'], ['ollama', 'workers-ai'], true)) {
            $envName = $provider['apiKeyEnv'] ?: strtoupper((string) $provider['id']) . '_API_KEY';
            return array_merge($base, [
                'ok' => false,
                'latencyMs' => 0,
                'error' => "No API key configured for provider '{$provider['name']}'.",
                'message' => 'Missing API key',
                'response' => [
                    'statusCode' => 401,
                    'renderedText' => '',
                    'reasoningContent' => '',
                    'rawJson' => null,
                    'rawError' => "Set it in Settings, or add {$envName}=… to the .env file.",
                ],
            ]);
        }

        $started = microtime(true);
        $attempts = [$proxy['effectiveUrl']];
        if ($proxy['effectiveUrl'] !== $directEndpoint) {
            $attempts[] = $directEndpoint;
        }

        $lastError = '';
        $lastStatus = 0;

        foreach ($attempts as $url) {
            $resp = HttpClient::postJson($url, $body, $headers, (int) ceil($readTimeoutSec), $proxy['proxyClient']);
            $latencyMs = (int) round((microtime(true) - $started) * 1000);
            $lastStatus = $resp['status'];
            $data = $resp['json'];

            if ($resp['ok']) {
                ['text' => $rendered, 'reasoning' => $reasoning] = self::renderText((string) $provider['protocol'], $data);
                $store->recordMetric((string) $provider['id'], (string) $model['id'], (float) $latencyMs, false);
                return array_merge($base, [
                    'ok' => true,
                    'latencyMs' => $latencyMs,
                    'message' => $rendered !== '' ? substr(trim($rendered), 0, 200) : 'Empty response body',
                    'response' => [
                        'statusCode' => $resp['status'],
                        'renderedText' => $rendered,
                        'reasoningContent' => $reasoning,
                        'rawJson' => $data,
                        'rawError' => null,
                    ],
                ]);
            }

            if (is_array($data)) {
                $err = $data['error']['message'] ?? $data['error'] ?? $data['message'] ?? null;
                $lastError = is_string($err) ? $err : substr((string) json_encode($err ?? $data), 0, 800);
            } else {
                $lastError = $resp['error'] ?? substr($resp['body'], 0, 800);
            }
        }

        $latencyMs = (int) round((microtime(true) - $started) * 1000);
        $store->recordMetric((string) $provider['id'], (string) $model['id'], (float) $latencyMs, true);
        return array_merge($base, [
            'ok' => false,
            'latencyMs' => $latencyMs,
            'error' => $lastError !== '' ? $lastError : 'Request failed',
            'message' => $lastError !== '' ? substr($lastError, 0, 200) : 'Request failed',
            'response' => [
                'statusCode' => $lastStatus,
                'renderedText' => '',
                'reasoningContent' => '',
                'rawJson' => null,
                'rawError' => $lastError,
            ],
        ]);
    }

    /**
     * Port of `/api/providers/test-all`. PHP has no event loop, so parallelism
     * comes from curl_multi: every enabled model is probed concurrently.
     */
    public static function testAllModels(ProviderStore $store, int $concurrency = 15, float $timeoutSec = 8.0): array
    {
        $tasks = [];
        foreach ($store->data as $p) {
            if (!$p['enabled']) {
                continue;
            }
            foreach ($p['models'] as $m) {
                $tasks[] = ['provider' => $p, 'model' => $m];
            }
        }
        if (!$tasks) {
            return [];
        }
        if (!function_exists('curl_multi_init')) {
            return array_map(
                fn(array $t): array => self::testProviderModel($store, $t['provider'], $t['model'], $timeoutSec),
                $tasks
            );
        }

        $results = [];
        foreach (array_chunk($tasks, max(1, $concurrency), true) as $chunk) {
            $multi = curl_multi_init();
            $handles = [];
            $meta = [];

            foreach ($chunk as $i => $task) {
                $provider = $task['provider'];
                $model = $task['model'];
                $apiKey = $store->apiKey($provider);
                ['url' => $direct, 'headers' => $headers, 'body' => $body] = self::buildTestRequest($provider, $model, $apiKey);

                $isLocal = $provider['protocol'] === 'ollama'
                    || str_contains($direct, '127.0.0.1') || str_contains($direct, 'localhost');
                $proxy = $isLocal
                    ? ['effectiveUrl' => $direct, 'proxyClient' => null]
                    : Config::proxyConfig($direct, $provider['proxyUrl'] ?: null);

                $meta[$i] = compact('provider', 'model', 'apiKey', 'direct', 'headers', 'body', 'proxy', 'isLocal');
                $meta[$i]['started'] = microtime(true);

                if ($apiKey === '' && !in_array($provider['protocol'], ['ollama', 'workers-ai'], true)) {
                    $results[$i] = self::testProviderModel($store, $provider, $model, $timeoutSec);
                    continue;
                }

                $ch = curl_init();
                curl_setopt_array($ch, [
                    CURLOPT_URL => $proxy['effectiveUrl'],
                    CURLOPT_POST => true,
                    CURLOPT_POSTFIELDS => json_encode($body, JSON_UNESCAPED_UNICODE),
                    CURLOPT_RETURNTRANSFER => true,
                    CURLOPT_HTTPHEADER => array_map(
                        static fn($k, $v): string => "$k: $v",
                        array_keys($headers),
                        array_values($headers)
                    ),
                    CURLOPT_TIMEOUT => (int) ceil($timeoutSec),
                    CURLOPT_CONNECTTIMEOUT => (int) ceil(min(5, $timeoutSec)),
                    CURLOPT_FOLLOWLOCATION => true,
                ]);
                if ($proxy['proxyClient']) {
                    curl_setopt($ch, CURLOPT_PROXY, $proxy['proxyClient']);
                }
                $handles[$i] = $ch;
                curl_multi_add_handle($multi, $ch);
            }

            $running = null;
            do {
                curl_multi_exec($multi, $running);
                if ($running > 0) {
                    curl_multi_select($multi, 0.2);
                }
            } while ($running > 0);

            foreach ($handles as $i => $ch) {
                $m = $meta[$i];
                $bodyText = (string) curl_multi_getcontent($ch);
                $status = (int) curl_getinfo($ch, CURLINFO_RESPONSE_CODE);
                $errno = curl_errno($ch);
                $error = $errno !== 0 ? curl_error($ch) : null;
                $latencyMs = (int) round((microtime(true) - $m['started']) * 1000);
                curl_multi_remove_handle($multi, $ch);
                curl_close($ch);

                $data = json_decode($bodyText, true);
                $proxyMode = $m['isLocal']
                    ? 'Direct (Local / Ollama)'
                    : ($m['proxy']['proxyClient']
                        ? "Forward proxy '{$m['proxy']['proxyClient']}' (cURL CURLOPT_PROXY)"
                        : ($m['proxy']['effectiveUrl'] !== $m['direct'] ? 'Gateway Proxy (URL rewrite)' : 'Direct'));

                $base = [
                    'provider' => $m['provider']['id'],
                    'providerName' => $m['provider']['name'],
                    'model' => $m['model']['id'],
                    'modelName' => $m['model']['name'],
                    'protocol' => $m['provider']['protocol'],
                    'request' => [
                        'method' => 'POST',
                        'directEndpoint' => $m['direct'],
                        'effectiveEndpoint' => $m['proxy']['effectiveUrl'],
                        'proxyClient' => $m['proxy']['proxyClient'],
                        'isProxyActive' => $m['proxy']['effectiveUrl'] !== $m['direct'] || (bool) $m['proxy']['proxyClient'],
                        'proxyMode' => $proxyMode,
                        'headers' => self::maskHeaders($m['headers']),
                        'body' => $m['body'],
                    ],
                    'timestamp' => self::nowIso(),
                    'latencyMs' => $latencyMs,
                ];

                $ok = $error === null && $status >= 200 && $status < 300;
                $store->recordMetric((string) $m['provider']['id'], (string) $m['model']['id'], (float) $latencyMs, !$ok);

                if ($ok) {
                    ['text' => $rendered, 'reasoning' => $reasoning] = self::renderText((string) $m['provider']['protocol'], $data);
                    $results[$i] = array_merge($base, [
                        'ok' => true,
                        'message' => $rendered !== '' ? substr(trim($rendered), 0, 200) : 'Empty response body',
                        'response' => [
                            'statusCode' => $status,
                            'renderedText' => $rendered,
                            'reasoningContent' => $reasoning,
                            'rawJson' => $data,
                            'rawError' => null,
                        ],
                    ]);
                } else {
                    $errText = $error;
                    if ($errText === null && is_array($data)) {
                        $e = $data['error']['message'] ?? $data['error'] ?? $data['message'] ?? null;
                        $errText = is_string($e) ? $e : substr((string) json_encode($e ?? $data), 0, 800);
                    }
                    $errText ??= substr($bodyText, 0, 800);
                    $results[$i] = array_merge($base, [
                        'ok' => false,
                        'error' => $errText !== '' ? $errText : 'Request failed',
                        'message' => $errText !== '' ? substr($errText, 0, 200) : 'Request failed',
                        'response' => [
                            'statusCode' => $status,
                            'renderedText' => '',
                            'reasoningContent' => '',
                            'rawJson' => null,
                            'rawError' => $errText,
                        ],
                    ]);
                }
            }
            curl_multi_close($multi);
        }

        ksort($results);
        return array_values($results);
    }

    /** Port of `/api/config/test-proxy`. */
    public static function testProxy(?string $proxyUrl = null, string $targetUrl = 'https://httpbin.org/get'): array
    {
        $target = $targetUrl !== '' ? $targetUrl : 'https://httpbin.org/get';
        $cfg = ($proxyUrl !== null && $proxyUrl !== '')
            ? Config::parseProxySetting($proxyUrl, $target)
            : Config::proxyConfig($target);

        $r = HttpClient::request('GET', $cfg['effectiveUrl'], ['User-Agent' => 'Arena-Agent-PHP/1.0'], null, 15, $cfg['proxyClient']);
        $latency = (int) round($r['latencyMs']);

        $out = [
            'ok' => $r['ok'],
            'status_code' => $r['status'],
            'latency_ms' => $latency,
            'proxy_url' => $proxyUrl ?? Config::raw('AGENT_PROXY_URL', ''),
            'effective_url' => $cfg['effectiveUrl'],
            'proxy_client' => $cfg['proxyClient'],
            'message' => $r['ok']
                ? "Proxy reachable (HTTP {$r['status']}) in {$latency}ms"
                : ($r['error'] !== null ? 'Proxy connectivity test failed' : "Proxy responded with HTTP {$r['status']}"),
        ];
        if ($r['error'] !== null) {
            $out['error'] = $r['error'];
        }
        return $out;
    }
}

/* ==========================================================================
 * FILE: LocalAI.php
 * ========================================================================== */
/**
 * Local AI installer & manager (Ollama runtime).
 *
 * This module has no equivalent in the Python or the Workers edition: it only
 * becomes possible on a host with a real shell, spare RAM and disk, which is
 * exactly the target of the PHP port.
 *
 * Pipeline:
 *   hostScan()   → what the machine actually has (RAM/CPU/GPU/disk/runtime)
 *   recommend()  → score every catalog variant against the user's profile
 *                  (RAM budget, task, context, language, speed↔quality)
 *   install()    → background job: install runtime → pull → tune → benchmark
 *                  → register as a provider/model in the agent's ProviderStore
 *
 * Everything runs without root: the Ollama runtime is unpacked into
 * storage/localai/ and served from 127.0.0.1 by a detached process.
 */

final class LocalAI
{
    public const DEFAULT_HOST = 'http://127.0.0.1:11434';
    public const REGISTRY = 'https://registry.ollama.ai';
    public const HF_API = 'https://huggingface.co/api/models';

    /** Bytes-per-weight of the quantisation schemes we ship in the catalog. */
    public const BPW = [
        'Q2_K' => 2.6, 'Q3_K_M' => 3.9, 'Q4_0' => 4.5, 'Q4_K_M' => 4.85,
        'Q5_K_M' => 5.7, 'Q6_K' => 6.6, 'Q8_0' => 8.5, 'F16' => 16.0,
    ];

    /** Runtime overhead of a loaded model (graph, buffers, server itself). */
    public const RUNTIME_OVERHEAD_GB = 0.6;
    /** Weights need a little more RAM than they take on disk. */
    public const WEIGHT_RAM_FACTOR = 1.08;

    /* ================================================================== */
    /* Paths & configuration                                              */
    /* ================================================================== */

    /**
     * Relative values (as written by the host console into .env) are resolved
     * against the application root, never against the CWD — php-fpm and the
     * CLI worker do not share one.
     */
    private static function absPath(string $v): string
    {
        $v = rtrim(trim($v), '/');
        if ($v === '') {
            return '';
        }
        return str_starts_with($v, '/') ? $v : Bootstrap::$root . '/' . $v;
    }

    public static function rootDir(): string
    {
        $v = self::absPath((string) (getenv('AGENT_LOCALAI_DIR') ?: ''));
        return $v !== '' ? $v : Bootstrap::$storageDir . '/localai';
    }

    public static function modelsDir(): string
    {
        $v = self::absPath((string) (getenv('OLLAMA_MODELS') ?: ''));
        return $v !== '' ? $v : self::rootDir() . '/models';
    }

    public static function binDir(): string
    {
        return self::rootDir() . '/bin';
    }

    /** Resolved engine executable: explicit env → database state → private install → standard paths → PATH. */
    public static function binary(?string $engine = null): ?string
    {
        $engine ??= (string) (Database::state('localai:engine', 'ollama') ?? 'ollama');

        if ($engine === 'llamacpp') {
            $explicit = (string) (getenv('AGENT_LLAMACPP_BIN') ?: '');
            if ($explicit !== '' && is_file($explicit)) {
                return $explicit;
            }
            $saved = (string) (Database::state('localai:llamacpp_bin', '') ?? '');
            if ($saved !== '' && is_file($saved) && is_executable($saved)) {
                return $saved;
            }
            $candidates = [
                self::binDir() . '/llama-server',
                self::binDir() . '/llama-cli',
                self::rootDir() . '/llama-server',
                '/usr/local/bin/llama-server',
                '/usr/bin/llama-server',
            ];
            foreach ($candidates as $c) {
                if (is_file($c) && is_executable($c)) {
                    return $c;
                }
            }
            if (function_exists('proc_open')) {
                $out = Terminal::rawCapture(['sh', '-lc', 'command -v llama-server 2>/dev/null || command -v llama-cli 2>/dev/null'], null, 5);
                $path = trim((string) ($out['stdout'] ?? ''));
                if ($path !== '') {
                    $first = explode("\n", $path)[0];
                    if (is_file($first) && is_executable($first)) {
                        return $first;
                    }
                }
            }
            return null;
        }

        // Default: ollama
        $explicit = (string) (getenv('AGENT_OLLAMA_BIN') ?: '');
        if ($explicit !== '' && is_file($explicit)) {
            return $explicit;
        }
        $saved = (string) (Database::state('localai:custom_bin', '') ?? '');
        if ($saved !== '' && is_file($saved) && is_executable($saved)) {
            return $saved;
        }
        $local = self::binDir() . '/ollama';
        if (is_file($local) && is_executable($local)) {
            return $local;
        }
        $candRoot = self::rootDir() . '/ollama';
        if (is_file($candRoot) && is_executable($candRoot)) {
            return $candRoot;
        }
        $candRootBin = self::rootDir() . '/bin/ollama';
        if (is_file($candRootBin) && is_executable($candRootBin)) {
            return $candRootBin;
        }
        $standard = ['/usr/local/bin/ollama', '/usr/bin/ollama', '/opt/ollama/bin/ollama'];
        $home = getenv('HOME') ?: '';
        if ($home !== '') {
            $standard[] = rtrim($home, '/') . '/.local/bin/ollama';
        }
        foreach ($standard as $p) {
            if (is_file($p) && is_executable($p)) {
                return $p;
            }
        }
        if (function_exists('proc_open')) {
            $out = Terminal::rawCapture(['sh', '-lc', 'command -v ollama 2>/dev/null'], null, 5);
            $path = trim((string) ($out['stdout'] ?? ''));
            if ($path !== '') {
                $first = explode("\n", $path)[0];
                if (is_file($first) && is_executable($first)) {
                    return $first;
                }
            }
        }
        return null;
    }

    /** Base URL of the Ollama HTTP API. */
    public static function host(): string
    {
        foreach (['AGENT_LOCALAI_HOST', 'OLLAMA_HOST'] as $key) {
            $v = trim((string) (getenv($key) ?: ''));
            if ($v !== '') {
                return self::normalizeHost($v);
            }
        }
        $saved = (string) (Database::state('localai:custom_host', '') ?? '');
        if ($saved !== '') {
            return self::normalizeHost($saved);
        }
        $cfg = trim(Config::raw('OLLAMA_BASE_URL', ''));
        return $cfg !== '' ? self::normalizeHost($cfg) : self::DEFAULT_HOST;
    }

    private static function normalizeHost(string $v): string
    {
        $v = rtrim(trim($v), '/');
        if ($v === '') {
            return self::DEFAULT_HOST;
        }
        if (!preg_match('#^https?://#i', $v)) {
            $v = 'http://' . $v;
        }
        return $v;
    }

    /** Tunables that are written into the server environment. */
    public static function serverEnv(array $overrides = []): array
    {
        $parsed = parse_url(self::host());
        $bind = ($parsed['host'] ?? '127.0.0.1') . ':' . ($parsed['port'] ?? 11434);

        $env = [
            'OLLAMA_HOST' => $bind,
            'OLLAMA_MODELS' => self::modelsDir(),
            'HOME' => self::rootDir(),
            'OLLAMA_KEEP_ALIVE' => (string) (getenv('OLLAMA_KEEP_ALIVE') ?: '10m'),
            'OLLAMA_MAX_LOADED_MODELS' => (string) (getenv('OLLAMA_MAX_LOADED_MODELS') ?: '1'),
            'OLLAMA_NUM_PARALLEL' => (string) (getenv('OLLAMA_NUM_PARALLEL') ?: '1'),
            'OLLAMA_FLASH_ATTENTION' => (string) (getenv('OLLAMA_FLASH_ATTENTION') ?: '1'),
            // q8_0 KV cache halves context memory with no measurable quality loss.
            'OLLAMA_KV_CACHE_TYPE' => (string) (getenv('OLLAMA_KV_CACHE_TYPE') ?: 'q8_0'),
        ];
        foreach ($overrides as $k => $v) {
            if ($v !== null && $v !== '') {
                $env[(string) $k] = (string) $v;
            }
        }
        return $env;
    }

    /* ================================================================== */
    /* Host capability scan                                               */
    /* ================================================================== */

    public static function hostScan(bool $refresh = false): array
    {
        static $cache = null;
        if ($cache !== null && !$refresh) {
            return $cache;
        }

        $mem = self::readMemory();
        $cpu = self::readCpu();
        $gpu = self::readGpu();
        $disk = self::diskInfo(self::modelsDir());

        // Memory bandwidth drives token throughput far more than raw FLOPs.
        $cpuBandwidth = (float) (getenv('AGENT_LOCALAI_CPU_BANDWIDTH') ?: 0);
        if ($cpuBandwidth <= 0) {
            $cpuBandwidth = $cpu['arch'] === 'arm64' && PHP_OS_FAMILY === 'Darwin' ? 100.0 : 28.0;
        }

        // Leave the OS, PHP-FPM and the agent itself some air.
        $reserve = max(1.0, min(4.0, $mem['totalGb'] * 0.15));
        $suggested = max(0.0, round(($mem['availableGb'] > 0 ? $mem['availableGb'] : $mem['totalGb']) - $reserve, 1));

        $cache = [
            'os' => PHP_OS_FAMILY,
            'uname' => php_uname('a'),
            'memory' => $mem,
            'cpu' => $cpu,
            'gpu' => $gpu,
            'disk' => $disk,
            'bandwidthGBs' => ['cpu' => $cpuBandwidth, 'gpu' => $gpu['bandwidthGBs'] ?? 0.0],
            'suggestedRamBudgetGb' => $suggested,
            'reservedForSystemGb' => round($reserve, 1),
            'runtime' => self::runtimeStatus(),
            'scannedAt' => gmdate('c'),
        ];
        return $cache;
    }

    private static function readMemory(): array
    {
        $totalKb = 0;
        $availKb = 0;
        $swapKb = 0;
        if (is_readable('/proc/meminfo')) {
            foreach (file('/proc/meminfo') ?: [] as $line) {
                if (preg_match('/^MemTotal:\s+(\d+)/', $line, $m)) {
                    $totalKb = (int) $m[1];
                } elseif (preg_match('/^MemAvailable:\s+(\d+)/', $line, $m)) {
                    $availKb = (int) $m[1];
                } elseif (preg_match('/^SwapTotal:\s+(\d+)/', $line, $m)) {
                    $swapKb = (int) $m[1];
                }
            }
        } elseif (PHP_OS_FAMILY === 'Darwin' && function_exists('proc_open')) {
            $out = Terminal::rawCapture(['sh', '-lc', 'sysctl -n hw.memsize'], null, 5);
            $totalKb = (int) (((float) trim((string) $out['stdout'])) / 1024);
        }

        // Respect a cgroup/container limit when it is lower than the host total.
        foreach (['/sys/fs/cgroup/memory.max', '/sys/fs/cgroup/memory/memory.limit_in_bytes'] as $f) {
            if (is_readable($f)) {
                $raw = trim((string) @file_get_contents($f));
                if ($raw !== '' && $raw !== 'max' && ctype_digit($raw)) {
                    $limitKb = (int) ((int) $raw / 1024);
                    if ($limitKb > 0 && ($totalKb === 0 || $limitKb < $totalKb)) {
                        $totalKb = $limitKb;
                        $availKb = min($availKb ?: $limitKb, $limitKb);
                    }
                }
            }
        }

        return [
            'totalGb' => round($totalKb / 1048576, 2),
            'availableGb' => round(($availKb ?: $totalKb) / 1048576, 2),
            'swapGb' => round($swapKb / 1048576, 2),
        ];
    }

    private static function readCpu(): array
    {
        $model = '';
        $cores = 0;
        $flags = [];
        if (is_readable('/proc/cpuinfo')) {
            foreach (file('/proc/cpuinfo') ?: [] as $line) {
                if ($model === '' && preg_match('/^model name\s*:\s*(.+)$/', $line, $m)) {
                    $model = trim($m[1]);
                }
                if (preg_match('/^processor\s*:/', $line)) {
                    $cores++;
                }
                if (!$flags && preg_match('/^(flags|Features)\s*:\s*(.+)$/', $line, $m)) {
                    $flags = preg_split('/\s+/', trim($m[2])) ?: [];
                }
            }
        }
        if ($cores === 0 && function_exists('proc_open')) {
            $out = Terminal::rawCapture(['sh', '-lc', 'nproc 2>/dev/null || sysctl -n hw.ncpu 2>/dev/null'], null, 5);
            $cores = (int) trim((string) $out['stdout']);
        }
        $arch = strtolower(php_uname('m'));
        if (in_array($arch, ['x86_64', 'amd64'], true)) {
            $arch = 'amd64';
        } elseif (in_array($arch, ['aarch64', 'arm64'], true)) {
            $arch = 'arm64';
        }
        return [
            'model' => $model ?: php_uname('p'),
            'cores' => max(1, $cores),
            'arch' => $arch,
            'avx2' => in_array('avx2', $flags, true),
            'avx512' => (bool) preg_grep('/^avx512/', $flags),
            'neon' => in_array('asimd', $flags, true) || in_array('neon', $flags, true),
        ];
    }

    private static function readGpu(): array
    {
        $none = ['present' => false, 'vendor' => '', 'name' => '', 'vramGb' => 0.0, 'freeVramGb' => 0.0, 'bandwidthGBs' => 0.0, 'driver' => ''];
        if (!function_exists('proc_open')) {
            return $none;
        }

        $nv = Terminal::rawCapture(
            ['sh', '-lc', 'nvidia-smi --query-gpu=name,memory.total,memory.free,driver_version --format=csv,noheader,nounits 2>/dev/null'],
            null,
            8
        );
        $line = trim(explode("\n", trim((string) $nv['stdout']))[0] ?? '');
        if ($line !== '' && str_contains($line, ',')) {
            $parts = array_map('trim', explode(',', $line));
            $vram = round(((float) ($parts[1] ?? 0)) / 1024, 2);
            return [
                'present' => true,
                'vendor' => 'nvidia',
                'name' => $parts[0] ?? 'NVIDIA GPU',
                'vramGb' => $vram,
                'freeVramGb' => round(((float) ($parts[2] ?? 0)) / 1024, 2),
                'bandwidthGBs' => self::guessGpuBandwidth((string) ($parts[0] ?? ''), $vram),
                'driver' => $parts[3] ?? '',
            ];
        }

        $rocm = Terminal::rawCapture(['sh', '-lc', 'rocm-smi --showmeminfo vram --csv 2>/dev/null | head -5'], null, 8);
        if (preg_match('/(\d{6,})/', (string) $rocm['stdout'], $m)) {
            $vram = round(((float) $m[1]) / 1073741824, 2);
            return ['present' => true, 'vendor' => 'amd', 'name' => 'AMD GPU (ROCm)', 'vramGb' => $vram,
                    'freeVramGb' => $vram, 'bandwidthGBs' => 400.0, 'driver' => ''];
        }

        if (PHP_OS_FAMILY === 'Darwin' && str_contains(strtolower(php_uname('m')), 'arm')) {
            $mem = self::readMemory();
            return ['present' => true, 'vendor' => 'apple', 'name' => 'Apple Silicon (unified memory)',
                    'vramGb' => $mem['totalGb'], 'freeVramGb' => $mem['availableGb'],
                    'bandwidthGBs' => 150.0, 'driver' => 'metal'];
        }

        return $none;
    }

    private static function guessGpuBandwidth(string $name, float $vramGb): float
    {
        $n = strtolower($name);
        $table = [
            'h100' => 3350.0, 'a100' => 1935.0, 'l40' => 864.0, 'a6000' => 768.0,
            '4090' => 1008.0, '4080' => 717.0, '4070' => 504.0, '4060' => 272.0,
            '3090' => 936.0, '3080' => 760.0, '3070' => 448.0, '3060' => 360.0,
            '2080' => 448.0, '2060' => 336.0, 't4' => 320.0, 'v100' => 900.0,
            'p100' => 732.0, 'p40' => 346.0, 'a10' => 600.0,
        ];
        foreach ($table as $key => $bw) {
            if (str_contains($n, $key)) {
                return $bw;
            }
        }
        return $vramGb >= 24 ? 700.0 : 320.0;
    }

    private static function diskInfo(string $path): array
    {
        $probe = $path;
        while ($probe !== '/' && $probe !== '' && !is_dir($probe)) {
            $probe = dirname($probe);
        }
        $free = @disk_free_space($probe ?: '/');
        $total = @disk_total_space($probe ?: '/');
        return [
            'path' => $path,
            'freeGb' => $free === false ? 0.0 : round(((float) $free) / 1073741824, 2),
            'totalGb' => $total === false ? 0.0 : round(((float) $total) / 1073741824, 2),
        ];
    }

    /* ================================================================== */
    /* Runtime (Ollama & llama.cpp) lifecycle                             */
    /* ================================================================== */

    public static function runtimeStatus(): array
    {
        $engine = (string) (Database::state('localai:engine', 'ollama') ?? 'ollama');
        $bin = self::binary($engine) ?? self::binary();
        $version = '';
        if ($bin !== null && function_exists('proc_open')) {
            $out = Terminal::rawCapture([$bin, '--version'], null, 8, self::serverEnv());
            if (preg_match('/([0-9]+\.[0-9]+(\.[0-9]+)?)/', (string) $out['stdout'] . (string) $out['stderr'], $m)) {
                $version = $m[1];
            }
        }
        $up = self::serverUp();
        $ollamaBin = self::binary('ollama');
        $llamaBin = self::binary('llamacpp');

        return [
            'engine' => $engine,
            'engines' => [
                'ollama' => [
                    'name' => 'Ollama',
                    'installed' => $ollamaBin !== null,
                    'binary' => $ollamaBin ?? '',
                ],
                'llamacpp' => [
                    'name' => 'llama.cpp (llama-server)',
                    'installed' => $llamaBin !== null,
                    'binary' => $llamaBin ?? '',
                ],
            ],
            'installed' => $bin !== null,
            'binary' => $bin ?? '',
            'managed' => $bin !== null && str_starts_with($bin, self::binDir()),
            'version' => $version,
            'running' => $up['ok'],
            'host' => self::host(),
            'modelsDir' => self::modelsDir(),
            'modelsDirWritable' => self::dirWritable(self::modelsDir()),
            'error' => $up['ok'] ? '' : (string) ($up['error'] ?? ''),
            'env' => self::serverEnv(),
        ];
    }

    public static function dirWritable(string $dir): bool
    {
        if (!is_dir($dir)) {
            @mkdir($dir, 0775, true);
        }
        $probe = $dir;
        while ($probe !== '/' && $probe !== '' && !is_dir($probe)) {
            $probe = dirname($probe);
        }
        if ($probe === '') {
            return false;
        }
        if (!is_writable($probe)) {
            @chmod($probe, 0775);
        }
        $test = rtrim($probe, '/') . '/.probe_' . getmypid() . '_' . time();
        $ok = @file_put_contents($test, '1') !== false;
        if ($ok) {
            @unlink($test);
            return true;
        }
        return is_writable($probe);
    }

    public static function fixPermissions(): array
    {
        $md = self::modelsDir();
        $rd = self::rootDir();
        $dirs = [DATA_DIR, STORAGE_DIR, $rd, $md, self::binDir()];
        $errors = [];
        foreach ($dirs as $d) {
            if (!is_dir($d)) {
                @mkdir($d, 0775, true);
            }
            if (!@chmod($d, 0775)) {
                if (!@chmod($d, 0755)) {
                    $errors[] = "chmod failed for $d";
                }
            }
        }
        $writable = self::dirWritable($md);
        return [
            'ok' => $writable,
            'modelsDir' => $md,
            'modelsDirWritable' => $writable,
            'errors' => $writable ? [] : $errors,
        ];
    }

    /** @return array{ok:bool, error?:string, version?:string} */
    public static function serverUp(): array
    {
        $r = HttpClient::request('GET', self::host() . '/api/version', [], null, 4);
        if (!$r['ok']) {
            return ['ok' => false, 'error' => $r['error'] ?? ('HTTP ' . $r['status'])];
        }
        $j = json_decode($r['body'], true);
        return ['ok' => true, 'version' => (string) ($j['version'] ?? '')];
    }

    /**
     * Install the runtime (Ollama or llama.cpp) without root into storage/localai/.
     * @param string|array|callable|null $opts
     */
    public static function installRuntime(mixed $opts = null, ?callable $log = null): array
    {
        $engine = 'ollama';
        if (is_callable($opts)) {
            $log = $opts;
        } elseif (is_string($opts) && $opts !== '') {
            $engine = $opts;
        } elseif (is_array($opts) && !empty($opts['engine'])) {
            $engine = (string) $opts['engine'];
        }
        $log ??= static function (string $m): void {
        };

        if (!function_exists('proc_open')) {
            throw new HttpError(501, 'proc_open() is disabled — the local AI runtime cannot be installed');
        }

        $existing = self::binary($engine);
        if ($existing !== null) {
            Database::setState('localai:engine', $engine);
            $log(ucfirst($engine) . ' is already installed at ' . $existing);
            return ['installed' => true, 'engine' => $engine, 'binary' => $existing, 'skipped' => true];
        }

        $cpu = self::readCpu();
        if (PHP_OS_FAMILY !== 'Linux') {
            throw new HttpError(400, 'Automatic runtime install is supported on Linux. Install manually and set AGENT_OLLAMA_BIN or AGENT_LLAMACPP_BIN.');
        }
        $archTag = $cpu['arch'] === 'arm64' ? 'arm64' : 'amd64';

        $root = self::rootDir();
        $binDir = self::binDir();
        $modelsDir = self::modelsDir();
        Files::ensureDir($root);
        Files::ensureDir($binDir);
        Files::ensureDir($modelsDir);

        $candidates = [];

        if ($engine === 'llamacpp') {
            $log('Discovering llama.cpp / llama-server release assets …');
            try {
                $gh = HttpClient::request('GET', 'https://api.github.com/repos/ggml-org/llama.cpp/releases/latest', ['User-Agent: ArenaAgent/3.0'], null, 8);
                if (!empty($gh['ok'])) {
                    $j = json_decode((string) ($gh['body'] ?? ''), true);
                    if (is_array($j) && !empty($j['assets']) && is_array($j['assets'])) {
                        foreach ($j['assets'] as $asset) {
                            $name = (string) ($asset['name'] ?? '');
                            $durl = (string) ($asset['browser_download_url'] ?? '');
                            if (str_contains($name, 'ubuntu') && str_contains($name, $archTag === 'arm64' ? 'arm64' : 'x64') && str_ends_with($name, '.zip')) {
                                $candidates[] = $durl;
                            }
                        }
                    }
                }
            } catch (\Throwable $e) {
                $log('llama.cpp GitHub API probe skipped (' . $e->getMessage() . ')');
            }
            $archZip = $archTag === 'arm64' ? 'arm64' : 'x64';
            $candidates[] = "https://github.com/ggml-org/llama.cpp/releases/download/b4800/llama-b4800-bin-ubuntu-{$archZip}.zip";
            $candidates[] = "https://github.com/ggml-org/llama.cpp/releases/download/b4000/llama-b4000-bin-ubuntu-{$archZip}.zip";
            $candidates[] = "https://github.com/ggml-org/llama.cpp/releases/download/b3900/llama-b3900-bin-ubuntu-{$archZip}.zip";
            $candidates[] = "https://mirror.ghproxy.com/https://github.com/ggml-org/llama.cpp/releases/download/b4800/llama-b4800-bin-ubuntu-{$archZip}.zip";
            $candidates[] = "https://ghproxy.net/https://github.com/ggml-org/llama.cpp/releases/download/b4800/llama-b4800-bin-ubuntu-{$archZip}.zip";
        } else {
            // Ollama
            $log('Discovering Ollama release assets …');
            try {
                $gh = HttpClient::request('GET', 'https://api.github.com/repos/ollama/ollama/releases/latest', ['User-Agent: ArenaAgent/3.0'], null, 8);
                if (!empty($gh['ok'])) {
                    $j = json_decode((string) ($gh['body'] ?? ''), true);
                    if (is_array($j) && !empty($j['assets']) && is_array($j['assets'])) {
                        foreach ($j['assets'] as $asset) {
                            $name = (string) ($asset['name'] ?? '');
                            $durl = (string) ($asset['browser_download_url'] ?? '');
                            if (str_contains($name, "linux-{$archTag}.tar.zst") || str_contains($name, "linux-{$archTag}.tgz") || str_contains($name, "linux-{$archTag}.tar.gz")) {
                                $candidates[] = $durl;
                            }
                        }
                    }
                }
            } catch (\Throwable $e) {
                $log('GitHub API probe skipped (' . $e->getMessage() . '), trying direct endpoints …');
            }

            $candidates[] = "https://github.com/ollama/ollama/releases/latest/download/ollama-linux-{$archTag}.tar.zst";
            $candidates[] = "https://github.com/ollama/ollama/releases/latest/download/ollama-linux-{$archTag}.tgz";
            $candidates[] = "https://github.com/ollama/ollama/releases/download/v0.5.12/ollama-linux-{$archTag}.tar.zst";
            $candidates[] = "https://github.com/ollama/ollama/releases/download/v0.5.12/ollama-linux-{$archTag}.tgz";
            $candidates[] = "https://github.com/ollama/ollama/releases/download/v0.3.14/ollama-linux-{$archTag}.tgz";
            $candidates[] = "https://ollama.com/download/ollama-linux-{$archTag}.tar.zst";
            $candidates[] = "https://ollama.com/download/ollama-linux-{$archTag}.tgz";
            $candidates[] = "https://mirror.ghproxy.com/https://github.com/ollama/ollama/releases/download/v0.5.12/ollama-linux-{$archTag}.tar.zst";
            $candidates[] = "https://ghproxy.net/https://github.com/ollama/ollama/releases/download/v0.5.12/ollama-linux-{$archTag}.tar.zst";
        }

        $unique = array_values(array_unique(array_filter($candidates)));
        $downloadedFile = null;
        $lastError = 'No download sources available';

        foreach ($unique as $url) {
            $log('Attempting download from: ' . $url);
            $parsed = parse_url($url, PHP_URL_PATH);
            $fname = $parsed ? basename($parsed) : ($engine === 'llamacpp' ? "llama-bin.zip" : "ollama-linux-{$archTag}.tar.zst");
            $dest = $root . '/' . $fname;

            // 1. Try curl CLI if available
            $dlOk = false;
            $res = Terminal::rawCapture(['curl', '-fSL', '--connect-timeout', '15', '-m', '300', '-A', 'Mozilla/5.0 (ArenaAgent/3.0)', '-o', $dest, $url], $root, 310);
            if ((int) ($res['exitCode'] ?? -1) === 0 && file_exists($dest) && filesize($dest) > 1000) {
                $dlOk = true;
            }

            // 2. Try wget CLI
            if (!$dlOk) {
                $res2 = Terminal::rawCapture(['wget', '-q', '-T', '15', '-t', '2', '-U', 'Mozilla/5.0 (ArenaAgent/3.0)', '-O', $dest, $url], $root, 310);
                if ((int) ($res2['exitCode'] ?? -1) === 0 && file_exists($dest) && filesize($dest) > 1000) {
                    $dlOk = true;
                }
            }

            // 3. Try HttpClient with proxy
            if (!$dlOk) {
                $proxy = Config::proxyConfig($url);
                $dl = HttpClient::download($proxy['effectiveUrl'], $dest, 1800, $proxy['proxyClient']);
                if (!empty($dl['ok']) && file_exists($dest) && filesize($dest) > 1000) {
                    $dlOk = true;
                } else {
                    $lastError = (string) ($dl['error'] ?? 'HTTP download failed');
                }
            }

            if ($dlOk) {
                $log('Downloaded ' . basename($dest) . ' (' . Files::humanSize((int) filesize($dest)) . '), extracting …');
                $downloadedFile = $dest;
                break;
            } else {
                $log('Candidate failed, trying next mirror …');
                @unlink($dest);
            }
        }

        if ($downloadedFile === null || !file_exists($downloadedFile)) {
            throw new HttpError(502, "Could not download {$engine} runtime: {$lastError}");
        }

        // Extract archive
        if (str_ends_with(strtolower($downloadedFile), '.zip')) {
            $extracted = false;
            if (function_exists('proc_open')) {
                $unz = Terminal::rawCapture(['unzip', '-o', $downloadedFile, '-d', $root], $root, 300);
                if ((int) ($unz['exitCode'] ?? -1) === 0) {
                    $extracted = true;
                }
            }
            if (!$extracted && class_exists('\ZipArchive')) {
                $za = new \ZipArchive();
                if ($za->open($downloadedFile) === true) {
                    $za->extractTo($root);
                    $za->close();
                    $extracted = true;
                }
            }
        } else {
            Terminal::rawCapture(['tar', '-xf', $downloadedFile, '-C', $root], $root, 900);
        }
        @unlink($downloadedFile);

        // Find extracted binary
        $targetBin = null;
        if ($engine === 'llamacpp') {
            $candidatesBin = [
                $binDir . '/llama-server',
                $root . '/llama-server',
                $root . '/build/bin/llama-server',
            ];
            foreach ($candidatesBin as $cb) {
                if (file_exists($cb)) {
                    $targetBin = $binDir . '/llama-server';
                    if ($cb !== $targetBin) {
                        @rename($cb, $targetBin);
                    }
                    break;
                }
            }
            if ($targetBin === null) {
                $found = glob($root . '/**/llama-server');
                if (!empty($found) && is_file($found[0])) {
                    $targetBin = $binDir . '/llama-server';
                    @rename($found[0], $targetBin);
                }
            }
        } else {
            $candidatesBin = [
                $binDir . '/ollama',
                $root . '/ollama',
                $root . '/bin/ollama',
            ];
            foreach ($candidatesBin as $cb) {
                if (file_exists($cb)) {
                    $targetBin = $binDir . '/ollama';
                    if ($cb !== $targetBin) {
                        @rename($cb, $targetBin);
                    }
                    break;
                }
            }
            if ($targetBin === null) {
                $found = glob($root . '/**/ollama');
                if (!empty($found) && is_file($found[0])) {
                    $targetBin = $binDir . '/ollama';
                    @rename($found[0], $targetBin);
                }
            }
        }

        if ($targetBin === null || !file_exists($targetBin)) {
            throw new HttpError(500, "Extraction completed but binary for {$engine} not found in {$root}");
        }

        @chmod($targetBin, 0755);
        Database::setState('localai:engine', $engine);
        $bin = self::binary($engine) ?? $targetBin;
        $log("Runtime {$engine} installed successfully at {$bin}");
        return ['installed' => true, 'engine' => $engine, 'binary' => $bin, 'skipped' => false];
    }

    public static function startServer(array $envOverrides = [], ?callable $log = null): array
    {
        $log ??= static function (string $m): void {
        };
        $up = self::serverUp();
        if ($up['ok']) {
            $log('Local AI server already running at ' . self::host());
            return ['running' => true, 'started' => false, 'host' => self::host()];
        }
        $engine = (string) (Database::state('localai:engine', 'ollama') ?? 'ollama');
        $bin = self::binary($engine) ?? self::binary();
        if ($bin === null) {
            throw new HttpError(409, 'Local AI engine (' . $engine . ') is not installed yet. Please click "Install Engine" first.');
        }
        Files::ensureDir(self::modelsDir());
        Files::ensureDir(self::rootDir() . '/logs');

        $env = self::serverEnv($envOverrides);
        $exports = '';
        foreach ($env as $k => $v) {
            $exports .= 'export ' . $k . '=' . escapeshellarg((string) $v) . '; ';
        }
        $logPath = self::rootDir() . '/logs/localai-server.log';
        if (str_contains(basename($bin), 'llama')) {
            $cmd = $exports . escapeshellarg($bin) . ' --host 127.0.0.1 --port 11434 --ctx-size 8192';
        } else {
            $cmd = $exports . escapeshellarg($bin) . ' serve';
        }
        $proc = Terminal::startDetached($cmd, self::rootDir(), 'localai', $logPath);
        Database::setState('localai:server:pid', (string) ($proc['pid'] ?? 0));

        for ($i = 0; $i < 40; $i++) {
            usleep(500000);
            if (self::serverUp()['ok']) {
                $log('Local AI server is up (pid ' . ($proc['pid'] ?? 0) . ')');
                return ['running' => true, 'started' => true, 'pid' => $proc['pid'] ?? 0, 'host' => self::host(), 'logPath' => $logPath, 'engine' => $engine];
            }
        }
        $tail = Terminal::readLog($logPath, 4000);
        throw new HttpError(500, 'Local AI server did not become ready within 20s. Log: ' . mb_substr($tail, -600));
    }

    public static function stopServer(): array
    {
        $pid = (int) Database::state('localai:server:pid', '0');
        $killed = false;
        if ($pid > 0) {
            $killed = Terminal::killTree($pid);
            Database::setState('localai:server:pid', '0');
        }
        return ['stopped' => $killed, 'pid' => $pid, 'running' => self::serverUp()['ok']];
    }

    /* ================================================================== */
    /* Catalog & search                                                   */
    /* ================================================================== */

    public static function catalogFile(): string
    {
        $v = (string) (getenv('AGENT_MODEL_CATALOG') ?: '');
        return $v !== '' ? $v : Bootstrap::$dataDir . '/model_catalog.json';
    }

    public static function catalog(bool $refresh = false): array
    {
        static $cache = null;
        if ($cache !== null && !$refresh) {
            return $cache;
        }
        $file = self::catalogFile();
        if (!is_file($file)) {
            $cache = ['schemaVersion' => 1, 'models' => [], 'taskLabels' => []];
            return $cache;
        }
        $data = json_decode(Files::read($file), true);
        $cache = is_array($data) ? $data : ['schemaVersion' => 1, 'models' => [], 'taskLabels' => []];
        return $cache;
    }

    /** Flatten the catalog into one row per (model, variant). */
    public static function variants(): array
    {
        $rows = [];
        foreach (self::catalog()['models'] ?? [] as $model) {
            foreach ($model['variants'] ?? [] as $v) {
                $row = $v;
                $row['modelId'] = (string) $model['id'];
                $row['ref'] = (string) $model['id'] . ':' . (string) $v['tag'];
                $row['name'] = (string) $model['name'] . ' ' . strtoupper((string) $v['tag']);
                $row['model'] = $model;
                $rows[] = $row;
            }
        }
        return $rows;
    }

    /** Real tag list straight from the Ollama registry (no auth required). */
    public static function registryTags(string $name): array
    {
        $name = trim($name);
        if ($name === '') {
            return [];
        }
        $repo = str_contains($name, '/') ? $name : 'library/' . $name;
        $url = self::REGISTRY . '/v2/' . $repo . '/tags/list';
        $proxy = Config::proxyConfig($url);
        $r = HttpClient::getJson($proxy['effectiveUrl'], [], 20, $proxy['proxyClient']);
        $tags = $r['json']['tags'] ?? [];
        return is_array($tags) ? array_values(array_map('strval', $tags)) : [];
    }

    /** Exact download size of a tag, from the registry manifest. */
    public static function registrySize(string $name, string $tag = 'latest'): ?float
    {
        $repo = str_contains($name, '/') ? $name : 'library/' . $name;
        $url = self::REGISTRY . '/v2/' . $repo . '/manifests/' . rawurlencode($tag);
        $proxy = Config::proxyConfig($url);
        $r = HttpClient::getJson(
            $proxy['effectiveUrl'],
            ['Accept' => 'application/vnd.docker.distribution.manifest.v2+json'],
            20,
            $proxy['proxyClient']
        );
        $layers = $r['json']['layers'] ?? null;
        if (!is_array($layers)) {
            return null;
        }
        $bytes = 0;
        foreach ($layers as $l) {
            $bytes += (int) ($l['size'] ?? 0);
        }
        return $bytes > 0 ? round($bytes / 1073741824, 2) : null;
    }

    /**
     * Search: curated catalog first (rich metadata), then Hugging Face GGUF
     * repositories as a long tail. Never throws — offline hosts get the
     * catalog only.
     */
    public static function search(string $query, int $limit = 25, bool $remote = true): array
    {
        $q = mb_strtolower(trim($query));
        $local = [];
        foreach (self::catalog()['models'] ?? [] as $m) {
            $hay = mb_strtolower(implode(' ', [
                (string) $m['id'], (string) $m['name'], (string) ($m['publisher'] ?? ''),
                (string) ($m['summary'] ?? ''), implode(' ', (array) ($m['tasks'] ?? [])),
            ]));
            if ($q === '' || str_contains($hay, $q)) {
                $local[] = [
                    'source' => 'catalog',
                    'id' => (string) $m['id'],
                    'name' => (string) $m['name'],
                    'publisher' => (string) ($m['publisher'] ?? ''),
                    'summary' => (string) ($m['summary'] ?? ''),
                    'description' => (string) ($m['summary'] ?? ''),
                    'license' => (string) ($m['license'] ?? 'Open'),
                    'tasks' => (array) ($m['tasks'] ?? []),
                    'toolCalling' => (bool) ($m['toolCalling'] ?? false),
                    'vision' => (bool) ($m['vision'] ?? false),
                    'reasoning' => (bool) ($m['reasoning'] ?? false),
                    'contextMax' => (int) ($m['contextMax'] ?? 8192),
                    'variants' => array_map(static fn(array $v): array => [
                        'tag' => (string) $v['tag'],
                        'ref' => (string) $m['id'] . ':' . (string) $v['tag'],
                        'diskGb' => (float) $v['diskGb'],
                        'ramGb' => round((float) $v['diskGb'] * self::WEIGHT_RAM_FACTOR + self::RUNTIME_OVERHEAD_GB + 0.8, 1),
                        'quant' => (string) $v['quant'],
                        'paramsB' => (float) ($v['paramsB'] ?? 0),
                        'quality' => (int) ($v['quality'] ?? 50),
                        'contextMax' => (int) ($m['contextMax'] ?? 8192),
                        'toolCalling' => (bool) ($m['toolCalling'] ?? false),
                        'vision' => (bool) ($m['vision'] ?? false),
                        'reasoning' => (bool) ($m['reasoning'] ?? false),
                    ], (array) ($m['variants'] ?? [])),
                ];
            }
        }

        $hf = [];
        if ($remote && $q !== '') {
            try {
                $url = self::HF_API . '?search=' . rawurlencode($query)
                    . '&filter=gguf&sort=downloads&direction=-1&limit=' . max(1, min(50, $limit));
                $proxy = Config::proxyConfig($url);
                $r = HttpClient::getJson($proxy['effectiveUrl'], ['Accept' => 'application/json'], 15, $proxy['proxyClient']);
                foreach ((array) ($r['json'] ?? []) as $item) {
                    if (!is_array($item)) {
                        continue;
                    }
                    $modelId = (string) ($item['modelId'] ?? $item['id'] ?? '');
                    $mLow = strtolower($modelId);
                    $estDisk = 4.5;
                    $estRam = 5.8;
                    if (str_contains($mLow, '0.5b')) { $estDisk = 0.6; $estRam = 1.2; }
                    elseif (str_contains($mLow, '1.5b') || str_contains($mLow, '1b') || str_contains($mLow, '2b')) { $estDisk = 1.5; $estRam = 2.4; }
                    elseif (str_contains($mLow, '3b') || str_contains($mLow, '4b')) { $estDisk = 2.5; $estRam = 3.6; }
                    elseif (str_contains($mLow, '7b') || str_contains($mLow, '8b')) { $estDisk = 4.8; $estRam = 6.2; }
                    elseif (str_contains($mLow, '14b') || str_contains($mLow, '13b')) { $estDisk = 9.2; $estRam = 11.5; }
                    elseif (str_contains($mLow, '32b') || str_contains($mLow, '34b')) { $estDisk = 20.0; $estRam = 24.0; }
                    elseif (str_contains($mLow, '70b') || str_contains($mLow, '72b')) { $estDisk = 42.0; $estRam = 48.0; }

                    $hf[] = [
                        'source' => 'huggingface',
                        'id' => $modelId,
                        'name' => $modelId,
                        'publisher' => explode('/', $modelId)[0] ?? 'HuggingFace',
                        'downloads' => (int) ($item['downloads'] ?? 0),
                        'likes' => (int) ($item['likes'] ?? 0),
                        'tasks' => array_values(array_filter((array) ($item['tags'] ?? []), 'is_string')),
                        'pullRef' => 'hf.co/' . $modelId,
                        'diskGb' => $estDisk,
                        'ramGb' => $estRam,
                        'toolCalling' => str_contains($mLow, 'tool') || str_contains($mLow, 'function'),
                        'vision' => str_contains($mLow, 'vision') || str_contains($mLow, 'vl'),
                        'reasoning' => str_contains($mLow, 'r1') || str_contains($mLow, 'reason') || str_contains($mLow, 'qwq'),
                        'summary' => 'مخزن GGUF در Hugging Face — با «ollama pull hf.co/' . $modelId . '» نصب می‌شود.',
                    ];
                }
            } catch (\Throwable $e) {
                Observability::log('WARNING', 'LOCALAI', 'Hugging Face search failed: ' . $e->getMessage());
            }
        }

        return ['query' => $query, 'catalog' => $local, 'huggingface' => array_slice($hf, 0, $limit)];
    }

    /* ================================================================== */
    /* Sizing & recommendation                                            */
    /* ================================================================== */

    /** @return array<string,mixed> a fully defaulted, validated wizard profile */
    public static function normalizeProfile(array $in): array
    {
        $host = self::hostScan();
        $tasks = array_values(array_filter(array_map(
            static fn($t): string => strtolower(trim((string) $t)),
            (array) ($in['tasks'] ?? ($in['task'] ?? []))
        )));
        if (!$tasks) {
            $tasks = ['chat'];
        }

        $budget = (float) ($in['ramBudgetGb'] ?? 0);
        if ($budget <= 0) {
            $budget = (float) $host['suggestedRamBudgetGb'];
        }
        $vram = array_key_exists('vramGb', $in) ? (float) $in['vramGb'] : (float) ($host['gpu']['vramGb'] ?? 0);
        $disk = (float) ($in['diskBudgetGb'] ?? 0);
        if ($disk <= 0) {
            $disk = max(1.0, (float) $host['disk']['freeGb'] - 2.0);
        }

        $priority = strtolower((string) ($in['priority'] ?? 'balanced'));
        if (!in_array($priority, ['speed', 'balanced', 'quality'], true)) {
            $priority = 'balanced';
        }

        return [
            'tasks' => $tasks,
            'ramBudgetGb' => round(max(0.5, $budget), 2),
            'vramGb' => round(max(0.0, $vram), 2),
            'diskBudgetGb' => round(max(0.5, $disk), 2),
            'contextTokens' => max(1024, min(1048576, (int) ($in['contextTokens'] ?? 8192))),
            'languages' => array_values(array_filter(array_map('strval', (array) ($in['languages'] ?? ['en'])))),
            'priority' => $priority,
            'concurrency' => max(1, min(16, (int) ($in['concurrency'] ?? 1))),
            'requireToolCalling' => (bool) ($in['requireToolCalling'] ?? in_array('agent', $tasks, true)),
            'requireVision' => (bool) ($in['requireVision'] ?? in_array('vision', $tasks, true)),
            'requireEmbedding' => (bool) ($in['requireEmbedding'] ?? in_array('embedding', $tasks, true)),
            'minTokensPerSec' => (float) ($in['minTokensPerSec'] ?? 0),
            'allowNonCommercial' => (bool) ($in['allowNonCommercial'] ?? true),
            'quantPreference' => (string) ($in['quantPreference'] ?? 'auto'),
        ];
    }

    /**
     * Memory / throughput model.
     *
     *   weights  = diskGb × 1.08                      dequantisation buffers
     *   active   = activeGb × 1.08                    MoE reads only the live experts
     *   kv       = kvGbPer1k × ctx/1024 × parallel    halved by an int8 KV cache
     *   ram      = weights + kv + 0.6 GB              0.6 GB = graph + server
     *   tok/s    ≈ bandwidth ÷ active × 0.72          local LLMs are bandwidth-bound
     *
     * `bandwidth` is the harmonic blend of GPU and CPU bandwidth weighted by the
     * fraction of the model that actually fits in VRAM — a partially offloaded
     * model runs at close to the speed of its slowest tier, not the average.
     */
    public static function estimate(array $variant, array $profile, ?array $host = null): array
    {
        $host ??= self::hostScan();
        $disk = (float) ($variant['diskGb'] ?? 0);
        $weights = $disk * self::WEIGHT_RAM_FACTOR;
        $active = ((float) ($variant['activeGb'] ?? $disk)) * self::WEIGHT_RAM_FACTOR;

        $kvScale = strtolower((string) (self::serverEnv()['OLLAMA_KV_CACHE_TYPE'] ?? 'f16')) === 'f16' ? 1.0 : 0.5;
        $ctxK = $profile['contextTokens'] / 1024;
        $kv = (float) ($variant['kvGbPer1k'] ?? 0.05) * $ctxK * $kvScale * max(1, (int) $profile['concurrency']);

        $ramGb = round($weights + $kv + self::RUNTIME_OVERHEAD_GB, 2);

        $vram = (float) $profile['vramGb'];
        $gpuBw = (float) ($host['bandwidthGBs']['gpu'] ?? 0);
        if ($gpuBw <= 0 && $vram > 0) {
            $gpuBw = 320.0; // user declared VRAM on a host we could not probe
        }
        $cpuBw = (float) ($host['bandwidthGBs']['cpu'] ?? 28.0);
        $offload = ($vram > 0 && $gpuBw > 0)
            ? max(0.0, min(1.0, ($vram - $kv - 0.5) / max(0.1, $weights)))
            : 0.0;
        $bandwidth = $offload >= 0.999
            ? $gpuBw
            : 1.0 / (($offload / max(1.0, $gpuBw)) + ((1 - $offload) / max(1.0, $cpuBw)));

        $tps = $active > 0 ? ($bandwidth / $active) * 0.72 : 0.0;
        // Tiny models become compute-bound rather than bandwidth-bound.
        $tps = min($tps, 20.0 * max(1, (int) ($host['cpu']['cores'] ?? 4)) * ($offload > 0.5 ? 6 : 1));

        return [
            'weightsGb' => round($weights, 2),
            'activeGb' => round($active, 2),
            'kvCacheGb' => round($kv, 2),
            'overheadGb' => self::RUNTIME_OVERHEAD_GB,
            'ramGb' => $ramGb,
            'diskGb' => round($disk, 2),
            'gpuOffloadRatio' => round($offload, 2),
            'effectiveBandwidthGBs' => round($bandwidth, 1),
            'tokensPerSec' => round($tps, 1),
            'fitsRam' => $ramGb <= (float) $profile['ramBudgetGb'],
            'fitsDisk' => $disk <= (float) $profile['diskBudgetGb'],
        ];
    }

    /**
     * Satisficing speed score: ~14 tok/s already reads faster than a human, so
     * more than that barely improves the experience, while anything under
     * 1.5 tok/s is genuinely painful and gets halved.
     */
    private static function speedScore(float $tps): float
    {
        $s = min(1.0, log(1 + $tps / 2.5) / log(1 + 14 / 2.5));
        return $tps < 1.5 ? $s * 0.5 : $s;
    }

    private static function taskMatch(array $model, array $tasks): float
    {
        $have = array_map('strval', (array) ($model['tasks'] ?? []));
        if (!$tasks) {
            return 0.5;
        }
        $hits = 0;
        foreach ($tasks as $t) {
            if (in_array($t, $have, true)) {
                $hits++;
            } elseif ($t === 'agent' && !empty($model['toolCalling'])) {
                $hits++;
            } elseif ($t === 'vision' && !empty($model['vision'])) {
                $hits++;
            } elseif ($t === 'reasoning' && !empty($model['reasoning'])) {
                $hits++;
            }
        }
        return $hits / count($tasks);
    }

    private static function languageScore(array $model, array $languages): float
    {
        if (!$languages) {
            return 0.7;
        }
        $have = array_map('strval', (array) ($model['languages'] ?? []));
        $total = 0.0;
        foreach ($languages as $lang) {
            $lang = strtolower($lang);
            if ($lang === 'fa') {
                $total += ((float) ($model['faScore'] ?? 0)) / 100;
            } elseif (in_array($lang, $have, true) || in_array('multi', $have, true)) {
                $total += 1.0;
            } else {
                $total += 0.25;
            }
        }
        return $total / count($languages);
    }

    /**
     * Rank every catalog variant for this profile.
     *
     * @return array{profile:array, host:array, recommendations:array, rejected:array}
     */
    public static function recommend(array $rawProfile): array
    {
        $profile = self::normalizeProfile($rawProfile);
        $host = self::hostScan();

        $weights = match ($profile['priority']) {
            'speed' => ['quality' => 0.18, 'speed' => 0.42, 'task' => 0.20, 'lang' => 0.10, 'fit' => 0.10],
            'quality' => ['quality' => 0.48, 'speed' => 0.08, 'task' => 0.22, 'lang' => 0.10, 'fit' => 0.12],
            default => ['quality' => 0.34, 'speed' => 0.22, 'task' => 0.22, 'lang' => 0.10, 'fit' => 0.12],
        };

        $ranked = [];
        $rejected = [];

        foreach (self::variants() as $v) {
            $model = $v['model'];
            $est = self::estimate($v, $profile, $host);
            $reasons = [];
            $blockers = [];

            if (!$est['fitsRam']) {
                $blockers[] = sprintf('به %.1f گیگ رم نیاز دارد (بودجه: %.1f)', $est['ramGb'], $profile['ramBudgetGb']);
            }
            if (!$est['fitsDisk']) {
                $blockers[] = sprintf('به %.1f گیگ دیسک نیاز دارد (آزاد: %.1f)', $est['diskGb'], $profile['diskBudgetGb']);
            }
            if ($profile['contextTokens'] > (int) ($model['contextMax'] ?? 8192)) {
                $blockers[] = sprintf('حداکثر پنجرهٔ این مدل %d توکن است', (int) ($model['contextMax'] ?? 0));
            }
            if ($profile['requireToolCalling'] && empty($model['toolCalling'])) {
                $blockers[] = 'ابزارفراخوانی (tool calling) ندارد';
            }
            if ($profile['requireVision'] && empty($model['vision'])) {
                $blockers[] = 'قابلیت بینایی ندارد';
            }
            if ($profile['requireEmbedding'] !== (bool) ($model['embedding'] ?? false)) {
                $blockers[] = $profile['requireEmbedding'] ? 'مدل امبدینگ نیست' : 'فقط مدل امبدینگ است و برای چت به کار نمی‌آید';
            }
            if ($profile['minTokensPerSec'] > 0 && $est['tokensPerSec'] < $profile['minTokensPerSec']) {
                $blockers[] = sprintf('سرعت تخمینی %.1f توکن/ثانیه کمتر از حداقل درخواستی است', $est['tokensPerSec']);
            }
            if (!$profile['allowNonCommercial'] && str_contains(strtoupper((string) ($model['license'] ?? '')), 'NC')) {
                $blockers[] = 'لایسنس غیرتجاری است';
            }

            if ($blockers) {
                $rejected[] = ['ref' => $v['ref'], 'name' => $v['name'], 'reasons' => $blockers, 'estimate' => $est];
                continue;
            }

            $rawQuality = (float) ($v['quality'] ?? 50);
            // Exponent > 1: a weak model has to be a *lot* faster to win.
            $quality = ($rawQuality / 100) ** 1.6;
            $speed = self::speedScore((float) $est['tokensPerSec']);
            $task = self::taskMatch($model, $profile['tasks']);
            $lang = self::languageScore($model, $profile['languages']);
            $ratio = $est['ramGb'] / max(0.1, (float) $profile['ramBudgetGb']);
            $fit = $ratio <= 0.85 ? ($ratio / 0.85) : max(0.0, 1 - ($ratio - 0.85) * 4);

            $score = $weights['quality'] * $quality
                + $weights['speed'] * $speed
                + $weights['task'] * $task
                + $weights['lang'] * $lang
                + $weights['fit'] * $fit;

            if (!empty($model['toolCalling']) && in_array('agent', $profile['tasks'], true)) {
                $score += 0.04;
                $reasons[] = 'ابزارفراخوانی رسمی دارد و با حلقهٔ عامل این برنامه سازگار است';
            }
            if ($est['gpuOffloadRatio'] >= 0.99) {
                $score += 0.03;
                $reasons[] = 'کاملاً روی GPU جا می‌شود';
            } elseif ($est['gpuOffloadRatio'] > 0.1) {
                $reasons[] = sprintf('حدود %d%% روی GPU بارگذاری می‌شود', (int) round($est['gpuOffloadRatio'] * 100));
            }
            if ($task >= 0.99) {
                $reasons[] = 'دقیقاً برای کاری که انتخاب کردید ساخته شده است';
            }
            if (in_array('fa', array_map('strtolower', $profile['languages']), true)) {
                $reasons[] = sprintf('امتیاز فارسی: %d از ۱۰۰', (int) ($model['faScore'] ?? 0));
            }
            $reasons[] = sprintf('حدود %.1f گیگ رم و %.1f گیگ دیسک؛ تقریباً %.0f توکن بر ثانیه',
                $est['ramGb'], $est['diskGb'], $est['tokensPerSec']);
            if (!empty($model['notes'])) {
                $reasons[] = (string) $model['notes'];
            }

            $ranked[] = [
                'ref' => $v['ref'],
                'modelId' => $v['modelId'],
                'tag' => (string) $v['tag'],
                'name' => $v['name'],
                'publisher' => (string) ($model['publisher'] ?? ''),
                'license' => (string) ($model['license'] ?? ''),
                'summary' => (string) ($model['summary'] ?? ''),
                'tasks' => (array) ($model['tasks'] ?? []),
                'contextMax' => (int) ($model['contextMax'] ?? 8192),
                'toolCalling' => (bool) ($model['toolCalling'] ?? false),
                'vision' => (bool) ($model['vision'] ?? false),
                'embedding' => (bool) ($model['embedding'] ?? false),
                'reasoning' => (bool) ($model['reasoning'] ?? false),
                'quant' => (string) ($v['quant'] ?? ''),
                'paramsB' => (float) ($v['paramsB'] ?? 0),
                'moe' => (bool) ($v['moe'] ?? false),
                'rawQuality' => $rawQuality,
                'score' => round($score, 4),
                'scorePct' => (int) round(min(100, $score * 100)),
                'breakdown' => [
                    'quality' => round($quality, 2), 'speed' => round($speed, 2),
                    'task' => round($task, 2), 'language' => round($lang, 2), 'fit' => round($fit, 2),
                ],
                'estimate' => $est,
                'reasons' => $reasons,
                'url' => (string) ($model['url'] ?? ''),
            ];
        }

        // Soft matching fallback: if strict criteria filtered out everything, relax constraints so user always gets actionable recommendations
        if (empty($ranked)) {
            foreach (self::variants() as $v) {
                $model = $v['model'];
                $est = self::estimate($v, $profile, $host);
                $softReasons = [];
                $penalty = 1.0;

                if (!$est['fitsRam']) {
                    $softReasons[] = sprintf('نیازمند %.1f گیگابایت رم (بودجه فعلی: %.1f گیگ)', $est['ramGb'], $profile['ramBudgetGb']);
                    $penalty *= max(0.2, 1.0 - (($est['ramGb'] - $profile['ramBudgetGb']) / max(1.0, $profile['ramBudgetGb'])));
                }
                if ($profile['contextTokens'] > (int) ($model['contextMax'] ?? 8192)) {
                    $softReasons[] = sprintf('پنجره کانتکست مدل به %d توکن محدود می‌شود', (int) ($model['contextMax'] ?? 8192));
                    $penalty *= 0.9;
                }
                if ($profile['requireToolCalling'] && empty($model['toolCalling'])) {
                    $softReasons[] = 'فاقد ابزارفراخوانی رسمی (پاسخ متنی و کدنویسی مستقیم)';
                    $penalty *= 0.7;
                }
                if ($profile['requireVision'] && empty($model['vision'])) {
                    $softReasons[] = 'فاقد قابلیت بینایی';
                    $penalty *= 0.7;
                }
                if ($profile['requireEmbedding'] !== (bool) ($model['embedding'] ?? false)) {
                    $softReasons[] = $profile['requireEmbedding'] ? 'مدل امبدینگ نیست' : 'فقط مدل امبدینگ است و برای چت/کدنویسی مناسب نیست';
                    $penalty *= 0.3;
                }

                $rawQuality = (float) ($v['quality'] ?? 50);
                $quality = ($rawQuality / 100) ** 1.6;
                $speed = self::speedScore((float) $est['tokensPerSec']);
                $task = self::taskMatch($model, $profile['tasks']);
                $lang = self::languageScore($model, $profile['languages']);
                $fit = 0.5;

                $score = ($weights['quality'] * $quality
                    + $weights['speed'] * $speed
                    + $weights['task'] * $task
                    + $weights['lang'] * $lang
                    + $weights['fit'] * $fit) * $penalty;

                $softReasons[] = sprintf('تخمین: %.1f گیگ رم · %.1f گیگ دیسک · تقریباً %.0f توکن بر ثانیه',
                    $est['ramGb'], $est['diskGb'], $est['tokensPerSec']);

                $ranked[] = [
                    'ref' => $v['ref'],
                    'modelId' => $v['modelId'],
                    'tag' => (string) $v['tag'],
                    'name' => $v['name'],
                    'publisher' => (string) ($model['publisher'] ?? ''),
                    'license' => (string) ($model['license'] ?? ''),
                    'summary' => (string) ($model['summary'] ?? ''),
                    'tasks' => (array) ($model['tasks'] ?? []),
                    'contextMax' => (int) ($model['contextMax'] ?? 8192),
                    'toolCalling' => (bool) ($model['toolCalling'] ?? false),
                    'vision' => (bool) ($model['vision'] ?? false),
                    'embedding' => (bool) ($model['embedding'] ?? false),
                    'reasoning' => (bool) ($model['reasoning'] ?? false),
                    'quant' => (string) ($v['quant'] ?? ''),
                    'paramsB' => (float) ($v['paramsB'] ?? 0),
                    'moe' => (bool) ($v['moe'] ?? false),
                    'rawQuality' => $rawQuality,
                    'score' => round($score, 4),
                    'scorePct' => (int) round(min(100, $score * 100)),
                    'breakdown' => [
                        'quality' => round($quality, 2), 'speed' => round($speed, 2),
                        'task' => round($task, 2), 'language' => round($lang, 2), 'fit' => round($fit, 2),
                    ],
                    'estimate' => $est,
                    'reasons' => $softReasons,
                    'url' => (string) ($model['url'] ?? ''),
                ];
            }
        }

        // Relative-quality demotion: when a clearly stronger model also fits the
        // budget, a toy-sized one must not win on raw speed alone.
        $bestQuality = 0.0;
        foreach ($ranked as $r) {
            $bestQuality = max($bestQuality, (float) $r['rawQuality']);
        }
        if ($bestQuality > 0) {
            foreach ($ranked as &$r) {
                $factor = 0.6 + 0.4 * ((float) $r['rawQuality'] / $bestQuality);
                $r['score'] = round($r['score'] * $factor, 4);
                $r['scorePct'] = (int) round(min(100, $r['score'] * 100));
                if ($factor < 0.85) {
                    $r['reasons'][] = 'در همین بودجه مدل قوی‌تری هم جا می‌شود؛ این گزینه فقط سریع‌تر است';
                }
            }
            unset($r);
        }

        usort($ranked, static fn(array $a, array $b): int => $b['score'] <=> $a['score']);
        usort($rejected, static fn(array $a, array $b): int => $a['estimate']['ramGb'] <=> $b['estimate']['ramGb']);

        return [
            'profile' => $profile,
            'host' => $host,
            'recommendations' => array_slice($ranked, 0, 12),
            'best' => $ranked[0] ?? null,
            'rejected' => array_slice($rejected, 0, 12),
            'totalEvaluated' => count($ranked) + count($rejected),
        ];
    }

    /* ================================================================== */
    /* Installed models                                                   */
    /* ================================================================== */

    public static function installed(): array
    {
        $up = self::serverUp();
        if (!$up['ok']) {
            return ['running' => false, 'models' => [], 'loaded' => [], 'error' => (string) ($up['error'] ?? '')];
        }
        $tags = HttpClient::getJson(self::host() . '/api/tags', [], 20);
        $ps = HttpClient::getJson(self::host() . '/api/ps', [], 10);
        $models = [];
        foreach ((array) ($tags['json']['models'] ?? []) as $m) {
            $models[] = [
                'name' => (string) ($m['name'] ?? ''),
                'sizeGb' => round(((float) ($m['size'] ?? 0)) / 1073741824, 2),
                'modifiedAt' => (string) ($m['modified_at'] ?? ''),
                'family' => (string) ($m['details']['family'] ?? ''),
                'parameterSize' => (string) ($m['details']['parameter_size'] ?? ''),
                'quantization' => (string) ($m['details']['quantization_level'] ?? ''),
                'digest' => substr((string) ($m['digest'] ?? ''), 0, 12),
            ];
        }
        $loaded = [];
        foreach ((array) ($ps['json']['models'] ?? []) as $m) {
            $loaded[] = [
                'name' => (string) ($m['name'] ?? ''),
                'sizeGb' => round(((float) ($m['size'] ?? 0)) / 1073741824, 2),
                'sizeVramGb' => round(((float) ($m['size_vram'] ?? 0)) / 1073741824, 2),
                'expiresAt' => (string) ($m['expires_at'] ?? ''),
            ];
        }
        return ['running' => true, 'version' => (string) ($up['version'] ?? ''), 'models' => $models, 'loaded' => $loaded, 'error' => ''];
    }

    public static function remove(string $model): array
    {
        $model = trim($model);
        if ($model === '') {
            throw new HttpError(400, 'Model name is required');
        }
        $r = HttpClient::request(
            'DELETE',
            self::host() . '/api/delete',
            ['Content-Type' => 'application/json'],
            (string) json_encode(['name' => $model]),
            60
        );
        if (!$r['ok']) {
            throw new HttpError(502, 'Delete failed: ' . ($r['error'] ?? ('HTTP ' . $r['status'])));
        }
        Observability::log('INFO', 'LOCALAI', 'Removed local model ' . $model);
        return ['ok' => true, 'removed' => $model];
    }

    /** Streamed `ollama pull` with NDJSON progress. */
    public static function pull(string $model, ?callable $onProgress = null, int $timeout = 7200): array
    {
        $buffer = '';
        $lastPct = -1.0;
        $status = '';
        $error = '';

        $res = HttpClient::stream(
            self::host() . '/api/pull',
            ['Accept' => 'application/x-ndjson'],
            (string) json_encode(['name' => $model, 'stream' => true]),
            static function (string $chunk) use (&$buffer, &$lastPct, &$status, &$error, $onProgress): bool {
                $buffer .= $chunk;
                while (($nl = strpos($buffer, "\n")) !== false) {
                    $line = trim(substr($buffer, 0, $nl));
                    $buffer = substr($buffer, $nl + 1);
                    if ($line === '') {
                        continue;
                    }
                    $j = json_decode($line, true);
                    if (!is_array($j)) {
                        continue;
                    }
                    if (!empty($j['error'])) {
                        $error = (string) $j['error'];
                        return false;
                    }
                    $status = (string) ($j['status'] ?? $status);
                    $total = (float) ($j['total'] ?? 0);
                    $done = (float) ($j['completed'] ?? 0);
                    $pct = $total > 0 ? round($done / $total * 100, 1) : $lastPct;
                    if ($onProgress !== null && ($pct !== $lastPct || $status !== '')) {
                        $onProgress($status, $pct < 0 ? 0.0 : $pct, $done, $total);
                    }
                    $lastPct = $pct;
                }
                return true;
            },
            $timeout
        );

        if ($error !== '') {
            throw new HttpError(502, 'Pull failed: ' . $error);
        }
        if (!$res['ok'] && !$res['aborted']) {
            throw new HttpError(502, 'Pull failed: ' . ($res['error'] ?? ('HTTP ' . $res['status'])));
        }
        return ['ok' => true, 'model' => $model, 'status' => $status ?: 'success', 'latencyMs' => $res['latencyMs']];
    }

    /**
     * Derive a tuned copy of a model with the context window and sampling the
     * wizard asked for, so the agent never has to pass them per request.
     */
    public static function tune(string $base, string $target, array $params): array
    {
        $body = ['model' => $target, 'from' => $base, 'parameters' => array_filter([
            'num_ctx' => (int) ($params['num_ctx'] ?? 0) ?: null,
            'temperature' => array_key_exists('temperature', $params) ? (float) $params['temperature'] : null,
            'top_p' => array_key_exists('top_p', $params) ? (float) $params['top_p'] : null,
            'repeat_penalty' => array_key_exists('repeat_penalty', $params) ? (float) $params['repeat_penalty'] : null,
        ], static fn($v): bool => $v !== null), 'stream' => false];
        if (!empty($params['system'])) {
            $body['system'] = (string) $params['system'];
        }
        $r = HttpClient::postJson(self::host() . '/api/create', $body, [], 900);
        if (!$r['ok']) {
            throw new HttpError(502, 'Tuning failed: ' . ($r['error'] ?? ('HTTP ' . $r['status'] . ' ' . mb_substr($r['body'], 0, 200))));
        }
        return ['ok' => true, 'model' => $target, 'from' => $base, 'parameters' => $body['parameters']];
    }

    /** Short generation used both as a smoke test and as a throughput measurement. */
    public static function benchmark(string $model, string $prompt = 'Say OK.', int $numPredict = 48): array
    {
        $started = microtime(true);
        $r = HttpClient::postJson(self::host() . '/api/generate', [
            'model' => $model,
            'prompt' => $prompt,
            'stream' => false,
            'options' => ['num_predict' => $numPredict],
        ], [], 600);
        $wall = round((microtime(true) - $started) * 1000, 1);
        if (!$r['ok']) {
            return ['ok' => false, 'model' => $model, 'error' => $r['error'] ?? ('HTTP ' . $r['status']), 'latencyMs' => $wall];
        }
        $j = (array) ($r['json'] ?? []);
        $evalCount = (int) ($j['eval_count'] ?? 0);
        $evalNs = (float) ($j['eval_duration'] ?? 0);
        return [
            'ok' => true,
            'model' => $model,
            'response' => mb_substr((string) ($j['response'] ?? ''), 0, 400),
            'tokens' => $evalCount,
            'tokensPerSec' => $evalNs > 0 ? round($evalCount / ($evalNs / 1e9), 1) : 0.0,
            'firstTokenMs' => round(((float) ($j['prompt_eval_duration'] ?? 0)) / 1e6, 1),
            'latencyMs' => $wall,
        ];
    }

    /* ================================================================== */
    /* Provider registration                                              */
    /* ================================================================== */

    /** Make the freshly pulled model selectable in the chat UI. */
    public static function registerProvider(string $modelRef, array $meta = []): array
    {
        $store = ProviderStore::reload();
        $provider = $store->get('ollama') ?? ProviderStore::normalizeProvider([
            'id' => 'ollama',
            'name' => 'Ollama (local)',
            'vendor' => 'ollama-models',
            'protocol' => 'ollama',
        ]);
        $provider['url'] = self::host();
        $provider['enabled'] = true;
        $provider['timeoutSec'] = max(300, (int) ($provider['timeoutSec'] ?? 120));

        $model = ProviderStore::normalizeModel([
            'id' => $modelRef,
            'name' => (string) ($meta['name'] ?? $modelRef),
            'toolCalling' => (bool) ($meta['toolCalling'] ?? false),
            'vision' => (bool) ($meta['vision'] ?? false),
            'free' => true,
            'maxInputTokens' => (int) ($meta['contextTokens'] ?? 8192),
            'maxOutputTokens' => (int) ($meta['maxOutputTokens'] ?? 4096),
            'enabled' => true,
            'extra' => ['local' => true, 'runtime' => 'ollama', 'installedAt' => gmdate('c')],
        ]);

        $models = [];
        $replaced = false;
        foreach ((array) ($provider['models'] ?? []) as $m) {
            if ((string) ($m['id'] ?? '') === $modelRef) {
                $models[] = $model;
                $replaced = true;
            } else {
                $models[] = $m;
            }
        }
        if (!$replaced) {
            $models[] = $model;
        }
        $provider['models'] = $models;

        $store->upsert($provider);
        Config::invalidate();
        Observability::log('INFO', 'LOCALAI', 'Registered local model as provider entry', ['model' => $modelRef]);
        return ['provider' => 'ollama', 'model' => $modelRef, 'url' => self::host()];
    }

    /* ================================================================== */
    /* Install pipeline (background job)                                  */
    /* ================================================================== */

    /** Validate a request and enqueue the job the worker will run. */
    public static function enqueueInstall(array $req, string $userId = 'user'): array
    {
        $ref = trim((string) ($req['ref'] ?? $req['model'] ?? ''));
        if ($ref === '') {
            throw new HttpError(400, 'A model reference (e.g. "qwen2.5-coder:7b") is required');
        }
        $profile = self::normalizeProfile((array) ($req['profile'] ?? []));

        $variant = null;
        foreach (self::variants() as $v) {
            if ($v['ref'] === $ref) {
                $variant = $v;
                break;
            }
        }
        $estimate = $variant !== null ? self::estimate($variant, $profile) : null;
        if ($estimate !== null && !$estimate['fitsRam'] && empty($req['force'])) {
            throw new HttpError(409, sprintf(
                'This model needs about %.1f GB of RAM but the budget is %.1f GB. Re-send with "force": true to override.',
                $estimate['ramGb'],
                $profile['ramBudgetGb']
            ));
        }

        $payload = [
            'kind' => 'localai_install',
            'ref' => $ref,
            'profile' => $profile,
            'estimate' => $estimate,
            'tune' => (bool) ($req['tune'] ?? true),
            'register' => (bool) ($req['register'] ?? true),
            'setDefault' => (bool) ($req['setDefault'] ?? false),
            'benchmark' => (bool) ($req['benchmark'] ?? true),
            'toolCalling' => (bool) ($variant['model']['toolCalling'] ?? ($req['toolCalling'] ?? false)),
            'vision' => (bool) ($variant['model']['vision'] ?? ($req['vision'] ?? false)),
            'displayName' => (string) ($variant['name'] ?? $ref),
        ];

        $job = Jobs::create([
            'title' => 'نصب مدل محلی: ' . $ref,
            'userId' => $userId,
            'providerId' => 'ollama',
            'modelId' => $ref,
            'maxSteps' => 6,
            'maxTimeoutSec' => (int) ($req['timeoutSec'] ?? 7200),
            'payload' => $payload,
        ]);

        return ['job' => $job, 'plan' => self::plan($payload), 'estimate' => $estimate, 'profile' => $profile];
    }

    /** Human-readable step list, shown in the UI before the user confirms. */
    public static function plan(array $payload): array
    {
        $rt = self::runtimeStatus();
        $steps = [];
        $steps[] = ['id' => 'runtime', 'title' => 'آماده‌سازی موتور Ollama',
                    'detail' => $rt['installed'] ? 'نصب است (' . ($rt['version'] ?: 'نسخهٔ نامشخص') . ')' : 'دانلود و نصب بدون نیاز به root در ' . self::binDir()];
        $steps[] = ['id' => 'server', 'title' => 'اجرای سرویس محلی', 'detail' => self::host() . ' با مدل‌های ' . self::modelsDir()];
        $steps[] = ['id' => 'pull', 'title' => 'دانلود مدل ' . (string) $payload['ref'],
                    'detail' => sprintf('حدود %.1f گیگابایت', (float) ($payload['estimate']['diskGb'] ?? 0))];
        if (!empty($payload['tune'])) {
            $steps[] = ['id' => 'tune', 'title' => 'ساخت نسخهٔ تنظیم‌شده',
                        'detail' => 'پنجرهٔ ' . (int) ($payload['profile']['contextTokens'] ?? 8192) . ' توکن'];
        }
        if (!empty($payload['benchmark'])) {
            $steps[] = ['id' => 'benchmark', 'title' => 'تست سلامت و سنجش سرعت', 'detail' => 'یک تولید کوتاه برای اندازه‌گیری توکن بر ثانیه'];
        }
        if (!empty($payload['register'])) {
            $steps[] = ['id' => 'register', 'title' => 'ثبت به‌عنوان ارائه‌دهنده', 'detail' => 'اضافه شدن به فهرست مدل‌های چت'];
        }
        return $steps;
    }

    /**
     * Executed by bin/worker.php (via Jobs::execute) — never in a web request.
     */
    public static function runInstallJob(string $jobId, array $payload): void
    {
        $ref = (string) ($payload['ref'] ?? '');
        $profile = (array) ($payload['profile'] ?? []);
        $log = static function (string $msg, string $level = 'INFO') use ($jobId): void {
            Jobs::log($jobId, $level, $msg);
        };
        $progress = static function (float $pct, string $summary = '') use ($jobId): void {
            Database::run(
                "UPDATE jobs SET progress = ?, summary = CASE WHEN ? = '' THEN summary ELSE ? END, updated_at = datetime('now') WHERE id = ?",
                [round($pct, 1), $summary, $summary, $jobId]
            );
        };
        $step = 0;
        $result = ['ref' => $ref, 'steps' => []];
        $started = microtime(true);

        try {
            /* 1 ─ runtime */
            $t = microtime(true);
            $log('Checking the local AI runtime…');
            $rt = self::installRuntime($log);
            Jobs::recordStep($jobId, $step++, 'localai.runtime', ['engine' => 'ollama'], $rt, 'success', (microtime(true) - $t) * 1000);
            $result['steps']['runtime'] = $rt;
            $progress(10, 'موتور محلی آماده شد');

            /* 2 ─ server */
            $t = microtime(true);
            $srv = self::startServer([
                'OLLAMA_NUM_PARALLEL' => (string) max(1, (int) ($profile['concurrency'] ?? 1)),
                'OLLAMA_CONTEXT_LENGTH' => (string) (int) ($profile['contextTokens'] ?? 8192),
            ], $log);
            Jobs::recordStep($jobId, $step++, 'localai.server', [], $srv, 'success', (microtime(true) - $t) * 1000);
            $result['steps']['server'] = $srv;
            $progress(15, 'سرویس محلی در حال اجراست');

            /* 3 ─ pull */
            $t = microtime(true);
            $log('Pulling ' . $ref . ' …');
            $lastLogged = 0.0;
            $pull = self::pull($ref, static function (string $status, float $pct, float $done, float $total) use ($progress, $log, &$lastLogged): void {
                $overall = 15 + ($pct * 0.65);
                $progress($overall, sprintf('دانلود مدل: %.0f%%', $pct));
                if ($pct - $lastLogged >= 10 || ($pct >= 100 && $lastLogged < 100)) {
                    $lastLogged = $pct;
                    $log(sprintf('%s — %.0f%% (%s / %s)', $status, $pct, Files::humanSize((int) $done), Files::humanSize((int) $total)));
                }
            });
            Jobs::recordStep($jobId, $step++, 'localai.pull', ['model' => $ref], $pull, 'success', (microtime(true) - $t) * 1000);
            $result['steps']['pull'] = $pull;
            $progress(80, 'مدل دانلود شد');

            /* 4 ─ tune */
            $finalRef = $ref;
            if (!empty($payload['tune'])) {
                $t = microtime(true);
                $target = preg_replace('/[^a-z0-9._-]+/i', '-', str_replace(':', '-', $ref)) . '-agent';
                try {
                    $tuned = self::tune($ref, $target, [
                        'num_ctx' => (int) ($profile['contextTokens'] ?? 8192),
                        'temperature' => 0.2,
                        'top_p' => 0.9,
                    ]);
                    $finalRef = $target;
                    $log('Tuned variant created: ' . $target);
                    Jobs::recordStep($jobId, $step++, 'localai.tune', ['from' => $ref], $tuned, 'success', (microtime(true) - $t) * 1000);
                    $result['steps']['tune'] = $tuned;
                } catch (\Throwable $e) {
                    $log('Tuning skipped: ' . $e->getMessage(), 'WARNING');
                    Jobs::recordStep($jobId, $step++, 'localai.tune', ['from' => $ref], ['error' => $e->getMessage()], 'error', (microtime(true) - $t) * 1000);
                }
            }
            $progress(86, 'نسخهٔ تنظیم‌شده آماده شد');

            /* 5 ─ benchmark */
            if (!empty($payload['benchmark'])) {
                $t = microtime(true);
                $bench = self::benchmark($finalRef, 'In one short sentence, say that the local model is ready.');
                $log($bench['ok']
                    ? sprintf('Benchmark: %.1f tok/s (%d tokens)', (float) ($bench['tokensPerSec'] ?? 0), (int) ($bench['tokens'] ?? 0))
                    : 'Benchmark failed: ' . (string) ($bench['error'] ?? ''), $bench['ok'] ? 'INFO' : 'WARNING');
                Jobs::recordStep($jobId, $step++, 'localai.benchmark', ['model' => $finalRef], $bench, $bench['ok'] ? 'success' : 'error', (microtime(true) - $t) * 1000);
                $result['steps']['benchmark'] = $bench;
            }
            $progress(93, 'تست سلامت انجام شد');

            /* 6 ─ register */
            if (!empty($payload['register'])) {
                $t = microtime(true);
                $reg = self::registerProvider($finalRef, [
                    'name' => (string) ($payload['displayName'] ?? $finalRef),
                    'toolCalling' => (bool) ($payload['toolCalling'] ?? false),
                    'vision' => (bool) ($payload['vision'] ?? false),
                    'contextTokens' => (int) ($profile['contextTokens'] ?? 8192),
                ]);
                if (!empty($payload['setDefault'])) {
                    Database::setState('localai:default', $finalRef);
                    Config::writeEnvironment(['OLLAMA_BASE_URL' => self::host()]);
                }
                Jobs::recordStep($jobId, $step++, 'localai.register', ['model' => $finalRef], $reg, 'success', (microtime(true) - $t) * 1000);
                $result['steps']['register'] = $reg;
            }

            $result['model'] = $finalRef;
            $result['durationSec'] = round(microtime(true) - $started, 1);
            $ref2 = Jobs::saveArtifact($jobId, $result);
            Database::run(
                "UPDATE jobs SET status='done', progress=100.0, step_count=?, result_ref=?, summary=?,
                 finished_at=datetime('now'), updated_at=datetime('now') WHERE id = ?",
                [$step, $ref2, 'مدل ' . $finalRef . ' با موفقیت نصب و فعال شد', $jobId]
            );
            $log('Local model install finished in ' . $result['durationSec'] . 's');
            Observability::log('INFO', 'LOCALAI', 'Local model installed', ['model' => $finalRef, 'job' => $jobId]);
        } catch (\Throwable $e) {
            $msg = $e->getMessage();
            Database::run(
                "UPDATE jobs SET status='failed', error=?, finished_at=datetime('now'), updated_at=datetime('now') WHERE id = ?",
                [$msg, $jobId]
            );
            $log('Install failed: ' . $msg, 'ERROR');
            Observability::log('ERROR', 'LOCALAI', 'Local model install failed', ['model' => $ref, 'error' => $msg]);
        }
    }

    /* ================================================================== */
    /* Saved wizard profiles                                              */
    /* ================================================================== */

    public static function saveProfile(string $name, array $profile): array
    {
        $all = (array) (Database::stateJson('localai:profiles', []) ?? []);
        $all[$name] = ['name' => $name, 'profile' => self::normalizeProfile($profile), 'savedAt' => gmdate('c')];
        Database::setStateJson('localai:profiles', $all);
        return ['profiles' => array_values($all)];
    }

    public static function profiles(): array
    {
        $all = (array) (Database::stateJson('localai:profiles', []) ?? []);
        return ['profiles' => array_values($all), 'default' => (string) Database::state('localai:default', '')];
    }

    public static function deleteProfile(string $name): array
    {
        $all = (array) (Database::stateJson('localai:profiles', []) ?? []);
        unset($all[$name]);
        Database::setStateJson('localai:profiles', $all);
        return ['profiles' => array_values($all)];
    }
}

/* ==========================================================================
 * FILE: Projects.php
 * ========================================================================== */
/**
 * Projects. Port of agent-python/app/projects.py.
 * The active project id lives in the `app_state` table.
 */

final class Projects
{
    public const ACTIVE_STATE_KEY = 'active_project_id';
    public const DEFAULT_ID = 'proj-default';

    private static function format(array $r): array
    {
        $r['code_generation_mode'] = (string) ($r['code_generation_mode'] ?? 'smart-auto');
        $r['env_vars'] = json_decode((string) ($r['env_vars'] ?? '{}'), true) ?: [];
        $r['custom_commands'] = json_decode((string) ($r['custom_commands'] ?? '[]'), true) ?: [];
        $r['is_default'] = (int) ($r['is_default'] ?? 0);
        return $r;
    }

    public static function active(): array
    {
        $pid = Database::state(self::ACTIVE_STATE_KEY, self::DEFAULT_ID);
        $row = Database::one('SELECT * FROM projects WHERE id = ?', [$pid])
            ?? Database::one('SELECT * FROM projects WHERE is_default = 1')
            ?? Database::one('SELECT * FROM projects ORDER BY created_at ASC LIMIT 1');

        if ($row !== null) {
            return self::format($row);
        }
        return [
            'id' => self::DEFAULT_ID,
            'name' => 'Primary Project',
            'description' => 'Primary coding workspace',
            'path' => Bootstrap::$workspacesDir . '/default',
            'git_url' => '',
            'default_branch' => 'main',
            'default_provider' => 'openrouter',
            'default_model' => '',
            'code_generation_mode' => 'smart-auto',
            'instructions' => '',
            'agent_rules' => '',
            'env_vars' => [],
            'custom_commands' => [],
            'is_default' => 1,
        ];
    }

    public static function setActive(string $projectId): array
    {
        $row = Database::one('SELECT * FROM projects WHERE id = ?', [$projectId]);
        if ($row === null) {
            throw new HttpError(404, 'Project not found');
        }
        Database::transaction(static function () use ($projectId): void {
            Database::run('UPDATE projects SET is_default = 0');
            Database::run("UPDATE projects SET is_default = 1, updated_at = datetime('now') WHERE id = ?", [$projectId]);
        });
        Database::setState(self::ACTIVE_STATE_KEY, $projectId);
        return self::format($row);
    }

    public static function all(): array
    {
        return array_map(
            [self::class, 'format'],
            Database::all('SELECT * FROM projects ORDER BY is_default DESC, created_at DESC')
        );
    }

    public static function find(string $projectId): ?array
    {
        $row = Database::one('SELECT * FROM projects WHERE id = ?', [$projectId]);
        return $row === null ? null : self::format($row);
    }

    public static function create(array $data): array
    {
        $projId = 'proj-' . time() . '-' . Crypto::hex(3);
        $path = (string) ($data['path'] ?? '');
        if ($path === '') {
            $path = Bootstrap::$workspacesDir . '/' . $projId;
        }
        Files::ensureDir($path);
        $codeMode = (string) ($data['codeGenerationMode'] ?? $data['code_generation_mode'] ?? 'smart-auto');

        Database::run(
            'INSERT INTO projects (
                id, name, description, path, git_url, default_branch, default_provider,
                default_model, code_generation_mode, instructions, agent_rules, env_vars, custom_commands, is_default
             ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,0)',
            [
                $projId,
                trim((string) ($data['name'] ?? 'New Project')),
                (string) ($data['description'] ?? ''),
                $path,
                (string) ($data['gitUrl'] ?? $data['git_url'] ?? ''),
                (string) ($data['defaultBranch'] ?? $data['default_branch'] ?? 'main'),
                (string) ($data['defaultProvider'] ?? $data['default_provider'] ?? 'openrouter'),
                (string) ($data['defaultModel'] ?? $data['default_model'] ?? ''),
                $codeMode,
                (string) ($data['instructions'] ?? ''),
                (string) ($data['agentRules'] ?? $data['agent_rules'] ?? ''),
                json_encode($data['envVars'] ?? $data['env_vars'] ?? [], JSON_UNESCAPED_UNICODE),
                json_encode($data['customCommands'] ?? $data['custom_commands'] ?? [], JSON_UNESCAPED_UNICODE),
            ]
        );

        // Projects get a matching workspace so the agent can work in them directly.
        Database::run(
            "INSERT OR IGNORE INTO workspaces (id, name, path, instructions, agent_rules, is_default)
             VALUES (?,?,?,?,?,0)",
            [
                $projId,
                trim((string) ($data['name'] ?? 'New Project')),
                $path,
                (string) ($data['instructions'] ?? ''),
                (string) ($data['agentRules'] ?? $data['agent_rules'] ?? ''),
            ]
        );

        Observability::log('INFO', 'PROJECT', "Created project {$projId}");
        return self::find($projId) ?? [];
    }

    public static function update(string $projectId, array $data): array
    {
        $current = self::find($projectId);
        if ($current === null) {
            throw new HttpError(404, 'Project not found');
        }
        $pick = static fn(mixed $incoming, mixed $fallback): mixed => $incoming ?? $fallback;

        Database::run(
            "UPDATE projects SET
                name = ?, description = ?, path = ?, git_url = ?, default_branch = ?,
                default_provider = ?, default_model = ?, code_generation_mode = ?, instructions = ?, agent_rules = ?,
                env_vars = ?, custom_commands = ?, updated_at = datetime('now')
             WHERE id = ?",
            [
                $pick($data['name'] ?? null, $current['name']),
                $pick($data['description'] ?? null, $current['description']),
                $pick($data['path'] ?? null, $current['path']),
                $pick($data['gitUrl'] ?? $data['git_url'] ?? null, $current['git_url']),
                $pick($data['defaultBranch'] ?? $data['default_branch'] ?? null, $current['default_branch']),
                $pick($data['defaultProvider'] ?? $data['default_provider'] ?? null, $current['default_provider']),
                $pick($data['defaultModel'] ?? $data['default_model'] ?? null, $current['default_model']),
                $pick($data['codeGenerationMode'] ?? $data['code_generation_mode'] ?? null, $current['code_generation_mode'] ?? 'smart-auto'),
                $pick($data['instructions'] ?? null, $current['instructions']),
                $pick($data['agentRules'] ?? $data['agent_rules'] ?? null, $current['agent_rules']),
                json_encode($pick($data['envVars'] ?? $data['env_vars'] ?? null, $current['env_vars']), JSON_UNESCAPED_UNICODE),
                json_encode($pick($data['customCommands'] ?? $data['custom_commands'] ?? null, $current['custom_commands']), JSON_UNESCAPED_UNICODE),
                $projectId,
            ]
        );
        return self::find($projectId) ?? [];
    }

    public static function delete(string $projectId): bool
    {
        $activeId = Database::state(self::ACTIVE_STATE_KEY, self::DEFAULT_ID);
        if ($projectId === $activeId) {
            throw new HttpError(400, 'Cannot delete the currently active project. Switch to another project first.');
        }
        return Database::run('DELETE FROM projects WHERE id = ?', [$projectId])->rowCount() > 0;
    }

    /** Resolve the workspace backing a project (its directory). */
    public static function workspaceFor(array $project): array
    {
        $ws = Workspaces::find((string) $project['id']);
        if ($ws !== null) {
            return $ws;
        }
        return [
            'id' => (string) $project['id'],
            'name' => (string) $project['name'],
            'path' => (string) $project['path'],
            'instructions' => (string) ($project['instructions'] ?? ''),
            'agent_rules' => (string) ($project['agent_rules'] ?? ''),
            'is_default' => 0,
        ];
    }
}

/* ==========================================================================
 * FILE: Workspaces.php
 * ========================================================================== */
/**
 * Workspace registry and file operations. Port of agent-python/app/workspaces.py.
 *
 * Unlike the Workers build (R2 object keys), a workspace here is a real
 * directory on disk, so `git`, `python`, `node` and the terminal all operate on
 * exactly the same bytes the UI edits.
 */

final class Workspaces
{
    public const ACTIVE_STATE_KEY = 'active_workspace_id';
    public const DEFAULT_ID = 'default';

    public const TEMPLATES = [
        'fastapi' => 'FastAPI service',
        'python-cli' => 'Python CLI tool',
        'node-vite' => 'Node + Vite frontend',
        'worker' => 'Cloudflare Worker',
    ];

    // ------------------------------------------------------------ registry

    public static function fallback(): array
    {
        return [
            'id' => self::DEFAULT_ID,
            'name' => 'Main Project',
            'path' => Bootstrap::$workspacesDir . '/default',
            'instructions' => '',
            'agent_rules' => '',
            'is_default' => 1,
        ];
    }

    public static function find(string $id): ?array
    {
        return Database::one(
            'SELECT id, name, path, instructions, agent_rules, is_default, created_at FROM workspaces WHERE id = ?',
            [$id]
        );
    }

    public static function active(): array
    {
        $id = Database::state(self::ACTIVE_STATE_KEY, self::DEFAULT_ID);
        $row = self::find((string) $id);
        if ($row === null) {
            $row = Database::one(
                'SELECT id, name, path, instructions, agent_rules, is_default, created_at FROM workspaces WHERE is_default = 1'
            );
        }
        return $row ?? self::fallback();
    }

    public static function setActive(string $workspaceId): array
    {
        $row = self::find($workspaceId);
        if ($row === null) {
            throw new HttpError(404, 'Workspace not found');
        }
        Database::setState(self::ACTIVE_STATE_KEY, $workspaceId);
        self::ensureRoot($row);
        return $row;
    }

    public static function all(): array
    {
        return Database::all(
            'SELECT id, name, path, instructions, agent_rules, is_default, created_at FROM workspaces ORDER BY is_default DESC, created_at ASC'
        );
    }

    public static function create(string $name, string $template = '', string $instructions = '', string $agentRules = ''): array
    {
        $name = trim($name);
        if ($name === '') {
            throw new HttpError(400, 'Workspace name is required');
        }
        $slug = strtolower((string) preg_replace('/[^a-zA-Z0-9\-_]+/', '-', $name));
        $slug = trim($slug, '-') ?: 'workspace';
        $id = $slug . '-' . Crypto::hex(3);
        $path = Bootstrap::$workspacesDir . '/' . $id;
        Files::ensureDir($path);

        Database::run(
            'INSERT INTO workspaces (id, name, path, instructions, agent_rules, is_default) VALUES (?,?,?,?,?,0)',
            [$id, $name, $path, $instructions, $agentRules]
        );
        if ($template !== '') {
            self::applyTemplate($path, $template, $name);
        }
        Observability::log('INFO', 'WORKSPACE', "Created workspace {$id}", ['template' => $template]);
        return self::find($id) ?? self::fallback();
    }

    public static function delete(string $id): void
    {
        if ($id === self::DEFAULT_ID) {
            throw new HttpError(400, 'The default workspace cannot be deleted');
        }
        $ws = self::find($id);
        if ($ws === null) {
            throw new HttpError(404, 'Workspace not found');
        }
        Files::deleteTree(self::root($ws));
        Database::run('DELETE FROM workspaces WHERE id = ?', [$id]);
        Database::run('DELETE FROM file_versions WHERE workspace_id = ?', [$id]);
        Database::run('DELETE FROM changesets WHERE workspace_id = ?', [$id]);
        if (Database::state(self::ACTIVE_STATE_KEY) === $id) {
            Database::setState(self::ACTIVE_STATE_KEY, self::DEFAULT_ID);
        }
    }

    public static function sessionWorkspaceId(string $sessionId): string
    {
        $clean = (string) preg_replace('/[^a-zA-Z0-9\-_]/', '', $sessionId);
        return 'session_' . ($clean !== '' ? $clean : 'conv_' . time());
    }

    /** Port of workspaces.get_or_create_session_workspace. */
    public static function getOrCreateSessionWorkspace(string $sessionId, string $title = ''): array
    {
        $wsId = self::sessionWorkspaceId($sessionId);
        $row = self::find($wsId);
        if ($row === null) {
            $label = $title !== '' ? $title : substr(str_replace('session_', '', $wsId), 0, 8);
            $path = Bootstrap::$workspacesDir . '/' . $wsId;
            Files::ensureDir($path);
            Database::run(
                "INSERT OR IGNORE INTO workspaces (id, name, path, instructions, agent_rules, is_default)
                 VALUES (?,?,?,'','',0)",
                [$wsId, "Session Workspace ({$label})", $path]
            );
            $row = self::find($wsId);
        }
        Database::setState(self::ACTIVE_STATE_KEY, $wsId);
        $row ??= self::fallback();
        self::ensureRoot($row);
        return $row;
    }

    /** Port of workspaces.reset_session_workspace — wipe the directory, keep the row. */
    public static function resetSessionWorkspace(string $sessionId): array
    {
        $ws = self::getOrCreateSessionWorkspace($sessionId);
        $root = self::ensureRoot($ws);
        $removed = 0;
        foreach (scandir($root) ?: [] as $entry) {
            if ($entry === '.' || $entry === '..') {
                continue;
            }
            $removed += Files::deleteTree($root . '/' . $entry);
        }
        Database::run('DELETE FROM file_versions WHERE workspace_id = ?', [$ws['id']]);
        Database::run('DELETE FROM changesets WHERE workspace_id = ?', [$ws['id']]);
        Observability::log('INFO', 'WORKSPACE', "Reset session workspace {$ws['id']} ({$removed} entries)");
        return ['ok' => true, 'workspace' => $ws, 'removed' => $removed] + $ws;
    }

    /**
     * Resolve which workspace a request targets: explicit id > conversation
     * scoped workspace > active workspace.
     */
    public static function resolve(?string $workspaceId = null, ?string $conversationId = null): array
    {
        if ($workspaceId !== null && $workspaceId !== '') {
            $row = self::find($workspaceId);
            if ($row !== null) {
                self::ensureRoot($row);
                return $row;
            }
        }
        if ($conversationId !== null && $conversationId !== '') {
            $wsId = self::sessionWorkspaceId($conversationId);
            $row = self::find($wsId);
            if ($row !== null) {
                self::ensureRoot($row);
                return $row;
            }
        }
        $active = self::active();
        self::ensureRoot($active);
        return $active;
    }

    /** Same resolution, from a Request's usual query/body parameters. */
    public static function forRequest(Request $req): array
    {
        $wsId = $req->str('workspace_id', '') ?: $req->str('workspaceId', '');
        $conv = $req->str('conversation_id', '') ?: $req->str('session_id', '');
        return self::resolve($wsId !== '' ? $wsId : null, $conv !== '' ? $conv : null);
    }

    // ------------------------------------------------------------- paths

    public static function root(array $ws): string
    {
        $path = (string) ($ws['path'] ?? '');
        // Legacy rows created by the Cloudflare build used `r2://ws/<id>`.
        if ($path === '' || str_starts_with($path, 'r2://')) {
            $path = Bootstrap::$workspacesDir . '/' . ($ws['id'] ?? self::DEFAULT_ID);
        }
        return rtrim($path, '/');
    }

    public static function ensureRoot(array $ws): string
    {
        $root = self::root($ws);
        Files::ensureDir($root);
        return $root;
    }

    /** Port of workspaces.safe_path: absolute path guaranteed inside the root. */
    public static function safePath(array $ws, ?string $rel): string
    {
        $root = self::ensureRoot($ws);
        $norm = Files::normalizeRel($rel);
        $abs = $norm === '' ? $root : $root . '/' . $norm;
        $realRoot = realpath($root) ?: $root;
        $probe = $abs;
        while (!file_exists($probe) && strlen($probe) > strlen($realRoot)) {
            $probe = dirname($probe);
        }
        $realProbe = realpath($probe) ?: $probe;
        if ($realProbe !== $realRoot && !str_starts_with($realProbe, $realRoot . DIRECTORY_SEPARATOR)) {
            throw new HttpError(400, "Path traversal detected: '{$rel}' is outside the workspace root");
        }
        return $abs;
    }

    // ------------------------------------------------------- file actions

    public static function readFile(array $ws, string $rel): array
    {
        $abs = self::safePath($ws, $rel);
        if (!is_file($abs)) {
            throw new HttpError(404, 'File not found');
        }
        $content = Files::read($abs);
        return [
            'path' => Files::normalizeRel($rel),
            'content' => $content,
            'size' => strlen($content),
        ];
    }

    public static function writeFile(array $ws, string $rel, string $content, string $author = 'agent'): array
    {
        $norm = Files::normalizeRel($rel);
        if ($norm === '') {
            throw new HttpError(400, 'Cannot write to the workspace root');
        }
        $abs = self::safePath($ws, $norm);
        $existed = is_file($abs);
        if ($existed) {
            self::snapshotVersion($ws, $norm, Files::read($abs), $author);
        }
        $size = Files::write($abs, $content);
        return ['ok' => true, 'path' => $norm, 'size' => $size, 'created' => !$existed];
    }

    public static function createEntry(array $ws, string $rel, bool $isDir, string $content = ''): array
    {
        $norm = Files::normalizeRel($rel);
        if ($norm === '') {
            throw new HttpError(400, 'A path is required');
        }
        $abs = self::safePath($ws, $norm);
        if (file_exists($abs)) {
            throw new HttpError(400, 'Path already exists');
        }
        if ($isDir) {
            Files::ensureDir($abs);
            $size = 0;
        } else {
            $size = Files::write($abs, $content);
        }
        return [
            'ok' => true,
            'path' => $norm,
            'type' => $isDir ? 'dir' : 'file',
            'isDir' => $isDir,
            'created' => true,
            'size' => $size,
        ];
    }

    public static function rename(array $ws, string $from, string $to): array
    {
        $fromNorm = Files::normalizeRel($from);
        $toNorm = Files::normalizeRel($to);
        if ($fromNorm === '' || $toNorm === '') {
            throw new HttpError(400, 'Both old_path and new_path are required');
        }
        $fromAbs = self::safePath($ws, $fromNorm);
        $toAbs = self::safePath($ws, $toNorm);
        if (!file_exists($fromAbs)) {
            throw new HttpError(404, 'Source path not found');
        }
        if (file_exists($toAbs)) {
            throw new HttpError(400, 'Target path already exists');
        }
        Files::ensureDir(dirname($toAbs));
        if (!@rename($fromAbs, $toAbs)) {
            throw new HttpError(500, 'Rename failed');
        }
        Database::run(
            'UPDATE file_versions SET path = ? WHERE workspace_id = ? AND path = ?',
            [$toNorm, $ws['id'], $fromNorm]
        );
        return [
            'ok' => true,
            'old_path' => $fromNorm,
            'new_path' => $toNorm,
            'type' => is_dir($toAbs) ? 'dir' : 'file',
            'isDir' => is_dir($toAbs),
        ];
    }

    public static function deletePath(array $ws, string $rel): array
    {
        $norm = Files::normalizeRel($rel);
        if ($norm === '') {
            throw new HttpError(400, 'Refusing to delete the workspace root');
        }
        $abs = self::safePath($ws, $norm);
        if (!file_exists($abs)) {
            throw new HttpError(404, 'Path not found');
        }
        $isDir = is_dir($abs);
        $removed = Files::deleteTree($abs);
        return ['ok' => true, 'path' => $norm, 'type' => $isDir ? 'dir' : 'file', 'removed' => $removed];
    }

    // ---------------------------------------------------------- versions

    public static function snapshotVersion(array $ws, string $rel, string $content, string $author = 'agent', ?string $changesetId = null): string
    {
        $next = (int) Database::scalar(
            'SELECT COALESCE(MAX(version_num), 0) + 1 FROM file_versions WHERE workspace_id = ? AND path = ?',
            [$ws['id'], $rel]
        );
        $id = Database::id('fv');
        Database::run(
            'INSERT INTO file_versions (id, workspace_id, path, version_num, content, created_by, changeset_id)
             VALUES (?,?,?,?,?,?,?)',
            [$id, $ws['id'], $rel, $next, $content, $author, $changesetId]
        );
        // Keep history bounded like the Python version did (50 newest per file).
        Database::run(
            'DELETE FROM file_versions WHERE workspace_id = ? AND path = ? AND id NOT IN (
                SELECT id FROM file_versions WHERE workspace_id = ? AND path = ?
                ORDER BY version_num DESC LIMIT 50)',
            [$ws['id'], $rel, $ws['id'], $rel]
        );
        return $id;
    }

    public static function versions(array $ws, string $rel): array
    {
        return Database::all(
            'SELECT id, path, version_num, created_by, changeset_id, created_at, LENGTH(content) AS size
             FROM file_versions WHERE workspace_id = ? AND path = ? ORDER BY version_num DESC',
            [$ws['id'], Files::normalizeRel($rel)]
        );
    }

    public static function version(string $id): ?array
    {
        return Database::one('SELECT * FROM file_versions WHERE id = ?', [$id]);
    }

    public static function rollback(array $ws, string $versionId, string $author = 'agent'): array
    {
        $v = self::version($versionId);
        if ($v === null || $v['workspace_id'] !== $ws['id']) {
            throw new HttpError(404, 'Version not found');
        }
        $abs = self::safePath($ws, $v['path']);
        if (is_file($abs)) {
            self::snapshotVersion($ws, $v['path'], Files::read($abs), $author);
        }
        Files::write($abs, (string) $v['content']);
        return ['ok' => true, 'path' => $v['path'], 'restored_version' => (int) $v['version_num']];
    }

    // --------------------------------------------------------- templates

    private static function applyTemplate(string $root, string $template, string $name): void
    {
        $files = match ($template) {
            'fastapi' => [
                'main.py' => "from fastapi import FastAPI\n\napp = FastAPI(title=\"{$name}\")\n\n\n@app.get(\"/\")\ndef read_root():\n    return {\"status\": \"ok\"}\n",
                'requirements.txt' => "fastapi\nuvicorn[standard]\n",
                'README.md' => "# {$name}\n\nRun with:\n\n```bash\nuvicorn main:app --reload\n```\n",
            ],
            'python-cli' => [
                'main.py' => "import argparse\n\n\ndef main() -> None:\n    parser = argparse.ArgumentParser(description=\"{$name}\")\n    parser.add_argument(\"--name\", default=\"world\")\n    args = parser.parse_args()\n    print(f\"Hello, {args.name}!\")\n\n\nif __name__ == \"__main__\":\n    main()\n",
                'README.md' => "# {$name}\n\n```bash\npython main.py --name you\n```\n",
            ],
            'node-vite' => [
                'package.json' => json_encode([
                    'name' => strtolower((string) preg_replace('/[^a-z0-9\-]+/i', '-', $name)),
                    'private' => true,
                    'version' => '0.1.0',
                    'type' => 'module',
                    'scripts' => ['dev' => 'vite', 'build' => 'vite build', 'preview' => 'vite preview'],
                    'devDependencies' => ['vite' => '^5.0.0'],
                ], JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES) . "\n",
                'index.html' => "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\" />\n    <title>{$name}</title>\n  </head>\n  <body>\n    <div id=\"app\"></div>\n    <script type=\"module\" src=\"/src/main.js\"></script>\n  </body>\n</html>\n",
                'src/main.js' => "document.querySelector('#app').textContent = 'Hello from {$name}';\n",
            ],
            'worker' => [
                'src/index.js' => "export default {\n  async fetch(request, env, ctx) {\n    return new Response('Hello from {$name}');\n  },\n};\n",
                'wrangler.toml' => "name = \"" . strtolower((string) preg_replace('/[^a-z0-9\-]+/i', '-', $name)) . "\"\nmain = \"src/index.js\"\ncompatibility_date = \"2024-01-01\"\n",
            ],
            default => [],
        };
        foreach ($files as $rel => $content) {
            Files::write($root . '/' . $rel, $content);
        }
    }

    // ------------------------------------------------------------- stats

    public static function stats(array $ws): array
    {
        $root = self::ensureRoot($ws);
        $size = Files::dirSize($root);
        $total = @disk_total_space($root) ?: 0;
        $free = @disk_free_space($root) ?: 0;
        return [
            'workspaceId' => $ws['id'],
            'root' => $root,
            'files' => $size['files'],
            'directories' => $size['dirs'],
            'bytes' => $size['bytes'],
            'humanSize' => Files::humanSize($size['bytes']),
            'diskTotalBytes' => (int) $total,
            'diskFreeBytes' => (int) $free,
            'diskUsedBytes' => (int) ($total - $free),
        ];
    }
}

/* ==========================================================================
 * FILE: References.php
 * ========================================================================== */
/**
 * Cross-chat / cross-project file references.
 * Port of the reference helpers in agent-python/app/workspaces.py.
 */

final class References
{
    /** Port of workspaces.resolve_reference_root — returns the backing workspace record. */
    public static function resolveWorkspace(string $targetType, string $targetId): array
    {
        $t = strtolower(trim($targetType));
        $id = trim($targetId);

        if (in_array($t, ['chat', 'session', 'conversation'], true)) {
            $clean = (string) preg_replace('/^session_/', '', $id);
            $wsId = 'session_' . $clean;
            $ws = Workspaces::find($wsId);
            if ($ws !== null) {
                return $ws;
            }
            $conv = Database::one('SELECT id FROM conversations WHERE id = ? OR title = ?', [$id, $id]);
            if ($conv !== null) {
                $wsId = 'session_' . preg_replace('/^session_/', '', (string) $conv['id']);
                $ws = Workspaces::find($wsId);
                if ($ws !== null) {
                    return $ws;
                }
            }
            return Workspaces::getOrCreateSessionWorkspace($clean);
        }

        if (in_array($t, ['project', 'proj'], true)) {
            if ($id === '' || $id === 'default' || $id === 'proj-default') {
                return Workspaces::find(Workspaces::DEFAULT_ID) ?? Workspaces::fallback();
            }
            $proj = Database::one('SELECT id, path FROM projects WHERE id = ? OR name = ?', [$id, $id]);
            if ($proj !== null) {
                $ws = Workspaces::find((string) $proj['id']);
                if ($ws !== null) {
                    return $ws;
                }
                // Projects carry their own directory; expose it as an ad-hoc workspace record.
                $path = (string) $proj['path'];
                if ($path !== '' && !str_starts_with($path, 'r2://')) {
                    return [
                        'id' => 'proj_' . $proj['id'],
                        'name' => 'Project ' . $proj['id'],
                        'path' => $path,
                        'instructions' => '',
                        'agent_rules' => '',
                        'is_default' => 0,
                    ];
                }
            }
            $ws = Workspaces::find($id);
            if ($ws !== null) {
                return $ws;
            }
            return Workspaces::find(Workspaces::DEFAULT_ID) ?? Workspaces::fallback();
        }

        if (str_starts_with($id, 'session_') || str_starts_with($id, 'conv-')) {
            return Workspaces::getOrCreateSessionWorkspace((string) preg_replace('/^session_/', '', $id));
        }
        return Workspaces::find(Workspaces::DEFAULT_ID) ?? Workspaces::fallback();
    }

    public static function listFiles(string $targetType, string $targetId, string $subpath = '.'): array
    {
        $ws = self::resolveWorkspace($targetType, $targetId);
        $root = Workspaces::ensureRoot($ws);
        return Files::listRecursive($root, Files::normalizeRel($subpath));
    }

    public static function readFile(string $targetType, string $targetId, string $filePath): string
    {
        $ws = self::resolveWorkspace($targetType, $targetId);
        $abs = Workspaces::safePath($ws, $filePath);
        if (!is_file($abs)) {
            throw new HttpError(404, "Referenced file not found: {$filePath} in {$targetType}:{$targetId}");
        }
        return Files::read($abs);
    }

    public static function copyFile(
        string $targetType,
        string $targetId,
        string $sourcePath,
        ?string $destPath,
        array $activeWorkspace
    ): array {
        $srcWs = self::resolveWorkspace($targetType, $targetId);
        $srcAbs = Workspaces::safePath($srcWs, $sourcePath);
        if (!file_exists($srcAbs)) {
            throw new HttpError(404, "Referenced path not found: {$sourcePath}");
        }
        $dest = $destPath !== null && $destPath !== ''
            ? Files::normalizeRel($destPath)
            : Files::basename(Files::normalizeRel($sourcePath));
        $destAbs = Workspaces::safePath($activeWorkspace, $dest);
        $isDir = is_dir($srcAbs);
        $copied = Files::copyTree($srcAbs, $destAbs);

        return [
            'ok' => true,
            'copied' => true,
            'type' => $isDir ? 'directory' : 'file',
            'source' => $sourcePath,
            'dest' => $dest,
            'bytes' => $isDir ? Files::dirSize($destAbs)['bytes'] : (int) (@filesize($destAbs) ?: 0),
            'files' => $copied,
            'targetType' => $targetType,
            'targetId' => $targetId,
        ];
    }

    // ------------------------------------------------- conversation links

    public static function add(string $convId, string $targetType, string $targetId, string $title = ''): array
    {
        $t = strtolower(trim($targetType));
        $id = trim($targetId);
        $refTitle = $title;

        if ($refTitle === '') {
            if ($t === 'chat') {
                $r = Database::one('SELECT title FROM conversations WHERE id = ?', [preg_replace('/^session_/', '', $id)]);
                $refTitle = $r['title'] ?? "Chat {$id}";
            } elseif ($t === 'project') {
                $r = Database::one('SELECT name FROM projects WHERE id = ? OR name = ?', [$id, $id]);
                $refTitle = $r['name'] ?? "Project {$id}";
            } else {
                $refTitle = "{$t}:{$id}";
            }
        }

        Database::run('INSERT OR IGNORE INTO conversations (id, title) VALUES (?,?)', [$convId, "Chat {$convId}"]);

        $existing = Database::one(
            'SELECT id FROM conversation_references WHERE conversation_id = ? AND target_type = ? AND target_id = ?',
            [$convId, $t, $id]
        );
        if ($existing !== null) {
            return [
                'id' => $existing['id'],
                'conversation_id' => $convId,
                'target_type' => $t,
                'target_id' => $id,
                'title' => $refTitle,
                'already_linked' => true,
            ];
        }

        $refId = 'ref_' . Crypto::hex(6);
        Database::run(
            'INSERT INTO conversation_references (id, conversation_id, target_type, target_id, title) VALUES (?,?,?,?,?)',
            [$refId, $convId, $t, $id, $refTitle]
        );
        return [
            'id' => $refId,
            'conversation_id' => $convId,
            'target_type' => $t,
            'target_id' => $id,
            'title' => $refTitle,
        ];
    }

    public static function remove(string $convId, string $targetType, string $targetId): array
    {
        Database::run(
            'DELETE FROM conversation_references WHERE conversation_id = ? AND target_type = ? AND target_id = ?',
            [$convId, $targetType, $targetId]
        );
        return ['ok' => true, 'removed' => "{$targetType}:{$targetId}"];
    }

    public static function forConversation(string $convId, bool $withFiles = true): array
    {
        $rows = Database::all(
            'SELECT id, conversation_id, target_type, target_id, title, created_at
             FROM conversation_references WHERE conversation_id = ? ORDER BY created_at ASC',
            [$convId]
        );
        foreach ($rows as &$ref) {
            if (!$withFiles) {
                continue;
            }
            try {
                $files = self::listFiles((string) $ref['target_type'], (string) $ref['target_id']);
                $ref['file_count'] = count(array_filter($files, static fn(array $f): bool => $f['type'] === 'file'));
                $ref['files'] = $files;
            } catch (\Throwable) {
                $ref['file_count'] = 0;
                $ref['files'] = [];
            }
        }
        return $rows;
    }

    /** `@chat:<id>/path` / `@project:<id>/path` prefix parsing. */
    public static function parsePrefixed(string $path): ?array
    {
        $raw = trim($path);
        if (!preg_match('#^@(chat|project|session|conversation|proj):([^/]+)(?:/(.*))?$#', $raw, $m)) {
            return null;
        }
        return ['targetType' => $m[1], 'targetId' => $m[2], 'subpath' => $m[3] ?? '.'];
    }

    /** `/api/references/search` — LIKE search over chats and projects, limit 10. */
    public static function search(string $query): array
    {
        $q = '%' . strtolower(trim($query)) . '%';
        $chats = Database::all(
            'SELECT id, title, created_at FROM conversations WHERE lower(title) LIKE ? OR lower(id) LIKE ?
             ORDER BY updated_at DESC LIMIT 10',
            [$q, $q]
        );
        $projects = Database::all(
            'SELECT id, name, description FROM projects WHERE lower(name) LIKE ? OR lower(id) LIKE ?
             ORDER BY created_at DESC LIMIT 10',
            [$q, $q]
        );
        return ['chats' => $chats, 'projects' => $projects];
    }
}

/* ==========================================================================
 * FILE: ChangeSets.php
 * ========================================================================== */
/**
 * ChangeSets, approvals, file version history, locks and rollbacks.
 * Port of agent-python/app/changesets.py. Files live on the real filesystem,
 * metadata in SQLite.
 */

final class ChangeSets
{
    // ------------------------------------------------------------- locks

    public static function acquireLock(string $relPath, string $userId, int $ttlSeconds = 300): bool
    {
        $now = microtime(true);
        $expires = $now + $ttlSeconds;
        $row = Database::one('SELECT locked_by, expires_at FROM file_locks WHERE path = ?', [$relPath]);
        if ($row !== null) {
            if ((float) $row['expires_at'] > $now && $row['locked_by'] !== $userId) {
                return false;
            }
            Database::run(
                'UPDATE file_locks SET locked_by = ?, locked_at = ?, expires_at = ? WHERE path = ?',
                [$userId, $now, $expires, $relPath]
            );
            return true;
        }
        Database::run(
            'INSERT INTO file_locks (path, locked_by, locked_at, expires_at) VALUES (?,?,?,?)',
            [$relPath, $userId, $now, $expires]
        );
        return true;
    }

    public static function releaseLock(string $relPath, string $userId): bool
    {
        Database::run(
            'DELETE FROM file_locks WHERE path = ? AND (locked_by = ? OR expires_at < ?)',
            [$relPath, $userId, microtime(true)]
        );
        return true;
    }

    public static function locks(): array
    {
        return Database::all('SELECT path, locked_by, locked_at, expires_at FROM file_locks ORDER BY locked_at DESC');
    }

    // ---------------------------------------------------------- versions

    public static function saveVersion(
        array $ws,
        string $relPath,
        string $content,
        string $createdBy = '',
        ?string $changesetId = null
    ): string {
        return Workspaces::snapshotVersion($ws, Files::normalizeRel($relPath), $content, $createdBy, $changesetId);
    }

    public static function compareVersions(string $relPath, string $v1Id, string $v2Id): array
    {
        $r1 = Database::one('SELECT content, version_num FROM file_versions WHERE id = ?', [$v1Id]);
        $r2 = Database::one('SELECT content, version_num FROM file_versions WHERE id = ?', [$v2Id]);
        if ($r1 === null || $r2 === null) {
            throw new HttpError(404, 'One or both version records not found');
        }
        return [
            'path' => $relPath,
            'v1' => ['id' => $v1Id, 'version_num' => (int) $r1['version_num']],
            'v2' => ['id' => $v2Id, 'version_num' => (int) $r2['version_num']],
            'diff' => Diff::compute(
                (string) $r1['content'],
                (string) $r2['content'],
                sprintf('%s (v%d -> v%d)', $relPath, (int) $r1['version_num'], (int) $r2['version_num'])
            ),
        ];
    }

    // -------------------------------------------------------- changesets

    public static function create(array $ws, string $title, array $files, string $createdBy = 'agent'): array
    {
        $csId = 'cs-' . time() . '-' . Crypto::hex(3);
        Database::run(
            "INSERT INTO changesets (id, workspace_id, title, status, created_by) VALUES (?,?,?,'pending',?)",
            [$csId, $ws['id'], $title, $createdBy]
        );

        $createdFiles = [];
        foreach ($files as $f) {
            $relPath = ltrim(trim((string) ($f['path'] ?? '')), '/');
            if ($relPath === '') {
                continue;
            }
            $newContent = (string) ($f['new_content'] ?? $f['content'] ?? '');
            $abs = Workspaces::safePath($ws, $relPath);
            $exists = is_file($abs);
            $oldContent = $exists ? Files::read($abs) : '';

            $changeType = (string) ($f['change_type'] ?? '');
            if ($changeType === '') {
                if (!$exists) {
                    $changeType = 'added';
                } elseif ($newContent === '' && $oldContent !== '') {
                    $changeType = 'deleted';
                } else {
                    $changeType = 'modified';
                }
            }

            $diff = Diff::compute($oldContent, $newContent, $relPath);
            $fileId = 'cf-' . Crypto::hex(4);
            Database::run(
                "INSERT INTO changeset_files (id, changeset_id, path, old_content, new_content, diff, change_type, status)
                 VALUES (?,?,?,?,?,?,?,'pending')",
                [$fileId, $csId, $relPath, $oldContent, $newContent, $diff, $changeType]
            );
            $createdFiles[] = [
                'id' => $fileId,
                'path' => $relPath,
                'change_type' => $changeType,
                'diff' => $diff,
                'old_size' => strlen($oldContent),
                'new_size' => strlen($newContent),
            ];
        }

        return [
            'id' => $csId,
            'title' => $title,
            'status' => 'pending',
            'created_by' => $createdBy,
            'files' => $createdFiles,
            'created_at' => Database::now(),
        ];
    }

    public static function get(string $csId): ?array
    {
        $cs = Database::one(
            'SELECT id, workspace_id, title, status, created_by, approved_by, created_at, updated_at
             FROM changesets WHERE id = ?',
            [$csId]
        );
        if ($cs === null) {
            return null;
        }
        $cs['files'] = Database::all(
            'SELECT id, changeset_id, path, old_content, new_content, diff, change_type, status, applied_at
             FROM changeset_files WHERE changeset_id = ?',
            [$csId]
        );
        return $cs;
    }

    public static function listFor(string $workspaceId, int $limit = 50): array
    {
        return Database::all(
            'SELECT c.id, c.workspace_id, c.title, c.status, c.created_by, c.approved_by,
                    c.created_at, c.updated_at,
                    (SELECT COUNT(*) FROM changeset_files f WHERE f.changeset_id = c.id) AS file_count
             FROM changesets c WHERE c.workspace_id = ? ORDER BY c.created_at DESC LIMIT ?',
            [$workspaceId, $limit]
        );
    }

    public static function approveFile(array $ws, string $csId, string $fileId, string $approvedBy = 'user'): array
    {
        $f = Database::one(
            'SELECT id, changeset_id, path, old_content, new_content, change_type, status
             FROM changeset_files WHERE id = ? AND changeset_id = ?',
            [$fileId, $csId]
        );
        if ($f === null) {
            throw new HttpError(404, 'File change not found');
        }

        $relPath = (string) $f['path'];
        $abs = Workspaces::safePath($ws, $relPath);
        if (is_file($abs)) {
            self::saveVersion($ws, $relPath, (string) $f['old_content'], "before-{$csId}", $csId);
        }

        if ($f['change_type'] === 'deleted') {
            if (file_exists($abs)) {
                Files::deleteTree($abs);
            }
        } else {
            Files::write($abs, (string) $f['new_content']);
        }

        self::saveVersion($ws, $relPath, (string) $f['new_content'], $approvedBy, $csId);
        Database::run(
            "UPDATE changeset_files SET status = 'approved', applied_at = datetime('now') WHERE id = ?",
            [$fileId]
        );

        $statuses = array_column(
            Database::all('SELECT status FROM changeset_files WHERE changeset_id = ?', [$csId]),
            'status'
        );
        $newStatus = 'pending';
        if ($statuses && count(array_filter($statuses, static fn($s): bool => $s === 'approved')) === count($statuses)) {
            $newStatus = 'approved';
        } elseif (in_array('approved', $statuses, true)) {
            $newStatus = 'partially_approved';
        }
        Database::run(
            "UPDATE changesets SET status = ?, approved_by = ?, updated_at = datetime('now') WHERE id = ?",
            [$newStatus, $approvedBy, $csId]
        );

        return ['ok' => true, 'file_id' => $fileId, 'path' => $relPath, 'status' => 'approved'];
    }

    public static function rejectFile(string $csId, string $fileId): array
    {
        Database::run(
            "UPDATE changeset_files SET status = 'rejected' WHERE id = ? AND changeset_id = ?",
            [$fileId, $csId]
        );
        $statuses = array_column(
            Database::all('SELECT status FROM changeset_files WHERE changeset_id = ?', [$csId]),
            'status'
        );
        if ($statuses && count(array_filter($statuses, static fn($s): bool => $s === 'rejected')) === count($statuses)) {
            Database::run("UPDATE changesets SET status = 'rejected', updated_at = datetime('now') WHERE id = ?", [$csId]);
        }
        return ['ok' => true, 'file_id' => $fileId, 'status' => 'rejected'];
    }

    public static function approve(array $ws, string $csId, string $approvedBy = 'user'): array
    {
        $cs = self::get($csId);
        if ($cs === null) {
            throw new HttpError(404, 'ChangeSet not found');
        }
        $applied = [];
        foreach ($cs['files'] as $f) {
            if ($f['status'] !== 'rejected') {
                $res = self::approveFile($ws, $csId, (string) $f['id'], $approvedBy);
                $applied[] = $res['path'];
            }
        }
        Database::run(
            "UPDATE changesets SET status = 'approved', approved_by = ?, updated_at = datetime('now') WHERE id = ?",
            [$approvedBy, $csId]
        );
        return ['ok' => true, 'changeset_id' => $csId, 'status' => 'approved', 'applied_files' => $applied];
    }

    public static function reject(string $csId, string $feedback = ''): array
    {
        Database::run("UPDATE changeset_files SET status = 'rejected' WHERE changeset_id = ?", [$csId]);
        Database::run("UPDATE changesets SET status = 'rejected', updated_at = datetime('now') WHERE id = ?", [$csId]);
        $out = ['ok' => true, 'changeset_id' => $csId, 'status' => 'rejected'];
        if ($feedback !== '') {
            $out['feedback'] = $feedback;
        }
        return $out;
    }

    public static function rollback(array $ws, string $csId): array
    {
        $cs = self::get($csId);
        if ($cs === null) {
            throw new HttpError(404, 'ChangeSet not found');
        }
        $reverted = [];
        foreach ($cs['files'] as $f) {
            if ($f['status'] !== 'approved') {
                continue;
            }
            $abs = Workspaces::safePath($ws, (string) $f['path']);
            if ($f['change_type'] === 'added') {
                if (file_exists($abs)) {
                    Files::deleteTree($abs);
                }
            } else {
                Files::write($abs, (string) $f['old_content']);
            }
            self::saveVersion($ws, (string) $f['path'], (string) $f['old_content'], "rollback-{$csId}");
            $reverted[] = $f['path'];
        }
        Database::run("UPDATE changesets SET status = 'rolled_back', updated_at = datetime('now') WHERE id = ?", [$csId]);
        return ['ok' => true, 'changeset_id' => $csId, 'status' => 'rolled_back', 'reverted_files' => $reverted];
    }

    public static function exportPatch(string $csId): string
    {
        $cs = self::get($csId);
        if ($cs === null) {
            throw new HttpError(404, 'ChangeSet not found');
        }
        $parts = [];
        foreach ($cs['files'] as $f) {
            $parts[] = $f['diff'] !== ''
                ? $f['diff']
                : Diff::compute((string) $f['old_content'], (string) $f['new_content'], (string) $f['path']);
        }
        return implode("\n", $parts);
    }

    /** Port of workflow.preview. */
    public static function previewFileChange(array $ws, string $path, string $content): array
    {
        $abs = Workspaces::safePath($ws, $path);
        $exists = is_file($abs);
        $oldContent = $exists ? Files::read($abs) : '';
        $diff = Diff::compute($oldContent, $content, $path);
        return [
            'path' => $path,
            'exists' => $exists,
            'changed' => $oldContent !== $content,
            'diff' => $diff,
            'hunks' => Diff::parseHunks($diff),
        ];
    }

    /** Port of workflow.backup. */
    public static function backupFile(array $ws, string $path): string
    {
        $abs = Workspaces::safePath($ws, $path);
        if (!is_file($abs)) {
            return '';
        }
        return self::saveVersion($ws, $path, Files::read($abs), 'backup');
    }
}

/* ==========================================================================
 * FILE: Conversations.php
 * ========================================================================== */
/**
 * Conversations, messages and resumable checkpoints.
 * Port of the conversation helpers in agent-python/app/{main,chat}.py.
 */

final class Conversations
{
    public static function ensure(string $id, string $title = '', string $providerId = '', string $modelId = ''): void
    {
        if ($id === '') {
            return;
        }
        Database::run(
            'INSERT OR IGNORE INTO conversations (id, title, provider_id, model_id) VALUES (?,?,?,?)',
            [$id, $title !== '' ? $title : "Chat {$id}", $providerId, $modelId]
        );
    }

    public static function all(int $limit = 200): array
    {
        return Database::all(
            'SELECT c.id, c.workspace_id, c.user_id, c.title, c.provider_id, c.model_id, c.created_at, c.updated_at,
                    (SELECT COUNT(*) FROM messages m WHERE m.conversation_id = c.id) AS message_count
             FROM conversations c ORDER BY c.updated_at DESC LIMIT ?',
            [$limit]
        );
    }

    public static function find(string $id): ?array
    {
        return Database::one('SELECT * FROM conversations WHERE id = ?', [$id]);
    }

    public static function create(array $data): array
    {
        $id = (string) ($data['id'] ?? Database::id('conv'));
        Database::run(
            'INSERT OR REPLACE INTO conversations (id, workspace_id, user_id, title, provider_id, model_id, updated_at)
             VALUES (?,?,?,?,?,?,datetime(\'now\'))',
            [
                $id,
                (string) ($data['workspace_id'] ?? ''),
                (string) ($data['user_id'] ?? ''),
                (string) ($data['title'] ?? "Chat {$id}"),
                (string) ($data['provider_id'] ?? ''),
                (string) ($data['model_id'] ?? ''),
            ]
        );
        return self::find($id) ?? ['id' => $id];
    }

    public static function update(string $id, array $data): array
    {
        $fields = [];
        $params = [];
        foreach (['title', 'provider_id', 'model_id', 'workspace_id'] as $col) {
            if (array_key_exists($col, $data)) {
                $fields[] = "{$col} = ?";
                $params[] = (string) $data[$col];
            }
        }
        if ($fields) {
            $params[] = $id;
            Database::run(
                'UPDATE conversations SET ' . implode(', ', $fields) . ", updated_at = datetime('now') WHERE id = ?",
                $params
            );
        }
        return self::find($id) ?? ['id' => $id];
    }

    public static function delete(string $id): array
    {
        Database::run('DELETE FROM messages WHERE conversation_id = ?', [$id]);
        Database::run('DELETE FROM conversation_references WHERE conversation_id = ?', [$id]);
        Database::run('DELETE FROM conversation_checkpoints WHERE conversation_id = ?', [$id]);
        Database::run('DELETE FROM conversations WHERE id = ?', [$id]);
        return ['ok' => true, 'deleted' => $id];
    }

    // ---------------------------------------------------------- messages

    public static function messages(string $conversationId, int $limit = 500): array
    {
        return Database::all(
            'SELECT id, conversation_id, role, content, tool_calls, tool_call_id, created_at
             FROM messages WHERE conversation_id = ? ORDER BY created_at ASC, rowid ASC LIMIT ?',
            [$conversationId, $limit]
        );
    }

    public static function addMessage(string $conversationId, array $message): string
    {
        self::ensure($conversationId);
        $id = Database::id('msg');
        Database::run(
            'INSERT INTO messages (id, conversation_id, role, content, tool_calls, tool_call_id) VALUES (?,?,?,?,?,?)',
            [
                $id,
                $conversationId,
                (string) ($message['role'] ?? 'user'),
                (string) ($message['content'] ?? ''),
                isset($message['tool_calls']) ? json_encode($message['tool_calls'], JSON_UNESCAPED_UNICODE) : null,
                $message['tool_call_id'] ?? null,
            ]
        );
        Database::run("UPDATE conversations SET updated_at = datetime('now') WHERE id = ?", [$conversationId]);
        return $id;
    }

    // ------------------------------------------------------- checkpoints

    public static function saveCheckpoint(array $input): string
    {
        $conversationId = (string) ($input['conversationId'] ?? '');
        if ($conversationId === '') {
            return '';
        }
        $cpId = 'cp-' . time() . '-' . Crypto::hex(3);
        try {
            self::ensure($conversationId, 'Conversation', (string) ($input['providerId'] ?? ''), (string) ($input['modelId'] ?? ''));
            Database::run(
                "INSERT INTO conversation_checkpoints (
                    id, conversation_id, step_index, provider_id, model_id,
                    accumulated_content, accumulated_reasoning,
                    chat_history_json, saved_files_json, execution_results_json,
                    status, error_message, updated_at
                 ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,datetime('now'))",
                [
                    $cpId,
                    $conversationId,
                    (int) ($input['stepIndex'] ?? 0),
                    (string) ($input['providerId'] ?? ''),
                    (string) ($input['modelId'] ?? ''),
                    (string) ($input['accumulatedContent'] ?? ''),
                    (string) ($input['accumulatedReasoning'] ?? ''),
                    json_encode($input['chatHistory'] ?? [], JSON_UNESCAPED_UNICODE),
                    json_encode($input['savedFiles'] ?? [], JSON_UNESCAPED_UNICODE),
                    json_encode($input['executionResults'] ?? [], JSON_UNESCAPED_UNICODE),
                    (string) ($input['status'] ?? 'in_progress'),
                    (string) ($input['errorMessage'] ?? ''),
                ]
            );
            return $cpId;
        } catch (\Throwable) {
            return '';
        }
    }

    private static function mapCheckpoint(array $r): array
    {
        $parse = static function (?string $s, mixed $default): mixed {
            $decoded = json_decode((string) $s, true);
            return $decoded === null ? $default : $decoded;
        };
        return [
            'id' => $r['id'],
            'conversationId' => $r['conversation_id'],
            'stepIndex' => (int) $r['step_index'],
            'providerId' => $r['provider_id'],
            'modelId' => $r['model_id'],
            'accumulatedContent' => $r['accumulated_content'],
            'accumulatedReasoning' => $r['accumulated_reasoning'],
            'chatHistory' => $parse($r['chat_history_json'] ?? null, []),
            'savedFiles' => $parse($r['saved_files_json'] ?? null, []),
            'executionResults' => $parse($r['execution_results_json'] ?? null, []),
            'status' => $r['status'],
            'errorMessage' => $r['error_message'],
            'updatedAt' => $r['updated_at'],
        ];
    }

    public static function latestCheckpoint(string $conversationId): ?array
    {
        if ($conversationId === '') {
            return null;
        }
        $row = Database::one(
            'SELECT * FROM conversation_checkpoints WHERE conversation_id = ?
             ORDER BY step_index DESC, updated_at DESC, id DESC LIMIT 1',
            [$conversationId]
        );
        return $row === null ? null : self::mapCheckpoint($row);
    }

    public static function checkpoints(string $conversationId, int $limit = 20): array
    {
        if ($conversationId === '') {
            return [];
        }
        $rows = Database::all(
            'SELECT * FROM conversation_checkpoints WHERE conversation_id = ?
             ORDER BY step_index DESC, updated_at DESC, id DESC LIMIT ?',
            [$conversationId, $limit]
        );
        return array_map([self::class, 'mapCheckpoint'], $rows);
    }

    public static function clearCheckpoints(string $conversationId): void
    {
        if ($conversationId === '') {
            return;
        }
        try {
            Database::run('DELETE FROM conversation_checkpoints WHERE conversation_id = ?', [$conversationId]);
        } catch (\Throwable) {
        }
    }
}

/* ==========================================================================
 * FILE: AgentTools.php
 * ========================================================================== */
/**
 * The OpenAI tool-calling surface exposed to the model, plus its execution
 * engine. Port of agent-python/app/agent_tools.py.
 *
 * `run_command` is a REAL shell here, so the tool descriptions no longer warn
 * the model away from python/node/pytest — it can actually run them.
 */

final class ToolContext
{
    public function __construct(
        public array $workspace,
        public ?string $conversationId = null,
        public string $userId = 'agent'
    ) {
    }
}

final class AgentTools
{
    public static function definitions(): array
    {
        $caps = Bootstrap::capabilities();
        $runtimes = array_values(array_filter([
            $caps['python'] ? 'python3' : null,
            $caps['node'] ? 'node' : null,
            'php',
            $caps['bash'] ? 'bash' : null,
            $caps['git'] ? 'git' : null,
            $caps['npm'] ? 'npm' : null,
        ]));

        return [
            [
                'type' => 'function',
                'function' => [
                    'name' => 'list_files',
                    'description' => 'List files and directories in the active project workspace.',
                    'parameters' => [
                        'type' => 'object',
                        'properties' => [
                            'path' => ['type' => 'string', 'description' => "Subdirectory to list (defaults to workspace root '.')."],
                        ],
                        'required' => [],
                    ],
                ],
            ],
            [
                'type' => 'function',
                'function' => [
                    'name' => 'read_file',
                    'description' => 'Read text content of a workspace file.',
                    'parameters' => [
                        'type' => 'object',
                        'properties' => [
                            'path' => ['type' => 'string', 'description' => 'Relative file path inside the workspace.'],
                        ],
                        'required' => ['path'],
                    ],
                ],
            ],
            [
                'type' => 'function',
                'function' => [
                    'name' => 'write_file',
                    'description' => 'Write or update a file in the workspace. Staged for diff approval if approval is enabled.',
                    'parameters' => [
                        'type' => 'object',
                        'properties' => [
                            'path' => ['type' => 'string', 'description' => 'Relative file path inside the workspace.'],
                            'content' => ['type' => 'string', 'description' => 'Complete file content to write.'],
                        ],
                        'required' => ['path', 'content'],
                    ],
                ],
            ],
            [
                'type' => 'function',
                'function' => [
                    'name' => 'run_command',
                    'description' => 'Run a real shell command inside the workspace. Available runtimes on this host: '
                        . (implode(', ', $runtimes) ?: 'shell built-ins only')
                        . '. Use it to install dependencies, run tests, start builds and verify your own code.',
                    'parameters' => [
                        'type' => 'object',
                        'properties' => [
                            'command' => ['type' => 'string', 'description' => 'Command to run.'],
                            'cwd' => ['type' => 'string', 'description' => "Working directory relative to workspace root (defaults to '.')."],
                            'timeout' => ['type' => 'integer', 'description' => 'Timeout in seconds (max 300).'],
                        ],
                        'required' => ['command'],
                    ],
                ],
            ],
            [
                'type' => 'function',
                'function' => [
                    'name' => 'browser_navigate',
                    'description' => 'Load a web page and retrieve its title, text content and links (Playwright when installed, otherwise HTTP + DOM extraction).',
                    'parameters' => [
                        'type' => 'object',
                        'properties' => ['url' => ['type' => 'string', 'description' => 'HTTP or HTTPS URL to load.']],
                        'required' => ['url'],
                    ],
                ],
            ],
            [
                'type' => 'function',
                'function' => [
                    'name' => 'http_request',
                    'description' => 'Perform a raw HTTP(S) GET against any URL and return the response body.',
                    'parameters' => [
                        'type' => 'object',
                        'properties' => ['url' => ['type' => 'string', 'description' => 'HTTP or HTTPS URL to request.']],
                        'required' => ['url'],
                    ],
                ],
            ],
            [
                'type' => 'function',
                'function' => [
                    'name' => 'git_status',
                    'description' => 'Get the git status of the active workspace (real `git status`).',
                    'parameters' => ['type' => 'object', 'properties' => new \stdClass(), 'required' => []],
                ],
            ],
            [
                'type' => 'function',
                'function' => [
                    'name' => 'git_diff',
                    'description' => 'Get the git diff of the active workspace (real `git diff`).',
                    'parameters' => [
                        'type' => 'object',
                        'properties' => [
                            'staged_only' => ['type' => 'boolean', 'description' => 'Only show staged changes.'],
                        ],
                        'required' => [],
                    ],
                ],
            ],
            [
                'type' => 'function',
                'function' => [
                    'name' => 'list_referenced_files',
                    'description' => 'List files from another referenced chat session or project workspace.',
                    'parameters' => [
                        'type' => 'object',
                        'properties' => [
                            'target_type' => ['type' => 'string', 'enum' => ['chat', 'project']],
                            'target_id' => ['type' => 'string', 'description' => 'Chat session ID/title or Project ID/name.'],
                            'path' => ['type' => 'string', 'description' => "Subdirectory to list (defaults to root '.')."],
                        ],
                        'required' => ['target_type', 'target_id'],
                    ],
                ],
            ],
            [
                'type' => 'function',
                'function' => [
                    'name' => 'read_referenced_file',
                    'description' => 'Read the complete text content of a file from a referenced chat session or project workspace.',
                    'parameters' => [
                        'type' => 'object',
                        'properties' => [
                            'target_type' => ['type' => 'string', 'enum' => ['chat', 'project']],
                            'target_id' => ['type' => 'string'],
                            'path' => ['type' => 'string', 'description' => 'Relative path in that referenced workspace.'],
                        ],
                        'required' => ['target_type', 'target_id', 'path'],
                    ],
                ],
            ],
            [
                'type' => 'function',
                'function' => [
                    'name' => 'copy_referenced_file',
                    'description' => 'Copy a file or directory from a referenced chat session or project workspace into the active workspace.',
                    'parameters' => [
                        'type' => 'object',
                        'properties' => [
                            'target_type' => ['type' => 'string', 'enum' => ['chat', 'project']],
                            'target_id' => ['type' => 'string'],
                            'source_path' => ['type' => 'string'],
                            'dest_path' => ['type' => 'string', 'description' => 'Optional destination in the active workspace.'],
                        ],
                        'required' => ['target_type', 'target_id', 'source_path'],
                    ],
                ],
            ],
        ];
    }

    // ------------------------------------------------------------- tools

    public static function listFiles(ToolContext $ctx, string $path = '.'): array
    {
        $ref = References::parsePrefixed($path);
        if ($ref !== null) {
            return References::listFiles($ref['targetType'], $ref['targetId'], $ref['subpath']);
        }
        return Files::listDir(Workspaces::ensureRoot($ctx->workspace), Files::normalizeRel($path));
    }

    public static function readFile(ToolContext $ctx, string $path): string
    {
        $ref = References::parsePrefixed($path);
        if ($ref !== null) {
            return References::readFile($ref['targetType'], $ref['targetId'], $ref['subpath']);
        }
        $abs = Workspaces::safePath($ctx->workspace, $path);
        if (!is_file($abs)) {
            throw new HttpError(404, "File not found: {$path}");
        }
        return Files::read($abs);
    }

    public static function writeFile(ToolContext $ctx, string $path, string $content, ?bool $requireApproval = null): array
    {
        $relPath = Files::normalizeRel($path);
        if ($relPath === '') {
            throw new HttpError(400, 'A file path is required');
        }
        $approvalNeeded = $requireApproval ?? Config::fileApprovalRequired();
        $abs = Workspaces::safePath($ctx->workspace, $relPath);
        $exists = is_file($abs);

        if ($approvalNeeded) {
            $cs = ChangeSets::create(
                $ctx->workspace,
                "Agent edit: {$relPath}",
                [['path' => $relPath, 'new_content' => $content, 'change_type' => $exists ? 'modified' : 'added']],
                'agent'
            );
            return [
                'status' => 'pending_approval',
                'requiresApproval' => true,
                'changesetId' => $cs['id'],
                'path' => $relPath,
                'diff' => $cs['files'][0]['diff'] ?? '',
                'message' => "Change to '{$relPath}' is staged in ChangeSet {$cs['id']} and requires user approval before applying.",
            ];
        }

        if ($exists) {
            ChangeSets::saveVersion($ctx->workspace, $relPath, Files::read($abs), 'before-direct-write');
        }
        $bytes = Files::write($abs, $content);
        ChangeSets::saveVersion($ctx->workspace, $relPath, $content, 'agent-direct');

        return [
            'status' => 'applied',
            'path' => $relPath,
            'bytes' => $bytes,
            'message' => "File '{$relPath}' saved successfully.",
        ];
    }

    public static function runCommand(ToolContext $ctx, string $command, string $cwd = '.', int $timeout = 60, bool $confirmed = false): array
    {
        $root = Workspaces::ensureRoot($ctx->workspace);
        $target = $cwd === '' || $cwd === '.' ? $root : Workspaces::safePath($ctx->workspace, $cwd);
        return Terminal::execute($command, $target, $timeout, $confirmed, $ctx->userId);
    }

    // -------------------------------------------------------- dispatcher

    public static function execute(ToolContext $ctx, string $name, array $args): mixed
    {
        return match ($name) {
            'list_files' => self::listFiles($ctx, (string) ($args['path'] ?? '.')),
            'read_file' => self::readFile($ctx, (string) ($args['path'] ?? '')),
            'write_file' => self::writeFile($ctx, (string) ($args['path'] ?? ''), (string) ($args['content'] ?? '')),
            'list_referenced_files' => References::listFiles(
                (string) ($args['target_type'] ?? 'chat'),
                (string) ($args['target_id'] ?? ''),
                (string) ($args['path'] ?? '.')
            ),
            'read_referenced_file' => References::readFile(
                (string) ($args['target_type'] ?? 'chat'),
                (string) ($args['target_id'] ?? ''),
                (string) ($args['path'] ?? '')
            ),
            'copy_referenced_file' => References::copyFile(
                (string) ($args['target_type'] ?? 'chat'),
                (string) ($args['target_id'] ?? ''),
                (string) ($args['source_path'] ?? ''),
                isset($args['dest_path']) ? (string) $args['dest_path'] : null,
                $ctx->workspace
            ),
            'run_command' => self::runCommand(
                $ctx,
                (string) ($args['command'] ?? ''),
                (string) ($args['cwd'] ?? '.'),
                (int) ($args['timeout'] ?? 60),
                (bool) ($args['confirmed'] ?? false)
            ),
            'browser_navigate' => Browser::navigate((string) ($args['url'] ?? '')),
            'http_request' => Browser::fetchUrl((string) ($args['url'] ?? '')),
            'git_status' => Git::status(Workspaces::ensureRoot($ctx->workspace)),
            'git_diff' => Git::diff((bool) ($args['staged_only'] ?? false), null, Workspaces::ensureRoot($ctx->workspace)),
            default => throw new HttpError(400, "Unknown agent tool: {$name}"),
        };
    }
}

/* ==========================================================================
 * FILE: Chat.php
 * ========================================================================== */
/**
 * The LLM engine: multi-protocol provider adapter, SSE streaming, the
 * tool-calling agent loop, automatic provider fallback, checkpointing and the
 * self-healing execution loop. Port of agent-python/app/chat.py.
 *
 * Python async generators map onto PHP Generators; `httpx` streaming maps onto
 * a curl_multi pump so tokens can be yielded while the socket is still open.
 */

final class Chat
{
    public const MAX_STEPS_STREAM = 30;
    public const MAX_STEPS_SYNC = 8;
    public const MAX_ATTEMPTS = 10;

    /* ---------------------------------------------------------------- */
    /* System prompt                                                     */
    /* ---------------------------------------------------------------- */

    public static function buildSystemPrompt(
        ?string $conversationId = null,
        ?array $referencedItems = null,
        ?array $messages = null,
        ?array $workspace = null
    ): string {
        $proj = Projects::active();
        $ws = $workspace ?? Workspaces::active();
        $caps = Bootstrap::capabilities();

        $runtimes = [];
        foreach (['python' => 'python3', 'node' => 'node', 'npm' => 'npm', 'git' => 'git', 'bash' => 'bash', 'docker' => 'docker', 'composer' => 'composer'] as $k => $label) {
            if (!empty($caps[$k])) {
                $runtimes[] = $label;
            }
        }
        $runtimes[] = 'php ' . $caps['phpVersion'];

        $prompt = "You are an expert AI Coding Agent running in the Arena Agent environment, deployed as a "
            . "self-hosted PHP application on a real server with shell access. You have full access to the "
            . "workspace filesystem, a real terminal, an HTTP/browser tool with unrestricted external web "
            . "access, and a real local `git` checkout.\n\n"
            . 'Active Project: ' . ($proj['name'] ?? 'Main Project') . "\n";

        if (!empty($proj['description'])) {
            $prompt .= 'Project Description: ' . $proj['description'] . "\n";
        }
        if (!empty($proj['path'])) {
            $prompt .= 'Project Workspace: ' . $proj['path'] . "\n";
        }
        if (!empty($proj['default_branch'])) {
            $prompt .= 'Target Git Branch: ' . $proj['default_branch'] . "\n";
        }

        $ins = $proj['instructions'] ?: ($ws['instructions'] ?? '');
        if ($ins) {
            $prompt .= "\nProject Instructions & Guidelines:\n{$ins}\n";
        }
        $rules = $proj['agent_rules'] ?: ($ws['agent_rules'] ?? '');
        if ($rules) {
            $prompt .= "\nAgent Rules & Constraints:\n{$rules}\n";
        }

        // Gather references (explicit + @chat:/@project: mentions).
        $refs = array_values($referencedItems ?? []);
        if ($conversationId !== null && $conversationId !== '' && !$refs) {
            try {
                $refs = References::forConversation($conversationId, false);
            } catch (\Throwable) {
                $refs = [];
            }
        }

        if ($messages) {
            foreach ($messages as $m) {
                $content = is_array($m) ? (string) ($m['content'] ?? '') : (string) $m;
                foreach ([['chat', '/@chat:([a-zA-Z0-9_\-]+)/'], ['project', '/@project:([a-zA-Z0-9_\-]+)/']] as [$type, $re]) {
                    if (preg_match_all($re, $content, $mm)) {
                        foreach ($mm[1] as $id) {
                            $known = false;
                            foreach ($refs as $r) {
                                if (($r['target_id'] ?? '') === $id) {
                                    $known = true;
                                    break;
                                }
                            }
                            if ($known) {
                                continue;
                            }
                            $refs[] = ['target_type' => $type, 'target_id' => $id, 'title' => ucfirst($type) . ' ' . $id];
                            if ($conversationId !== null && $conversationId !== '') {
                                try {
                                    References::add($conversationId, $type, $id);
                                } catch (\Throwable) {
                                }
                            }
                        }
                    }
                }
            }
        }

        if ($refs) {
            $prompt .= "\n\n### 🔗 Referenced Chats & Projects (Cross-Session File Access):\n"
                . "This chat references the following other chats and projects. You have FULL permission and "
                . "ability to inspect, read, and copy files from them into the active workspace using the "
                . "`read_referenced_file`, `list_referenced_files`, and `copy_referenced_file` tools (or by "
                . "prefixing paths with `@chat:<id>/path` or `@project:<id>/path`):\n";
            foreach ($refs as $r) {
                $tType = (string) ($r['target_type'] ?? 'chat');
                $tId = (string) ($r['target_id'] ?? '');
                $title = (string) ($r['title'] ?: $tId);
                $prompt .= '- [' . strtoupper($tType) . "] Reference '{$title}' (ID: `{$tId}`):\n";
                try {
                    $files = References::listFiles($tType, $tId, '.');
                    $names = [];
                    foreach ($files as $f) {
                        if (($f['type'] ?? '') === 'file') {
                            $names[] = $f['path'];
                        }
                        if (count($names) >= 15) {
                            break;
                        }
                    }
                    $prompt .= $names
                        ? '  Files (' . count($names) . '): ' . implode(', ', $names) . "\n"
                        : "  Files: (empty or newly created)\n";
                } catch (\Throwable $e) {
                    $prompt .= '  Files: (unable to list: ' . $e->getMessage() . ")\n";
                }
            }
        }

        $codeMode = (string) ($proj['code_generation_mode'] ?? 'smart-auto');
        if ($codeMode === 'single-file') {
            $prompt .= "\n### 📄 CODE GENERATION STRATEGY: SINGLE-FILE (SELF-CONTAINED):\n"
                . "- The project/user is configured for SINGLE-FILE code generation.\n"
                . "- Always generate fully self-contained, standalone single-file code without external local dependencies.\n"
                . "- For HTML / Web applications: Embed ALL CSS in `<style>` tags and ALL JavaScript in `<script>` tags inside the single HTML file (`index.html`). DO NOT reference external local `.css` or `.js` files via `<link>` or `<script src>` tags. This eliminates 404 missing asset errors and ensures immediate live preview rendering.\n"
                . "- For Python / Backend scripts: Include all necessary helper classes, functions, and logic within the single script file (`main.py` or script name).\n"
                . "- Always call `write_file` to save the complete single-file code to the workspace.\n";
        } elseif ($codeMode === 'multi-file') {
            $prompt .= "\n### 📁 CODE GENERATION STRATEGY: MULTI-FILE (MODULAR):\n"
                . "- The project/user is configured for MULTI-FILE modular code generation.\n"
                . "- Split the application into well-organized separate files (e.g. `index.html`, `style.css`, `app.js` or `main.py`, `utils.py`, `models.py`).\n"
                . "- Always call `write_file` for EVERY generated file so no component is missing in the workspace.\n";
        } else { // smart-auto
            $prompt .= "\n### 🌟 CODE GENERATION STRATEGY: SMART AUTO:\n"
                . "- For interactive web applications, UI demos, visual prototypes, dashboards, and calculators: Prefer self-contained single files with inline `<style>` and `<script>` inside `index.html` so that live preview and visual rendering work instantly with zero 404 errors.\n"
                . "- For complex multi-module backend architectures or multi-package projects: Generate structured separate modular files and save each using `write_file`.\n";
        }

        $prompt .= "\n### 🤖 ARENA AGENT WORKFLOW & AGENTIC CODING STANDARD:\n"
            . "You must structure all your multi-step coding, debugging, and implementation responses according to the Arena Agent standard:\n"
            . "1. **اعلام هدف و نیت (Goal & Intent)**: Start immediately with a clear statement of your goal and the approach you will take.\n"
            . "2. **برنامه کاری مرحله‌ای (Step-by-Step Work Plan)**: Provide an explicit numbered work plan under `### 📋 برنامه کاری (Work Plan)`.\n"
            . "3. **اجرای گام‌ها در کشوهای تاشو (Collapsible Step Drawers)**: Wrap each step's execution details, tools called, generated code, and error tracebacks inside `<details class=\"agent-step-drawer\" open>` with a `<summary class=\"agent-step-summary\">` line displaying the step number, title, and badge (e.g. `<span class=\"agent-step-badge done\">تکمیل شد ✓</span>` or `<span class=\"agent-step-badge healed\">اصلاح شد ✓</span>`).\n"
            . "4. **خلاصه کارهای انجام‌شده (Accomplishments Summary)**: End with a clean bulleted report under `### 🏁 خلاصه کارهای انجام‌شده (Accomplishments)` listing all created files, executed tests, and verified results.\n\n"
            . "### 🖥️ HOST RUNTIME CAPABILITIES (IMPORTANT):\n"
            . "- This agent runs on a real server with **full process execution**. Available runtimes: " . implode(', ', $runtimes) . ".\n"
            . "- `run_command` runs a REAL shell inside the workspace directory. You may install dependencies (`pip install`, `npm install`), run tests (`pytest`, `npm test`), build projects and inspect output.\n"
            . "- Every executable file you save is executed automatically, and if it fails you will be given the real traceback and must fix it (self-healing loop, up to 3 attempts).\n"
            . "- Therefore: DO verify your own work by running it. Do not claim something works without executing it.\n"
            . "- Destructive commands (rm -rf /, mkfs, shutdown, fork bombs, ...) are blocked by the sandbox and require explicit user confirmation.\n"
            . "- Version control uses a REAL local git checkout (`git_status`, `git_diff`, and `run_command` with any git subcommand).\n"
            . "- HTML/CSS/JS files can be previewed live from the workspace — prefer them for visual demos.\n\n"
            . "### 🛠️ WORKSPACE FILE CREATION & EDITING RULES:\n"
            . "- When the user asks you to write, create, generate, modify, refactor, or test code or files, you MUST ALWAYS call the `write_file` tool (`write_file(path=..., content=...)`) so the code is saved directly into the active workspace.\n"
            . "- DO NOT just output markdown code blocks without saving the file using `write_file`.\n"
            . "- Always ensure the generated code is completely implemented, production-ready, and saved to the correct relative path in the workspace.\n";

        return $prompt;
    }

    /* ---------------------------------------------------------------- */
    /* Request building (multi-protocol)                                 */
    /* ---------------------------------------------------------------- */

    public static function buildProviderRequest(
        array $provider,
        array $model,
        array $messages,
        string $apiKey,
        bool $stream
    ): array {
        $baseUrl = rtrim((string) ($provider['url'] ?? ''), '/');
        $protocol = (string) ($provider['protocol'] ?? 'openai-compatible');
        $headers = ['Content-Type' => 'application/json'];

        if ($apiKey !== '') {
            if ($protocol === 'anthropic') {
                $headers['x-api-key'] = $apiKey;
                $headers['anthropic-version'] = '2023-06-01';
            } elseif ($protocol === 'azure') {
                $headers['api-key'] = $apiKey;
            } else {
                $headers['Authorization'] = 'Bearer ' . $apiKey;
            }
        }

        if ($protocol === 'anthropic') {
            $url = str_ends_with($baseUrl, '/messages') ? $baseUrl : $baseUrl . '/v1/messages';
            $systemMsg = '';
            $userMsgs = [];
            foreach ($messages as $m) {
                $role = (string) ($m['role'] ?? 'user');
                if ($role === 'system') {
                    if ($systemMsg === '') {
                        $systemMsg = (string) ($m['content'] ?? '');
                    }
                    continue;
                }
                $userMsgs[] = ['role' => $role === 'tool' ? 'user' : $role, 'content' => (string) ($m['content'] ?? '')];
            }
            $body = [
                'model' => $model['id'],
                'system' => $systemMsg,
                'messages' => $userMsgs,
                'max_tokens' => (int) ($model['maxOutputTokens'] ?? 0) ?: 4096,
                'temperature' => 0.2,
            ];
            if ($stream) {
                $body['stream'] = true;
            }
            return ['url' => $url, 'headers' => $headers, 'body' => $body];
        }

        if ($protocol === 'ollama') {
            if (str_ends_with($baseUrl, '/api/chat') || str_ends_with($baseUrl, '/chat')) {
                $url = $baseUrl;
            } elseif (str_ends_with($baseUrl, '/api')) {
                $url = $baseUrl . '/chat';
            } else {
                $url = ($baseUrl !== '' ? $baseUrl : 'http://127.0.0.1:11434') . '/api/chat';
            }
            return ['url' => $url, 'headers' => $headers, 'body' => ['model' => $model['id'], 'messages' => $messages, 'stream' => $stream]];
        }

        if ($protocol === 'gemini') {
            // Google AI Studio exposes an OpenAI-compatible surface at /openai.
            $url = str_ends_with($baseUrl, '/chat/completions')
                ? $baseUrl
                : (rtrim((string) preg_replace('#/openai$#', '', $baseUrl), '/') . '/openai/chat/completions');
        } else {
            // openai-compatible, mistral, azure, cloudflare, openrouter, workers-ai
            if (str_ends_with($baseUrl, '/chat/completions')) {
                $url = $baseUrl;
            } else {
                $url = ($baseUrl !== '' ? $baseUrl : 'https://api.openai.com/v1') . '/chat/completions';
            }
        }

        $body = ['model' => $model['id'], 'messages' => $messages, 'temperature' => 0.2];
        if ($stream) {
            $body['stream'] = true;
        }
        if (!empty($model['toolCalling'])) {
            $body['tools'] = AgentTools::definitions();
        }
        return ['url' => (string) $url, 'headers' => $headers, 'body' => $body];
    }

    /** @return array{targetUrl:string, proxyClient:?string} */
    public static function resolveTargetUrl(array $provider, string $directUrl): array
    {
        $baseUrl = (string) ($provider['url'] ?? '');
        if (
            ($provider['protocol'] ?? '') === 'ollama'
            || str_contains($baseUrl, '127.0.0.1')
            || str_contains($baseUrl, 'localhost')
        ) {
            return ['targetUrl' => $directUrl, 'proxyClient' => null];
        }
        $cfg = Config::proxyConfig($directUrl, (string) ($provider['proxyUrl'] ?? '') ?: null);
        return ['targetUrl' => (string) $cfg['effectiveUrl'], 'proxyClient' => $cfg['proxyClient']];
    }

    public static function normalizeResponse(array $provider, mixed $data): array
    {
        $protocol = (string) ($provider['protocol'] ?? '');
        if (!is_array($data)) {
            $data = [];
        }
        if ($protocol === 'anthropic') {
            $contentText = '';
            $thinkingText = '';
            foreach ($data['content'] ?? [] as $b) {
                if (($b['type'] ?? '') === 'text') {
                    $contentText .= (string) ($b['text'] ?? '');
                } elseif (($b['type'] ?? '') === 'thinking') {
                    $thinkingText .= (string) ($b['thinking'] ?? '');
                }
            }
            $msg = ['role' => 'assistant', 'content' => $contentText];
            if ($thinkingText !== '') {
                $msg['reasoning_content'] = $thinkingText;
            }
            return ['choices' => [['message' => $msg]]];
        }
        if ($protocol === 'ollama') {
            return ['choices' => [['message' => $data['message'] ?? ['role' => 'assistant', 'content' => '']]]];
        }
        return $data;
    }

    /* ---------------------------------------------------------------- */
    /* Non-streaming call                                                */
    /* ---------------------------------------------------------------- */

    public static function callProviderApi(
        ProviderStore $store,
        array $provider,
        array $model,
        array $messages,
        string $apiKey,
        ?int $customTimeoutSec = null
    ): array {
        $built = self::buildProviderRequest($provider, $model, $messages, $apiKey, false);
        $resolved = self::resolveTargetUrl($provider, $built['url']);
        $timeout = $customTimeoutSec ?? (int) ($provider['timeoutSec'] ?? 120);
        $started = microtime(true);
        $payload = (string) json_encode($built['body'], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);

        $attempt = static function (string $url) use ($built, $payload, $timeout, $resolved): array {
            $r = HttpClient::request('POST', $url, $built['headers'], $payload, $timeout, $resolved['proxyClient']);
            if (!$r['ok'] || $r['status'] >= 400) {
                $detail = $r['error'] ?? substr((string) $r['body'], 0, 500);
                throw new \RuntimeException('HTTP ' . $r['status'] . ': ' . $detail);
            }
            $json = json_decode((string) $r['body'], true);
            if (!is_array($json)) {
                throw new \RuntimeException('Provider returned a non-JSON response: ' . substr((string) $r['body'], 0, 300));
            }
            return $json;
        };

        try {
            $data = $attempt($resolved['targetUrl']);
            ProviderStore::breaker()->recordSuccess((string) $provider['id']);
            $store->recordMetric((string) $provider['id'], (string) $model['id'], (microtime(true) - $started) * 1000, false);
            return self::normalizeResponse($provider, $data);
        } catch (\Throwable $primaryErr) {
            if ($resolved['targetUrl'] !== $built['url'] && ($provider['protocol'] ?? '') !== 'ollama') {
                try {
                    $data = $attempt($built['url']);
                    ProviderStore::breaker()->recordSuccess((string) $provider['id']);
                    $store->recordMetric((string) $provider['id'], (string) $model['id'], (microtime(true) - $started) * 1000, false);
                    return self::normalizeResponse($provider, $data);
                } catch (\Throwable) {
                    // fall through to the original error
                }
            }
            ProviderStore::breaker()->recordFailure((string) $provider['id']);
            $store->recordMetric((string) $provider['id'], (string) $model['id'], (microtime(true) - $started) * 1000, true);
            throw $primaryErr;
        }
    }

    /* ---------------------------------------------------------------- */
    /* Streaming primitives                                              */
    /* ---------------------------------------------------------------- */

    /**
     * Yield response lines from a streaming POST while the connection is open.
     * Uses curl_multi so the generator can hand tokens to the caller mid-flight.
     *
     * @return \Generator<int, string>
     */
    private static function streamLines(
        string $url,
        array $headers,
        string $body,
        int $timeoutSec,
        ?string $proxy
    ): \Generator {
        if (!function_exists('curl_init')) {
            throw new \RuntimeException('The cURL extension is not enabled on this host');
        }
        $hdrs = [];
        foreach ($headers as $k => $v) {
            $hdrs[] = $k . ': ' . $v;
        }

        $buffer = '';
        $ch = curl_init();
        curl_setopt_array($ch, [
            CURLOPT_URL => $url,
            CURLOPT_POST => true,
            CURLOPT_POSTFIELDS => $body,
            CURLOPT_HTTPHEADER => $hdrs,
            CURLOPT_TIMEOUT => max(10, $timeoutSec),
            CURLOPT_CONNECTTIMEOUT => min(30, max(5, $timeoutSec)),
            CURLOPT_FOLLOWLOCATION => true,
            CURLOPT_SSL_VERIFYPEER => true,
            CURLOPT_RETURNTRANSFER => false,
            CURLOPT_WRITEFUNCTION => static function ($handle, string $chunk) use (&$buffer): int {
                $buffer .= $chunk;
                return strlen($chunk);
            },
        ]);
        if ($proxy !== null && $proxy !== '') {
            curl_setopt($ch, CURLOPT_PROXY, $proxy);
        }

        $mh = curl_multi_init();
        curl_multi_add_handle($mh, $ch);

        $status = 0;
        $errorBody = '';
        $running = 1;
        try {
            do {
                curl_multi_exec($mh, $running);
                if ($running > 0) {
                    curl_multi_select($mh, 0.25);
                }
                if ($status === 0) {
                    $status = (int) curl_getinfo($ch, CURLINFO_RESPONSE_CODE);
                }
                if ($buffer === '') {
                    continue;
                }
                if ($status >= 400) {
                    $errorBody .= $buffer;
                    $buffer = '';
                    continue;
                }
                if ($status === 0) {
                    continue; // headers not in yet — keep buffering
                }
                $parts = explode("\n", $buffer);
                $buffer = (string) array_pop($parts);
                foreach ($parts as $line) {
                    yield trim($line);
                }
            } while ($running > 0);

            curl_multi_exec($mh, $running);
            $status = $status ?: (int) curl_getinfo($ch, CURLINFO_RESPONSE_CODE);
            $curlErr = curl_error($ch);

            if ($status >= 400) {
                $errorBody .= $buffer;
                throw new \RuntimeException('HTTP ' . $status . ': ' . substr(trim($errorBody), 0, 500));
            }
            if ($curlErr !== '') {
                throw new \RuntimeException('Connection error: ' . $curlErr);
            }
            if ($status === 0) {
                throw new \RuntimeException('Connection error: no response from ' . $url);
            }
            if (trim($buffer) !== '') {
                yield trim($buffer);
            }
        } finally {
            curl_multi_remove_handle($mh, $ch);
            curl_close($ch);
            curl_multi_close($mh);
        }
    }

    /**
     * Parse one provider stream into {type: token|reasoning|full_message} items.
     *
     * @return \Generator<int, array>
     */
    private static function streamRequest(
        array $provider,
        string $url,
        array $headers,
        array $body,
        int $timeoutSec,
        ?string $proxy
    ): \Generator {
        $protocol = (string) ($provider['protocol'] ?? '');
        $payload = (string) json_encode($body, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);

        $fullContent = [];
        $fullReasoning = [];
        $toolCalls = [];

        foreach (self::streamLines($url, $headers, $payload, $timeoutSec, $proxy) as $line) {
            if ($line === '' || str_starts_with($line, ':')) {
                continue;
            }

            if (str_starts_with($line, 'data:')) {
                $dataStr = trim(substr($line, 5));
                if ($dataStr === '[DONE]') {
                    break;
                }
                $chunk = json_decode($dataStr, true);
                if (!is_array($chunk)) {
                    continue;
                }

                // Anthropic event stream
                if ($protocol === 'anthropic') {
                    if (($chunk['type'] ?? '') === 'content_block_delta') {
                        $delta = $chunk['delta'] ?? [];
                        if (($delta['type'] ?? '') === 'text_delta' && ($delta['text'] ?? '') !== '') {
                            $fullContent[] = (string) $delta['text'];
                            yield ['type' => 'token', 'text' => (string) $delta['text']];
                        } elseif (($delta['type'] ?? '') === 'thinking_delta' && ($delta['thinking'] ?? '') !== '') {
                            $fullReasoning[] = (string) $delta['thinking'];
                            yield ['type' => 'reasoning', 'reasoning' => (string) $delta['thinking']];
                        }
                    }
                    continue;
                }

                $choices = $chunk['choices'] ?? [];
                if (!$choices) {
                    continue;
                }
                $delta = $choices[0]['delta'] ?? [];

                $rText = (string) ($delta['reasoning_content'] ?? $delta['reasoning'] ?? $delta['thought'] ?? '');
                if ($rText !== '') {
                    $fullReasoning[] = $rText;
                    yield ['type' => 'reasoning', 'reasoning' => $rText];
                }

                $cText = (string) ($delta['content'] ?? '');
                if ($cText !== '') {
                    $fullContent[] = $cText;
                    yield ['type' => 'token', 'text' => $cText];
                }

                foreach ($delta['tool_calls'] ?? [] as $tc) {
                    $idx = (int) ($tc['index'] ?? 0);
                    if (!isset($toolCalls[$idx])) {
                        $toolCalls[$idx] = [
                            'id' => (string) ($tc['id'] ?? ('call_' . $idx . '_' . (int) (microtime(true) * 1000))),
                            'type' => 'function',
                            'function' => ['name' => '', 'arguments' => ''],
                        ];
                    }
                    if (!empty($tc['id'])) {
                        $toolCalls[$idx]['id'] = (string) $tc['id'];
                    }
                    $fn = $tc['function'] ?? [];
                    if (!empty($fn['name'])) {
                        $toolCalls[$idx]['function']['name'] .= (string) $fn['name'];
                    }
                    if (isset($fn['arguments']) && $fn['arguments'] !== '') {
                        $toolCalls[$idx]['function']['arguments'] .= (string) $fn['arguments'];
                    }
                }
                continue;
            }

            // Ollama emits bare NDJSON objects
            if ($protocol === 'ollama' && str_starts_with($line, '{')) {
                $chunk = json_decode($line, true);
                if (!is_array($chunk)) {
                    continue;
                }
                $cText = (string) ($chunk['message']['content'] ?? '');
                if ($cText !== '') {
                    $fullContent[] = $cText;
                    yield ['type' => 'token', 'text' => $cText];
                }
                if (!empty($chunk['done'])) {
                    break;
                }
            }
        }

        $finalMsg = ['role' => 'assistant', 'content' => implode('', $fullContent)];
        if ($fullReasoning) {
            $finalMsg['reasoning_content'] = implode('', $fullReasoning);
        }
        if ($toolCalls) {
            ksort($toolCalls);
            $finalMsg['tool_calls'] = array_values($toolCalls);
        }
        yield ['type' => 'full_message', 'message' => $finalMsg];
    }

    /** @return \Generator<int, array> */
    public static function streamCallProviderApi(
        ProviderStore $store,
        array $provider,
        array $model,
        array $messages,
        string $apiKey,
        ?int $customTimeoutSec = null
    ): \Generator {
        $built = self::buildProviderRequest($provider, $model, $messages, $apiKey, true);
        $resolved = self::resolveTargetUrl($provider, $built['url']);
        $timeout = $customTimeoutSec ?? (int) ($provider['timeoutSec'] ?? 120);
        $started = microtime(true);
        $pid = (string) $provider['id'];
        $mid = (string) $model['id'];

        try {
            foreach (self::streamRequest($provider, $resolved['targetUrl'], $built['headers'], $built['body'], $timeout, $resolved['proxyClient']) as $item) {
                yield $item;
            }
            ProviderStore::breaker()->recordSuccess($pid);
            $store->recordMetric($pid, $mid, (microtime(true) - $started) * 1000, false);
            return;
        } catch (\Throwable $proxyErr) {
            if ($resolved['targetUrl'] !== $built['url'] && ($provider['protocol'] ?? '') !== 'ollama') {
                try {
                    foreach (self::streamRequest($provider, $built['url'], $built['headers'], $built['body'], $timeout, null) as $item) {
                        yield $item;
                    }
                    ProviderStore::breaker()->recordSuccess($pid);
                    $store->recordMetric($pid, $mid, (microtime(true) - $started) * 1000, false);
                    return;
                } catch (\Throwable) {
                    // fall through to the non-streaming path
                }
            }

            // Last resort: non-streaming call, chunked client-side (same as Python).
            try {
                $resp = self::callProviderApi($store, $provider, $model, $messages, $apiKey, $customTimeoutSec);
                $msg = $resp['choices'][0]['message'] ?? ['role' => 'assistant', 'content' => ''];
                $reasoning = (string) ($msg['reasoning_content'] ?? $msg['reasoning'] ?? $msg['thought'] ?? '');
                if ($reasoning !== '') {
                    yield ['type' => 'reasoning', 'reasoning' => $reasoning];
                }
                $content = (string) ($msg['content'] ?? '');
                $len = strlen($content);
                for ($i = 0; $i < $len; $i += 25) {
                    yield ['type' => 'token', 'text' => substr($content, $i, 25)];
                }
                yield ['type' => 'full_message', 'message' => $msg];
                return;
            } catch (\Throwable $nonStreamErr) {
                ProviderStore::breaker()->recordFailure($pid);
                $store->recordMetric($pid, $mid, (microtime(true) - $started) * 1000, true);
                throw $nonStreamErr;
            }
        }
    }

    /* ---------------------------------------------------------------- */
    /* Auto file detection                                               */
    /* ---------------------------------------------------------------- */

    /** @return array<int, array{path:string,type:string,content:string,isExecutable:bool,isHtml:bool}> */
    public static function autoDetectAndSaveCodeFiles(array $ws, string $content): array
    {
        $saved = [];
        if ($content === '' || !str_contains($content, '```')) {
            return $saved;
        }

        $used = [];
        $blocks = explode('```', $content);
        $count = count($blocks);

        for ($i = 1; $i < $count; $i += 2) {
            $block = $blocks[$i];
            $precedingText = $blocks[$i - 1] ?? '';
            $nl = strpos($block, "\n");
            $firstLine = trim($nl !== false ? substr($block, 0, $nl) : $block);
            $code = $nl !== false ? substr($block, $nl + 1) : '';
            if (trim($code) === '') {
                continue;
            }

            $filename = null;
            $lang = strtolower($firstLine);
            $langParts = preg_split('/[\s:;=]/', $lang) ?: [];
            $cleanLang = trim((string) ($langParts[0] ?? 'code')) ?: 'code';

            // 1. filename attached to the fence info string
            if (preg_match('/(?:^|[\s:])(?:file=|filename=|path=|:)?\s*([a-zA-Z0-9_\-.\/]+\.[a-zA-Z0-9]+)/i', $firstLine, $m)) {
                $filename = trim($m[1]);
            }

            // 2. filename in a leading comment of the block
            if ($filename === null) {
                $codeHead = implode("\n", array_slice(explode("\n", trim($code)), 0, 3));
                if (preg_match('/(?:#|\/\/|\/\*|<!--)\s*(?:filename|filepath|file|path|نام فایل)?\s*:?\s*`?([a-zA-Z0-9_\-.\/]+\.[a-zA-Z0-9]+)`?/iu', $codeHead, $m)) {
                    $filename = trim($m[1]);
                }
            }

            // 3. filename in the preceding prose
            if ($filename === null && trim($precedingText) !== '') {
                $lastLines = array_values(array_filter(array_map('trim', array_slice(explode("\n", trim($precedingText)), -3))));
                foreach (array_reverse($lastLines) as $l) {
                    if (preg_match('/(?:###|##|#|\*\*|فایل|File:?|ساخت فایل|کد فایل)?\s*`?([a-zA-Z0-9_\-.\/]+\.(?:html|htm|py|js|ts|jsx|tsx|css|json|sql|sh|md|txt|php|toml|yaml|yml))`?/iu', $l, $m)) {
                        $filename = trim($m[1]);
                        break;
                    }
                }
            }

            // 4. language-based fallbacks
            if ($filename === null) {
                $lower = strtolower($code);
                $nth = count($used) + 1;
                if (str_contains($lower, '<!doctype html') || str_contains($lower, '<html')) {
                    $filename = 'index.html';
                } elseif (in_array($cleanLang, ['html', 'htm'], true)) {
                    $filename = isset($used['index.html']) ? "page_{$nth}.html" : 'index.html';
                } elseif ($cleanLang === 'css') {
                    $filename = isset($used['style.css']) ? "style_{$nth}.css" : 'style.css';
                } elseif (in_array($cleanLang, ['javascript', 'js'], true)) {
                    $filename = isset($used['app.js']) ? "script_{$nth}.js" : 'app.js';
                } elseif (in_array($cleanLang, ['typescript', 'ts'], true)) {
                    $filename = isset($used['app.ts']) ? "script_{$nth}.ts" : 'app.ts';
                } elseif (in_array($cleanLang, ['python', 'py'], true)) {
                    $filename = isset($used['main.py']) ? "script_{$nth}.py" : 'main.py';
                } elseif ($cleanLang === 'json') {
                    $filename = 'data.json';
                } elseif ($cleanLang === 'sql') {
                    $filename = 'schema.sql';
                } elseif (in_array($cleanLang, ['bash', 'sh', 'zsh'], true)) {
                    $filename = 'run.sh';
                } elseif ($cleanLang === 'php' || str_contains($code, '')) {
                    $filename = isset($used['index.php']) ? "script_{$nth}.php" : 'index.php';
                } elseif ($cleanLang === 'toml') {
                    $filename = 'config.toml';
                }
            }

            if ($filename === null) {
                continue;
            }
            $cleanFn = str_replace('\\', '/', ltrim(trim($filename), '/'));
            if ($cleanFn === '' || str_starts_with($cleanFn, '..') || !str_contains($cleanFn, '.')) {
                continue;
            }

            try {
                $abs = Workspaces::safePath($ws, $cleanFn);
                Files::write($abs, $code);
                ChangeSets::saveVersion($ws, $cleanFn, $code, 'agent-auto-save');
                $used[$cleanFn] = true;
                $lower = strtolower($cleanFn);
                $saved[] = [
                    'path' => $cleanFn,
                    'type' => $cleanLang,
                    'content' => $code,
                    'isExecutable' => (bool) preg_match('/\.(py|pyw|sh|bash|js|mjs|ts|php)$/', $lower),
                    'isHtml' => (bool) preg_match('/\.(html|htm)$/', $lower),
                ];
            } catch (\Throwable) {
                // skip unwritable paths
            }
        }

        return $saved;
    }

    /* ---------------------------------------------------------------- */
    /* Error classification                                              */
    /* ---------------------------------------------------------------- */

    public static function isRateLimitError(\Throwable|string $err): bool
    {
        $s = strtolower($err instanceof \Throwable ? $err->getMessage() : $err);
        foreach (['429', 'rate limit', 'rate_limit', '402', 'quota', 'credit', 'billing', 'insufficient'] as $needle) {
            if (str_contains($s, $needle)) {
                return true;
            }
        }
        return false;
    }

    public static function isNetworkError(\Throwable|string $err): bool
    {
        $s = strtolower($err instanceof \Throwable ? $err->getMessage() : $err);
        foreach ([
            'timeout', 'timed out', 'connect', 'connection', '502', '503', '504',
            '520', '521', '522', '524', 'network', 'disconnected', 'resolve host',
            'ssl', 'eof', 'reset by peer',
        ] as $needle) {
            if (str_contains($s, $needle)) {
                return true;
            }
        }
        return false;
    }

    /* ---------------------------------------------------------------- */
    /* Candidate resolution                                              */
    /* ---------------------------------------------------------------- */

    /** @return array<int, array{provider:array, model:array, isFallback:bool}> */
    private static function buildCandidates(ProviderStore $store, array $primary, array $model): array
    {
        $candidates = [['provider' => $primary, 'model' => $model, 'isFallback' => false]];
        $seen = [$primary['id'] . '::' . $model['id'] => true];

        foreach ($store->verifiedFallbackCandidates((string) $primary['id'], (string) $model['id'], true) as [$vp, $vm]) {
            $key = $vp['id'] . '::' . $vm['id'];
            if (!isset($seen[$key])) {
                $candidates[] = ['provider' => $vp, 'model' => $vm, 'isFallback' => true];
                $seen[$key] = true;
            }
        }

        $sorted = array_values($store->data);
        usort($sorted, static fn(array $a, array $b): int => (int) ($b['priority'] ?? 0) <=> (int) ($a['priority'] ?? 0));
        foreach ($sorted as $p) {
            if (empty($p['enabled']) || $p['id'] === $primary['id'] || ProviderStore::breaker()->isTripped((string) $p['id'])) {
                continue;
            }
            $apiKey = $store->apiKey($p);
            if ($apiKey === '' && !in_array($p['protocol'], ['ollama', 'workers-ai'], true)) {
                continue;
            }
            foreach ($p['models'] ?? [] as $m) {
                $key = $p['id'] . '::' . $m['id'];
                if (!isset($seen[$key])) {
                    $candidates[] = ['provider' => $p, 'model' => $m, 'isFallback' => true];
                    $seen[$key] = true;
                }
            }
        }
        return $candidates;
    }

    private static function nowUtc(): string
    {
        return gmdate('Y-m-d H:i:s') . ' UTC';
    }

    private static function hasAnyOtherUsableProvider(ProviderStore $store, string $excludeId): bool
    {
        foreach ($store->data as $p) {
            if (empty($p['enabled']) || $p['id'] === $excludeId) {
                continue;
            }
            if ($store->apiKey($p) !== '' || ($p['protocol'] ?? '') === 'ollama') {
                return true;
            }
        }
        return false;
    }

    /** Resolve the workspace and checkpoint-aware message list shared by both loops. */
    private static function prepare(array $opts): array
    {
        $conversationId = ($opts['conversationId'] ?? null) ?: null;
        $ws = Workspaces::active();
        if ($conversationId !== null) {
            try {
                $ws = Workspaces::getOrCreateSessionWorkspace($conversationId);
            } catch (\Throwable) {
                // keep the active workspace
            }
        }

        $incoming = array_values(array_filter(
            $opts['messages'] ?? [],
            static fn(array $m): bool => ($m['role'] ?? '') !== 'system'
        ));
        $sysPrompt = self::buildSystemPrompt($conversationId, $opts['references'] ?? null, $opts['messages'] ?? null, $ws);
        $chatMsgs = array_merge([['role' => 'system', 'content' => $sysPrompt]], $incoming);

        $resumed = null;
        if ($conversationId !== null) {
            $cp = Conversations::latestCheckpoint($conversationId);
            $history = $cp['chatHistory'] ?? [];
            if (is_array($history) && $history) {
                $cpNonSys = array_values(array_filter($history, static fn($m): bool => is_array($m) && ($m['role'] ?? '') !== 'system'));
                $hasProgress = false;
                foreach ($history as $m) {
                    if (is_array($m) && in_array($m['role'] ?? '', ['assistant', 'tool'], true)) {
                        $hasProgress = true;
                        break;
                    }
                }
                if (count($cpNonSys) >= count($incoming) && $hasProgress) {
                    $chatMsgs = array_merge([['role' => 'system', 'content' => $sysPrompt]], $cpNonSys);
                    $resumed = $cp;
                }
            }
        }

        return [
            'conversationId' => $conversationId,
            'workspace' => $ws,
            'chatMsgs' => $chatMsgs,
            'resumed' => $resumed,
        ];
    }

    private static function fallbackDetails(array $primary, array $primaryModel, array $p, array $m): array
    {
        return [
            'used' => true,
            'originalProvider' => $primary['name'],
            'originalModel' => $primaryModel['id'],
            'activeProvider' => $p['name'],
            'activeModel' => $m['id'],
        ];
    }

    /* ---------------------------------------------------------------- */
    /* Streaming agent loop                                              */
    /* ---------------------------------------------------------------- */

    /** @return \Generator<int, array> SSE event payloads */
    public static function streamCompleteChat(ProviderStore $store, array $opts): \Generator
    {
        $maxSteps = (int) ($opts['maxSteps'] ?? self::MAX_STEPS_STREAM);
        $prep = self::prepare($opts);
        $conversationId = $prep['conversationId'];
        $ws = $prep['workspace'];
        $chatMsgs = $prep['chatMsgs'];

        $toolCtx = new ToolContext($ws, $conversationId, (string) ($opts['userId'] ?? 'agent'));

        if ($prep['resumed'] !== null) {
            $cp = $prep['resumed'];
            yield [
                'type' => 'checkpoint_resumed',
                'checkpointId' => $cp['id'],
                'stepIndex' => (int) ($cp['stepIndex'] ?? 0),
                'message' => 'Resumed execution from checkpoint at step ' . (((int) ($cp['stepIndex'] ?? 0)) + 1) . '.',
            ];
        }

        $primary = $store->get((string) ($opts['providerId'] ?? ''));
        if ($primary === null) {
            throw new HttpError(400, "Provider '" . ($opts['providerId'] ?? '') . "' is not configured in the Provider Catalog.");
        }
        $primaryModel = $store->findModel($primary, (string) ($opts['modelId'] ?? ''));

        yield ['type' => 'status', 'status' => 'started', 'provider' => $primary['id'], 'model' => $primaryModel['id']];

        $primaryKey = $store->apiKey($primary);
        if ($primaryKey === '' && !in_array($primary['protocol'], ['ollama', 'workers-ai'], true)) {
            if (!self::hasAnyOtherUsableProvider($store, (string) $primary['id'])) {
                $errMsg = "Provider '{$primary['name']}' ({$primary['id']}) does not have an API key configured.";
                yield [
                    'type' => 'error',
                    'error' => $errMsg,
                    'errorDetails' => [
                        'provider' => $primary['id'],
                        'providerName' => $primary['name'],
                        'model' => $primaryModel['id'],
                        'protocol' => $primary['protocol'],
                        'url' => $primary['url'],
                        'error' => $errMsg,
                        'timestamp' => self::nowUtc(),
                        'remediation' => 'Set ' . ($primary['apiKeyEnv'] ?: 'OPENROUTER_API_KEY') . " in the .env file (or enter it in 'Providers & Models' / 'Security & Settings').",
                    ],
                ];
                return;
            }
        }

        $candidates = self::buildCandidates($store, $primary, $primaryModel);
        $pendingApprovals = [];
        $primaryError = null;
        $fallbackErrors = [];
        $maxRetrySleep = (int) Config::rawInt('MAX_RETRY_SLEEP_SEC', 20) ?: 20;

        foreach ($candidates as $cand) {
            $p = $cand['provider'];
            $targetModel = $cand['model'];
            $isFallback = $cand['isFallback'];

            $apiKey = $store->apiKey($p);
            if ($apiKey === '' && !in_array($p['protocol'], ['ollama', 'workers-ai'], true)) {
                continue;
            }

            if ($isFallback) {
                yield ['type' => 'fallback_activated', 'fallbackDetails' => self::fallbackDetails($primary, $primaryModel, $p, $targetModel)];
            }

            $stepIdx = 0;
            try {
                for ($stepIdx = 0; $stepIdx < $maxSteps; $stepIdx++) {
                    $lastMsg = null;

                    // Exponential backoff retry for transient network failures.
                    for ($attempt = 1; $attempt <= self::MAX_ATTEMPTS; $attempt++) {
                        try {
                            foreach (self::streamCallProviderApi($store, $p, $targetModel, $chatMsgs, $apiKey) as $chunk) {
                                if ($chunk['type'] === 'token') {
                                    yield ['type' => 'token', 'text' => $chunk['text']];
                                } elseif ($chunk['type'] === 'reasoning') {
                                    yield ['type' => 'reasoning', 'reasoning' => $chunk['reasoning']];
                                } elseif ($chunk['type'] === 'full_message') {
                                    $lastMsg = $chunk['message'];
                                }
                            }
                            break;
                        } catch (\Throwable $streamErr) {
                            if (self::isRateLimitError($streamErr)) {
                                throw $streamErr;
                            }
                            if (!self::isNetworkError($streamErr) || $attempt >= self::MAX_ATTEMPTS) {
                                throw $streamErr;
                            }
                            $delaySec = min(2 ** ($attempt - 1), 60);
                            $actual = min($delaySec, $maxRetrySleep);
                            yield [
                                'type' => 'retry_countdown',
                                'attempt' => $attempt,
                                'maxAttempts' => self::MAX_ATTEMPTS,
                                'delaySec' => $delaySec,
                                'provider' => $p['name'],
                                'model' => $targetModel['name'] ?? $targetModel['id'],
                                'reason' => "قطع ارتباط شبکه یا تایم‌اوت ({$streamErr->getMessage()}). تلاش مجدد در {$delaySec} ثانیه...",
                            ];
                            if ($actual > 0) {
                                sleep((int) $actual);
                            }
                        }
                    }

                    if ($lastMsg === null) {
                        break;
                    }

                    $chatMsgs[] = $lastMsg;
                    $toolCalls = $lastMsg['tool_calls'] ?? [];

                    if (!$toolCalls) {
                        $savedFiles = self::autoDetectAndSaveCodeFiles($ws, (string) ($lastMsg['content'] ?? ''));
                        $executionReports = [];

                        if ($conversationId !== null) {
                            Conversations::saveCheckpoint([
                                'conversationId' => $conversationId,
                                'stepIndex' => $stepIdx,
                                'providerId' => $p['id'],
                                'modelId' => $targetModel['id'],
                                'accumulatedContent' => (string) ($lastMsg['content'] ?? ''),
                                'accumulatedReasoning' => (string) ($lastMsg['reasoning_content'] ?? ''),
                                'chatHistory' => $chatMsgs,
                                'savedFiles' => $savedFiles,
                                'executionResults' => $executionReports,
                                'status' => 'completed',
                            ]);
                        }

                        // Autonomous execution / self-healing loop (real execution here).
                        foreach ($savedFiles as $sf) {
                            if ($sf['isHtml']) {
                                $qs = ['path' => $sf['path']];
                                if ($conversationId !== null) {
                                    $qs['conversation_id'] = $conversationId;
                                }
                                yield [
                                    'type' => 'render_preview_ready',
                                    'path' => $sf['path'],
                                    'previewUrl' => '/api/workspace/raw?' . http_build_query($qs),
                                    'previewType' => 'html',
                                ];
                                continue;
                            }
                            if (!$sf['isExecutable']) {
                                continue;
                            }

                            $execRes = Terminal::executeFile($ws, $sf['path'], $conversationId);
                            $executionReports[] = $execRes;

                            if ((int) ($execRes['exitCode'] ?? 1) === 0) {
                                yield [
                                    'type' => 'execution_result',
                                    'path' => $sf['path'],
                                    'status' => 'success',
                                    'exitCode' => 0,
                                    'command' => $execRes['command'] ?? '',
                                    'stdout' => $execRes['stdout'] ?? '',
                                    'stderr' => $execRes['stderr'] ?? '',
                                    'attempt' => 1,
                                ];
                                continue;
                            }

                            if (!empty($execRes['unsupported'])) {
                                yield [
                                    'type' => 'execution_result',
                                    'path' => $sf['path'],
                                    'status' => 'unsupported',
                                    'exitCode' => (int) ($execRes['exitCode'] ?? 127),
                                    'command' => $execRes['command'] ?? '',
                                    'stdout' => '',
                                    'stderr' => $execRes['stderr'] ?? '',
                                    'unsupported' => true,
                                    'attempt' => 1,
                                ];
                                continue;
                            }

                            yield [
                                'type' => 'execution_result',
                                'path' => $sf['path'],
                                'status' => 'failed',
                                'exitCode' => (int) ($execRes['exitCode'] ?? 1),
                                'command' => $execRes['command'] ?? '',
                                'stdout' => $execRes['stdout'] ?? '',
                                'stderr' => $execRes['stderr'] ?? '',
                                'attempt' => 1,
                            ];

                            $currentErr = (string) ($execRes['stderr'] ?: $execRes['stdout'] ?: 'Execution failed with non-zero exit code');
                            $lastExec = $execRes;
                            for ($healAttempt = 1; $healAttempt <= 3; $healAttempt++) {
                                $chatMsgs[] = [
                                    'role' => 'user',
                                    'content' => "\n\n[AUTONOMOUS TEST EXECUTION FAILURE - Attempt {$healAttempt}/3]\n"
                                        . "File `{$sf['path']}` was executed and failed with Exit Code " . (int) ($lastExec['exitCode'] ?? 1) . ".\n"
                                        . "Error Traceback:\n```\n{$currentErr}\n```\n\n"
                                        . "Please diagnose this error, fix all issues in `{$sf['path']}`, and output the full corrected code in a code block.",
                                ];
                                yield ['type' => 'token', 'text' => "\n\n⚙️ *در حال رفع خودکار خطای اجرای `{$sf['path']}` (تلاش {$healAttempt})...*\n\n"];

                                $healMsg = null;
                                foreach (self::streamCallProviderApi($store, $p, $targetModel, $chatMsgs, $apiKey) as $chunk) {
                                    if ($chunk['type'] === 'token') {
                                        yield ['type' => 'token', 'text' => $chunk['text']];
                                    } elseif ($chunk['type'] === 'reasoning') {
                                        yield ['type' => 'reasoning', 'reasoning' => $chunk['reasoning']];
                                    } elseif ($chunk['type'] === 'full_message') {
                                        $healMsg = $chunk['message'];
                                    }
                                }
                                if ($healMsg === null) {
                                    break;
                                }

                                $chatMsgs[] = $healMsg;
                                self::autoDetectAndSaveCodeFiles($ws, (string) ($healMsg['content'] ?? ''));

                                $reExec = Terminal::executeFile($ws, $sf['path'], $conversationId);
                                if ((int) ($reExec['exitCode'] ?? 1) === 0) {
                                    yield [
                                        'type' => 'execution_healed',
                                        'path' => $sf['path'],
                                        'status' => 'healed',
                                        'exitCode' => 0,
                                        'command' => $reExec['command'] ?? '',
                                        'stdout' => $reExec['stdout'] ?? '',
                                        'stderr' => $reExec['stderr'] ?? '',
                                        'durationMs' => $reExec['durationMs'] ?? 0,
                                        'attempts' => $healAttempt + 1,
                                    ];
                                    $executionReports[] = $reExec;
                                    break;
                                }
                                $currentErr = (string) ($reExec['stderr'] ?: $reExec['stdout'] ?: $currentErr);
                                $lastExec = $reExec;
                            }
                        }

                        ProviderStore::breaker()->recordSuccess((string) $p['id']);
                        $store->recordMetric((string) $p['id'], (string) $targetModel['id'], 0, false);

                        if ($pendingApprovals) {
                            yield ['type' => 'approvals', 'approvals' => $pendingApprovals];
                        }

                        yield [
                            'type' => 'done',
                            'steps' => $stepIdx + 1,
                            'provider' => $p['id'],
                            'model' => $targetModel['id'],
                            'reasoning' => $lastMsg['reasoning_content'] ?? '',
                            'savedFiles' => $savedFiles,
                            'executionReports' => $executionReports,
                            'isFallback' => $isFallback,
                            'fallbackDetails' => $isFallback ? self::fallbackDetails($primary, $primaryModel, $p, $targetModel) : null,
                        ];
                        if ($conversationId !== null) {
                            Conversations::clearCheckpoints($conversationId);
                        }
                        return;
                    }

                    // Execute tool calls
                    foreach ($toolCalls as $tc) {
                        $name = (string) ($tc['function']['name'] ?? '');
                        $args = json_decode((string) ($tc['function']['arguments'] ?? '{}'), true);
                        if (!is_array($args)) {
                            $args = [];
                        }

                        yield ['type' => 'tool_executing', 'tool' => $name, 'args' => $args];
                        try {
                            $res = AgentTools::execute($toolCtx, $name, $args);
                            if (is_array($res) && !empty($res['requiresApproval'])) {
                                $pendingApprovals[] = $res;
                            }
                        } catch (\Throwable $e) {
                            $res = ['error' => $e->getMessage()];
                        }

                        yield ['type' => 'tool_result', 'tool' => $name, 'result' => $res];

                        $chatMsgs[] = [
                            'role' => 'tool',
                            'tool_call_id' => (string) ($tc['id'] ?? ''),
                            'content' => (string) json_encode($res, JSON_UNESCAPED_UNICODE),
                        ];

                        if ($conversationId !== null) {
                            Conversations::saveCheckpoint([
                                'conversationId' => $conversationId,
                                'stepIndex' => $stepIdx,
                                'providerId' => $p['id'],
                                'modelId' => $targetModel['id'],
                                'chatHistory' => $chatMsgs,
                                'status' => 'in_progress',
                            ]);
                        }
                    }
                }

                ProviderStore::breaker()->recordSuccess((string) $p['id']);
                yield [
                    'type' => 'done',
                    'steps' => $maxSteps,
                    'provider' => $p['id'],
                    'model' => $targetModel['id'],
                    'isFallback' => $isFallback,
                ];
                if ($conversationId !== null) {
                    Conversations::clearCheckpoints($conversationId);
                }
                return;
            } catch (\Throwable $e) {
                $errText = $e->getMessage();
                ProviderStore::breaker()->recordFailure((string) $p['id']);
                $store->recordMetric((string) $p['id'], (string) $targetModel['id'], 0, true);

                if ($conversationId !== null) {
                    Conversations::saveCheckpoint([
                        'conversationId' => $conversationId,
                        'stepIndex' => $stepIdx,
                        'providerId' => $p['id'],
                        'modelId' => $targetModel['id'],
                        'chatHistory' => $chatMsgs,
                        'status' => 'failed',
                        'errorMessage' => $errText,
                    ]);
                }

                if (self::isRateLimitError($e)) {
                    $fallbacks = $store->verifiedFallbackCandidates((string) $p['id'], (string) $targetModel['id'], true);
                    if ($fallbacks) {
                        [$nextP, $nextM] = $fallbacks[0];
                        yield [
                            'type' => 'model_switched_rate_limit',
                            'previousProvider' => $p['name'],
                            'previousModel' => $targetModel['name'] ?? $targetModel['id'],
                            'newProvider' => $nextP['name'],
                            'newModel' => $nextM['name'] ?? $nextM['id'],
                            'reason' => "خطای ریت‌لیمیت یا اتمام اعتبار ({$errText})؛ سوییچ هوشمند به مدل " . ($nextM['name'] ?? $nextM['id']) . ' از ارائه‌دهنده ' . $nextP['name'],
                        ];
                    }
                }

                if ($p['id'] === $primary['id']) {
                    $primaryError = $errText . ' (Endpoint: ' . $p['url'] . ')';
                } else {
                    $fallbackErrors[] = [
                        'provider' => $p['id'],
                        'providerName' => $p['name'],
                        'model' => $targetModel['id'],
                        'url' => $p['url'],
                        'error' => $errText,
                    ];
                }
                continue;
            }
        }

        yield [
            'type' => 'error',
            'error' => "Failed to get response from {$primary['name']}: " . ($primaryError ?? 'Network/API error'),
            'errorDetails' => [
                'provider' => $primary['id'],
                'providerName' => $primary['name'],
                'model' => $primaryModel['id'],
                'protocol' => $primary['protocol'],
                'url' => $primary['url'],
                'error' => $primaryError ?? 'All candidate models failed to respond.',
                'fallbackErrors' => $fallbackErrors,
                'timestamp' => self::nowUtc(),
                'remediation' => "1. Check the provider API keys in the .env file or the Settings tab.\n"
                    . "2. In Providers & Models, run the model health test.\n"
                    . "3. Verify the proxy gateway URL in Settings (AGENT_PROXY_URL).",
            ],
        ];
    }

    /* ---------------------------------------------------------------- */
    /* Non-streaming agent loop                                          */
    /* ---------------------------------------------------------------- */

    public static function completeChat(ProviderStore $store, array $opts): array
    {
        $maxSteps = (int) ($opts['maxSteps'] ?? self::MAX_STEPS_SYNC);
        $prep = self::prepare($opts);
        $conversationId = $prep['conversationId'];
        $ws = $prep['workspace'];
        $chatMsgs = $prep['chatMsgs'];
        $toolCtx = new ToolContext($ws, $conversationId, (string) ($opts['userId'] ?? 'agent'));

        $primary = $store->get((string) ($opts['providerId'] ?? ''));
        if ($primary === null) {
            throw new HttpError(400, "Provider '" . ($opts['providerId'] ?? '') . "' is not configured in the Provider Catalog.");
        }
        $primaryModel = $store->findModel($primary, (string) ($opts['modelId'] ?? ''));

        $primaryKey = $store->apiKey($primary);
        if ($primaryKey === '' && !in_array($primary['protocol'], ['ollama', 'workers-ai'], true)) {
            if (!self::hasAnyOtherUsableProvider($store, (string) $primary['id'])) {
                $errMsg = "Provider '{$primary['name']}' ({$primary['id']}) does not have an API key configured.";
                $envName = $primary['apiKeyEnv'] ?: 'OPENROUTER_API_KEY';
                return [
                    'message' => [
                        'role' => 'assistant',
                        'content' => "⚠️ **API Key Required**: Provider `{$primary['name']}` (`{$primary['id']}`) does not have an API key configured.\n\n"
                            . "Add `{$envName}=...` to the `.env` file, or enter it in the **Providers & Models** / **Security & Settings** tab.",
                    ],
                    'steps' => 0,
                    'provider' => $primary['id'],
                    'model' => $primaryModel['id'],
                    'errorDetails' => [
                        'provider' => $primary['id'],
                        'providerName' => $primary['name'],
                        'model' => $primaryModel['id'],
                        'protocol' => $primary['protocol'],
                        'url' => $primary['url'],
                        'error' => $errMsg,
                        'timestamp' => self::nowUtc(),
                        'remediation' => "Configure the API key for {$primary['name']}.",
                    ],
                    'pendingApprovals' => [],
                ];
            }
        }

        $candidates = self::buildCandidates($store, $primary, $primaryModel);
        $pendingApprovals = [];
        $stepHistory = [];
        $primaryError = null;
        $fallbackErrors = [];
        $maxRetrySleep = (int) Config::rawInt('MAX_RETRY_SLEEP_SEC', 20) ?: 20;

        foreach ($candidates as $cand) {
            $p = $cand['provider'];
            $targetModel = $cand['model'];
            $isFallback = $cand['isFallback'];

            $apiKey = $store->apiKey($p);
            if ($apiKey === '' && !in_array($p['protocol'], ['ollama', 'workers-ai'], true)) {
                continue;
            }

            try {
                for ($stepIdx = 0; $stepIdx < $maxSteps; $stepIdx++) {
                    $resp = null;
                    for ($attempt = 1; $attempt <= self::MAX_ATTEMPTS; $attempt++) {
                        try {
                            $resp = self::callProviderApi($store, $p, $targetModel, $chatMsgs, $apiKey);
                            break;
                        } catch (\Throwable $reqErr) {
                            if (self::isRateLimitError($reqErr) || !self::isNetworkError($reqErr) || $attempt >= self::MAX_ATTEMPTS) {
                                throw $reqErr;
                            }
                            sleep((int) min(min(2 ** ($attempt - 1), 60), $maxRetrySleep));
                        }
                    }
                    if (!is_array($resp) || empty($resp['choices'])) {
                        break;
                    }

                    $msg = $resp['choices'][0]['message'] ?? ['role' => 'assistant', 'content' => ''];
                    $chatMsgs[] = $msg;

                    $toolCalls = $msg['tool_calls'] ?? [];
                    if (!$toolCalls) {
                        $savedFiles = self::autoDetectAndSaveCodeFiles($ws, (string) ($msg['content'] ?? ''));
                        $executionReports = [];
                        foreach ($savedFiles as $sf) {
                            if (!$sf['isExecutable']) {
                                continue;
                            }
                            $executionReports[] = Terminal::executeFile($ws, $sf['path'], $conversationId);
                        }

                        if ($conversationId !== null) {
                            Conversations::saveCheckpoint([
                                'conversationId' => $conversationId,
                                'stepIndex' => $stepIdx,
                                'providerId' => $p['id'],
                                'modelId' => $targetModel['id'],
                                'accumulatedContent' => (string) ($msg['content'] ?? ''),
                                'chatHistory' => $chatMsgs,
                                'savedFiles' => $savedFiles,
                                'executionResults' => $executionReports,
                                'status' => 'completed',
                            ]);
                            Conversations::clearCheckpoints($conversationId);
                        }

                        ProviderStore::breaker()->recordSuccess((string) $p['id']);
                        $store->recordMetric((string) $p['id'], (string) $targetModel['id'], 0, false);

                        return [
                            'message' => $msg,
                            'steps' => $stepIdx + 1,
                            'provider' => $p['id'],
                            'model' => $targetModel['id'],
                            'reasoning' => $msg['reasoning_content'] ?? '',
                            'savedFiles' => $savedFiles,
                            'executionReports' => $executionReports,
                            'stepHistory' => $stepHistory,
                            'pendingApprovals' => $pendingApprovals,
                            'isFallback' => $isFallback,
                            'fallbackDetails' => $isFallback ? self::fallbackDetails($primary, $primaryModel, $p, $targetModel) : null,
                        ];
                    }

                    foreach ($toolCalls as $tc) {
                        $name = (string) ($tc['function']['name'] ?? '');
                        $args = json_decode((string) ($tc['function']['arguments'] ?? '{}'), true);
                        if (!is_array($args)) {
                            $args = [];
                        }
                        $started = microtime(true);
                        $status = 'success';
                        try {
                            $res = AgentTools::execute($toolCtx, $name, $args);
                            if (is_array($res) && !empty($res['requiresApproval'])) {
                                $pendingApprovals[] = $res;
                            }
                        } catch (\Throwable $e) {
                            $res = ['error' => $e->getMessage()];
                            $status = 'error';
                        }
                        $stepHistory[] = [
                            'step' => $stepIdx,
                            'tool' => $name,
                            'args' => $args,
                            'status' => $status,
                            'durationMs' => (int) round((microtime(true) - $started) * 1000),
                            'result' => $res,
                        ];
                        $chatMsgs[] = [
                            'role' => 'tool',
                            'tool_call_id' => (string) ($tc['id'] ?? ''),
                            'content' => (string) json_encode($res, JSON_UNESCAPED_UNICODE),
                        ];
                    }
                }

                return [
                    'message' => ['role' => 'assistant', 'content' => 'Reached the maximum number of agent steps.'],
                    'steps' => $maxSteps,
                    'provider' => $p['id'],
                    'model' => $targetModel['id'],
                    'stepHistory' => $stepHistory,
                    'pendingApprovals' => $pendingApprovals,
                    'isFallback' => $isFallback,
                ];
            } catch (\Throwable $e) {
                $errText = $e->getMessage();
                ProviderStore::breaker()->recordFailure((string) $p['id']);
                $store->recordMetric((string) $p['id'], (string) $targetModel['id'], 0, true);
                if ($p['id'] === $primary['id']) {
                    $primaryError = $errText . ' (Endpoint: ' . $p['url'] . ')';
                } else {
                    $fallbackErrors[] = [
                        'provider' => $p['id'],
                        'providerName' => $p['name'],
                        'model' => $targetModel['id'],
                        'url' => $p['url'],
                        'error' => $errText,
                    ];
                }
                continue;
            }
        }

        return [
            'message' => [
                'role' => 'assistant',
                'content' => "⚠️ Failed to get a response from {$primary['name']}: " . ($primaryError ?? 'Network/API error'),
            ],
            'steps' => 0,
            'provider' => $primary['id'],
            'model' => $primaryModel['id'],
            'errorDetails' => [
                'provider' => $primary['id'],
                'providerName' => $primary['name'],
                'model' => $primaryModel['id'],
                'protocol' => $primary['protocol'],
                'url' => $primary['url'],
                'error' => $primaryError ?? 'All candidate models failed to respond.',
                'fallbackErrors' => $fallbackErrors,
                'timestamp' => self::nowUtc(),
            ],
            'pendingApprovals' => $pendingApprovals,
        ];
    }
}

/* ==========================================================================
 * FILE: Jobs.php
 * ========================================================================== */
/**
 * Background job queue. Port of agent-python/app/worker.py.
 *
 * The Python version ran a `while True` asyncio loop inside the server
 * process. PHP-FPM requests die at the end of the response, so the same
 * lifecycle is built from two primitives:
 *   • `bin/worker.php` — a real long-lived daemon that drains the queue
 *     (systemd / supervisor / `nohup`), the supervision path.
 *   • an autospawned detached `php bin/worker.php --job <id>` right after the
 *     enqueueing request, the low-latency path.
 *
 * Claiming is atomic (`UPDATE ... WHERE status='queued'`) so the two can never
 * run the same job twice. Job state lives in SQLite, artifacts on disk under
 * `storage/job_outputs/`.
 */

final class Jobs
{
    public const DEFAULT_MAX_STEPS = 8;
    public const DEFAULT_TIMEOUT_SEC = 600;

    /* ------------------------------------------------- control flags */

    private static function flagKey(string $jobId): string
    {
        return 'job:control:' . $jobId;
    }

    public static function setControlFlag(string $jobId, string $flag): void
    {
        Database::setState(self::flagKey($jobId), $flag);
    }

    public static function controlFlag(string $jobId): string
    {
        return (string) Database::state(self::flagKey($jobId), '');
    }

    public static function clearControlFlag(string $jobId): void
    {
        Database::run('DELETE FROM app_state WHERE key = ?', [self::flagKey($jobId)]);
    }

    /* ----------------------------------------------------- artifacts */

    private static function artifactPath(string $jobId): string
    {
        return Bootstrap::$jobOutputsDir . '/' . $jobId . '.json';
    }

    public static function saveArtifact(string $jobId, mixed $data): string
    {
        $path = self::artifactPath($jobId);
        Files::write($path, (string) json_encode($data, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_PARTIAL_OUTPUT_ON_ERROR));
        return 'file://' . $path;
    }

    public static function loadArtifact(string $jobId): mixed
    {
        $path = self::artifactPath($jobId);
        if (!is_file($path)) {
            return null;
        }
        return json_decode(Files::read($path), true);
    }

    /* ---------------------------------------------------- logs/steps */

    public static function log(string $jobId, string $level, string $message): void
    {
        try {
            Database::run('INSERT INTO job_logs (job_id, level, message) VALUES (?,?,?)', [$jobId, $level, Security::maskLogTokens($message)]);
        } catch (\Throwable) {
        }
    }

    public static function logs(string $jobId, int $limit = 500): array
    {
        return Database::all(
            'SELECT level, message, created_at FROM job_logs WHERE job_id = ? ORDER BY id ASC LIMIT ?',
            [$jobId, $limit]
        );
    }

    public static function recordStep(
        string $jobId,
        int $stepIndex,
        string $toolName,
        array $args,
        mixed $result,
        string $status,
        float $durationMs
    ): void {
        try {
            Database::run(
                'INSERT INTO job_steps (id, job_id, step_index, tool_name, arguments, result, status, duration_ms)
                 VALUES (?,?,?,?,?,?,?,?)',
                [
                    'step-' . Crypto::hex(2),
                    $jobId,
                    $stepIndex,
                    $toolName,
                    (string) json_encode($args, JSON_UNESCAPED_UNICODE),
                    is_string($result) ? $result : (string) json_encode($result, JSON_UNESCAPED_UNICODE | JSON_PARTIAL_OUTPUT_ON_ERROR),
                    $status,
                    (int) round($durationMs),
                ]
            );
        } catch (\Throwable) {
        }
    }

    /* -------------------------------------------------------- CRUD */

    public static function create(array $input): array
    {
        $jobId = 'job-' . time() . '-' . Crypto::hex(2);
        Database::run(
            "INSERT INTO jobs (id, workspace_id, user_id, conversation_id, title, provider_id, model_id,
                               status, max_steps, max_timeout_sec, payload)
             VALUES (?,?,?,?,?,?,?, 'queued', ?, ?, ?)",
            [
                $jobId,
                (string) ($input['workspaceId'] ?? Workspaces::DEFAULT_ID),
                (string) ($input['userId'] ?? 'user'),
                (string) ($input['conversationId'] ?? ''),
                (string) ($input['title'] ?? 'Background job'),
                (string) ($input['providerId'] ?? ''),
                (string) ($input['modelId'] ?? ''),
                (int) ($input['maxSteps'] ?? self::DEFAULT_MAX_STEPS),
                (int) ($input['maxTimeoutSec'] ?? self::DEFAULT_TIMEOUT_SEC),
                (string) json_encode($input['payload'] ?? [], JSON_UNESCAPED_UNICODE),
            ]
        );
        self::log($jobId, 'INFO', 'Job created and queued: ' . ($input['title'] ?? ''));
        self::autospawn($jobId);
        return self::details($jobId) ?? [];
    }

    /** Kick a detached worker for this job so it starts without waiting for the daemon tick. */
    public static function autospawn(string $jobId): void
    {
        if (!Config::rawBool('AGENT_WORKER_AUTOSPAWN', true)) {
            return;
        }
        if (self::daemonRunning()) {
            return; // the daemon will pick it up within a second
        }
        if (!function_exists('proc_open')) {
            return;
        }
        $php = PHP_BINARY ?: 'php';
        $script = Bootstrap::$binDir . '/worker.php';
        if (!is_file($script)) {
            return;
        }
        $cmd = escapeshellarg($php) . ' ' . escapeshellarg($script) . ' --job ' . escapeshellarg($jobId);
        try {
            Terminal::startDetached($cmd, Bootstrap::$root, 'worker');
        } catch (\Throwable $e) {
            Observability::log('WARNING', 'WORKER', 'Could not autospawn job worker: ' . $e->getMessage());
        }
    }

    public static function daemonRunning(): bool
    {
        $hb = (int) Database::state('worker:heartbeat', '0');
        return $hb > 0 && (time() - $hb) < 30;
    }

    public static function heartbeat(): void
    {
        Database::setState('worker:heartbeat', (string) time());
    }

    public static function details(string $jobId): ?array
    {
        $row = Database::one(
            'SELECT id, workspace_id, user_id, conversation_id, provider_id, model_id, title, status,
                    progress, step_count, max_steps, max_timeout_sec, retry_count, max_retries, error,
                    result_ref, summary, payload, created_at, updated_at, started_at, finished_at
             FROM jobs WHERE id = ?',
            [$jobId]
        );
        if ($row === null) {
            return null;
        }
        $payload = json_decode((string) ($row['payload'] ?? ''), true);
        $row['payload'] = is_array($payload) ? $payload : [];
        $row['steps'] = Database::all(
            'SELECT step_index, tool_name, arguments, result, status, duration_ms, created_at
             FROM job_steps WHERE job_id = ? ORDER BY step_index ASC',
            [$jobId]
        );
        $row['logs'] = self::logs($jobId);
        if (!empty($row['result_ref'])) {
            $row['result'] = self::loadArtifact($jobId);
        }
        return $row;
    }

    public static function all(array $filters = []): array
    {
        $query = 'SELECT id, workspace_id, user_id, title, provider_id, model_id, status, progress,
                         step_count, max_steps, retry_count, error, created_at, updated_at,
                         started_at, finished_at
                  FROM jobs WHERE 1=1';
        $params = [];
        if (!empty($filters['status'])) {
            $query .= ' AND status = ?';
            $params[] = $filters['status'];
        }
        if (!empty($filters['provider'])) {
            $query .= ' AND provider_id = ?';
            $params[] = $filters['provider'];
        }
        if (!empty($filters['model'])) {
            $query .= ' AND model_id = ?';
            $params[] = $filters['model'];
        }
        $query .= ' ORDER BY created_at DESC LIMIT ?';
        $params[] = (int) ($filters['limit'] ?? 50);
        return Database::all($query, $params);
    }

    public static function cancel(string $jobId): bool
    {
        self::setControlFlag($jobId, 'cancel');
        Database::run("UPDATE jobs SET status = 'cancelled', updated_at = datetime('now') WHERE id = ?", [$jobId]);
        self::log($jobId, 'WARNING', 'Job cancelled by user.');
        return true;
    }

    public static function pause(string $jobId): bool
    {
        self::setControlFlag($jobId, 'pause');
        Database::run("UPDATE jobs SET status = 'paused', updated_at = datetime('now') WHERE id = ?", [$jobId]);
        self::log($jobId, 'INFO', 'Job paused.');
        return true;
    }

    public static function resume(string $jobId): bool
    {
        self::clearControlFlag($jobId);
        Database::run("UPDATE jobs SET status = 'queued', updated_at = datetime('now') WHERE id = ?", [$jobId]);
        self::log($jobId, 'INFO', 'Job resumed and re-queued.');
        self::autospawn($jobId);
        return true;
    }

    public static function retry(string $jobId): bool
    {
        self::clearControlFlag($jobId);
        Database::run("UPDATE jobs SET status = 'queued', error = '', updated_at = datetime('now') WHERE id = ?", [$jobId]);
        self::log($jobId, 'INFO', 'Job manually re-queued for retry.');
        self::autospawn($jobId);
        return true;
    }

    public static function deleteOld(int $days = 7): int
    {
        $stmt = Database::run("DELETE FROM jobs WHERE created_at < datetime('now', '-' || ? || ' days')", [$days]);
        return $stmt->rowCount();
    }

    /* ---------------------------------------------------- execution */

    /** Port of `recover_orphaned_jobs`. */
    public static function recoverOrphaned(): int
    {
        $rows = Database::all("SELECT id, retry_count, max_retries FROM jobs WHERE status = 'running'");
        foreach ($rows as $r) {
            if ((int) ($r['retry_count'] ?? 0) < (int) ($r['max_retries'] ?? 3)) {
                Database::run(
                    "UPDATE jobs SET status = 'queued', retry_count = retry_count + 1, updated_at = datetime('now') WHERE id = ?",
                    [$r['id']]
                );
                self::log((string) $r['id'], 'WARNING', 'Recovered job from worker restart: re-queued for execution.');
            } else {
                Database::run(
                    "UPDATE jobs SET status = 'failed',
                     error = 'Worker restarted while job was in progress (max retries reached)',
                     updated_at = datetime('now') WHERE id = ?",
                    [$r['id']]
                );
                self::log((string) $r['id'], 'ERROR', 'Job marked failed due to worker restart.');
            }
        }
        return count($rows);
    }

    /** Atomically move a queued job to running. Returns false when someone beat us to it. */
    public static function claim(string $jobId): bool
    {
        $stmt = Database::run(
            "UPDATE jobs SET status = 'running', started_at = datetime('now'), updated_at = datetime('now')
             WHERE id = ? AND status = 'queued'",
            [$jobId]
        );
        return $stmt->rowCount() > 0;
    }

    /** Port of `execute_job_task`. */
    public static function execute(string $jobId, bool $alreadyClaimed = false): void
    {
        if (!$alreadyClaimed && !self::claim($jobId)) {
            return;
        }
        self::log($jobId, 'INFO', 'Starting job task execution...');

        $job = self::details($jobId);
        if ($job === null) {
            return;
        }

        $payload = $job['payload'] ?? [];

        // Non-LLM job kinds run their own pipeline (local model installs, …).
        $kind = (string) ($payload['kind'] ?? 'chat');
        if ($kind === 'localai_install') {
            LocalAI::runInstallJob($jobId, $payload);
            self::clearControlFlag($jobId);
            return;
        }

        $messages = $payload['messages'] ?? [['role' => 'user', 'content' => (string) ($payload['message'] ?? $job['title'] ?? '')]];
        $timeoutSec = (int) ($job['max_timeout_sec'] ?? self::DEFAULT_TIMEOUT_SEC);
        $started = microtime(true);

        // Wall-clock guard: PHP CLI has no time limit by default, so arm one.
        if (PHP_SAPI === 'cli') {
            @set_time_limit($timeoutSec + 30);
        }

        try {
            $store = ProviderStore::reload();
            $result = Chat::completeChat($store, [
                'providerId' => (string) $job['provider_id'],
                'modelId' => (string) $job['model_id'],
                'messages' => $messages,
                'maxSteps' => (int) ($job['max_steps'] ?? self::DEFAULT_MAX_STEPS),
                'userId' => (string) ($job['user_id'] ?? 'user'),
                'conversationId' => ($job['conversation_id'] ?? '') ?: null,
            ]);

            if (self::controlFlag($jobId) === 'cancel') {
                Database::run(
                    "UPDATE jobs SET status = 'cancelled', finished_at = datetime('now'), updated_at = datetime('now') WHERE id = ?",
                    [$jobId]
                );
                return;
            }

            foreach (array_values($result['stepHistory'] ?? []) as $i => $step) {
                self::recordStep(
                    $jobId,
                    (int) ($step['step'] ?? $i),
                    (string) ($step['tool'] ?? ''),
                    (array) ($step['args'] ?? []),
                    $step['result'] ?? null,
                    (string) ($step['status'] ?? 'success'),
                    (float) ($step['durationMs'] ?? 0)
                );
            }

            $artifactRef = self::saveArtifact($jobId, $result);
            $summary = mb_substr((string) ($result['message']['content'] ?? ''), 0, 300);

            Database::run(
                "UPDATE jobs SET status = 'done', progress = 100.0, step_count = ?, result_ref = ?,
                 summary = ?, finished_at = datetime('now'), updated_at = datetime('now') WHERE id = ?",
                [(int) ($result['steps'] ?? 1), $artifactRef, $summary, $jobId]
            );
            self::log($jobId, 'INFO', 'Job completed successfully in ' . (int) round(microtime(true) - $started) . 's.');
        } catch (\Throwable $e) {
            $errStr = $e->getMessage();
            $isTimeout = str_contains(strtolower($errStr), 'timed out') || str_contains($errStr, '__job_timeout__');
            Database::run(
                "UPDATE jobs SET status = 'failed', error = ?, finished_at = datetime('now'), updated_at = datetime('now') WHERE id = ?",
                [$errStr, $jobId]
            );
            self::log($jobId, 'ERROR', $isTimeout
                ? "Job exceeded max execution time ({$timeoutSec}s)."
                : "Job failed with error: {$errStr}");
        } finally {
            self::clearControlFlag($jobId);
        }
    }

    /**
     * One supervision tick — replaces `persistent_worker_loop`'s body.
     * Recovers orphans, then drains up to MAX_CONCURRENT_JOBS queued jobs.
     *
     * @return array{recovered:int, started:string[]}
     */
    public static function drain(bool $recover = true): array
    {
        $recovered = $recover ? self::recoverOrphaned() : 0;
        $maxConcurrent = Config::maxConcurrentJobs();
        $rows = Database::all("SELECT id FROM jobs WHERE status = 'queued' ORDER BY created_at ASC LIMIT ?", [$maxConcurrent]);

        $started = [];
        foreach ($rows as $r) {
            $jid = (string) $r['id'];
            if (!self::claim($jid)) {
                continue;
            }
            $started[] = $jid;
            self::execute($jid, true);
        }

        if ($recovered > 0 || $started) {
            Observability::log('INFO', 'WORKER', 'Job queue drained', ['recovered' => $recovered, 'started' => $started]);
        }
        return ['recovered' => $recovered, 'started' => $started];
    }

    public static function stats(): array
    {
        $rows = Database::all('SELECT status, COUNT(*) AS n FROM jobs GROUP BY status');
        $counts = [];
        foreach ($rows as $r) {
            $counts[(string) $r['status']] = (int) $r['n'];
        }
        return [
            'total' => array_sum($counts),
            'byStatus' => $counts,
            'queued' => $counts['queued'] ?? 0,
            'running' => $counts['running'] ?? 0,
            'done' => $counts['done'] ?? 0,
            'failed' => $counts['failed'] ?? 0,
            'workerRunning' => self::daemonRunning(),
            'maxConcurrent' => Config::maxConcurrentJobs(),
        ];
    }
}

/* ==========================================================================
 * FILE: Auth.php
 * ========================================================================== */
/**
 * Session auth, RBAC, the auth middleware and user management.
 * Port of agent-python/app/auth.py.
 */

final class Auth
{
    public const SESSION_COOKIE = Security::SESSION_COOKIE;

    public const ANONYMOUS_ADMIN = [
        'id' => 'anonymous-admin',
        'username' => 'admin',
        'role' => Security::ROLE_ADMIN,
        'full_name' => 'Anonymous Superuser',
    ];

    /** Port of `public_paths` in auth_middleware. */
    public const PUBLIC_PATHS = [
        '/health',
        '/api/version',
        '/api/auth/status',
        '/api/auth/login',
        '/docs',
        '/openapi.json',
        '/redoc',
    ];

    public const VALID_ROLES = [Security::ROLE_ADMIN, Security::ROLE_DEVELOPER, Security::ROLE_VIEWER];

    public static function sessionToken(Request $req): string
    {
        $cookie = $req->cookies[self::SESSION_COOKIE] ?? '';
        if ($cookie !== '') {
            return (string) $cookie;
        }
        $authHeader = (string) $req->header('authorization', '');
        if (str_starts_with($authHeader, 'Bearer ')) {
            return trim(substr($authHeader, 7));
        }
        return (string) $req->header('x-auth-token', '');
    }

    public static function currentUserOptional(Request $req): ?array
    {
        $token = self::sessionToken($req);
        return $token === '' ? null : Security::validateSession($token);
    }

    /**
     * Rate limiting on /api/*, then session enforcement outside the public
     * path list. Returns true when the request may continue; when it returns
     * false the response has already been written.
     */
    public static function middleware(Request $req): bool
    {
        $path = $req->path;
        $ip = $req->clientIp();

        if (str_starts_with($path, '/api/')) {
            $configured = Config::rateLimitPerMinute();
            $limit = str_contains($path, 'login') ? 30 : $configured;
            if (!Security::checkRateLimit("rate:{$ip}:{$path}", $limit, 60)) {
                Security::logEvent('RATE_LIMIT_EXCEEDED', 'blocked', "Rate limit exceeded on {$path}", $ip);
                Response::json(['detail' => 'Rate limit exceeded. Please try again later.'], 429);
                return false;
            }
        }

        if (!Config::authEnabled()) {
            $req->user = self::ANONYMOUS_ADMIN;
            return true;
        }

        $user = self::currentUserOptional($req);
        if ($user !== null) {
            $req->user = $user;
        }

        if (in_array($path, self::PUBLIC_PATHS, true)) {
            return true;
        }

        if ($user === null && str_starts_with($path, '/api/')) {
            Security::logEvent('UNAUTHORIZED_API_ACCESS', 'failed', "Unauthorized access to {$path}", $ip);
            Response::json(['detail' => 'Authentication required'], 401);
            return false;
        }

        return true;
    }

    /** Port of `get_current_user` — 401 when auth is on and no session exists. */
    public static function requireUser(Request $req): array
    {
        if ($req->user !== null) {
            return $req->user;
        }
        if (!Config::authEnabled()) {
            return self::ANONYMOUS_ADMIN;
        }
        throw new HttpError(401, 'Authentication required');
    }

    /** Port of `require_role([...])`. */
    public static function requireRole(Request $req, array $allowedRoles): array
    {
        if (!Config::authEnabled()) {
            return $req->user ?? self::ANONYMOUS_ADMIN;
        }
        $user = $req->user;
        if ($user === null) {
            throw new HttpError(401, 'Authentication required');
        }
        if (!in_array($user['role'] ?? '', $allowedRoles, true)) {
            Security::logEvent(
                'PERMISSION_DENIED',
                'failed',
                "{$req->method} {$req->path} requires " . implode(', ', $allowedRoles),
                $req->clientIp(),
                (string) ($user['id'] ?? '')
            );
            throw new HttpError(403, 'Permission denied. Required role: ' . implode(', ', $allowedRoles));
        }
        return $user;
    }

    public static function requireAdmin(Request $req): array
    {
        return self::requireRole($req, [Security::ROLE_ADMIN]);
    }

    public static function requireDeveloper(Request $req): array
    {
        return self::requireRole($req, [Security::ROLE_ADMIN, Security::ROLE_DEVELOPER]);
    }

    public static function requireViewer(Request $req): array
    {
        return self::requireRole($req, [Security::ROLE_ADMIN, Security::ROLE_DEVELOPER, Security::ROLE_VIEWER]);
    }

    /* -------------------------------------------------------------- */
    /* Login / logout                                                  */
    /* -------------------------------------------------------------- */

    private static function setSessionCookie(string $token): void
    {
        Response::setCookie(self::SESSION_COOKIE, $token, Security::SESSION_TTL_HOURS * 3600);
    }

    public static function status(Request $req): array
    {
        if (!Config::authEnabled()) {
            return [
                'enabled' => false,
                'authenticated' => true,
                'user' => self::ANONYMOUS_ADMIN,
            ];
        }
        $user = self::currentUserOptional($req);
        return [
            'enabled' => true,
            'authenticated' => $user !== null,
            'user' => $user,
        ];
    }

    public static function login(Request $req, array $payload): array
    {
        $ip = $req->clientIp();
        $ua = $req->userAgent();

        // 1. Direct environment token login.
        $token = trim((string) ($payload['token'] ?? ''));
        if ($token !== '') {
            $envToken = Config::raw('AGENT_AUTH_TOKEN', '');
            if ($envToken !== '' && hash_equals($envToken, $token)) {
                $sessionToken = Security::createSession('env-admin', $ip, $ua);
                self::setSessionCookie($sessionToken);
                Security::logEvent('LOGIN_SUCCESS_TOKEN', 'success', 'Admin logged in via token', $ip, 'env-admin');
                return [
                    'ok' => true,
                    'token' => $sessionToken,
                    'user' => ['id' => 'env-admin', 'username' => 'admin', 'role' => Security::ROLE_ADMIN, 'full_name' => 'Environment Admin'],
                ];
            }
        }

        // 2. Username / password login.
        $username = trim((string) ($payload['username'] ?? ''));
        $password = (string) ($payload['password'] ?? '');
        if ($username !== '' && $password !== '') {
            $row = Database::one(
                'SELECT id, username, password_hash, salt, role, full_name FROM users WHERE username = ?',
                [$username]
            );
            if ($row !== null && Crypto::verifyPassword($password, (string) $row['password_hash'], (string) $row['salt'])) {
                $sessionToken = Security::createSession((string) $row['id'], $ip, $ua);
                self::setSessionCookie($sessionToken);
                Security::logEvent('LOGIN_SUCCESS', 'success', "User {$row['username']} logged in", $ip, (string) $row['id']);
                return [
                    'ok' => true,
                    'token' => $sessionToken,
                    'user' => [
                        'id' => $row['id'],
                        'username' => $row['username'],
                        'role' => $row['role'],
                        'full_name' => $row['full_name'],
                    ],
                ];
            }
        }

        Security::logEvent('LOGIN_FAILED', 'failed', "Failed login attempt for username: {$username}", $ip);
        throw new HttpError(401, 'Invalid username or password');
    }

    public static function logout(Request $req): void
    {
        $token = self::sessionToken($req);
        if ($token !== '') {
            Security::deleteSession($token);
        }
        Response::clearCookie(self::SESSION_COOKIE);
    }

    public static function changePassword(Request $req, string $oldPassword, string $newPassword): void
    {
        $user = self::requireUser($req);
        $uid = (string) ($user['id'] ?? '');
        if ($uid === 'env-admin' || $uid === 'anonymous-admin') {
            throw new HttpError(400, 'Cannot change password for environment admin. Update AGENT_AUTH_TOKEN in configuration.');
        }
        if (strlen($newPassword) < 6) {
            throw new HttpError(400, 'New password must be at least 6 characters long');
        }
        $row = Database::one('SELECT password_hash, salt FROM users WHERE id = ?', [$uid]);
        if ($row === null || !Crypto::verifyPassword($oldPassword, (string) $row['password_hash'], (string) $row['salt'])) {
            throw new HttpError(400, 'Incorrect current password');
        }
        [$hash, $salt] = Crypto::hashPassword($newPassword);
        Database::run(
            "UPDATE users SET password_hash = ?, salt = ?, updated_at = datetime('now') WHERE id = ?",
            [$hash, $salt, $uid]
        );
        Security::logEvent('PASSWORD_CHANGED', 'success', "User {$user['username']} changed password", $req->clientIp(), $uid);
    }

    /* -------------------------------------------------------------- */
    /* User management                                                 */
    /* -------------------------------------------------------------- */

    public static function users(): array
    {
        return Database::all(
            'SELECT id, username, role, full_name, is_active, created_at, last_login
             FROM users ORDER BY created_at ASC'
        );
    }

    public static function createUser(string $username, string $password, string $role = Security::ROLE_DEVELOPER, string $fullName = ''): array
    {
        if (!in_array($role, self::VALID_ROLES, true)) {
            throw new HttpError(400, 'Invalid role');
        }
        $name = trim($username);
        if ($name === '' || $password === '') {
            throw new HttpError(400, 'Username and password are required');
        }
        [$hash, $salt] = Crypto::hashPassword($password);
        $id = 'user-' . Crypto::hex(3);
        try {
            Database::run(
                'INSERT INTO users (id, username, password_hash, salt, role, full_name) VALUES (?,?,?,?,?,?)',
                [$id, $name, $hash, $salt, $role, $fullName]
            );
        } catch (\Throwable $e) {
            throw new HttpError(400, 'Could not create user: ' . $e->getMessage());
        }
        Security::logEvent('USER_CREATED', 'success', "Created user {$name} ({$role})");
        return ['id' => $id, 'username' => $name, 'role' => $role];
    }

    public static function updateUserRole(string $userId, string $role): void
    {
        if (!in_array($role, self::VALID_ROLES, true)) {
            throw new HttpError(400, 'Invalid role');
        }
        Database::run("UPDATE users SET role = ?, updated_at = datetime('now') WHERE id = ?", [$role, $userId]);
    }

    public static function deleteUser(string $userId, string $actingUserId): void
    {
        if ($userId === $actingUserId) {
            throw new HttpError(400, 'Cannot delete your own active account');
        }
        Database::run('DELETE FROM sessions WHERE user_id = ?', [$userId]);
        Database::run('DELETE FROM users WHERE id = ?', [$userId]);
        Security::logEvent('USER_DELETED', 'success', "Deleted user {$userId}");
    }
}

/* ==========================================================================
 * FILE: Router.php
 * ========================================================================== */
/**
 * Tiny regex router with {param} placeholders and {path:...} greedy captures.
 */

final class Router
{
    /** @var array<string, array<int, array{regex:string, keys:string[], handler:callable}>> */
    private array $routes = [];
    /** @var callable|null */
    private $fallback = null;

    public function add(string $method, string $pattern, callable $handler): void
    {
        $keys = [];
        $regex = preg_replace_callback(
            '#\{([a-zA-Z_][a-zA-Z0-9_]*)(\*)?\}#',
            static function (array $m) use (&$keys): string {
                $keys[] = $m[1];
                return isset($m[2]) && $m[2] === '*' ? '(.+)' : '([^/]+)';
            },
            $pattern
        );
        $this->routes[strtoupper($method)][] = [
            'regex' => '#^' . $regex . '$#',
            'keys' => $keys,
            'handler' => $handler,
        ];
    }

    public function get(string $p, callable $h): void
    {
        $this->add('GET', $p, $h);
    }

    public function post(string $p, callable $h): void
    {
        $this->add('POST', $p, $h);
    }

    public function put(string $p, callable $h): void
    {
        $this->add('PUT', $p, $h);
    }

    public function patch(string $p, callable $h): void
    {
        $this->add('PATCH', $p, $h);
    }

    public function delete(string $p, callable $h): void
    {
        $this->add('DELETE', $p, $h);
    }

    /** Register the same handler for several verbs. */
    public function map(array $methods, string $p, callable $h): void
    {
        foreach ($methods as $m) {
            $this->add($m, $p, $h);
        }
    }

    public function setFallback(callable $h): void
    {
        $this->fallback = $h;
    }

    /** @return array{0:callable,1:array<string,string>}|null */
    public function match(string $method, string $path): ?array
    {
        foreach ($this->routes[strtoupper($method)] ?? [] as $route) {
            if (preg_match($route['regex'], $path, $m)) {
                $params = [];
                foreach ($route['keys'] as $i => $key) {
                    $params[$key] = rawurldecode($m[$i + 1] ?? '');
                }
                return [$route['handler'], $params];
            }
        }
        return null;
    }

    public function allowedMethods(string $path): array
    {
        $allowed = [];
        foreach ($this->routes as $method => $routes) {
            foreach ($routes as $route) {
                if (preg_match($route['regex'], $path)) {
                    $allowed[] = $method;
                    break;
                }
            }
        }
        return $allowed;
    }

    public function dispatch(Request $req): void
    {
        $hit = $this->match($req->method, $req->path);
        if ($hit === null) {
            if ($req->method === 'OPTIONS') {
                Response::sendHeaders(204, [
                    'Allow' => implode(', ', $this->allowedMethods($req->path) ?: ['GET']),
                ]);
                return;
            }
            $allowed = $this->allowedMethods($req->path);
            if ($allowed) {
                Response::json(['detail' => 'Method Not Allowed'], 405, ['Allow' => implode(', ', $allowed)]);
                return;
            }
            if ($this->fallback !== null) {
                ($this->fallback)($req);
                return;
            }
            Response::json(['detail' => 'Not Found'], 404);
            return;
        }
        [$handler, $params] = $hit;
        $req->params = $params;
        $result = $handler($req);
        // Handlers may either write the response themselves (SSE, files) or
        // return an array/scalar that we JSON-encode, like FastAPI does.
        if ($result !== null && !Response::$headersSent) {
            if ($result instanceof \Generator) {
                foreach ($result as $_) {
                    // drained by the handler itself
                }
                return;
            }
            Response::json($result);
        }
    }

    public function routeCount(): int
    {
        return array_sum(array_map('count', $this->routes));
    }

    public function listRoutes(): array
    {
        $out = [];
        foreach ($this->routes as $method => $routes) {
            foreach ($routes as $r) {
                $out[] = ['method' => $method, 'pattern' => $r['regex']];
            }
        }
        return $out;
    }
}

/* ==========================================================================
 * FILE: Routes.php
 * ========================================================================== */
/**
 * The full HTTP API. Port of agent-python/app/main.py (FastAPI) — route paths,
 * HTTP verbs and JSON response shapes are preserved byte-for-byte so the
 * existing single-page UI in public/index.html runs unmodified.
 */

final class Routes
{
    public static function register(Router $r): void
    {
        self::meta($r);
        self::auth($r);
        self::projects($r);
        self::workspaces($r);
        self::files($r);
        self::changesets($r);
        self::terminal($r);
        self::git($r);
        self::github($r);
        self::browser($r);
        self::chat($r);
        self::conversations($r);
        self::jobs($r);
        self::providers($r);
        self::config($r);
        self::observability($r);
        self::localAi($r);
        self::staticUi($r);
    }

    /* ------------------------------------------------------------ */
    /* Helpers                                                       */
    /* ------------------------------------------------------------ */

    /** Mirror of the `if conversation_id: activate session workspace` prelude. */
    private static function wsFor(?string $conversationId): array
    {
        if ($conversationId !== null && trim($conversationId) !== '') {
            try {
                $ws = Workspaces::getOrCreateSessionWorkspace($conversationId);
                Workspaces::setActive((string) $ws['id']);
                return $ws;
            } catch (\Throwable) {
                // fall through to the active workspace
            }
        }
        $ws = Workspaces::active();
        Workspaces::ensureRoot($ws);
        return $ws;
    }

    private static function convOf(Request $req): ?string
    {
        $v = $req->str('conversation_id', '') ?: $req->str('session_id', '') ?: $req->str('conversationId', '');
        return $v !== '' ? $v : null;
    }

    private static function username(Request $req): string
    {
        return (string) ($req->user['username'] ?? 'user');
    }

    private static function q(Request $req, string $key, string $default = ''): string
    {
        $v = $req->query[$key] ?? $default;
        return is_scalar($v) ? (string) $v : $default;
    }

    /* ------------------------------------------------------------ */
    /* Meta                                                          */
    /* ------------------------------------------------------------ */

    private static function meta(Router $r): void
    {
        $r->get('/api/version', static fn(Request $req): array => [
            'name' => 'Arena Coding Agent',
            'version' => APP_VERSION,
            'apiVersion' => APP_API_VERSION,
            'status' => 'ok',
        ]);

        $r->get('/health', static fn(Request $req): array => ['status' => 'ok', 'version' => APP_VERSION]);

        // Self-diagnosis for deployment problems (routing prefix, writability,
        // upload limits). Deliberately unauthenticated-safe: it exposes no
        // secrets, only whether the plumbing works.
        $r->get('/api/__diag', static function (Request $req): array {
            $dataDir = Bootstrap::$dataDir;
            $storageDir = Bootstrap::$storageDir;
            $providersFile = ProviderStore::file();

            $writable = static function (string $path): array {
                $target = is_file($path) ? $path : dirname($path);
                return [
                    'path' => $path,
                    'exists' => file_exists($path),
                    'writable' => is_writable($target),
                ];
            };

            return [
                'status' => 'ok',
                'version' => APP_VERSION,
                'routing' => [
                    'seenPath' => $req->path,
                    'apiBase' => Request::$basePath,
                    'rewriteWorking' => !Request::$viaFrontControllerPath,
                    'requestUri' => (string) ($_SERVER['REQUEST_URI'] ?? ''),
                    'scriptName' => (string) ($_SERVER['SCRIPT_NAME'] ?? ''),
                    'pathInfo' => (string) ($_SERVER['PATH_INFO'] ?? ''),
                    'serverSoftware' => (string) ($_SERVER['SERVER_SOFTWARE'] ?? ''),
                ],
                'limits' => [
                    'post_max_size' => ini_get('post_max_size') ?: '',
                    'upload_max_filesize' => ini_get('upload_max_filesize') ?: '',
                    'memory_limit' => ini_get('memory_limit') ?: '',
                    'max_execution_time' => ini_get('max_execution_time') ?: '',
                ],
                'paths' => [
                    'data' => $writable($dataDir),
                    'storage' => $writable($storageDir),
                    'providers' => $writable($providersFile),
                    'database' => $writable($dataDir . '/agent.db'),
                ],
                'php' => [
                    'version' => PHP_VERSION,
                    'procOpen' => function_exists('proc_open'),
                    'curl' => extension_loaded('curl'),
                    'sqlite' => extension_loaded('pdo_sqlite'),
                    'zip' => extension_loaded('zip'),
                    'openssl' => extension_loaded('openssl'),
                ],
                'auth' => ['enabled' => Config::authEnabled()],
            ];
        });

        // PHP-edition extra: what the host can actually do.
        $r->get('/api/system/capabilities', static function (Request $req): array {
            Auth::requireViewer($req);
            return [
                'capabilities' => Bootstrap::capabilities(),
                'missing' => Bootstrap::missingRequirements(),
                'browserEngine' => Browser::engineName(),
                'gitAvailable' => Git::available(),
                'workerRunning' => Jobs::daemonRunning(),
            ];
        });
    }

    /* ------------------------------------------------------------ */
    /* Auth                                                          */
    /* ------------------------------------------------------------ */

    private static function auth(Router $r): void
    {
        $r->get('/api/auth/status', static fn(Request $req): array => Auth::status($req));

        $r->post('/api/auth/login', static fn(Request $req): array => Auth::login($req, $req->json()));

        $r->post('/api/auth/logout', static function (Request $req): array {
            Auth::logout($req);
            return ['ok' => true];
        });

        $r->post('/api/auth/logout-all', static function (Request $req): array {
            $user = Auth::requireViewer($req);
            Security::deleteAllUserSessions((string) $user['id']);
            Auth::logout($req);
            Security::logEvent(
                'LOGOUT_ALL_SESSIONS',
                'success',
                "User {$user['username']} logged out of all sessions",
                $req->clientIp(),
                (string) $user['id']
            );
            return ['ok' => true, 'message' => 'All sessions terminated'];
        });

        $r->post('/api/auth/renew', static function (Request $req): array {
            $token = Auth::sessionToken($req);
            if ($token === '' || !Security::renewSession($token)) {
                throw new HttpError(401, 'Session expired or invalid');
            }
            return ['ok' => true];
        });

        $r->post('/api/auth/change-password', static function (Request $req): array {
            Auth::requireViewer($req);
            $p = $req->json();
            Auth::changePassword($req, (string) ($p['oldPassword'] ?? ''), (string) ($p['newPassword'] ?? ''));
            return ['ok' => true, 'message' => 'Password updated successfully'];
        });

        $r->get('/api/auth/me', static function (Request $req): array {
            Auth::requireViewer($req);
            return ['user' => $req->user ?? Auth::ANONYMOUS_ADMIN];
        });

        // Alias used by the SPA login screen when no users exist yet.
        $r->post('/api/auth/register', static function (Request $req): array {
            $p = $req->json();
            $count = (int) Database::scalar('SELECT COUNT(*) FROM users');
            $isBootstrap = $count === 0;
            if (!$isBootstrap) {
                $user = $req->user;
                if ($user === null || ($user['role'] ?? '') !== Security::ROLE_ADMIN) {
                    throw new HttpError(403, 'Only an administrator can register new users.');
                }
            }
            $created = Auth::createUser(
                (string) ($p['username'] ?? ''),
                (string) ($p['password'] ?? ''),
                (string) ($p['role'] ?? ($isBootstrap ? Security::ROLE_ADMIN : Security::ROLE_DEVELOPER)),
                (string) ($p['fullName'] ?? '')
            );
            return ['ok' => true] + $created;
        });

        $r->get('/api/users', static function (Request $req): array {
            Auth::requireAdmin($req);
            return ['users' => Auth::users()];
        });

        $r->post('/api/users', static function (Request $req): array {
            $acting = Auth::requireAdmin($req);
            $p = $req->json();
            $created = Auth::createUser(
                (string) ($p['username'] ?? ''),
                (string) ($p['password'] ?? ''),
                (string) ($p['role'] ?? Security::ROLE_DEVELOPER),
                (string) ($p['fullName'] ?? '')
            );
            Security::logEvent(
                'USER_CREATED',
                'success',
                "User {$created['username']} created with role {$created['role']}",
                $req->clientIp(),
                (string) ($acting['id'] ?? '')
            );
            return ['ok' => true] + $created;
        });

        $r->put('/api/users/{userId}/role', static function (Request $req): array {
            Auth::requireAdmin($req);
            Auth::updateUserRole($req->param('userId'), (string) ($req->json()['role'] ?? ''));
            return ['ok' => true];
        });

        $r->delete('/api/users/{userId}', static function (Request $req): array {
            $acting = Auth::requireAdmin($req);
            Auth::deleteUser($req->param('userId'), (string) ($acting['id'] ?? ''));
            return ['ok' => true];
        });

        $r->get('/api/security/logs', static function (Request $req): array {
            Auth::requireAdmin($req);
            $limit = min((int) (self::q($req, 'limit', '100') ?: 100), 1000);
            return [
                'logs' => Database::all(
                    'SELECT id, timestamp, ip, user_id, event, status, details
                     FROM security_logs ORDER BY id DESC LIMIT ?',
                    [$limit]
                ),
            ];
        });
    }

    /* ------------------------------------------------------------ */
    /* Projects                                                      */
    /* ------------------------------------------------------------ */

    private static function projects(Router $r): void
    {
        $r->get('/api/projects', static function (Request $req): array {
            Auth::requireViewer($req);
            return ['projects' => Projects::all(), 'active' => Projects::active()];
        });

        $r->get('/api/projects/{projId}', static function (Request $req): array {
            Auth::requireViewer($req);
            $proj = Projects::find($req->param('projId'));
            if ($proj === null) {
                throw new HttpError(404, 'Project not found');
            }
            return $proj;
        });

        $r->post('/api/projects', static function (Request $req): array {
            Auth::requireDeveloper($req);
            return Projects::create($req->json());
        });

        $r->put('/api/projects/{projId}', static function (Request $req): array {
            Auth::requireDeveloper($req);
            return Projects::update($req->param('projId'), $req->json());
        });

        $r->delete('/api/projects/{projId}', static function (Request $req): array {
            Auth::requireDeveloper($req);
            if (!Projects::delete($req->param('projId'))) {
                throw new HttpError(404, 'Project not found');
            }
            return ['ok' => true];
        });

        $r->post('/api/projects/{projId}/activate', static function (Request $req): array {
            Auth::requireDeveloper($req);
            return Projects::setActive($req->param('projId'));
        });
    }

    /* ------------------------------------------------------------ */
    /* Workspaces                                                    */
    /* ------------------------------------------------------------ */

    private static function workspaces(Router $r): void
    {
        $r->get('/api/workspaces', static function (Request $req): array {
            Auth::requireViewer($req);
            return ['workspaces' => Workspaces::all(), 'active' => Workspaces::active()];
        });

        $r->get('/api/workspace/session/{sessionId}', static function (Request $req): array {
            Auth::requireViewer($req);
            return Workspaces::getOrCreateSessionWorkspace($req->param('sessionId'));
        });

        $r->post('/api/workspace/session/{sessionId}/activate', static function (Request $req): array {
            Auth::requireDeveloper($req);
            $ws = Workspaces::getOrCreateSessionWorkspace($req->param('sessionId'));
            Workspaces::setActive((string) $ws['id']);
            return $ws;
        });

        $r->post('/api/workspace/session/{sessionId}/reset', static function (Request $req): array {
            Auth::requireDeveloper($req);
            return Workspaces::resetSessionWorkspace($req->param('sessionId'));
        });

        $r->post('/api/workspaces', static function (Request $req): array {
            Auth::requireDeveloper($req);
            $p = $req->json();
            $name = trim((string) ($p['name'] ?? ''));
            if ($name === '') {
                throw new HttpError(400, 'Workspace name is required');
            }
            return Workspaces::create(
                $name,
                (string) ($p['template'] ?? 'blank'),
                (string) ($p['instructions'] ?? ''),
                (string) ($p['agentRules'] ?? $p['agent_rules'] ?? '')
            );
        });

        $r->post('/api/workspaces/switch', static function (Request $req): array {
            Auth::requireDeveloper($req);
            $p = $req->json();
            $id = trim((string) ($p['id'] ?? $p['workspaceId'] ?? ''));
            if ($id === '') {
                throw new HttpError(400, 'Workspace id is required');
            }
            return Workspaces::setActive($id);
        });

        $r->delete('/api/workspaces/{wsId}', static function (Request $req): array {
            Auth::requireDeveloper($req);
            Workspaces::delete($req->param('wsId'));
            return ['ok' => true];
        });

        $r->get('/api/workspaces/metrics', static function (Request $req): array {
            Auth::requireViewer($req);
            return Workspaces::stats(Workspaces::active());
        });
    }

    /* ------------------------------------------------------------ */
    /* Workspace files                                               */
    /* ------------------------------------------------------------ */

    private static function files(Router $r): void
    {
        $r->get('/api/workspace/files', static function (Request $req): array {
            Auth::requireViewer($req);
            $ws = self::wsFor(self::q($req, 'conversation_id') ?: null);
            return Files::listDir(Workspaces::ensureRoot($ws), Files::normalizeRel(self::q($req, 'path', '.')));
        });

        $r->get('/api/workspace/file', static function (Request $req): array {
            Auth::requireViewer($req);
            $path = self::q($req, 'path');
            if ($path === '') {
                throw new HttpError(400, 'path is required');
            }
            $ws = self::wsFor(self::q($req, 'conversation_id') ?: null);
            return Workspaces::readFile($ws, $path);
        });

        $r->get('/api/workspace/raw', static function (Request $req): void {
            Auth::requireViewer($req);
            $path = self::q($req, 'path');
            if ($path === '') {
                throw new HttpError(400, 'path is required');
            }
            $convId = self::q($req, 'conversation_id') ?: null;
            $ws = self::wsFor($convId);
            $abs = Workspaces::safePath($ws, $path);
            if (!is_file($abs)) {
                $defaultWs = Workspaces::find('default') ?? Workspaces::fallback();
                $defAbs = Workspaces::safePath($defaultWs, $path);
                if (is_file($defAbs)) {
                    $abs = $defAbs;
                } else {
                    $found = null;
                    $dir = Bootstrap::$workspacesDir;
                    if (is_dir($dir)) {
                        $entries = scandir($dir) ?: [];
                        foreach ($entries as $e) {
                            if ($e === '.' || $e === '..') continue;
                            $cand = $dir . '/' . $e . '/' . ltrim($path, '/');
                            if (is_file($cand)) {
                                $found = $cand;
                                break;
                            }
                        }
                    }
                    if ($found !== null) {
                        $abs = $found;
                    } else {
                        throw new HttpError(404, 'File not found');
                    }
                }
            }
            $mime = Files::mimeType($abs);
            $suffix = strtolower(pathinfo($abs, PATHINFO_EXTENSION));
            if (in_array($suffix, ['html', 'htm'], true)) {
                $rawHtml = Files::read($abs);
                $bundled = Files::bundleHtmlPreview($rawHtml, dirname($abs));
                Response::html($bundled);
                return;
            }
            Response::file($abs, $mime);
        });

        $r->get('/api/workspace/file-preview', static function (Request $req): array {
            Auth::requireViewer($req);
            $path = self::q($req, 'path');
            if ($path === '') {
                throw new HttpError(400, 'path is required');
            }
            $convId = self::q($req, 'conversation_id') ?: null;
            $ws = self::wsFor($convId);
            $abs = Workspaces::safePath($ws, $path);
            if (!is_file($abs) && !is_dir($abs)) {
                $defaultWs = Workspaces::find('default') ?? Workspaces::fallback();
                $defAbs = Workspaces::safePath($defaultWs, $path);
                if (is_file($defAbs) || is_dir($defAbs)) {
                    $ws = $defaultWs;
                }
            }
            $rawBase = '/api/workspace/raw?' . ($convId ? 'conversation_id=' . rawurlencode($convId) . '&' : '') . 'path=';
            return Files::buildPreview(Workspaces::ensureRoot($ws), $path, $rawBase);
        });

        $r->get('/api/workspace/reference-files', static function (Request $req): array {
            Auth::requireViewer($req);
            $targetType = self::q($req, 'target_type', 'chat');
            $targetId = self::q($req, 'target_id');
            return [
                'target_type' => $targetType,
                'target_id' => $targetId,
                'files' => References::listFiles($targetType, $targetId, self::q($req, 'path', '.')),
            ];
        });

        $r->get('/api/workspace/reference-raw', static function (Request $req): void {
            Auth::requireViewer($req);
            $path = self::q($req, 'path');
            if ($path === '') {
                throw new HttpError(400, 'path is required');
            }
            $ws = References::resolveWorkspace(self::q($req, 'target_type', 'chat'), self::q($req, 'target_id'));
            $abs = Workspaces::safePath($ws, $path);
            if (!is_file($abs)) {
                throw new HttpError(404, 'File not found in reference workspace');
            }
            Response::file($abs, Files::mimeType($abs));
        });

        $r->get('/api/workspace/reference-preview', static function (Request $req): array {
            Auth::requireViewer($req);
            $targetType = self::q($req, 'target_type', 'chat');
            $targetId = self::q($req, 'target_id');
            $path = self::q($req, 'path');
            if ($path === '') {
                throw new HttpError(400, 'path is required');
            }
            $ws = References::resolveWorkspace($targetType, $targetId);
            $rawBase = '/api/workspace/reference-raw?target_type=' . rawurlencode($targetType)
                . '&target_id=' . rawurlencode($targetId) . '&path=';
            $preview = Files::buildPreview(Workspaces::ensureRoot($ws), $path, $rawBase);
            return $preview + ['targetType' => $targetType, 'targetId' => $targetId, 'isReferenced' => true];
        });

        $r->post('/api/workspace/import-reference-file', static function (Request $req): array {
            Auth::requireDeveloper($req);
            $p = $req->json();
            $targetId = trim((string) ($p['target_id'] ?? ''));
            $sourcePath = trim((string) ($p['source_path'] ?? ''));
            if ($targetId === '' || $sourcePath === '') {
                throw new HttpError(400, 'target_id and source_path are required');
            }
            $ws = self::wsFor(self::convOf($req));
            return References::copyFile(
                (string) ($p['target_type'] ?? 'chat'),
                $targetId,
                $sourcePath,
                isset($p['dest_path']) ? (string) $p['dest_path'] : null,
                $ws
            );
        });

        $r->post('/api/workspace/execute', static function (Request $req): array {
            Auth::requireDeveloper($req);
            $p = $req->json();
            $path = trim((string) ($p['path'] ?? ''));
            if ($path === '') {
                throw new HttpError(400, 'File path is required');
            }
            $conversationId = self::convOf($req);
            $ws = self::wsFor($conversationId);

            // Reference-prefixed path: @chat:<id>/file or @project:<id>/file
            $ref = References::parsePrefixed($path);
            if ($ref !== null) {
                $refWs = References::resolveWorkspace($ref['targetType'], $ref['targetId']);
                return Terminal::executeFile($refWs, $ref['subpath'], $conversationId);
            }
            return Terminal::executeFile($ws, $path, $conversationId);
        });

        $r->post('/api/workspace/preview', static function (Request $req): array {
            Auth::requireViewer($req);
            $p = $req->json();
            $ws = self::wsFor(self::convOf($req));
            return ChangeSets::previewFileChange($ws, (string) ($p['path'] ?? ''), (string) ($p['content'] ?? ''));
        });

        $r->put('/api/workspace/file', static function (Request $req): array {
            Auth::requireDeveloper($req);
            $p = $req->json();
            $ws = self::wsFor(self::convOf($req));
            $path = (string) ($p['path'] ?? '');
            $content = (string) ($p['content'] ?? '');
            if ($path === '') {
                throw new HttpError(400, 'path is required');
            }

            if (!empty($p['requireApproval'])) {
                $cs = ChangeSets::create(
                    $ws,
                    "Manual edit: {$path}",
                    [['path' => $path, 'new_content' => $content]],
                    self::username($req)
                );
                return ['requiresApproval' => true, 'changeset' => $cs];
            }

            ChangeSets::backupFile($ws, $path);
            $res = Workspaces::writeFile($ws, $path, $content, self::username($req));
            ChangeSets::saveVersion($ws, $path, $content, self::username($req));
            return ['ok' => true, 'path' => $path, 'size' => $res['size'] ?? strlen($content)];
        });

        $r->post('/api/workspace/create', static function (Request $req): array {
            Auth::requireDeveloper($req);
            $p = $req->json();
            $ws = self::wsFor(self::convOf($req));
            $path = trim((string) ($p['path'] ?? ''));
            if ($path === '') {
                throw new HttpError(400, 'Path is required');
            }
            return Workspaces::createEntry($ws, $path, (bool) ($p['isDir'] ?? false), (string) ($p['content'] ?? ''));
        });

        $r->delete('/api/workspace/file', static function (Request $req): array {
            Auth::requireDeveloper($req);
            $path = self::q($req, 'path');
            if ($path === '') {
                throw new HttpError(400, 'Path is required');
            }
            $ws = self::wsFor(self::q($req, 'conversation_id') ?: null);
            return ['ok' => true, 'path' => $path] + Workspaces::deletePath($ws, $path);
        });

        $r->post('/api/workspace/rename', static function (Request $req): array {
            Auth::requireDeveloper($req);
            $p = $req->json();
            $ws = self::wsFor(self::convOf($req));
            $oldPath = trim((string) ($p['oldPath'] ?? ''));
            $newPath = trim((string) ($p['newPath'] ?? ''));
            if ($oldPath === '' || $newPath === '') {
                throw new HttpError(400, 'Both oldPath and newPath are required');
            }
            return ['ok' => true, 'old_path' => $oldPath, 'new_path' => $newPath]
                + Workspaces::rename($ws, $oldPath, $newPath);
        });

        $r->get('/api/workspace/export-zip', static function (Request $req): void {
            Auth::requireViewer($req);
            $ws = self::wsFor(self::q($req, 'conversation_id') ?: null);
            $zipPath = Bootstrap::$storageDir . '/export-' . Crypto::hex(4) . '.zip';
            Files::zipDirectory(Workspaces::ensureRoot($ws), $zipPath);
            try {
                Response::file($zipPath, 'application/zip', 'workspace.zip');
            } finally {
                @unlink($zipPath);
            }
        });

        // File locking (collaborative editing guard).
        $r->get('/api/workspace/locks', static function (Request $req): array {
            Auth::requireViewer($req);
            return ['locks' => ChangeSets::locks()];
        });

        $r->post('/api/workspace/lock', static function (Request $req): array {
            $user = Auth::requireDeveloper($req);
            $p = $req->json();
            $path = (string) ($p['path'] ?? '');
            $ok = ChangeSets::acquireLock($path, (string) ($user['id'] ?? 'user'), (int) ($p['ttl'] ?? 300));
            return ['ok' => $ok, 'path' => $path];
        });

        $r->post('/api/workspace/unlock', static function (Request $req): array {
            $user = Auth::requireDeveloper($req);
            $p = $req->json();
            $path = (string) ($p['path'] ?? '');
            return ['ok' => ChangeSets::releaseLock($path, (string) ($user['id'] ?? 'user')), 'path' => $path];
        });
    }

    /* ------------------------------------------------------------ */
    /* ChangeSets & versions                                         */
    /* ------------------------------------------------------------ */

    private static function changesets(Router $r): void
    {
        $r->get('/api/changesets', static function (Request $req): array {
            Auth::requireViewer($req);
            $ws = self::wsFor(self::q($req, 'conversation_id') ?: null);
            $limit = (int) (self::q($req, 'limit', '50') ?: 50);
            return ['changesets' => ChangeSets::listFor((string) $ws['id'], $limit)];
        });

        $r->get('/api/changesets/{csId}', static function (Request $req): array {
            Auth::requireViewer($req);
            $cs = ChangeSets::get($req->param('csId'));
            if ($cs === null) {
                throw new HttpError(404, 'ChangeSet not found');
            }
            return $cs;
        });

        $r->get('/api/changesets/{csId}/patch', static function (Request $req): void {
            Auth::requireViewer($req);
            $csId = $req->param('csId');
            Response::raw(
                ChangeSets::exportPatch($csId),
                'text/x-patch; charset=utf-8',
                200,
                ['Content-Disposition' => "attachment; filename={$csId}.patch"]
            );
        });

        $r->post('/api/changesets/{csId}/reject-with-feedback', static function (Request $req): array {
