    /* ------------------------------------------------------------ */
    /* Static UI                                                     */
    /* ------------------------------------------------------------ */

    private static function serveSpa(): void
    {
        $index = Bootstrap::$publicDir . '/index.html';
        $html = '';
        if (is_file($index)) {
            $html = Files::read($index);
        } elseif (class_exists('Arena\\EmbeddedAssets') && defined('Arena\\EmbeddedAssets::INDEX_HTML')) {
            $html = EmbeddedAssets::INDEX_HTML;
        }
        if ($html === '') {
            Response::html('<h1>Arena Coding Agent</h1><p>public/index.html is missing.</p>', 500);
            return;
        }
        Response::raw(self::withApiBase($html), 'text/html; charset=utf-8');
    }

    /**
     * Tell the page which URL prefix its API calls need.
     *
     * The front end ships with absolute `/api/...` paths, which only work when
     * the app owns the domain root *and* URL rewriting is available. Injecting
     * the detected prefix makes subdirectory installs and rewrite-less hosts
     * work without touching a single call site.
     */
    private static function withApiBase(string $html): string
    {
        $snippet = '<script>window.__API_BASE__=' . json_encode(Request::$basePath, JSON_UNESCAPED_SLASHES)
            . ';window.__NO_REWRITE__=' . (Request::$viaFrontControllerPath ? 'true' : 'false') . ';</script>';
        $pos = stripos($html, '<head>');
        if ($pos !== false) {
            return substr_replace($html, '<head>' . $snippet, $pos, strlen('<head>'));
        }
        return $snippet . $html;
    }

    private static function staticUi(Router $r): void
    {
        foreach (['/', '/chat', '/ui'] as $p) {
            $r->get($p, static function (Request $req): void {
                self::serveSpa();
            });
        }

        // Local-AI wizard: a separate page so the 347 KB SPA stays untouched.
        foreach (['/localai', '/local-ai'] as $p) {
            $r->get($p, static function (Request $req): void {
                $page = Bootstrap::$publicDir . '/localai.html';
                $html = '';
                if (is_file($page)) {
                    $html = Files::read($page);
                } elseif (class_exists('Arena\\EmbeddedAssets') && defined('Arena\\EmbeddedAssets::LOCALAI_HTML')) {
                    $html = EmbeddedAssets::LOCALAI_HTML;
                }
                if ($html === '') {
                    Response::json(['detail' => 'localai.html is missing'], 404);
                    return;
                }
                Response::raw(self::withApiBase($html), 'text/html; charset=utf-8');
            });
        }

        // Connectivity self-test. Deliberately unauthenticated and read-only:
        // it has to be reachable precisely when the rest of the app is not.
        foreach (['/diag', '/diagnostics'] as $p) {
            $r->get($p, static function (Request $req): void {
                $page = Bootstrap::$publicDir . '/diag.html';
                $html = '';
                if (is_file($page)) {
                    $html = Files::read($page);
                } elseif (class_exists('Arena\\EmbeddedAssets') && defined('Arena\\EmbeddedAssets::DIAG_HTML')) {
                    $html = EmbeddedAssets::DIAG_HTML;
                }
                if ($html === '') {
                    Response::json(['detail' => 'diag.html is missing'], 404);
                    return;
                }
                Response::raw(self::withApiBase($html), 'text/html; charset=utf-8');
            });
        }

        $r->setFallback(static function (Request $req): void {
            if (str_starts_with($req->path, '/api/')) {
                Response::json(['detail' => "No API route for {$req->path}"], 404);
                return;
            }
            if ($req->method !== 'GET' && $req->method !== 'HEAD') {
                Response::json(['detail' => 'Method not allowed'], 405);
                return;
            }
            // Static asset from public/, else the SPA (client-side routing).
            $rel = Files::normalizeRel($req->path);
            $abs = Bootstrap::$publicDir . '/' . $rel;
            $realPublic = realpath(Bootstrap::$publicDir) ?: Bootstrap::$publicDir;
            $realAbs = realpath($abs);
            if ($rel !== '' && $realAbs !== false && str_starts_with($realAbs, $realPublic) && is_file($realAbs)) {
                if (str_ends_with(strtolower($realAbs), '.html')) {
                    Response::raw(self::withApiBase(Files::read($realAbs)), 'text/html; charset=utf-8');
                    return;
                }
                Response::file($realAbs, Files::mimeType($realAbs));
                return;
            }
            self::serveSpa();
        });
    }
}



namespace Arena {
    // Single-File Dispatcher & Front-Controller
    if (php_sapi_name() === 'cli' && isset($argv[1]) && in_array($argv[1], ['migrate', 'doctor', 'worker', 'version', 'help', '--help', '-h'], true)) {
        Bootstrap::init();
        Database::init();
        $cmd = $argv[1];
        if ($cmd === 'migrate') {
            echo "✓ Database schema verified.\n";
            exit(0);
        } elseif ($cmd === 'doctor') {
            $caps = Bootstrap::capabilities();
            echo "Arena Agent PHP Doctor Report:\n";
            foreach ($caps as $k => $v) {
                echo " - " . str_pad($k, 18) . ": " . (is_bool($v) ? ($v ? 'YES' : 'NO') : (string)$v) . "\n";
            }
            exit(0);
        } elseif ($cmd === 'version') {
            echo "Arena Coding Agent PHP v" . APP_VERSION . "\n";
            exit(0);
        } elseif ($cmd === 'worker') {
            Jobs::runWorkerLoop(2);
            exit(0);
        } else {
            echo "Arena Coding Agent PHP v" . APP_VERSION . " (Single-File Distribution)\n";
            echo "Usage: php -S 0.0.0.0:8099 " . basename(__FILE__) . "\n";
            echo "CLI commands: migrate | doctor | worker | version\n";
            exit(0);
        }
    }

    // Web Request Handler
    Bootstrap::init();

    // Ensure database is initialized with embedded fallback if file missing
    try {
        Database::init();
    } catch (\Throwable $e) {
        // Fallback migration with embedded SQL
        try {
            $pdo = Database::pdo();
            $pdo->exec(EmbeddedAssets::INIT_SQL);
        } catch (\Throwable $inner) {}
    }

    $req = Request::capture();

    // CORS Handling
    $origins = Config::corsOrigins();
    $requestOrigin = (string) $req->header('origin', '');
    $allowAll = in_array('*', $origins, true);
    $allowOrigin = $allowAll ? '*' : (in_array($requestOrigin, $origins, true) ? $requestOrigin : '');

    if ($allowOrigin !== '') {
        header('Access-Control-Allow-Origin: ' . $allowOrigin);
        header('Vary: Origin');
        if (!$allowAll) {
            header('Access-Control-Allow-Credentials: true');
        }
        header('Access-Control-Allow-Headers: Content-Type, Authorization, X-Auth-Token');
        header('Access-Control-Allow-Methods: GET, POST, PUT, DELETE, PATCH, OPTIONS');
    }

    if ($req->method === 'OPTIONS') {
        http_response_code(204);
        exit;
    }

    try {
        Observability::boot();
        if (!Auth::middleware($req)) {
            exit;
        }
        $router = new Router();
        Routes::register($router);
        $router->dispatch($req);
    } catch (HttpError $e) {
        if (!Response::$headersSent) {
            Response::json($e->payload, $e->getCode() ?: 400);
        }
    } catch (\Throwable $e) {
        $message = $e->getMessage();
        try {
            Observability::log('ERROR', 'API', $message, [
                'path' => $req->path,
                'method' => $req->method,
                'file' => $e->getFile() . ':' . $e->getLine(),
            ]);
        } catch (\Throwable) {}
        if (!Response::$headersSent) {
            Response::json(['detail' => $message], 400);
        }
    }
}

